function clubSetupStepStatus(step){
  if(step.key==='workshop'&&step.complete)return 'Completed · How We Bat selected';
  return step.complete?'Complete':'Not complete';
}
function clubSetupProgressHtml(progress){
  return `<ol class="club-setup-progress" aria-label="Five preparation steps before players build their plans">${progress.steps.map((step,index)=>{
    const current=index===progress.currentIndex;
    return `<li class="${step.complete?'is-complete':current?'is-current':'is-future'}"><button type="button" data-club-stage="${step.key}" aria-expanded="false" aria-controls="clubHomeStagePanel" ${current?'aria-current="step"':''}><span class="club-setup-marker" aria-hidden="true">${step.complete?'✓':index+1}</span><span><strong>${esc(step.shortTitle)}</strong><small>${esc(clubSetupStepStatus(step))}${!step.complete&&current?' · Next step':''}</small></span></button></li>`;
  }).join('')}</ol>`;
}

async function expandClubHomeStage(key,progress){
  const page=document.getElementById('page');
  const panel=document.getElementById('clubHomeStagePanel');
  const content=document.getElementById('clubHomePhaseContent');
  if(!panel||!content||currentTab!=='dashboard')return;
  clubHomeExpandedStage=key;
  recordAppNavigation(clubNavigationRoute());
  page.querySelectorAll('[data-club-stage]').forEach(button=>button.setAttribute('aria-expanded',String(button.dataset.clubStage===key)));
  const branding=page.querySelector('.club-branding-card');
  if(branding)branding.hidden=true;
  panel.hidden=!key;
  content.innerHTML='';
  if(!key)return;
  const step=progress.steps.find(item=>item.key===key);
  if(!step)return;
  const index=progress.steps.indexOf(step);
  const current=index===progress.currentIndex;
  const waiting=step.key==='workshop'&&canContributePhilosophy()&&!isPhilosophyLead()&&!isAdmin()&&myContributor?.status==='submitted';
  const canAct=current&&canActOnClubSetupStep(step);
  const canView=step.complete&&canOpenClubTab(step.tab)&&(key!=='details'||isAdmin());
  const inlineWorkshop=key==='workshop'&&canOpenClubTab('workshop')&&(canView||myContributor?.status==='submitted'||(isPhilosophyLead()&&workshop?.final_draft_ready));
  const description=step.complete
    ?(key==='publish'?'The club’s batting approach and Player Plan questions are published. Registered players can now build their Player Plans, train, and learn through feedback. People can continue to register.':`View the saved ${step.title}. The full phase information is shown below.`)
    :current?(waiting?'Your response is submitted. You can now compare and discuss the options. Only the Philosophy Lead confirms the club’s approach.':step.description)
    :`Complete ${progress.steps.slice(0,index).filter(item=>!item.complete).map(item=>item.shortTitle).join(', ')} first. This stage is not complete yet.`;
  document.getElementById('clubHomeStageHeading').innerHTML=`<div><div class="section-label">Step ${index+1} · ${esc(clubSetupStepStatus(step))}</div><h3>${step.complete?'View ':''}${esc(step.title)}</h3><p>${esc(description)}</p><small>${step.complete?'Saved stage':canAct?'Led by':'Waiting for'} ${step.complete?'':esc(step.owner)}${waiting?' · Your response is submitted':''}</small></div><button class="btn ghost compact-btn" type="button" id="closeClubHomeStage">Close details</button>`;
  document.getElementById('closeClubHomeStage').onclick=()=>{
    expandClubHomeStage(null,progress);
    page.querySelector(`[data-club-stage="${key}"]`)?.focus({preventScroll:true});
  };
  if(key==='details'&&(canAct||canView)&&branding){branding.hidden=false;return;}
  if(inlineWorkshop){
    document.getElementById('clubHomeStageHeading').innerHTML=`<div class="section-label">Workshop · ${step.complete?'Completed — How We Bat selected':'Choose How We Bat'}</div><button class="btn ghost compact-btn" type="button" id="closeClubHomeStage">Close details</button>`;
    document.getElementById('closeClubHomeStage').onclick=()=>expandClubHomeStage(null,progress);
  }
  if((canView||inlineWorkshop)&&key!=='details'){
    try{
      if(key==='workshop')await renderWorkshop();
      else if(key==='howwebat')renderPublishedHowWeBat();
      else await renderPlanStructure();
    }catch(error){
      if(clubHomeExpandedStage===key&&currentTab==='dashboard')content.innerHTML=`<div class="notice">${esc(error.message||String(error))}</div>`;
    }
    return;
  }
  if(current){
    const label=waiting?'Compare and discuss How We Bat':key==='workshop'&&!workshop?.philosophy_lead_user_id&&isAdmin()?'Choose a Philosophy Lead':step.action;
    content.innerHTML=`${!canAct&&!waiting?`<p class="help">${key==='details'?'Your Club Admin':'Your Philosophy Lead'} needs to complete this step.</p>`:''}<button class="btn secondary" id="continueClubHomeStage" type="button" ${canAct?'':'disabled'}>${esc(label)}</button>`;
    document.getElementById('continueClubHomeStage').onclick=async()=>{
      if(!canAct||!canOpenClubTab(step.tab)||!await saveClubEditsBeforeNavigation())return;
      currentTab=step.tab;localStorage.setItem(`bdp-tab-${club.id}`,currentTab);await renderTab();
    };
  }else if(step.complete){content.innerHTML='<p class="help">Your club’s authorised setup team can view the details of this phase.</p>';}
}


async function saveClubEditsBeforeNavigation(){
  if(!confirmLeaveClubBranding())return false;
  if(!confirmLeaveSelections())return false;
  if(!confirmLeaveCoachingStaff())return false;
  if(!confirmLeaveClubMessages())return false;
  if(!await savePhilosophyResponseBeforeNavigation())return false;
  if(!await saveClubPlanBeforeNavigation())return false;
  if(!await savePlayerPlanStructureBeforeNavigation())return false;
  if(!await saveHowWeBatBeforeNavigation())return false;
  if(!confirmLeaveWorkshopSetup())return false;
  if(!confirmLeaveMakeYourCall())return false;
  return confirmLeaveFeedbackEntry();
}
function contributionLocked(){
  return myContributor?.status==='submitted';
}

let philosophyResponseNavigationSaving=false;
let workshopSetupSavedSnapshot=null;

function workshopSetupSnapshotOnPage(){
  if(!document.getElementById('saveWorkshopSetup')||!document.getElementById('leadUser'))return null;
  return JSON.stringify({
    mode:document.querySelector('input[name="workshopMode"]:checked')?.value||'solo',
    lead:document.getElementById('leadUser').value,
    contributors:[...document.querySelectorAll('[data-contributor-user]:checked')].map(input=>input.dataset.contributorUser).sort(),
    invitees:[...document.querySelectorAll('[data-new-contributor-row]')].map(row=>({
      name:row.querySelector('[data-new-name]')?.value.trim()||'',
      email:row.querySelector('[data-new-email]')?.value.trim()||''
    })).filter(person=>person.name||person.email)
  });
}

function rememberWorkshopSetupSnapshot(snapshot=workshopSetupSnapshotOnPage()){
  workshopSetupSavedSnapshot={clubId:club.id,snapshot};
}

function confirmLeaveWorkshopSetup(){
  if(currentTab!=='workshop'||workshopSetupSavedSnapshot?.clubId!==club?.id)return true;
  const current=workshopSetupSnapshotOnPage();
  if(current===null||current===workshopSetupSavedSnapshot.snapshot)return true;
  return confirm('You have unsaved changes to the workshop setup. Leave this page and discard those changes? Choose Cancel to keep editing or save your selections first.');
}

function philosophyResponseFieldsOnPage(){
  if(currentTab==='identity'&&document.getElementById('identityNote')){
    return {
      identity_values:[...document.querySelectorAll('[data-identity]:checked')].map(x=>x.dataset.identity),
      identity_note:val('identityNote'),
      formats_enabled:Object.fromEntries(FORMATS.map(([key])=>[key,!!document.querySelector(`[data-format="${key}"]`)?.checked]))
    };
  }
  if(currentTab==='dimensions'&&document.getElementById('dimensionNotes')){
    const keys=[...document.querySelectorAll('[data-dim]:checked')].map(x=>x.dataset.dim);
    const formatWeights=new Map(weights);
    for(const key of keys)for(const [format] of FORMATS){
      const weightKey=`${key}:${format}`;
      if(!formatWeights.has(weightKey))formatWeights.set(weightKey,DEFAULT_WEIGHTS[key]?.[format]??2);
    }
    return {
      selected_dimensions:keys,
      dimension_notes:Object.fromEntries(keys.map(key=>[key,document.querySelector(`[data-dim-note="${key}"]`)?.value.trim()||''])),
      format_weights:Object.fromEntries(formatWeights)
    };
  }
  if(currentTab==='formats'&&document.getElementById('saveWeights')){
    const formatWeights=new Map(weights);
    document.querySelectorAll('[data-weight-key]').forEach(x=>formatWeights.set(x.dataset.weightKey,Number(x.value)));
    return {format_weights:Object.fromEntries(formatWeights)};
  }
  return null;
}

function samePhilosophyResponseFields(fields,response){
  // JSONB does not retain object-key order. Compare content rather than the
  // original serialisation so merely opening Help never creates another save.
  const ordered=value=>Array.isArray(value)?value.map(ordered):value&&typeof value==='object'
    ?Object.fromEntries(Object.keys(value).sort().map(key=>[key,ordered(value[key])])):value;
  return !!fields&&Object.keys(fields).every(key=>JSON.stringify(ordered(fields[key]))===JSON.stringify(ordered(response?.[key])));
}

async function savePhilosophyResponseBeforeNavigation(){
  if(philosophyResponseNavigationSaving)return false;
  if(!['identity','dimensions','formats'].includes(currentTab)||!myContribution||contributionLocked())return true;
  const fields=philosophyResponseFieldsOnPage();
  if(!fields||samePhilosophyResponseFields(fields,myContribution))return true;
  const targetClubId=club.id;
  const targetUserId=session.user.id;
  const targetTab=currentTab;
  const statusId=({identity:'identityStatus',dimensions:'dimStatus',formats:'weightStatus'})[targetTab];
  const status=document.getElementById(statusId);
  if(status)status.textContent='Saving your response…';
  philosophyResponseNavigationSaving=true;
  try{
    const {data,error}=await supabase.from('philosophy_contributions')
      .update({...fields,updated_at:new Date().toISOString()})
      .eq('club_id',targetClubId).eq('user_id',targetUserId).select('*').single();
    if(error)throw error;
    if(club?.id!==targetClubId||session?.user?.id!==targetUserId||currentTab!==targetTab)return false;
    myContribution=data||{...myContribution,...fields};
    if(targetTab==='identity')clubProfile={...clubProfile,...fields};
    if(targetTab==='dimensions')selectedDims=new Map(fields.selected_dimensions.map(key=>[key,{club_id:targetClubId,dimension_key:key,enabled:true,club_note:fields.dimension_notes[key]||''}]));
    if(fields.format_weights)weights=new Map(Object.entries(fields.format_weights).map(([key,value])=>[key,Number(value)]));
    if(workshop?.final_draft_ready&&isPhilosophyLead()&&howWeBatDraft)howWeBatDraft.status='draft';
    if(!samePhilosophyResponseFields(philosophyResponseFieldsOnPage(),fields)){
      if(status)status.textContent='Earlier edits saved. Your latest changes are still here; save again before leaving.';
      return false;
    }
    if(status)status.textContent='Saved ✓';
    return true;
  }catch(error){
    const message=`Couldn’t save your response. Your changes are still here. ${error?.message||'Please try again.'}`;
    if(club?.id===targetClubId&&currentTab===targetTab){
      if(status)status.textContent=message;
      else alert(message);
    }
    return false;
  }finally{
    philosophyResponseNavigationSaving=false;
  }
}


let myCoachingUpdates={clubId:null,userId:null,updates:[],openRequestCount:0,error:'',loaded:false};
let coachingUpdatesSequence=0,coachingNoteObserver=null,pendingCoachingUpdate=null;
const coachingSeenPending=new Set();
function coachingUpdateScopeMatches(state=myCoachingUpdates){return state.clubId===club?.id&&state.userId===session?.user?.id&&!!membership&&!!club;}

function renderCoachingUpdatesMenu(){
  const host=document.getElementById('coachingUpdatesHost');if(!host)return;
  const state=myCoachingUpdates,scoped=coachingUpdateScopeMatches(state);
  const rows=scoped?state.updates:[],openRequestCount=scoped?state.openRequestCount||0:0;
  host.hidden=!rows.length&&!openRequestCount;
  if(host.hidden){const menu=document.getElementById('coachingUpdatesMenu');if(menu)menu.open=false;}
  // Keep the native details/summary attached during a click. Replacing them
  // here cancels the browser's opening action and discards keyboard focus.
  if(!document.getElementById('coachingUpdatesMenu'))host.innerHTML=`<details class="account-menu" id="coachingUpdatesMenu">
    <summary class="btn ghost" id="coachingUpdatesToggle" style="min-height:44px"></summary>
    <div class="account-menu-popover coaching-updates-popover"></div></details>`;
  const toggle=document.getElementById('coachingUpdatesToggle');
  toggle.setAttribute('aria-label',`Coaching updates${rows.length?`: ${rows.length} unread`:''}`);
  toggle.innerHTML=`
      <svg width="18" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>
      Coaching ${rows.length?`<span class="coaching-unread-badge">${rows.length}</span>`:''}<span class="account-menu-chevron" aria-hidden="true">⌄</span>`;
  host.querySelector('.coaching-updates-popover').innerHTML=`<strong>Coaching updates</strong>
      <div role="status" aria-live="polite" class="account-access-status">${state.error?'Updates could not be checked. Try again.':!state.loaded?'Checking for new notes…':rows.length?`${rows.length} unread coaching update${rows.length===1?'':'s'}`:openRequestCount?`${openRequestCount} open conversation request${openRequestCount===1?'':'s'}`:'You’re up to date.'}</div>
      ${rows.map(u=>`<button type="button" class="account-menu-action" data-open-coaching-update="${esc(u.source_key)}">${esc(u.author_name)} · ${u.source_kind==='conversation'?'Coach Conversation':u.source_kind==='match'?'Match observation':'Training observation'}<small>${esc(formatDateShort(u.changed_at))} · ${u.can_open?'View note':'Add your reflection to view'}</small></button>`).join('')}
      <button type="button" class="account-menu-action" id="openMyConversations">Open Coach Conversations</button>
      <button type="button" class="account-menu-action" id="checkCoachingUpdates">Check for updates</button>`;
  toggle.onclick=()=>{if(!toggle.closest('details').open)void refreshMyCoachingUpdates();};
  document.getElementById('openMyConversations').onclick=openCoachConversations;
  document.getElementById('checkCoachingUpdates').onclick=()=>refreshMyCoachingUpdates();
  host.querySelectorAll('[data-open-coaching-update]').forEach(button=>button.onclick=async()=>{
    const update=myCoachingUpdates.updates.find(u=>u.source_key===button.dataset.openCoachingUpdate);
    if(!update||!coachingUpdateScopeMatches()||!await saveClubEditsBeforeNavigation()||!confirmLeaveFeedbackEntry())return;
    pendingCoachingUpdate={...update,clubId:club.id,userId:session.user.id};
    document.getElementById('coachingUpdatesMenu').open=false;
    currentTab=update.source_kind==='conversation'?'conversations':update.source_kind==='match'?'innings':'howwetrain';
    if(currentTab==='innings'){const state=ensureMyInningsState();state.season='all';state.format='';state.openId=update.match_id;state.editId=update.can_open?null:update.match_id;}
    howWeTrainReflectionEditId=null;
    await renderTab();
  });
}

async function openCoachConversations(){
  if(!await saveClubEditsBeforeNavigation()||!confirmLeaveFeedbackEntry())return;
  const alerts=document.getElementById('coachingUpdatesMenu');if(alerts)alerts.open=false;
  const account=document.getElementById('accountCoaching')?.closest('details');if(account)account.open=false;
  currentTab='conversations';await renderTab();
}

async function refreshMyCoachingUpdates(){
  if(!document.getElementById('coachingUpdatesHost')||!membership||!club||!session?.user)return;
  const clubId=club.id,userId=session?.user?.id,sequence=++coachingUpdatesSequence;
  if(!coachingUpdateScopeMatches())myCoachingUpdates={clubId,userId,updates:[],openRequestCount:0,error:'',loaded:false};
  renderCoachingUpdatesMenu();
  // Read both through existing scoped RPCs. Read requests remain reachable
  // until completed; unread observations retain their existing alert behaviour.
  const results=await Promise.allSettled([
    supabase.rpc('get_my_coaching_updates',{p_club_id:clubId}),
    supabase.rpc('get_my_coach_conversations',{p_club_id:clubId})
  ]);
  if(club?.id!==clubId||session?.user?.id!==userId||sequence!==coachingUpdatesSequence)return;
  const [updates,inbox]=results.map(result=>result.status==='fulfilled'?result.value:{error:result.reason});
  const errors=[updates.error,inbox.error].filter(Boolean);
  myCoachingUpdates={...myCoachingUpdates,clubId,userId,
    updates:updates.error?myCoachingUpdates.updates:Array.isArray(updates.data?.updates)?updates.data.updates:[],
    openRequestCount:inbox.error?myCoachingUpdates.openRequestCount||0:(inbox.data?.actions||[]).filter(a=>a.is_player_request&&a.status==='open').length,
    error:errors.map(error=>error?.message||'Could not check updates').join(' '),loaded:true};
  renderCoachingUpdatesMenu();watchVisibleCoachingNotes();void updatePhoneAppBadge();
}

function coachingNoteElement(update){
  return document.querySelector(update.source_kind==='conversation'?`[data-coaching-action-card="${update.source_id}"]`:update.source_kind==='match'?`[data-coach-feedback-id="${update.source_id}"]`:`[data-training-observation-id="${update.source_id}"]`);
}
async function acknowledgeCoachingUpdate(update){
  const note=coachingNoteElement(update);
  if(!['howwetrain','conversations','innings'].includes(currentTab)||!coachingUpdateScopeMatches()||!note||note.dataset.coachingNoteUpdatedAt!==update.changed_at)return;
  const scope=myCoachingUpdates,key=`${scope.clubId}:${scope.userId}:${update.source_key}:${update.changed_at}`;
  if(coachingSeenPending.has(key))return;
  coachingSeenPending.add(key);
  try{
    const {data,error}=await supabase.rpc('mark_my_coaching_update_seen',{p_club_id:scope.clubId,p_source_key:update.source_key,p_changed_at:update.changed_at});
    if(error)throw error;
    if(data===true&&coachingUpdateScopeMatches(scope)){
      myCoachingUpdates={...myCoachingUpdates,updates:myCoachingUpdates.updates.filter(u=>!(u.source_key===update.source_key&&u.changed_at===update.changed_at))};
      renderCoachingUpdatesMenu();
    }
  }catch(error){/* Keep the unread badge if the acknowledgement was not saved. */}
  finally{coachingSeenPending.delete(key);}
}

function watchVisibleCoachingNotes(){
  bindCompletePlayerPlanButtons(document.getElementById('page'));
  coachingNoteObserver?.disconnect();coachingNoteObserver=null;
  if(!['howwetrain','conversations','innings'].includes(currentTab)||!coachingUpdateScopeMatches()||typeof IntersectionObserver==='undefined')return;
  const scope=myCoachingUpdates;
  coachingNoteObserver=new IntersectionObserver(entries=>{
    if(!coachingUpdateScopeMatches(scope)||!['howwetrain','conversations','innings'].includes(currentTab))return;
    for(const entry of entries){
      if(!entry.isIntersecting)continue;
      const update=myCoachingUpdates.updates.find(u=>coachingNoteElement(u)===entry.target);
      if(update)void acknowledgeCoachingUpdate(update);
    }
  },{threshold:0.25});
  for(const update of myCoachingUpdates.updates){const element=coachingNoteElement(update);if(element)coachingNoteObserver.observe(element);}
}

function coachingHistoryItems(items,kind,limit){
  const target=pendingCoachingUpdate;
  return items.filter((item,index)=>index<limit||(target&&coachingUpdateScopeMatches(target)&&
    (kind==='match'?item.id===target.match_id:item.id===target.source_id)));
}

function coachingHistoryHtml(items,kind,limit,renderItem){
  const recent=coachingHistoryItems(items,kind,limit),shown=new Set(recent.map(item=>item.id));
  const older=items.filter(item=>!shown.has(item.id));
  return recent.map(renderItem).join('')+(older.length?`<details><summary>Earlier ${kind==='match'?'match':'training'} notes (${older.length})</summary>${older.map(renderItem).join('')}</details>`:'');
}

async function revealPendingCoachingUpdate(){
  watchVisibleCoachingNotes();
  const update=pendingCoachingUpdate;
  if(!update||!coachingUpdateScopeMatches(update)||!['howwetrain','conversations','innings'].includes(currentTab))return;
  const history=document.getElementById('trainingFeedbackLoop');if(history)history.open=true;
  const note=coachingNoteElement(update);
  if(note){
    pendingCoachingUpdate=null;for(let parent=note.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;note.scrollIntoView({behavior:'smooth',block:'center'});
    // Also supports browsers without IntersectionObserver when a note was explicitly opened.
    await acknowledgeCoachingUpdate(update);
  }else{
    document.getElementById('myReflectionForm')?.scrollIntoView({behavior:'smooth',block:'start'});
  }
}

