// Browser history stores destinations and roster filters, never answers or credentials.
// The first screen replaces the current entry; subsequent screens create real Back/Forward steps.
function recordAccountScreen(tab){
  if(!club||!session)return;
  if(!['join_club'].includes(currentTab))accountReturnTab=currentTab;
  currentTab=tab;
  recordAppNavigation(clubNavigationRoute());
}
function closeAccountScreen(){
  currentTab=canOpenClubTab(accountReturnTab)?accountReturnTab:'dashboard';
  return renderShell();
}
function clubNavigationRoute(){
  const route={scope:'club',clubId:club?.id,tab:currentTab};
  if(currentTab==='teams'){const s=ensureSelections();route.selections={view:s.view,date:s.date};}
  if(currentTab==='players')Object.assign(route,{
    playerId:playersWorkspaceSelectedId,playerSection:playersWorkspaceSection,
    search:playersWorkspaceSearch,group:playersWorkspaceGroupFilter,showAll:playersWorkspaceShowAll,
    matchFormat:playersWorkspaceMatchFormat,matchOpenId:playersWorkspaceMatchOpenId
  });
  if(currentTab==='groups'){
    const {source,search,target}=ensurePlayingGroupsView();
    route.assignments={source,search,target};
  }
  if(currentTab==='innings'){const {season,format,openId,editId}=ensureMyInningsState();route.innings={season,format,openId,editId};}
  if(currentTab==='make_your_call'){const {week,season,month}=ensureMakeYourCallState();route.makeYourCall={week,season,month:month||null,results:serializeCallResultsState()};}
  if(currentTab==='training_preparation')route.trainingPreparation={group:ensureTrainingPreparationState().group};
  if(currentTab==='messages'){const m=ensureClubMessages();route.messages={mode:m.mode==='compose'?'inbox':m.mode,openId:m.openId};}
  if(currentTab==='team_review')route.teamReview=serializeTeamReviewState();
  if(currentTab==='myplan')route.planSection=builderSection;
  if(currentTab==='dashboard')route.homeStage=clubHomeExpandedStage;
  if(currentTab==='workshop_preview'&&workshopPreview){
    route.previewKey=workshopPreview.key;
    route.preview={ids:[...workshopPreview.ids],round:workshopPreview.round,format:workshopPreview.format};
  }
  route.viewState={howWeBatFormat:publishedHowWeBatFormat,builderFormat:howWeBatBuilderFormat,questionsSection:playerPlanStructureSection,responseFormat:previewFormat,guideTopic:guideSelectedCapabilityKey};
  if(['join_club'].includes(currentTab))route.returnTab=accountReturnTab;
  return route;
}
function platformNavigationRoute(){
  return {scope:'platform',view:platformView,prospectId:platformSelectedProspectId,onboardingId:platformSelectedOnboardingId};
}
function appNavigationKey(route){
  return JSON.stringify([route.scope,route.clubId,route.tab,route.playerId,route.playerId?route.playerSection:null,route.planSection,route.innings?.editId,route.previewKey,route.view,route.prospectId,route.onboardingId,route.tab==='make_your_call'?(route.makeYourCall?.results?.view||'board'):null]);
}
function validAppNavigationMarker(marker){
  return !!(marker?.version===1&&marker.userId===session?.user?.id&&typeof marker.trail==='string'&&Number.isInteger(marker.index)&&marker.index>=0&&
    (marker.route?.scope==='platform'||(marker.route?.scope==='club'&&typeof marker.route.clubId==='string'&&typeof marker.route.tab==='string')));
}
function restorePlatformNavigationState(route){
  platformView=route.view==='selections'?'clubs':['home','add_clubs','clubs','market','outbox','guide_requests','settings'].includes(route.view)?route.view:'home';
  platformSelectedProspectId=route.prospectId||null;
  platformSelectedOnboardingId=route.onboardingId||null;
}
function replaceRestoredNavigation(marker){
  const route=document.getElementById('platformPage')?platformNavigationRoute():document.getElementById('page')||document.getElementById('cancelJoin')?clubNavigationRoute():null;
  if(!route)return;
  appNavigationCurrent={...marker,route};
  history.replaceState({...history.state,clubBattingNavigation:appNavigationCurrent,clubBattingWorkshop:null},'');
}
async function resumeAppNavigationOnLoad(){
  if(new URLSearchParams(location.search).has('club'))return false;
  const marker=history.state?.clubBattingNavigation;
  if(appNavigationCurrent||!validAppNavigationMarker(marker))return false;
  const request=++appNavigationRequest;
  appNavigationCurrent=marker;appNavigationRestoring=true;
  try{
    await loadContext({navigation:marker.route,navigationRequest:request});
    if(request===appNavigationRequest&&session?.user?.id===marker.userId)replaceRestoredNavigation(marker);
  }catch(error){
    if(request===appNavigationRequest&&session?.user?.id===marker.userId){
      app.innerHTML=`<div class="login"><h1>This screen could not reload.</h1><p>${esc(error?.message||'Check your connection and try again.')}</p><button class="btn secondary" id="retryNavigationReload">Try again</button></div>`;
      document.getElementById('retryNavigationReload').onclick=()=>{appNavigationCurrent=null;return routeAuth();};
    }
  }finally{
    if(request===appNavigationRequest)appNavigationRestoring=false;
  }
  return true;
}
function recordAppNavigation(route){
  if(appNavigationRestoring||!session?.user?.id||!history.pushState)return;
  const userId=session.user.id;
  const previous=appNavigationCurrent?.userId===userId?appNavigationCurrent:null;
  const changed=previous&&appNavigationKey(previous.route)!==appNavigationKey(route);
  const marker={version:1,userId,trail:previous?.trail||`${Date.now()}-${Math.random()}`,index:previous?(previous.index+(changed?1:0)):0,route};
  const state={...history.state,clubBattingWorkshop:null,clubBattingNavigation:marker};
  if(changed)history.pushState(state,'');
  else history.replaceState(state,'');
  appNavigationCurrent=marker;
  return !!changed;
}
function restoreClubNavigationState(route){
  const view=route.viewState||{};
  if(FORMATS.some(([key])=>key===view.howWeBatFormat))publishedHowWeBatFormat=view.howWeBatFormat;
  if(FORMATS.some(([key])=>key===view.builderFormat))howWeBatBuilderFormat=view.builderFormat;
  if(FORMATS.some(([key])=>key===view.responseFormat))previewFormat=view.responseFormat;
  if(['core',...FORMATS.map(([key])=>key)].includes(view.questionsSection))playerPlanStructureSection=view.questionsSection;
  if(typeof view.guideTopic==='string')guideSelectedCapabilityKey=view.guideTopic;
  if(typeof route.returnTab==='string')accountReturnTab=route.returnTab;
  const tab=route.tab==='workshop_preview'&&!workshopPreview?'workshop':route.tab;
  currentTab=canOpenClubTab(tab)?tab:selectionsStandalone()?'teams':canUseClubHome()?'dashboard':isPlayerUser()?'playerhome':'howwetrain';
  if(currentTab==='teams'){const s=ensureSelections();s.view=route.selections?.view||'published';s.date=route.selections?.date||'';}
  if(currentTab==='make_your_call'){const s=ensureMakeYourCallState();s.week=route.makeYourCall?.week||null;s.season=route.makeYourCall?.season||null;s.month=route.makeYourCall?.month||null;restoreCallResultsState(route.makeYourCall?.results||{});}
  if(currentTab==='players'){
    resetPlayersWorkspaceForClub();
    playersWorkspaceSelectedId=route.playerId||null;
    playersWorkspaceSection=route.playerSection||'summary';
    playersWorkspaceSearch=route.search||'';
    playersWorkspaceGroupFilter=route.group==='__actions__'?'__discussion__':route.group||'';
    playersWorkspaceShowAll=!!route.showAll;
    playersWorkspaceMatchFormat=FORMATS.some(([key])=>key===route.matchFormat)?route.matchFormat:'';
    playersWorkspaceMatchOpenId=typeof route.matchOpenId==='string'?route.matchOpenId:null;
    playersWorkspaceLocalRaw=null;
    playersWorkspaceDevelopmentMode=null;
    playersWorkspaceDevelopmentMatchId=null;
  }
  if(currentTab==='innings'){const state=ensureMyInningsState(),saved=route.innings||{};Object.assign(state,{season:saved.season==='all'||/^\d{4}$/.test(saved.season||'')?saved.season:null,format:FORMATS.some(([k])=>k===saved.format)?saved.format:'',openId:typeof saved.openId==='string'?saved.openId:null,editId:typeof saved.editId==='string'?saved.editId:null});}
  if(currentTab==='training_preparation')restoreTrainingPreparationState(route.trainingPreparation||{});
  if(currentTab==='messages'){const m=ensureClubMessages();m.mode=route.messages?.mode==='sent'?'sent':'inbox';m.openId=route.messages?.openId||null;}
  if(currentTab==='team_review')restoreTeamReviewState(route.teamReview||{});
  if(currentTab==='myplan')builderSection=route.planSection||'core';
  if(currentTab==='groups'){
    const state=ensurePlayingGroupsView();
    const saved=route.assignments||{};
    state.source=typeof saved.source==='string'?saved.source:'unassigned';
    state.search=typeof saved.search==='string'?saved.search:'';
    state.target=typeof saved.target==='string'?saved.target:'';
  }
  if(currentTab==='dashboard'){
    clubHomeStageClubId=club.id;clubHomeExpandedStage=route.homeStage||null;
    clubHomeRestoredStage=Object.hasOwn(route,'homeStage');
  }
  if(currentTab==='workshop_preview'&&(!workshopPreview||workshopPreview.key!==route.previewKey||workshopPreview.clubId!==club.id||workshopPreview.userId!==session.user.id||workshopPreview.round!==workshopReviewContext?.round_number))currentTab='workshop';
  localStorage.setItem(`bdp-tab-${club.id}`,currentTab);
}
async function handleAppNavigationHistory(event){
  const target=event.state?.clubBattingNavigation;
  if(appNavigationBounce&&target?.trail===appNavigationBounce.trail&&target.index===appNavigationBounce.index){
    appNavigationBounce=null;return;
  }
  const source=appNavigationCurrent;
  if(!target||target.version!==1||!['club','platform'].includes(target.route?.scope))return;
  const request=++appNavigationRequest;
  if(!session||target.userId!==session.user.id){
    appNavigationCurrent=null;appNavigationRestoring=false;
    await routeAuth();return;
  }
  appNavigationRestoring=true;
  const returnToSource=()=>{
    if(source?.trail===target.trail&&source.index!==target.index){
      appNavigationBounce=source;history.go(source.index-target.index);
    }else if(source)history.replaceState({...history.state,clubBattingNavigation:source},'');
  };
  try{
    // Back uses the same autosave/unsaved-work checks as the app's own navigation.
    const saved=await saveClubEditsBeforeNavigation();
    if(request!==appNavigationRequest||session?.user?.id!==target.userId)return;
    if(!saved){returnToSource();return;}
    const route=target.route;
    if(route.scope==='platform'){
      restorePlatformNavigationState(route);
      await renderPlatformConsole(); // Refresh platform permission before opening an old destination.
    }else{
      localStorage.setItem('bdp-context','club');localStorage.setItem('bdp-club-id',route.clubId);
      if(club?.id!==route.clubId||!document.getElementById('page'))await loadContext({navigation:route,navigationRequest:request});
      else{
        if(route.tab==='workshop_preview')await restoreWorkshopPreviewFromNavigation(route);
        if(request!==appNavigationRequest||session?.user?.id!==target.userId)return;
        restoreClubNavigationState(route);
        await renderTab(); // Player details are reloaded through the permitted workspace RPC.
      }
    }
    if(request!==appNavigationRequest)return;
    replaceRestoredNavigation(target);
    window.scrollTo?.({top:0,left:0,behavior:'instant'});
  }catch(error){
    if(request===appNavigationRequest){returnToSource();alert(`Couldn’t open that screen. ${error?.message||'Please try again.'}`);}
  }finally{
    if(request===appNavigationRequest)appNavigationRestoring=false;
  }
}

function renderTab(){
  installDisclosureUI();
  if(currentTab!=='myplan')playerPlanEditScope='';
  if(currentTab==='feedback'&&canUsePlayersWorkspace()){
    resetPlayersWorkspaceForClub();playersWorkspaceSelectedId=null;playersWorkspaceSection='summary';
    playersWorkspaceSearch='';playersWorkspaceGroupFilter='__discussion__';currentTab='players';
    localStorage.setItem(`bdp-tab-${club.id}`,currentTab);
  }
  if(!canOpenClubTab(currentTab)){
    currentTab=productTrialWaiting()?'products':selectionsStandalone()?'teams':canUseClubHome()?'dashboard':isPlayerUser()?'playerhome':'howwetrain';
    localStorage.setItem(`bdp-tab-${club.id}`,currentTab);
  }
  if(currentTab==='players')resetPlayersWorkspaceForClub();
  recordAppNavigation(clubNavigationRoute());
  const route=`${club?.id}:${currentTab}`;
  const scrollOnArrival=route!==workshopLastRoute;
  workshopLastRoute=route;
  if(currentTab!=='workshop_preview'){
    if(!['workshop','dashboard'].includes(currentTab))clearTimeout(workshopDiscussionTimer);
  }
  const arrived=()=>{
    bindPhoneAppControls();bindClubBrandingLinks();bindProductTrialLinks();bindContextHelpVideos();
    if(scrollOnArrival&&`${club?.id}:${currentTab}`===route){
      const inningsFocus=currentTab==='innings'?(document.getElementById('myReflectionForm')||document.getElementById('innings-detail-'+ensureMyInningsState().openId)):null;
      if(inningsFocus){if(inningsFocus.id==='myReflectionForm')revealMyInningsForm();else{inningsFocus.setAttribute('tabindex','-1');inningsFocus.focus({preventScroll:true});inningsFocus.scrollIntoView({block:'start'});}bindWorkshopReturn();return;}
      window.scrollTo?.({top:0,left:0,behavior:'instant'});
      const heading=document.getElementById('page')?.querySelector('h1')||document.getElementById('page')?.querySelector('h2');
      if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}
    }
    bindWorkshopReturn();
  };
  document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));
  const map={
    products:renderMyClubProducts,teams:renderSelections,messages:renderClubMessages,phone_app:renderPhoneApp,
    join_club:renderJoinAnotherClub,
    dashboard:renderClubDashboard,club_settings:renderClubBrandingSettings,
    playerhome:renderPlayerHome,
    innings:renderMyInnings,make_your_call:renderMakeYourCall,
    groups:renderPlayingGroups,
    players:renderPlayersWorkspace,
    team_review:renderTeamReview,
    training_preparation:renderTrainingPreparation,
    feedback:renderFeedbackWorkspace,
    workshop:renderWorkshop,
    workshop_preview:renderWorkshopPreview,
    identity:renderIdentity,
    dimensions:renderDimensions,
    formats:renderFormats,
    preview:renderPreview,
    submitted_response:()=>renderMySubmittedPhilosophyResponse(myContribution),
    plan:renderPlanStructure,
    permissions:renderPermissions,
    howwebat:renderPublishedHowWeBat,
    myplan:renderMyPlan,
    howwetrain:renderHowWeTrain,
    conversations:renderCoachConversations,
    guide:renderClubBattingGuide
  };
  try{
    const result=(map[currentTab]||renderMyPlan)();
    if(result && typeof result.then==='function'){
      return result.then(arrived).catch(err=>{
        console.error(err);
        const page=document.getElementById('page');
        if(page)page.innerHTML=`<section class="card"><div class="section-label">This page could not finish loading</div><h2>Something interrupted the page.</h2><div class="notice">${esc(err?.message||String(err))}</div><div class="help" style="margin-top:10px">Your saved data has not been deleted. Refresh once; if this returns, send us the wording above.</div></section>`;
      });
    }
    arrived();
  }catch(err){
    console.error(err);
    const page=document.getElementById('page');
    if(page)page.innerHTML=`<section class="card"><div class="section-label">This page could not finish loading</div><h2>Something interrupted the page.</h2><div class="notice">${esc(err?.message||String(err))}</div></section>`;
  }
}



/* ---------------- CLUB BATTING GUIDE ---------------- */

function guideAudienceKey(){
  const role=membership?.permission_role||'';
  if(['admin','head_coach','coach','captain'].includes(role))return role;
  if(hasMatchCaptainAccess())return 'captain';
  return isPlayerUser()?'player':'member';
}

function focusClubGuideArea(area='tutorials'){
  requestAnimationFrame(()=>{
    if(currentTab!=='guide')return;
    const target=area==='page'?document.getElementById('guidePageTitle'):area==='chat'
      ?document.getElementById('demoGuideNote')||document.querySelector('.guide-chat-card')
      :guideSelectedCapabilityKey==='whole_process'?document.getElementById('guideProcessHeading'):document.querySelector('.guide-tutorial-card');
    if(!target)return;
    const nav=document.querySelector('.nav');
    const offset=(nav?.getBoundingClientRect().height||0)+(document.getElementById('demoToolbar')?.getBoundingClientRect().height||0)+18;
    target.style.scrollMarginTop=offset+'px';
    target.setAttribute('tabindex','-1');target.focus({preventScroll:true});
    target.scrollIntoView({block:'start',behavior:'auto'});
  });
}

async function openClubBattingGuideTopic(capabilityKey='whole_process',{focus='tutorials'}={}){
  if(!await saveClubEditsBeforeNavigation())return;
  guideSelectedCapabilityKey=capabilityKey||'whole_process';
  currentTab='guide';
  localStorage.setItem(`bdp-tab-${club.id}`,currentTab);
  await renderTab();
  focusClubGuideArea(focus);
}

function guideTargetLabel(tab){
  return ({dashboard:'Club Home',permissions:'People & Sign-up',workshop:'Batting Philosophy Workshop',howwebat:'How We Bat',plan:'Player Plan Structure',players:'Players',playerhome:'Player Home',myplan:'My Player Plan',innings:'My Innings',make_your_call:'Make your prediction',howwetrain:'How We Train',conversations:'Coach Conversations',messages:'Messages',phone_app:'App & notifications'}[tab]||'Open area');
}

function guideTargetUnavailableReason(tab,focus=''){
  if(focus==='plan_dates'&&!isAdmin())return 'The Club Admin sets Player Plan dates.';
  if(focus==='plan_dates'&&!philosophyVersions.length)return 'Player Plan dates become available after the Philosophy Lead publishes the Club Batting System.';
  if(canOpenClubTab(tab))return '';
  const prerequisite=clubSetupUnavailableReason(tab);
  if(prerequisite)return prerequisite;
  if(['dashboard','permissions','groups'].includes(tab))return 'The Club Admin manages this step.';
  if(tab==='workshop')return 'The Philosophy Lead and invited contributors work on this step.';
  if(tab==='plan')return 'The Philosophy Lead finalises the Player Plan Structure.';
  if(tab==='players'||tab==='feedback')return 'This workspace is for club staff with assigned player access.';
  if(tab==='myplan'||tab==='playerhome')return 'This step is for registered players.';
  if(tab==='howwebat'||tab==='howwetrain')return 'This becomes available when the Philosophy Lead publishes the Club Batting System.';
  return 'This area is not available for your club role.';
}

async function guideGoToTarget(tab,focus=''){
  if(!tab||tab==='guide')return;
  const unavailable=guideTargetUnavailableReason(tab,focus);
  if(unavailable){alert(unavailable);return;}
  if(!await saveClubEditsBeforeNavigation())return;
  if(tab==='players'){
    resetPlayersWorkspaceForClub();
    clearPlayersWorkspaceSearch();
    playersWorkspaceSelectedId=null;
    playersWorkspaceSection='summary';
  }
  if(focus==='plan_dates'){
    currentTab='players';
    localStorage.setItem(`bdp-tab-${club.id}`,currentTab);
    renderTab();
    setTimeout(()=>openPlanDueDateDialog(),120);
    return;
  }
  if(focus==='coach_conversations')playersWorkspaceGroupFilter='__discussion__';
  currentTab=tab;
  localStorage.setItem(`bdp-tab-${club.id}`,currentTab);
  renderTab();
}

function guideVisibleMessages(messages=[]){
  return (messages||[]).filter(m=>['user','assistant'].includes(m.role));
}

const GUIDE_TOPIC_ORDER=["whole_process", "trial_sign_up", "people_sign_up", "roles_and_access", "admin_handover", "philosophy_workshop", "workshop_changes", "how_we_bat", "player_plan_structure", "club_look_publication", "playing_groups", "plan_dates", "player_plan", "current_focus", "how_we_train", "training_preparation", "my_innings", "make_your_call", "weekly_engagement", "feedback_loop", "coach_conversations", "request_conversation", "youtube_video", "notifications", "navigation_account", "guide_support", "platform_pipeline", "team_review", "phone_app", "club_messages", "selections", "selection_availability", "selection_playing_groups", "selections_subscription"];

function guideTopicNumber(key){
  const index=GUIDE_TOPIC_ORDER.indexOf(key);
  return index>0?index:null;
}

function guideHelpStyles(){
  // Keep the reading order vertical even where the existing stylesheet uses two columns.
  return `<style>
    .guide-page-heading{margin:0 0 12px}
    .guide-page-heading h1{margin:0;font-size:clamp(24px,3vw,30px);line-height:1.2;color:var(--primary)}
    .guide-chat-card{margin-top:0;padding:16px;border:1px solid var(--line);background:#f4f7ff}
    .guide-chat-card h2{margin:0 0 10px}
    .guide-chat-card .guide-chat-messages{max-height:300px}
    .guide-chat-card .guide-chat-messages.is-empty{display:none}
    .guide-chat-card .guide-chat-compose{margin-top:10px;grid-template-columns:minmax(0,1fr) auto;gap:8px}
    .guide-chat-card .guide-chat-compose textarea{width:100%;min-width:0;min-height:68px;box-sizing:border-box;border:1px solid var(--line);border-radius:9px;padding:10px;font:inherit;font-size:16px;line-height:1.4;resize:vertical}
    .guide-chat-card .btn{min-height:44px}
    .guide-chat-card .guide-human-handoff{margin-top:8px;padding-top:0;border-top:0}
    .guide-chat-card #guideHandoffBox{padding-top:8px}
    .guide-chat-card #guideHandoffBox .help{margin:0 0 10px}
    .guide-chat-card #guideHandoffBox textarea{box-sizing:border-box;min-height:68px;font-size:16px}
    .guide-chat-card #guideHandoffBox .btnrow{margin-top:8px}
    .guide-process-heading{margin:20px 0 8px;font-size:20px}
    #guideTopicSearchStatus:empty{display:none}
    @media(max-width:620px){.guide-chat-card .guide-chat-compose{grid-template-columns:minmax(0,1fr)}.guide-chat-card .guide-chat-compose .btn{width:auto;justify-self:end}}
    .guide-layout.guide-is-overview{grid-template-columns:minmax(0,1fr)}
    .guide-layout.guide-is-overview .guide-chat-card{grid-column:1}
    .guide-layout .guide-topic-list{display:flex;flex-direction:column;min-width:0;gap:8px}
    .guide-layout .guide-topic-list button{display:grid;grid-template-columns:30px minmax(0,1fr);gap:10px;align-items:start;width:100%;min-height:48px;font:inherit}
    .guide-layout .guide-topic-list button.guide-topic-overview{grid-template-columns:minmax(0,1fr)}
    .guide-layout .guide-topic-list button:focus-visible{outline:3px solid var(--primary);outline-offset:3px}
    .guide-layout .guide-topic-list .guide-topic-number{display:grid;place-items:center;width:30px;height:30px;margin:0;border-radius:50%;background:var(--primary);color:#fff;font-size:.85rem;font-weight:800;line-height:1}
    .guide-layout .guide-topic-list .guide-topic-copy{margin:0;min-width:0}
    .guide-layout .guide-topic-list [hidden]{display:none!important}
    .guide-layout .guide-topic-list strong{color:var(--text);line-height:1.35}
    .guide-layout .guide-topic-list .guide-topic-description{margin-top:5px;font-size:.85rem;line-height:1.45}
    .guide-layout .guide-topic-list .guide-topic-complete{margin-top:7px;font-size:.75rem;font-weight:700;color:var(--primary)}
  </style>`;
}

