function handleWorkshopPreviewHistory(event){
  if(event.state?.clubBattingNavigation)return handleAppNavigationHistory(event);
  const marker=event.state?.clubBattingWorkshop;
  if(!marker||marker.clubId!==club?.id||marker.userId!==session?.user?.id)return;
  if(marker.view==='preview'&&workshopPreview&&workshopPreview.clubId===club.id&&workshopPreview.userId===session.user.id){
    currentTab='workshop_preview';renderTab();
  }else if(marker.view==='workshop'){
    currentTab='workshop';renderTab();
  }
}
function closeWorkshopPreview(){
  clearTimeout(workshopDiscussionTimer);
  if(history.state?.clubBattingNavigation?.route?.tab==='workshop_preview'||history.state?.clubBattingWorkshop?.view==='preview'){
    history.back();
  }else{currentTab='workshop';renderTab();}
}
function makeWorkshopPreview(selected,pMap,ctx,requestedFormat=null){
  const draft=generatedHowWeBatDraftFromPhilosophy(buildScenarioDraft(selected));
  const formats=FORMATS.filter(([f])=>draft.formats?.[f]);
  if(!formats.length)return null;
  const ids=selected.map(r=>r.user_id).sort();
  return {clubId:club.id,userId:session.user.id,round:ctx.round_number,ids,responses:selected,pMap,draft,format:formats.some(([key])=>key===requestedFormat)?requestedFormat:formats[0][0],
    names:selected.map(r=>r.display_name||pMap.get(r.user_id)?.display_name||'Contributor'),
    key:[club.id,session.user.id,ctx.round_number,...ids].join(':'),expectedDraftUpdatedAt:ctx.draft_meta?.updated_at??howWeBatDraft?.updated_at??null,hasExistingDraft:!!(ctx.draft_meta||howWeBatDraft),choiceRequestId:null};
}
async function restoreWorkshopPreviewFromNavigation(route){
  if(workshopPreview?.key===route.previewKey&&workshopPreview?.round===workshopReviewContext?.round_number){
    if(workshopPreview.draft.formats?.[route.preview?.format])workshopPreview.format=route.preview.format;
    return;
  }
  workshopPreview=null;
  const clubId=club?.id,userId=session?.user?.id;
  const prefix=`${clubId}:${userId}:`;
  // Version .13 stored the same round and selected response IDs in its preview key.
  const legacy=typeof route.previewKey==='string'&&route.previewKey.startsWith(prefix)?route.previewKey.slice(prefix.length).split(':'):[];
  const selection=route.preview||{round:Number(legacy[0]),ids:legacy.slice(1)};
  if(!Array.isArray(selection.ids)||!selection.ids.length||!Number.isInteger(selection.round))return;
  const {data:context,error}=await supabase.rpc('get_workshop_review_context',{p_club_id:clubId});
  if(error)throw error;
  if(club?.id!==clubId||session?.user?.id!==userId)return;
  workshopReviewContext={...context,clubId,userId};
  if(context?.workshop_state)workshop={...workshop,...context.workshop_state};
  if(!context?.can_review||context.round_number!==selection.round)return;
  const ids=new Set(selection.ids);
  const selected=(context.responses||[]).filter(response=>ids.has(response.user_id));
  if(selected.length!==ids.size||!selected.some(response=>response.user_id===workshop?.philosophy_lead_user_id))return;
  const profiles=new Map(selected.map(response=>[response.user_id,{display_name:response.display_name}]));
  workshopPreview=makeWorkshopPreview(selected,profiles,workshopReviewContext,selection.format);
}
function openScenarioHowWeBatPreview(responses,pMap){
  const ctx=workshopReviewContext;
  if(!ctx?.can_review||ctx.clubId!==club?.id||ctx.userId!==session?.user?.id){alert('Return to Workshop and refresh the submitted responses.');return;}
  const selected=selectedScenarioResponses(responses);
  if(!selected.some(r=>r.user_id===workshop?.philosophy_lead_user_id)){alert('The Philosophy Lead needs to submit their response before comparisons can begin.');return;}
  const preview=makeWorkshopPreview(selected,pMap,ctx);
  if(!preview){alert('This combination does not currently produce a How We Bat preview.');return;}
  workshopPreview=preview;
  recordAppNavigation(clubNavigationRoute());
  currentTab='workshop_preview';return renderTab();
}
function workshopPreviewCurrent(ctx){
  return workshopPreview===ctx&&currentTab==='workshop_preview'&&club?.id===ctx.clubId&&session?.user?.id===ctx.userId;
}
function renderWorkshopPreview(){
  const ctx=workshopPreview;
  if(!ctx||!workshopPreviewCurrent(ctx)){currentTab='workshop';return renderTab();}
  clearTimeout(workshopDiscussionTimer);
  const formats=FORMATS.filter(([f])=>ctx.draft.formats?.[f]);
  const page=document.getElementById('page');
  page.innerHTML=`<style>
    .workshop-preview-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px}
    .workshop-preview-head .btn{min-height:44px}
    .workshop-preview .hwb-publication-preview{margin-top:12px}.workshop-preview .hwb-public-tabs{display:none}
    @media(max-width:600px){.workshop-preview .hwb-public-hero{padding:22px 18px}.workshop-preview .hwb-public-body{padding:20px 16px}}
  </style><div class="workshop-preview">
    <div class="workshop-preview-head"><button type="button" class="btn ghost" id="backWorkshopPreview">← Back to Workshop</button></div>
    <section class="card"><div class="section-label">Comparison preview · Workshop round ${Number(ctx.round)}</div><h1 style="font-size:clamp(23px,4vw,32px)">How We Bat: ${esc(naturalList(ctx.names))}</h1><p class="help">This preview shows how these submitted responses combine. Opening a preview does not choose it. Use the shared conversation on the Workshop screen to discuss all versions. Only the Philosophy Lead can confirm How We Bat.</p>
    <div class="btnrow">${formats.map(([f,label])=>`<button class="btn ${f===ctx.format?'secondary':'ghost'}" type="button" data-workshop-preview-format="${esc(f)}" aria-pressed="${f===ctx.format}">${esc(label)}</button>`).join('')}</div></section>
    <div id="workshopVersionContent">${renderHowWeBatLivePreview(ctx.draft,ctx.format,false)}</div>
    ${isPhilosophyLead()&&howWeBatDraft?.status!=='ready'?'<section class="card" style="margin-top:16px"><h2>Is this the club’s How We Bat?</h2><p class="help">Choosing this version completes the Workshop selection step. You can review the wording next, before confirming it for the season.</p><button type="button" class="btn secondary" id="usePreviewScenario">Choose this How We Bat →</button></section>':''}
    <div class="btnrow" style="margin-top:16px"><button type="button" class="btn ghost" id="bottomBackWorkshopPreview">← Back to comparisons and conversation</button></div></div>`;
  document.getElementById('backWorkshopPreview').onclick=closeWorkshopPreview;
  document.getElementById('bottomBackWorkshopPreview').onclick=closeWorkshopPreview;
  page.querySelectorAll('[data-workshop-preview-format]').forEach(btn=>btn.onclick=()=>{
    ctx.format=btn.dataset.workshopPreviewFormat;
    recordAppNavigation(clubNavigationRoute());
    page.querySelectorAll('[data-workshop-preview-format]').forEach(b=>{const active=b===btn;b.className=`btn ${active?'secondary':'ghost'}`;b.setAttribute('aria-pressed',String(active));});
    document.getElementById('workshopVersionContent').innerHTML=renderHowWeBatLivePreview(ctx.draft,ctx.format,false);
  });
  const choose=document.getElementById('usePreviewScenario');
  if(choose)choose.onclick=async()=>{
    if(ctx.choosing)return;
    ctx.choosing=true;choose.disabled=true;
    try{
      philosophyScenarioSelectedIds=new Set(ctx.ids);
      await applySelectedVoiceScenario(ctx.responses,ctx.pMap,ctx);
    }catch(error){if(workshopPreviewCurrent(ctx))alert(error.message||'The draft could not be created.');}
    finally{ctx.choosing=false;choose.disabled=false;}
  };
}
function workshopConversationCurrent(ctx){
  return workshopConversation===ctx&&club?.id===ctx.clubId&&session?.user?.id===ctx.userId&&
    (currentTab==='workshop'||(currentTab==='dashboard'&&clubHomeExpandedStage==='workshop'))&&!!document.getElementById('workshopCommentForm');
}
function workshopConversationArgs(ctx){return {p_club_id:ctx.clubId,p_round_number:ctx.round};}
function renderWorkshopConversation(ctx){
  return `<style>.workshop-discussion{margin-top:16px}.workshop-discussion .btn{min-height:44px}.workshop-comment{padding:14px 0;border-bottom:1px solid #dce2ee;overflow-wrap:anywhere}.workshop-comment p{white-space:pre-wrap;line-height:1.6;margin:8px 0}.workshop-comment time,.workshop-comment small{display:block;font-size:12px;color:#59657c;margin-top:4px}.workshop-discussion textarea{width:100%;box-sizing:border-box;min-height:110px}.workshop-discussion [role="status"]{display:block;margin:10px 0}</style>
    <section class="card workshop-discussion" aria-labelledby="workshopDiscussionHeading"><div class="section-label">One shared conversation</div><h2 id="workshopDiscussionHeading">Which version do we prefer?</h2><p class="help">Talk about all the How We Bat options here. Name the combination you mean, explain your preference and reply to each other. The Philosophy Lead makes the final choice.</p><button type="button" class="btn ghost" id="refreshWorkshopDiscussion">Refresh conversation</button><span id="workshopDiscussionLoadStatus" role="status">Loading conversation…</span><div id="workshopComments"></div>
    <form id="workshopCommentForm"><div class="field"><label for="workshopCommentBody">Add to the conversation</label><textarea id="workshopCommentBody" maxlength="2000" placeholder="Which version feels right for our club, and why?" ${ctx.sending?'disabled':''}>${esc(workshopCommentDrafts.get(ctx.key)?.body||'')}</textarea><small>Up to 2,000 characters. Shared with the Workshop review group; no email is sent.</small></div><button type="submit" class="btn secondary" id="postWorkshopComment" ${ctx.sending?'disabled':''}>Post comment</button><span role="status" id="workshopCommentStatus">${ctx.sending?'Posting…':''}</span></form></section>`;
}
function bindWorkshopConversation(ctx){
  document.getElementById('workshopCommentBody').oninput=e=>{
    const old=workshopCommentDrafts.get(ctx.key);
    workshopCommentDrafts.set(ctx.key,{body:e.target.value,id:old?.body===e.target.value?old.id:null});
  };
  document.getElementById('workshopCommentForm').onsubmit=async e=>{e.preventDefault();await postWorkshopComment(ctx);};
  document.getElementById('refreshWorkshopDiscussion').onclick=()=>refreshWorkshopConversation(ctx);
  return refreshWorkshopConversation(ctx);
}
async function refreshWorkshopConversation(ctx){
  clearTimeout(workshopDiscussionTimer);
  if(!workshopConversationCurrent(ctx)||ctx.loading)return;
  ctx.loading=true;
  try{
    if(document.hidden)return;
    const {data,error}=await supabase.rpc('get_workshop_conversation',workshopConversationArgs(ctx));
    if(!workshopConversationCurrent(ctx))return;
    if(error)throw error;
    const messages=data?.messages||[];
    document.getElementById('workshopComments').innerHTML=messages.length?messages.map(m=>`<article class="workshop-comment"><strong>${esc(m.author_name)}${m.author_user_id===ctx.userId?' · You':''}</strong><time datetime="${esc(m.created_at)}">${esc(new Date(m.created_at).toLocaleString())}</time>${m.original_version?`<small>Earlier comment on ${esc(m.original_version)}</small>`:''}<p>${esc(m.body)}</p></article>`).join(''):'<p class="help">No comments yet. Start the conversation about the versions above.</p>';
    document.getElementById('workshopDiscussionLoadStatus').textContent=`${Number(data?.total_count||0)>100?'Showing the latest 100 comments. ':''}Conversation up to date. Refreshes automatically while this screen is open.`;
  }catch(error){
    if(workshopConversationCurrent(ctx))document.getElementById('workshopDiscussionLoadStatus').textContent=`The conversation could not be refreshed. ${error.message||'Check your connection and try Refresh conversation.'}`;
  }finally{
    ctx.loading=false;
    if(workshopConversationCurrent(ctx))workshopDiscussionTimer=setTimeout(()=>refreshWorkshopConversation(ctx),15000);
  }
}
async function postWorkshopComment(ctx){
  if(!workshopConversationCurrent(ctx)||ctx.sending)return;
  const input=document.getElementById('workshopCommentBody'),status=document.getElementById('workshopCommentStatus');
  const body=input.value.trim();
  if(!body||body.length>2000){status.textContent='Write a comment of 1 to 2,000 characters.';return;}
  const previous=workshopCommentDrafts.get(ctx.key);
  const pending={body,id:previous?.body?.trim()===body&&previous.id?previous.id:crypto.randomUUID()};
  workshopCommentDrafts.set(ctx.key,pending);
  ctx.sending=true;document.getElementById('postWorkshopComment').disabled=true;input.disabled=true;status.textContent='Posting…';
  try{
    const {error}=await supabase.rpc('post_workshop_conversation',{...workshopConversationArgs(ctx),p_message_id:pending.id,p_body:body});
    if(error)throw error;
    if(workshopCommentDrafts.get(ctx.key)===pending)workshopCommentDrafts.delete(ctx.key);
    if(!workshopConversationCurrent(ctx))return;
    document.getElementById('workshopCommentBody').value='';document.getElementById('workshopCommentStatus').textContent='Comment posted.';
    await refreshWorkshopConversation(ctx);
  }catch(error){if(workshopConversationCurrent(ctx))document.getElementById('workshopCommentStatus').textContent=`We could not confirm your comment was posted. Your text is kept; retrying will not post it twice. ${error.message||''}`;}
  finally{ctx.sending=false;if(workshopConversationCurrent(ctx)){document.getElementById('postWorkshopComment').disabled=false;document.getElementById('workshopCommentBody').disabled=false;}}
}

function renderDetailedSynthesisBody(responses,pMap){
  const syn=buildSynthesis(responses);
  return `<div class="scenario-detail-body">
    <div class="help">This is the underlying response analysis. It is here for anyone who wants to inspect the mechanics; it is not intended to be the main decision-making view.</div>
    <h3>Club identity</h3>
    <div class="consensus-grid">${syn.identity.filter(x=>x.ratio>=.35).map(x=>`
      <div class="consensus-item ${x.cls}"><div><strong>${esc(x.itemLabel)}</strong><small>${x.count} of ${syn.n} selected this</small></div><span>${esc(x.consensusLabel)}</span></div>`).join('')}</div>
    <h3>What belongs in the batting system</h3>
    <div class="consensus-grid">${syn.dims.filter(x=>x.ratio>=.35).map(x=>`
      <div class="consensus-item ${x.cls}"><div><strong>${esc(x.itemLabel)}</strong><small>${x.count} of ${syn.n} selected this</small></div><span>${esc(x.consensusLabel)}</span></div>`).join('')}</div>
    <h3>Format emphasis</h3>
    <div class="synthesis-table-wrap"><table class="synthesis-table"><thead><tr><th>Dimension</th><th>Format</th><th>Typical emphasis</th><th>Spread</th><th></th></tr></thead><tbody>${syn.weightRows.map(x=>`
      <tr class="${x.cls}"><td>${esc(x.dimension)}</td><td>${esc(x.formatLabel)}</td><td>${esc(WEIGHT_LABELS[x.median])}</td><td>${esc(WEIGHT_LABELS[x.min])}${x.min!==x.max?` → ${esc(WEIGHT_LABELS[x.max])}`:''}</td><td><span class="consensus-badge ${x.cls}">${esc(x.consensusLabel)}</span></td></tr>`).join('')}</tbody></table></div>
    ${syn.flags.length?`<h3>Discussion prompts</h3><div class="discussion-list">${syn.flags.map(x=>`<div class="discussion-flag">⚑ ${esc(x)}</div>`).join('')}</div>`:''}
    ${renderSourceComments(responses,pMap)}
  </div>`;
}

function renderVoiceScenarioExplorer(responses,pMap,allSubmitted,meta=null){
  const leadId=workshop?.philosophy_lead_user_id;
  const leadResponse=(responses||[]).find(r=>r.user_id===leadId)||null;
  if(!leadResponse)return `<section class="card workshop-stage-card" style="margin-top:16px"><div class="section-label">3 · Compare How We Bat options</div><h2>The Philosophy Lead needs to submit their response.</h2><div class="help">The submitted response provides the starting point for How We Bat.</div></section>`;

  const selected=selectedScenarioResponses(responses);
  const safeSelected=selected.length?selected:[leadResponse];
  const scenarioPhilosophy=buildScenarioDraft(safeSelected);
  const baselinePhilosophy=buildScenarioDraft([leadResponse]);
  const scenarioHwb=generatedHowWeBatDraftFromPhilosophy(scenarioPhilosophy);
  const baselineHwb=generatedHowWeBatDraftFromPhilosophy(baselinePhilosophy);
  const changes=scenarioHowWeBatChanges(baselineHwb,scenarioHwb);
  const otherResponses=(responses||[]).filter(r=>r.user_id!==leadResponse.user_id);
  const displayName=r=>r.display_name||pMap.get(r.user_id)?.display_name||'Contributor';
  const shortName=r=>(displayName(r)||'Contributor').trim().split(/\s+/)[0]||'Contributor';
  const leadShort=shortName(leadResponse);

  // Scenario buttons replace the old duplicate checkbox + preset controls.
  // With a small contributor group, show every combination so the Lead can
  // visually compare David, David + Bryce, David + Mitch, David + Bryce + Mitch, etc.
  const presets=[{label:`${leadShort} only`,ids:[leadResponse.user_id]}];
  if(otherResponses.length<=3){
    const count=1<<otherResponses.length;
    for(let mask=1;mask<count;mask++){
      const chosen=otherResponses.filter((_,i)=>mask&(1<<i));
      presets.push({
        label:[leadShort,...chosen.map(shortName)].join(' + '),
        ids:[leadResponse.user_id,...chosen.map(r=>r.user_id)]
      });
    }
  }else{
    for(const r of otherResponses){
      presets.push({label:`${leadShort} + ${shortName(r)}`,ids:[leadResponse.user_id,r.user_id]});
    }
    presets.push({label:`${leadShort} + all voices`,ids:[leadResponse.user_id,...otherResponses.map(r=>r.user_id)]});
  }

  const selectedIds=new Set(safeSelected.map(r=>r.user_id));
  const sameIds=ids=>ids.length===selectedIds.size&&ids.every(id=>selectedIds.has(id));
  const currentLabel=(presets.find(p=>sameIds(p.ids))?.label)||safeSelected.map(shortName).join(' + ');
  const baselineOnly=safeSelected.length===1;
  const hwbLocked=howWeBatDraft?.status==='ready';

  return `<section class="card synthesis workshop-stage-card" style="margin-top:16px">
    <div class="section-label">3 · Compare How We Bat options</div>
    <h2>Which How We Bat feels most like the club?</h2>${meta?.progressHtml||''}
    <div class="help">Choose a combination to preview. Discuss all versions together in the conversation below. Everyone who has submitted can explore these options. ${hwbLocked?'These previews do not change the locked How We Bat.':isPhilosophyLead()?'When you have decided, open that preview and select “Choose this How We Bat”.':'The Philosophy Lead chooses which option to use for the club.'}</div>

    <div class="btnrow" style="margin-top:16px">
      ${presets.map(p=>`<button class="btn ${sameIds(p.ids)?'secondary':'ghost'}" aria-pressed="${sameIds(p.ids)}" data-scenario-preset="${esc(p.ids.join(','))}">${esc(p.label)}</button>`).join('')}
    </div>

    ${otherResponses.length>3?`<fieldset style="margin-top:16px;border:1px solid #dce2ee;border-radius:10px;padding:16px"><legend>Or choose any combination</legend><p class="help">${esc(displayName(leadResponse))} is included as the Philosophy Lead.</p>${otherResponses.map(r=>`<label style="display:flex;gap:10px;align-items:center;min-height:44px"><input type="checkbox" data-scenario-voice="${esc(r.user_id)}" ${selectedIds.has(r.user_id)?'checked':''}>${esc(displayName(r))}</label>`).join('')}</fieldset>`:''}
    ${hwbLocked?`<div class="help" style="margin-top:10px">🔒 How We Bat is locked. These comparisons remain available for reference.</div>`:(hasChosenWorkshopApproach()?`<div class="help" style="margin-top:10px">A version has been selected. The Philosophy Lead can choose another until How We Bat is confirmed.</div>`:'')}

    <div class="btnrow" style="margin-top:18px">
      <button class="btn secondary" id="openScenarioHwbPreview">Preview this version →</button><span class="help">${esc(currentLabel)}</span>
      ${!baselineOnly?`<button class="btn ghost" id="showScenarioChanges">What changed?</button>`:''}

    </div>

    ${!baselineOnly?`<dialog id="scenarioChangesDialog" style="max-width:620px;width:calc(100% - 32px);border:0;border-radius:16px;padding:0;box-shadow:0 20px 60px rgba(20,32,80,.25)">
      <div style="padding:22px 24px">
        <div class="section-label">Optional detail</div>
        <h2 style="margin:4px 0 10px">What changed from ${esc(leadShort)} only?</h2>
        ${changes.length
          ?`<ul style="margin:0;padding-left:22px">${changes.slice(0,6).map(x=>`<li style="margin:7px 0">${esc(x)}</li>`).join('')}</ul>`
          :'<div class="help">The player-facing How We Bat stays visually the same. These voices reinforce the existing message rather than redirecting it.</div>'}
        <div class="btnrow" style="margin-top:18px"><button class="btn secondary" id="closeScenarioChanges">Close</button></div>
      </div>
    </dialog>`:''}

    <details class="source-responses" style="margin-top:18px">
      <summary>Detailed response data</summary>
      ${renderDetailedSynthesisBody(safeSelected,pMap)}
      ${renderSubmittedContributionReview(safeSelected,pMap)}
    </details>
  </section>`;
}

async function applySelectedVoiceScenario(responses,pMap,preview=workshopPreview){
  if(!isPhilosophyLead()){alert('Only the Philosophy Lead can choose the club’s How We Bat.');return;}
  const targetClubId=club.id,targetUserId=session.user.id;
  const isCurrent=()=>club?.id===targetClubId&&session?.user?.id===targetUserId;
  if(!preview||!workshopPreviewCurrent(preview)){alert('Open a How We Bat preview before choosing it.');return;}
  if(!confirmLeaveWorkshopSetup())return;
  const selected=responses.filter(r=>preview.ids.includes(r.user_id));
  if(!selected.some(r=>r.user_id===workshop?.philosophy_lead_user_id)){alert('The Philosophy Lead original must be included.');return;}
  if(howWeBatDraft?.status==='ready'){
    alert('How We Bat is confirmed for this season. Start a new Workshop round to replace it.');return;
  }
  if(preview.hasExistingDraft&&!preview.choiceRequestId&&!confirm('Choose this How We Bat for the club?\n\nThis replaces the existing editable draft with this version. All original contributions and conversation comments are kept.'))return;
  const draft=buildScenarioDraft(selected);
  if(!preview.choiceRequestId)preview.choiceRequestId=crypto.randomUUID();
  let saved=false;
  try{
    const {error}=await supabase.rpc('choose_workshop_how_we_bat',{
      p_club_id:targetClubId,p_round_number:preview.round,p_response_user_ids:preview.ids,
      p_philosophy:draft,p_how_we_bat:preview.draft,
      p_response_versions:Object.fromEntries(selected.map(r=>[r.user_id,r.submitted_at||null])),
      p_expected_draft_updated_at:preview.expectedDraftUpdatedAt,p_request_id:preview.choiceRequestId
    });
    if(error)throw error;
    saved=true;
    if(!isCurrent())return;
    await loadData();
    if(!isCurrent())return;
    currentTab='howwebat';renderShell();
  }catch(error){
    if(isCurrent())alert(saved?'Your How We Bat choice was saved, but the page could not refresh. Refresh to continue; you do not need to choose again.':`The choice could not be confirmed. Return to Workshop and check before trying again. ${error.message||''}`);
  }
}

function renderSynthesis(responses,pMap,allSubmitted,meta=null){
  return renderVoiceScenarioExplorer(responses,pMap,allSubmitted,meta);
}


function renderSourceComments(responses,pMap){
  const items=[];
  for(const r of responses){
    const name=r.display_name||pMap.get(r.user_id)?.display_name||'Contributor';
    if(r.identity_note)items.push(`<div class="source-comment"><strong>${esc(name)} · Club Identity</strong><p>${esc(r.identity_note)}</p></div>`);
    const notes=r.dimension_notes||{};
    for(const [k,note] of Object.entries(notes)){
      if(!note)continue;
      const label=dimensions.find(d=>d.dimension_key===k)?.label||k;
      items.push(`<div class="source-comment"><strong>${esc(name)} · ${esc(label)}</strong><p>${esc(note)}</p></div>`);
    }
  }
  if(!items.length)return '';
  return `<details class="source-responses"><summary>View source comments</summary><div class="source-comments">${items.join('')}</div></details>`;
}

function renderLateResponseDetail(response){
  const r=response||{};
  const identities=(r.identity_values||[])
    .map(k=>IDENTITY_OPTIONS.find(([key])=>key===k)?.[1]||k);

  const dims=(r.selected_dimensions||[]).map(k=>{
    const label=dimensions.find(d=>d.dimension_key===k)?.label||k;
    const weights=FORMATS
      .filter(([f])=>r.formats_enabled?.[f]!==false)
      .map(([f,fl])=>{
        const raw=Number(r.format_weights?.[`${k}:${f}`]);
        return Number.isFinite(raw)?`${fl}: ${WEIGHT_LABELS[raw]||raw}`:null;
      })
      .filter(Boolean)
      .join(' · ');
    const note=r.dimension_notes?.[k];
    return `<div class="late-detail-dimension">
      <strong>${esc(label)}</strong>
      ${weights?`<span>${esc(weights)}</span>`:''}
      ${note?`<p>${esc(note)}</p>`:''}
    </div>`;
  }).join('');

  const formats=FORMATS
    .filter(([f])=>r.formats_enabled?.[f]!==false)
    .map(([,fl])=>fl);

  return `<div class="late-response-detail-grid">
    <div>
      <h3>Club identity</h3>
      <p>${identities.length?esc(identities.join(' · ')):'No identity options selected.'}</p>
      ${r.identity_note?`<div class="source-comment"><p>${esc(r.identity_note)}</p></div>`:''}
    </div>
    <div>
      <h3>Formats</h3>
      <p>${formats.length?esc(formats.join(' · ')):'No formats enabled.'}</p>
    </div>
  </div>
  <div class="section-label" style="margin-top:12px">Dimensions + emphasis</div>
  <div class="late-detail-dimensions">${dims||'<div class="help">No dimensions selected.</div>'}</div>`;
}

function renderMySubmittedPhilosophyResponse(response){
  currentTab='submitted_response';
  recordAppNavigation(clubNavigationRoute());
  workshopLastRoute=`${club.id}:submitted_response`;
  document.getElementById('page').innerHTML=`${workshopReturnHtml()}<section class="card">
    <div class="section-label">Your submitted response</div>
    <h2>Review your philosophy contribution</h2>
    ${response
      ?`<div class="help">Your response is submitted and locked. Here are your identity choices, notes and priorities for each format.</div>${renderLateResponseDetail(response)}`
      :'<div class="notice">Your response could not be loaded. Return to Batting Philosophy Workshop and refresh the page to try again.</div>'}
    <div class="btnrow" style="margin-top:16px"><button class="btn secondary" id="backWorkshop">Return to Batting Philosophy Workshop</button></div>
  </section>`;
  document.getElementById('backWorkshop').onclick=()=>{currentTab='workshop';renderTab();};
  bindWorkshopReturn();
  window.scrollTo?.({top:0,left:0,behavior:'instant'});
}

function renderLatePhilosophyResponses(actions,pMap){
  const pending=(actions||[]).filter(a=>a.status==='pending');
  const actioned=(actions||[]).filter(a=>a.status!=='pending');

  if(!pending.length){
    if(!actioned.length)return '';
    return `<details class="card late-history-card" style="margin-top:16px">
      <summary>Late-response history</summary>
      <div class="late-contribution-list">${actioned.map(a=>{
        const name=pMap.get(a.user_id)?.display_name||'Contributor';
        return `<div class="late-contribution actioned">
          <div><strong>${esc(name)}</strong><span>${a.status==='incorporated'?'Incorporated into the current synthesis and working draft':'Reviewed · not incorporated'} · ${new Date(a.submitted_at).toLocaleString()}</span></div>
        </div>`;
      }).join('')}</div>
    </details>`;
  }

  return `<section class="card late-contributions-card" style="margin-top:16px">
    <div class="section-label">New contribution</div>
    <h2>Response received after the draft started</h2>
    <div class="help">Review it here, before the synthesis below. It does not alter the current synthesis or working draft unless you explicitly incorporate it.</div>

    <div class="late-contribution-list">${pending.map(a=>{
      const name=pMap.get(a.user_id)?.display_name||'Contributor';
      return `<div class="late-contribution pending">
        <div class="late-contribution-head">
          <div>
            <strong>${esc(name)}</strong>
            <span>Submitted ${new Date(a.submitted_at).toLocaleString()}${a.reviewed_at?' · reviewed':''}</span>
          </div>
          <span class="pending">NEW RESPONSE</span>
        </div>
        <div class="late-contribution-actions">
          <button class="btn ghost" data-review-late="${a.id}">Review contribution</button>
          <button class="btn secondary" data-incorporate-late="${a.id}">Include in synthesis + rebuild draft</button>
          <button class="btn ghost" data-ignore-late="${a.id}">Do not incorporate</button>
        </div>
        <div class="late-response-detail" id="late-detail-${a.id}" style="display:none">
          ${renderLateResponseDetail(a.response_snapshot)}
        </div>
      </div>`;
    }).join('')}</div>

    ${actioned.length?`<details class="late-history">
      <summary>Previously actioned late responses</summary>
      <div class="late-contribution-list">${actioned.map(a=>{
        const name=pMap.get(a.user_id)?.display_name||'Contributor';
        return `<div class="late-contribution actioned">
          <div><strong>${esc(name)}</strong><span>${a.status==='incorporated'?'Incorporated into the current synthesis and working draft':'Reviewed · not incorporated'} · ${new Date(a.submitted_at).toLocaleString()}</span></div>
        </div>`;
      }).join('')}</div>
    </details>`:''}
  </section>`;
}


async function discardFinalDraftAndRestart(){
  const ok=confirm(
    `Discard the current UNPUBLISHED final philosophy draft and How We Bat draft?\n\n`+
    `What WILL be discarded:\n`+
    `• edits made to the current final philosophy draft\n`+
    `• the current unpublished How We Bat draft\n\n`+
    `What WILL be kept:\n`+
    `• every contributor's submitted workshop response\n`+
    `• late responses already submitted\n`+
    `• every published Philosophy / How We Bat version\n\n`+
    `Your own original independent response will be restored from the frozen snapshot. `+
    `You can then create a fresh synthesis using all responses currently submitted.\n\n`+
    `This cannot restore manual edits made only in the discarded draft.`
  );
  if(!ok)return;

  const btn=document.getElementById('discardFinalDraft');
  if(btn){
    btn.disabled=true;
    btn.textContent='Discarding…';
  }

  const {error}=await supabase.rpc('discard_unpublished_philosophy_draft',{
    p_club_id:club.id
  });

  if(error){
    alert(error.message);
    if(btn){
      btn.disabled=false;
      btn.textContent='Discard draft & restart synthesis';
    }
    return;
  }

  await loadData();
  currentTab='workshop';
  renderShell();
}

async function beginFinalDraftFromSynthesis(){
  // Use the same authoritative server-side response set that powers the visible synthesis.
  // This avoids a final draft being built from a different set of rows because of client RLS.
  const {data:source,error}=await supabase.rpc('get_philosophy_synthesis_source',{
    p_club_id:club.id
  });

  if(error){alert(error.message);return;}
  const responses=Array.isArray(source?.responses)?source.responses:[];
  const mismatchCount=Number(source?.mismatch_count||0);

  if(mismatchCount>0){
    alert(
      `The workshop has ${mismatchCount} contributor record${mismatchCount===1?'':'s'} whose submission status does not match the stored response.\n\n`+
      `Club Batting will not create a final draft until that inconsistency is resolved, because doing so could silently leave out a contributor.`
    );
    return;
  }

  if(!responses.length){alert('No submitted responses are available to the synthesis yet.');return;}

  const draft=buildConsensusDraft(responses);
  const ok=confirm(
    `Create the final working draft using the ${responses.length} response${responses.length===1?'':'s'} submitted right now?\n\n`+
    `This creates a snapshot. Any response submitted later will NOT change the draft unless you explicitly choose to incorporate it.`
  );
  if(!ok)return;

  const {error:e}=await supabase.rpc('begin_final_philosophy_draft',{
    p_club_id:club.id,
    p_identity_values:draft.identity_values,
    p_identity_note:draft.identity_note,
    p_formats_enabled:draft.formats_enabled,
    p_selected_dimensions:draft.selected_dimensions,
    p_dimension_notes:draft.dimension_notes,
    p_format_weights:draft.format_weights
  });
  if(e){alert(e.message);return;}

  await loadData();
  currentTab='identity';
  renderShell();
}

async function publishPhilosophy(){
  if(!isPhilosophyLead())return;
  const progress=clubSetupProgress();
  if(!progress.workshopReady||!progress.howWeBatReady||!progress.structureReady||playerPlanStructureDirty){
    alert('Complete the Batting Philosophy Workshop, How We Bat and Player Plan questions before publication.');return;
  }
  if(!progress.detailsReady){
    alert('Ask your Club Admin to review the club look from Club Home before publication. They can keep the current look.');return;
  }
  const firstPublish=philosophyVersions.length===0;

  const ok=confirm(firstPublish
    ?`Publish How We Bat and open Player Plans for ${club.name}?\n\n`+
      `Players will be able to read How We Bat and start answering their Player Plan questions. An email will be queued automatically for everyone already registered as a player, including those who also coach or captain.\n\n`+
      `Publish and notify players?`
    :`Publish the updated How We Bat and Player Plan questions for ${club.name}?\n\n`+
      `This replaces the currently published club system. An email will be queued automatically for everyone already registered as a player, including those who also coach or captain.\n\n`+
      `Publish and notify players?`);
  if(!ok)return;

  const publishButton=document.getElementById('publishClubSystem');
  const publishStatus=document.getElementById('publishClubSystemStatus');

  if(publishButton){
    publishButton.disabled=true;
    publishButton.textContent='Publishing…';
  }
  if(publishStatus)publishStatus.textContent='Finalising the release…';

  // The Lead's independent response was converted into the editable final draft
  // when synthesis began. If that working draft has not yet been re-submitted,
  // finalise it here rather than forcing the Lead backwards through earlier pages.
  if(myContributor?.status!=='submitted'){
    const {error:submitError}=await supabase.rpc('submit_my_philosophy_response',{
      p_club_id:club.id
    });

    if(submitError){
      if(publishButton){
        publishButton.disabled=false;
        publishButton.textContent='Publish & notify players';
      }
      if(publishStatus)publishStatus.textContent=submitError.message;
      return;
    }
  }

  const {data,error}=await supabase.rpc('publish_philosophy',{
    p_club_id:club.id,
    p_notify_players:true
  });

  if(error){
    if(publishButton){
      publishButton.disabled=false;
      publishButton.textContent='Publish & notify players';
    }
    if(publishStatus)publishStatus.textContent=error.message;
    return;
  }

  alert(`Club Batting System v${data} is live. Players can read How We Bat and open My Player Plan. Notification emails are queued for registered players.`);

  await loadData();
  currentTab='howwebat';
  renderShell();
}

