let myInningsState={scope:'',season:null,format:'',openId:null,editId:null};
let myInningsCache=null;
let myInningsSequence=0;
const preparationScoringState=new WeakMap();
function ensureMyInningsState(){
  const scope=`${club?.id||''}:${session?.user?.id||''}`;
  if(myInningsState.scope!==scope){myInningsState={scope,season:null,format:'',openId:null,editId:null};myInningsCache=null;}
  return myInningsState;
}
function inningsSeason(date){
  const parts=String(date||'').match(/^(\d{4})-(\d{2})-\d{2}$/);
  return parts?String(Number(parts[1])-(Number(parts[2])<7?1:0)):null;
}
function inningsSeasonLabel(year){return `${year}/${String(Number(year)+1).slice(-2)}`;}
function inningsInView(matches,state){
  return matches.filter(m=>(state.season==='all'||inningsSeason(m.match_date)===state.season)&&(!state.format||m.format_key===state.format))
    .sort((a,b)=>String(b.match_date).localeCompare(String(a.match_date))||String(b.created_at).localeCompare(String(a.created_at))||String(a.id).localeCompare(String(b.id)));
}
function inningsVideoLink(video,label='Watch ↗'){
  if(!video?.url)return '';
  let url;try{url=normaliseCoachingYouTubeUrl(video.url);}catch{return '';}
  return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(label==='Watch ↗'?'Watch innings video on YouTube':label)}">${esc(label)}</a>`;
}
function renderInningsVideo(video){
  const link=inningsVideoLink(video,'Open innings video on YouTube ↗');
  return link?`<div class="notice compact"><strong>Player’s innings video</strong>${video.note?`<p>${esc(video.note)}</p>`:''}<p>${link}</p></div>`:'';
}
const MATCH_PREPARATION_FIELDER_TAGS={quick_pickup:'Quick pickup',strong_arm:'Strong arm',accurate_throw:'Accurate throw',safe_hands:'Safe hands',quick_across_ground:'Quick across the ground'};
const MATCH_PREPARATION_DECISIONS={used:'Used my approach',adapted:'Adapted to the situation',away:'Went away from it',not_faced:'Didn’t face this bowler'};
function matchPreparationStatus(status){return ({planned:'Upcoming',did_not_bat:'Did not bat',cancelled:'Match cancelled',played:'Played'})[status]||'Upcoming';}
function preparationLinkedMatch(record){return record?.match_id||record?.resolved_match_id||null;}
// Opposition is descriptive. The server resolves ownership and ambiguity; this
// same-day suggestion must never use spelling to hide an existing innings.
function sameInningsSlot(a,b){
  return !!a&&!!b&&a.match_date===b.match_date&&a.format_key===b.format_key&&Number(a.innings_number||1)===Number(b.innings_number||1);
}
function inningsCandidateLabel(match){
  return [match.opposition||'Opposition not recorded','innings '+Number(match.innings_number||1),match.participation_status==='did_not_bat'?'Did not bat':match.score_text||'Score not recorded'].join(' · ');
}
function bindCompletePlayerPlanButtons(host){
  host?.querySelectorAll('[data-complete-player-plan]').forEach(button=>button.onclick=async()=>{
    if(!isPlayerUser()||!confirmLeaveFeedbackEntry()||!await saveClubEditsBeforeNavigation())return;
    builderSection='core';currentTab='myplan';await renderTab();
  });
}
function mergeMyInnings(matches,preparations){
  const byMatch=new Map(preparations.filter(p=>preparationLinkedMatch(p)).map(p=>[preparationLinkedMatch(p),p]));
  const rows=matches.map(m=>({...m,preparation_record:byMatch.get(m.id)||null}));
  const actualIds=new Set(matches.map(m=>m.id));
  for(const p of preparations)if(!preparationLinkedMatch(p)||!actualIds.has(preparationLinkedMatch(p)))rows.push({...p,id:preparationLinkedMatch(p)||p.id,preparation_only:true,missing_match:!!preparationLinkedMatch(p),preparation_record:p});
  return rows;
}
