    const submitted=pending.values.rows.map(row=>row.player_id),confirmed=data?.saved?.map(row=>row.player_id);
    const requestedRemoved=pending.values.remove_player_ids||[],confirmedRemoved=(data?.removed||[]).map(r=>typeof r==='string'?r:r.player_id);if(requestedRemoved.some(id=>!confirmedRemoved.includes(id)))throw new Error('The save response did not confirm the removed players.');
