async function loadTeamReviewHistory(){const s=ensureTeamReviewState(),scope=s.scope,sequence=++teamReviewSequence;if(!canUseTeamReview())return;const f=s.historyFilters,filters={group_id:['','__unassigned__'].includes(f.group_id)?null:f.group_id,group_scope:f.group_id==='__unassigned__'?'unassigned':f.group_id?'group':null,date_from:f.match_date||null,date_to:f.match_date||null,format_key:f.format_key||null,player_query:f.player_query||null};s.loading=true;s.message='Loading saved match reviews…';renderTeamReviewHistoryContent();try{const {data,error}=await supabase.rpc('get_saved_team_reviews',{p_club_id:club.id,p_filters:filters});if(error)throw error;if(scope!==ensureTeamReviewState().scope||sequence!==teamReviewSequence||currentTab!=='team_review'||s.view!=='history')return;if(!Array.isArray(data?.reviews)||!Array.isArray(data?.groups))throw new Error('Saved match reviews could not be verified.');s.history=data.reviews;s.groups=data.groups;s.message='';}catch(error){if(scope!==ensureTeamReviewState().scope||sequence!==teamReviewSequence||currentTab!=='team_review')return;s.history=null;s.message=error?.message||'Could not load saved match reviews.';}s.loading=false;renderTeamReviewHistoryContent();recordAppNavigation(clubNavigationRoute());}
function renderTeamReviewHistoryContent(){const page=document.getElementById('page'),s=ensureTeamReviewState();if(!page||currentTab!=='team_review'||s.view!=='history')return;const f=s.historyFilters,locked=teamReviewControlsLocked(),preview=s.deletePreview;page.innerHTML=`${teamReviewStyles()}<section class="card"><div class="team-review-heading"><div><div class="section-label">Captain & coach workspace</div><h1>Saved match reviews</h1><p>Find a saved team entry. Each player’s innings remains shared with their other observations and reflection.</p></div><div class="btnrow"><button type="button" class="btn ghost" id="backTeamReview" ${locked?'disabled':''}>Back to entry</button><button type="button" class="btn secondary" id="newTeamReview" ${locked?'disabled':''}>New match review</button></div></div><div class="team-review-history-filters"><div class="field"><label for="savedReviewGrade">Grade / Playing Group</label><select id="savedReviewGrade" ${locked?'disabled':''}><option value="">All grades</option><option value="__unassigned__" ${f.group_id==='__unassigned__'?'selected':''}>Currently unassigned</option>${(s.groups||[]).map(g=>`<option value="${esc(g.id)}" ${g.id===f.group_id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label for="savedReviewDate">Match date</label><input type="date" id="savedReviewDate" value="${esc(f.match_date)}" ${locked?'disabled':''}></div><div class="field"><label for="savedReviewFormat">Format</label><select id="savedReviewFormat" ${locked?'disabled':''}><option value="">All formats</option>${FORMATS.map(([key,label])=>`<option value="${key}" ${key===f.format_key?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div class="field"><label for="savedReviewPlayer">Player name</label><input type="search" id="savedReviewPlayer" maxlength="100" value="${esc(f.player_query)}" placeholder="Find a player’s match review" ${locked?'disabled':''}></div></div><div class="btnrow"><button type="button" class="btn secondary" id="searchSavedReviews" ${locked?'disabled':''}>Search saved reviews</button><button type="button" class="btn ghost" id="resetSavedReviewFilters" ${locked?'disabled':''}>Clear filters</button></div><p id="teamReviewHistoryStatus" role="status">${esc(s.message)}</p></section>${preview?`<section class="card team-review-delete-preview"><h2>Delete this saved match review?</h2><p><strong>${esc(preview.review?.opposition||'Match')} · ${esc(formatDateShort(preview.review?.match_date))}</strong> · ${esc(teamReviewSavedGroupName(preview.review))} · ${esc(preview.review?.author_name||'Club member')}</p><p>This will remove ${Number(preview.remove_feedback_count)||0} team-review observations and ${Number(preview.remove_innings_count)||0} otherwise empty innings. ${Number(preview.preserved_innings_count)||0} innings will remain because they contain other information.</p><ul>${(preview.rows||[]).map(row=>`<li><strong>${esc(row.name||'Player')}</strong>: ${row.remove_innings?'remove empty innings':row.preserved_reason?esc(row.preserved_reason):'keep the shared innings'}${row.remove_feedback?' · remove this review’s assessment':''}</li>`).join('')}</ul><p class="help">Players’ preparation, reflections, official results and other observers’ contributions are preserved. Deletion stops if this review changes after this preview.</p><div class="btnrow"><button type="button" class="btn danger" id="confirmDeleteTeamReview" ${s.saving?'disabled':''}>${s.deletePending?'Retry deletion':'Delete this match review'}</button><button type="button" class="btn ghost" id="cancelDeleteTeamReview" ${s.deletePending||s.saving?'disabled':''}>Keep review</button></div></section>`:''}<section class="card">${s.history?.length?`<div class="team-review-history-wrap"><table class="team-review-history-table"><caption class="sr-only">Saved match reviews</caption><thead><tr><th scope="col">Match</th><th scope="col">Grade</th><th scope="col">Recorded by</th><th scope="col">Players</th><th scope="col">Actions</th></tr></thead><tbody>${matchReviewGroupedHistory(s.history).map(review=>`<tr><td><strong>${esc(formatDateShort(review.match_date))} · ${esc(review.opposition)}</strong><br><span class="help">${esc(formatLabel(review.format_key))}</span><br>${matchReviewHistorySelector(review)}</td><td>${esc(teamReviewSavedGroupName(review))}</td><td>${esc(review.author_name||'Club member')}</td><td>${Number(review.player_count)||0}<br><span class="help">${(review.player_names||[]).map(esc).join(', ')}</span></td><td><div class="team-review-history-actions"><button type="button" class="btn secondary" data-team-review-view="${esc(review.id)}" ${locked?'disabled':''}>View${review.can_edit?' / edit':''}</button>${review.can_delete?`<button type="button" class="btn ghost" data-team-review-delete="${esc(review.id)}" ${locked?'disabled':''}>Delete</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:`<p>${s.loading?'Loading saved reviews…':s.history?'No saved match reviews match these filters.':'Saved reviews are not available. Try Search saved reviews again.'}</p>`}</section>`;
const capture=()=>{s.historyFilters={group_id:document.getElementById('savedReviewGrade').value,match_date:document.getElementById('savedReviewDate').value,format_key:document.getElementById('savedReviewFormat').value,player_query:document.getElementById('savedReviewPlayer').value.trim()};};document.getElementById('searchSavedReviews').onclick=()=>{capture();s.deletePreview=null;return loadTeamReviewHistory();};for(const id of ['savedReviewGrade','savedReviewDate','savedReviewFormat'])document.getElementById(id).onchange=()=>{capture();s.deletePreview=null;return loadTeamReviewHistory();};document.getElementById('savedReviewPlayer').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();capture();s.deletePreview=null;loadTeamReviewHistory();}};document.getElementById('resetSavedReviewFilters').onclick=()=>{s.historyFilters={group_id:'',match_date:'',format_key:'',player_query:''};s.deletePreview=null;return loadTeamReviewHistory();};document.getElementById('backTeamReview').onclick=()=>{s.view='entry';s.deletePreview=null;renderTeamReviewContent();recordAppNavigation(clubNavigationRoute());};document.getElementById('newTeamReview').onclick=clearTeamReviewEntry;page.querySelectorAll('[data-team-review-view]').forEach(b=>b.onclick=()=>loadSavedTeamReview(b.dataset.teamReviewView));page.querySelectorAll('[data-team-review-delete]').forEach(b=>b.onclick=()=>previewTeamReviewDelete(b.dataset.teamReviewDelete));document.getElementById('cancelDeleteTeamReview')?.addEventListener('click',()=>{s.deletePreview=null;renderTeamReviewHistoryContent();});document.getElementById('confirmDeleteTeamReview')?.addEventListener('click',deleteSavedTeamReview);bindMatchReviewHistory();
}
async function loadSavedTeamReview(id,{restoring=false}={}){const s=ensureTeamReviewState(),scope=s.scope,sequence=++teamReviewSequence;if(teamReviewSavePending())return;if(!restoring&&teamReviewHasUnsavedChanges()&&!confirm('Discard your unsaved entry choices and open this saved review?'))return;s.loading=true;s.message='Loading saved review…';renderTeamReviewContent();try{const {data,error}=await supabase.rpc('get_team_review_session',{p_club_id:club.id,p_review_id:id});if(error)throw error;if(scope!==ensureTeamReviewState().scope||sequence!==teamReviewSequence||currentTab!=='team_review')return;if(!data?.review?.id||!Array.isArray(data.players)||!Array.isArray(data.groups))throw new Error('The saved review could not be verified.');const r=data.review;if(!restoring){s.drafts={};s.removed=[];s.importer=null;s.siblingReviews=[];}Object.assign(s,{match_date:r.match_date,format_key:r.format_key,opposition:r.opposition,innings_number:Number(r.innings_number)||1,group:r.group_scope==='legacy'?'__legacy__':r.group_scope==='unassigned'?'__unassigned__':r.group_id||'__all__',sessionId:r.id,sessionRevision:r.revision,sessionGroupScope:r.group_scope,sessionGroupId:r.group_id||null,reviewCanEdit:!!r.can_edit,reviewCanDelete:!!r.can_delete,sessionLabel:r.author_name||'',view:'entry',search:'',editReview:restoring?s.editReview:false});s.loaded=teamReviewIdentity(s);teamReviewReconcile(data);s.saved=data.players.filter(p=>p.included_in_review).map(p=>p.player_id);s.message=Object.values(s.drafts).some(d=>d._conflict)?'Check the highlighted changes before saving.':'Saved match review.';}catch(error){if(scope!==ensureTeamReviewState().scope||sequence!==teamReviewSequence||currentTab!=='team_review')return;s.message=error?.message||'Could not open this review.';}s.loading=false;renderTeamReviewContent();recordAppNavigation(clubNavigationRoute());}
async function previewTeamReviewDelete(id){const s=ensureTeamReviewState(),scope=s.scope;if(teamReviewControlsLocked())return;s.loading=true;s.message='Checking what this deletion would remove…';renderTeamReviewHistoryContent();try{const {data,error}=await supabase.rpc('preview_team_review_delete',{p_club_id:club.id,p_review_id:id});if(error)throw error;if(scope!==ensureTeamReviewState().scope||currentTab!=='team_review')return;if(!data?.preview_token||!data?.review?.id||!Array.isArray(data.rows))throw new Error('The deletion preview could not be verified.');s.deletePreview=data;s.message='Review the details below before deleting.';}catch(error){s.message=error?.message||'Could not preview deletion.';s.deletePreview=null;}s.loading=false;renderTeamReviewHistoryContent();document.querySelector('.team-review-delete-preview')?.scrollIntoView({block:'start',behavior:'smooth'});}
