  const actual=playerPlanStructureVersions?.[0]?.snapshot?.core;
  const question=Array.isArray(actual)?actual.find(q=>q.id==='core_strengths'&&q.active!==false&&q.response_type!=='text'):null;
  return workspacePlayerPlansPublished()&&question?question:null;
