    const answers=section==='core'?raw.core||{}:raw.formats?.[section]||{};
    for(const [question_id,answer] of Object.entries(answers))candidates.push({source_kind:'plan',source_id:null,source_key:section+':'+question_id,source_snapshot:{section,question_id,answer:structuredClone(answer)}});
