// BEGIN AWARD RELEASE — a deliberate, server-verified reveal for one award period.
let callAwardReleaseState={scope:'',selection:'',open:false,kind:'weekly',season:null,preview:null,needsPreview:false,loading:false,saving:false,command:null,sequence:0,message:'',dates:{weekly:null,monthly:null},announcement:null};
function callAwardReleaseScope(){return `${club?.id||''}:${session?.user?.id||''}`;}
function callAwardReleaseSavePending(){return callAwardReleaseState.scope===callAwardReleaseScope()&&(callAwardReleaseState.saving||!!callAwardReleaseState.command);}
function callAwardReleaseKinds(data){const kinds=['weekly'];if((data.period_awards||[]).some(a=>a.cadence==='monthly')||Object.entries(data.settings?.award_cadence||{}).some(([key,cadence])=>cadence==='monthly'&&callAwardEnabled(data.settings,key)))kinds.push('monthly');if(data.settings?.season_awards_visibility==='on_release'&&['season_points','season_accuracy','season_beats','grinch'].some(key=>callAwardEnabled(data.settings,key)))kinds.push('season');return kinds;}
function ensureCallAwardReleaseState(data){const scope=callAwardReleaseScope();if(callAwardReleaseState.scope!==scope){callAwardReleaseState={scope,selection:'',open:false,kind:'weekly',season:null,preview:null,needsPreview:false,loading:false,saving:false,command:null,sequence:callAwardReleaseState.sequence+1,message:'',dates:{weekly:null,monthly:null},announcement:null};}const state=callAwardReleaseState;if(!Number.isInteger(state.season)||state.season<1900||state.season>2200)state.season=Number(data.season)||new Date().getFullYear();state.dates=state.dates||{weekly:null,monthly:null};const anchor=data.settings?.award_cycle_start||null;if(state.cycleAnchor!==undefined&&state.cycleAnchor!==anchor&&!callAwardReleaseSavePending()){state.dates.monthly=null;if(state.kind==='monthly'){state.preview=null;state.needsPreview=true;state.sequence++;}}state.cycleAnchor=anchor;for(const kind of ['weekly','monthly'])if(!state.dates[kind])state.dates[kind]=data.release_defaults?.[kind]?.period_start||null;if(!callAwardReleaseKinds(data).includes(state.kind)&&!callAwardReleaseSavePending()){state.kind='weekly';state.preview=null;state.needsPreview=true;state.sequence++;}return state;}
function callAwardReleaseIdentity(data,kind){const state=ensureCallAwardReleaseState(data);return {p_club_id:club.id,p_period_kind:kind,p_period_date:kind==='season'?null:state.dates[kind]||null,p_season:kind==='season'?state.season:null};}
function callAwardReleasePreviewMatches(preview,identity){if(!preview||preview.period_kind!==identity.p_period_kind||!/^\d{4}-\d{2}-\d{2}$/.test(preview.period_start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(preview.period_end||'')||preview.period_start>=preview.period_end)return false;if(identity.p_period_kind==='season')return Number(preview.season)===Number(identity.p_season);return !identity.p_period_date||(identity.p_period_date>=preview.period_start&&identity.p_period_date<preview.period_end);}
function callAwardReleaseHasContent(preview){return !!preview&&((preview.awards||[]).length>0||Number(preview.entry_count)>0);}
function callAwardReleaseReady(preview){return !!preview&&preview.can_release_now===true&&(preview.period_kind==='season'||preview.period_completed===true);}
function callAwardReleaseSelectionMeta(data,state){if(state.preview&&callAwardReleasePreviewMatches(state.preview,callAwardReleaseIdentity(data,state.kind)))return state.preview;const meta=data.release_defaults?.[state.kind];return meta&&state.dates[state.kind]>=meta.period_start&&state.dates[state.kind]<meta.period_end?meta:null;}
function callAwardReleaseSelectionValid(data,kind,value){if(kind==='season')return true;const latest=data.release_defaults?.[kind]?.period_last_date;if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;return data.release_defaults?.[kind]?.has_completed_period!==false&&data.release_defaults?.[kind]?.configured!==false&&!!latest&&value<=latest&&(kind!=='monthly'||!data.settings?.award_cycle_start||value>=data.settings.award_cycle_start);}
function callAwardReleaseDate(date){if(!date)return '';return typeof formatDateShort==='function'?formatDateShort(date):String(date);}
function callAwardReleaseRange(meta){if(!meta?.period_start)return '';const start=callAwardReleaseDate(meta.period_start);if(!meta.period_end)return start;const end=new Date(`${String(meta.period_end).slice(0,10)}T12:00:00Z`);if(Number.isNaN(end.getTime()))return start;end.setUTCDate(end.getUTCDate()-1);return `${start} – ${callAwardReleaseDate(end.toISOString().slice(0,10))}`;}
function callAwardReleaseLabel(kind){return {weekly:'Weekly awards',monthly:'Four-week awards',season:'Season awards'}[kind]||'Awards';}
function callAwardReleaseAction(kind,update=false,meta=null){const range=callAwardReleaseRange(meta),noun=meta&&Array.isArray(meta.awards)&&!meta.awards.length?'results':'awards';return range?`${update?'Update':'Release'} ${noun} for ${range}`:kind==='season'?'Release season awards':'Release selected awards';}
function callAwardReleaseTimestamp(value,data){return value?(typeof callDateTime==='function'?callDateTime(value,data.settings?.timezone):String(value)):'';}
function renderCallAwardReleasePreview(preview){if(!preview)return '';const awards=Array.isArray(preview.awards)?preview.awards:[];return `<div class="call-release-preview"><h3 id="callAwardReleasePreviewHeading" tabindex="-1">${esc(callAwardReleaseLabel(preview.period_kind))} · ${esc(callAwardReleaseRange(preview))}</h3><p class="help">Check the winners, prizes and claim conditions below. Batting and prediction awards use the recorded result date within this period. Engagement uses the activity week. Play from the current period is separate. Weekly or four-week release also reveals the included player predictions, club estimates and named peer predictions; season release does not.</p>${awards.length?`<div class="call-release-awards">${awards.map(award=>{const prize=String(award.reward_text||'').trim(),name=award.label||(typeof callAwardLabel==='function'?callAwardLabel(award.key,award.cadence||preview.period_kind):String(award.key||'Award').replaceAll('_',' '));return `<article><h4>${esc(name)}</h4>${(award.winners||[]).length?award.winners.map(winner=>`<p><strong>${esc(winner.name||'Club member')}</strong>${winner.detail?`<br><span class="help">${esc(winner.detail)}</span>`:''}</p>`).join(''):'<p class="help">No qualifying winner yet.</p>'}<p><strong>${prize?'Club prize:':'Recognition only'}</strong>${prize?' '+esc(prize):''}</p>${prize&&award.claim_text?`<p class="help"><strong>To claim:</strong> ${esc(award.claim_text)}</p>`:''}</article>`;}).join('')}</div>`:'<p class="help">No awards are selected for this period. Any included predictions and confirmed scores can still be released.</p>'}</div>`;}
function renderCallAwardReleaseBody(data){const state=ensureCallAwardReleaseState(data),kinds=callAwardReleaseKinds(data),preview=state.preview,meta=callAwardReleaseSelectionMeta(data,state),pending=callAwardReleaseSavePending(),ann=state.announcement,annSelected=ann?.period_kind===state.kind&&(state.kind==='season'?Number(ann.season)===state.season:ann.period_start===state.dates[state.kind]),updating=!!preview?.released||annSelected,buttonText=updating?'Review updated awards':'Review & release awards',latest=data.release_defaults?.[state.kind],disabled=pending||state.loading;return `<style>.call-release-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.call-release-heading h2{margin:0}.call-release-panel{margin-top:14px;border-top:1px solid #dce1ed;padding-top:14px}.call-release-panel>label,.call-release-period>label{display:block;font-weight:700;margin:12px 0 5px}.call-release-panel>select,.call-release-period>input{width:100%;max-width:24rem}.call-release-preview h3{margin:16px 0 6px}.call-release-awards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:12px 0}.call-release-awards article{padding:12px;border:1px solid #dce1ed;border-radius:10px;background:#f5f6fd}.call-release-awards h4{margin:0}.call-release-awards p{margin:8px 0 0}.call-release-status:empty{display:none}.call-release-panel .btnrow{margin-top:14px}</style><div class="call-release-heading"><div><h2>Award announcement</h2><p class="help">Announce a completed week or four-week period. The match entries shown above keep their own selected week.</p>${meta?`<p class="help"><strong>${esc(callAwardReleaseLabel(state.kind))} · ${esc(callAwardReleaseRange(meta))}</strong></p>`:''}</div><button type="button" class="btn secondary" id="callAwardReleaseOpen" aria-controls="callAwardReleasePanel" aria-expanded="${state.open}" ${state.open?'hidden':''} ${pending?'disabled':''}>${buttonText}</button></div>${ann?`<p class="notice compact">Released: ${esc(callAwardReleaseLabel(ann.period_kind))} · ${esc(callAwardReleaseRange(ann))}. <button type="button" class="btn ghost" id="callAwardReleaseView" ${pending?'disabled':''}>View announced awards</button></p>`:''}<div id="callAwardReleasePanel" class="call-release-panel" ${state.open?'':'hidden'}><label for="callAwardReleaseKind">Which awards are you releasing?</label><select id="callAwardReleaseKind" ${disabled?'disabled':''}>${kinds.map(kind=>`<option value="${kind}" ${kind===state.kind?'selected':''}>${callAwardReleaseLabel(kind)}</option>`).join('')}</select>${state.kind==='season'?`<div class="call-release-period"><label for="callAwardReleaseSeason">Season starting year</label><input id="callAwardReleaseSeason" type="number" min="1900" max="2200" step="1" inputmode="numeric" value="${esc(state.season)}" aria-describedby="callAwardReleaseSeasonHelp" ${disabled?'disabled':''}><p class="help" id="callAwardReleaseSeasonHelp"><strong>Season awards are separate.</strong> Choose the year the season started, including an earlier season. Check the exact dates in the preview before releasing.</p></div>`:`<div class="call-release-period"><label for="callAwardReleaseDate">Choose a completed award ${state.kind==='monthly'?'four-week period':'week'}</label><input type="date" id="callAwardReleaseDate" value="${esc(state.dates[state.kind]||'')}" ${latest?.period_last_date?`max="${esc(latest.period_last_date)}"`:''} ${disabled||(latest?.has_completed_period===false||latest?.configured===false)?'disabled':''}><p class="help">${state.kind==='monthly'?'Choose any date within a completed four-week period.':'Choose any date within a completed award week.'} The latest completed period is selected initially. You can choose an earlier period to review or correct its announcement.</p>${(latest?.has_completed_period===false||latest?.configured===false)?`<p class="notice compact">${latest.configured===false?'Set the first four-week award week in Club setup before releasing these awards.':`The first four-week period will be ready to release from ${esc(callAwardReleaseDate(latest.available_from))}.`}</p>`:''}</div>`}${preview?.released_at?`<p class="help">Last released ${esc(callAwardReleaseTimestamp(preview.released_at,data))}. Players keep seeing that announcement until you release an update.</p>`:''}${state.loading?'<p role="status">Preparing the award preview…</p>':renderCallAwardReleasePreview(preview)}${preview&&!callAwardReleaseReady(preview)?`<p class="notice compact" role="status">${esc(preview.release_block_reason||'This period is not ready to release. Choose a completed period whose prediction deadlines have passed.')}</p>`:''}<p id="callAwardReleaseStatus" class="status call-release-status" role="status" aria-live="polite">${esc(state.message)}</p><div class="btnrow"><button type="button" class="btn" id="callAwardReleaseConfirm" ${state.saving||state.loading||(!state.command&&(!callAwardReleaseReady(preview)||!callAwardReleasePreviewMatches(preview,callAwardReleaseIdentity(data,state.kind))||state.needsPreview||!callAwardReleaseHasContent(preview)))?'disabled':''}>${state.saving?'Releasing…':state.command?'Confirm previous release':callAwardReleaseAction(state.kind,updating,preview||meta)}</button><button type="button" class="btn secondary" id="callAwardReleasePreviewButton" ${disabled?'disabled':''}>${state.needsPreview?'Review updated awards':'Refresh preview'}</button><button type="button" class="btn ghost" id="callAwardReleaseCancel" ${pending?'disabled':''}>Close preview</button></div><p class="help">Your club checks any prize conditions when handing over the prize. Releasing awards does not send an email or notification.</p></div>`;}
function renderCallAwardReleaseControls(data){if(data?.can_release_awards!==true||!data.settings?.enabled)return '';return `<section class="card call-release" id="callAwardRelease">${renderCallAwardReleaseBody(data)}</section>`;}
function refreshCallAwardReleaseControls(data,current,focusId=''){const host=document.getElementById('callAwardRelease');if(!host||!current())return;host.innerHTML=renderCallAwardReleaseBody(data);wireCallAwardReleaseControls(data,current);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
function callAwardReleaseOtherPending(){return (typeof makeYourCallSaving!=='undefined'&&makeYourCallSaving)||(typeof makeYourCallCommands!=='undefined'&&makeYourCallCommands.size>0);}
async function loadCallAwardReleasePreview(data,current){const state=ensureCallAwardReleaseState(data);if(data.can_release_awards!==true||callAwardReleaseSavePending()||callAwardReleaseOtherPending()||!current())return;const sequence=++state.sequence,kind=state.kind,identity=callAwardReleaseIdentity(data,kind);state.open=true;state.loading=true;state.needsPreview=false;state.preview=null;state.message='';refreshCallAwardReleaseControls(data,current);try{const {data:preview,error}=await supabase.rpc('preview_make_your_call_awards',identity);if(error)throw error;if(!preview||preview.can_release_awards!==true||!callAwardReleasePreviewMatches(preview,identity)||!preview.preview_token||!Array.isArray(preview.awards)||!Number.isInteger(Number(preview.revision)))throw new Error('The award preview could not be confirmed. Try refreshing it.');if(!current()||state!==callAwardReleaseState||sequence!==state.sequence||state.kind!==kind)return;if(kind!=='season')state.dates[kind]=preview.period_start;state.preview=preview;state.message=preview.released?(preview.source_changed?'Results or prize details have changed since the last announcement. Check the updated preview before releasing it.':'This period has already been released. The preview matches the latest confirmed information.'):'Preview only. Players will see these awards after you click Release.';}catch(error){if(current()&&state===callAwardReleaseState&&sequence===state.sequence){state.message=error?.message||'Could not load the award preview. Try again.';state.needsPreview=true;}}finally{if(current()&&state===callAwardReleaseState&&sequence===state.sequence){state.loading=false;refreshCallAwardReleaseControls(data,current,state.preview?'callAwardReleasePreviewHeading':'callAwardReleasePreviewButton');}}}
async function confirmCallAwardRelease(data,current){const state=ensureCallAwardReleaseState(data);if(data.can_release_awards!==true||state.saving||state.loading||callAwardReleaseOtherPending()||!current())return;if(!state.command){const preview=state.preview;if(!callAwardReleaseReady(preview)||!callAwardReleasePreviewMatches(preview,callAwardReleaseIdentity(data,state.kind))||state.needsPreview||!callAwardReleaseHasContent(preview))return;state.command={period:{period_kind:preview.period_kind,period_start:preview.period_start,period_end:preview.period_end,season:preview.season||state.season},rpc:'release_make_your_call_awards',args:{...callAwardReleaseIdentity(data,state.kind),p_period_date:state.kind==='season'?null:preview.period_start,p_season:Number(preview.season)||null,p_expected_revision:Number(preview.revision),p_preview_token:preview.preview_token,p_request_id:preparationUuid()}};}const command=state.command;state.saving=true;state.message='Releasing this period’s awards…';const controls=state.lockedControls||[...document.querySelectorAll('.call-page input,.call-page textarea,.call-page select,.call-page button')].map(el=>[el,el.disabled]);state.lockedControls=controls;controls.forEach(([el])=>el.disabled=true);refreshCallAwardReleaseControls(data,current);try{const {data:result,error}=await supabase.rpc(command.rpc,command.args);if(error)throw error;if(result?.ok!==true||result.released!==true||result.period_kind!==command.period.period_kind||result.period_start!==command.period.period_start||result.period_end!==command.period.period_end)throw new Error('Could not confirm that the selected period’s awards were released.');if(state===callAwardReleaseState){state.announcement={...command.period,released_at:result.released_at};state.command=null;state.saving=false;state.open=false;state.preview=null;state.message='';}if(!current())return;const drafts=typeof captureCallDrafts==='function'?captureCallDrafts():null;await renderMakeYourCall({message:`${result.already_saved?'The previous release is confirmed.':'Awards released.'} ${callAwardReleaseLabel(command.period.period_kind)} · ${callAwardReleaseRange(command.period)}. The match entries shown above have not changed.`,drafts});document.getElementById('callAwardReleaseOpen')?.focus({preventScroll:true});}catch(error){if(state!==callAwardReleaseState)return;const definite=typeof definiteInningsSaveFailure==='function'&&definiteInningsSaveFailure(error);if(definite){state.command=null;state.needsPreview=true;}state.message=(error?.message||'Could not confirm the award release.')+(state.command?' Choose Confirm previous release to check the same announcement; it will not be released twice.':' Nothing further has been released. Review updated awards before trying again.');}finally{if(state===callAwardReleaseState){state.saving=false;if(!state.command)state.lockedControls=null;}for(const [el,disabled]of controls)if(document.documentElement.contains(el))el.disabled=disabled;if(current()){refreshCallAwardReleaseControls(data,current,state.command?'callAwardReleaseConfirm':state.needsPreview?'callAwardReleasePreviewButton':'');if(state.command){for(const el of document.querySelectorAll('.call-page input,.call-page textarea,.call-page select,.call-page button'))el.disabled=true;const retry=document.getElementById('callAwardReleaseConfirm');if(retry)retry.disabled=false;}}}}
function wireCallAwardReleaseControls(data,parentCurrent=null){const host=document.getElementById('callAwardRelease'),scope=callAwardReleaseScope();if(!host||data.can_release_awards!==true)return;const current=()=>callAwardReleaseScope()===scope&&currentTab==='make_your_call'&&document.getElementById('callAwardRelease')===host&&(!parentCurrent||parentCurrent());const open=document.getElementById('callAwardReleaseOpen');if(open)open.onclick=()=>{if(callAwardReleaseOtherPending()){alert('Confirm the pending save before reviewing awards.');return;}return loadCallAwardReleasePreview(data,current);};const kind=document.getElementById('callAwardReleaseKind');if(kind)kind.onchange=()=>{const state=ensureCallAwardReleaseState(data);if(callAwardReleaseSavePending()||callAwardReleaseOtherPending()||state.loading||!callAwardReleaseKinds(data).includes(kind.value)){kind.value=state.kind;return;}state.kind=kind.value;return loadCallAwardReleasePreview(data,current);};const date=document.getElementById('callAwardReleaseDate');if(date)date.onchange=()=>{const state=ensureCallAwardReleaseState(data),kind=state.kind,value=date.value;if(callAwardReleaseSavePending()||callAwardReleaseOtherPending()||state.loading){date.value=state.dates[kind]||'';return;}if(!callAwardReleaseSelectionValid(data,kind,value)){state.message='Choose a completed award period. The current period and future periods cannot be released.';refreshCallAwardReleaseControls(data,current,'callAwardReleaseDate');return;}state.dates[kind]=value;return loadCallAwardReleasePreview(data,current);};const season=document.getElementById('callAwardReleaseSeason');if(season)season.onchange=()=>{const state=ensureCallAwardReleaseState(data),value=String(season.value).trim();if(callAwardReleaseSavePending()||callAwardReleaseOtherPending()||state.loading){season.value=String(state.season);return;}if(!/^\d{4}$/.test(value)||Number(value)<1900||Number(value)>2200){state.message='Choose a season starting year from 1900 to 2200.';refreshCallAwardReleaseControls(data,current,'callAwardReleaseSeason');return;}state.season=Number(value);return loadCallAwardReleasePreview(data,current);};const view=document.getElementById('callAwardReleaseView');if(view)view.onclick=async()=>{const state=ensureCallAwardReleaseState(data),ann=state.announcement;if(!ann||callAwardReleaseSavePending()||callAwardReleaseOtherPending()||!current())return;await openCallResultsHistory({periodKind:ann.period_kind,periodStart:ann.period_start});};const preview=document.getElementById('callAwardReleasePreviewButton');if(preview)preview.onclick=()=>loadCallAwardReleasePreview(data,current);const confirm=document.getElementById('callAwardReleaseConfirm');if(confirm)confirm.onclick=()=>confirmCallAwardRelease(data,current);const cancel=document.getElementById('callAwardReleaseCancel');if(cancel)cancel.onclick=()=>{if(callAwardReleaseSavePending())return;const state=ensureCallAwardReleaseState(data);state.open=false;state.preview=null;state.needsPreview=false;state.loading=false;state.message='';state.sequence++;refreshCallAwardReleaseControls(data,current,'callAwardReleaseOpen');};}
// END AWARD RELEASE

// BEGIN MAKE YOUR CALL — explicit club sharing, independent of private preparation.
let makeYourCallState={scope:'',week:null,month:null,season:null,query:'',needsPrediction:false,openId:null,savedOpenId:null,editSettings:false,recordResults:false,scoreId:null};
let makeYourCallCache=null,makeYourCallSequence=0,makeYourCallSaving=false,makeYourCallDeadlineTimer=null;
const makeYourCallCommands=new Map();
const CALL_RECURRING_AWARDS=['weekly_points','weekly_accuracy','engagement','believer','nasty'];
const CALL_WEEK_DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const CALL_REWARD_LABELS={weekly_points:'Weekly points winner',weekly_accuracy:'Weekly Best Judge',season_points:'Season points champion',season_accuracy:'Season Best Judge',season_beats:'Most club predictions beaten',believer:'You believed in them',nasty:'That’s just nasty award',engagement:'Engagement award',engagement_claim:'How to claim the engagement prize'};
function ensureMakeYourCallState(){const scope=`${club?.id||''}:${session?.user?.id||''}`;if(makeYourCallState.scope!==scope){makeYourCallState={scope,week:null,month:null,season:null,query:'',needsPrediction:false,openId:null,savedOpenId:null,editSettings:false,recordResults:false,scoreId:null};makeYourCallCache=null;makeYourCallCommands.clear();}return makeYourCallState;}
function makeYourCallFormState(form){return JSON.stringify([...form.querySelectorAll('input,textarea,select')].map(f=>[f.id,f.value,!!f.checked]));}
function makeYourCallHasUnsavedChanges(){return currentTab==='make_your_call'&&[...document.querySelectorAll('[data-call-form]')].some(f=>f.callBaseline!==makeYourCallFormState(f));}
function makeYourCallSavePending(){return makeYourCallSaving||makeYourCallCommands.size>0||(typeof callAwardReleaseSavePending==='function'&&callAwardReleaseSavePending());}
function confirmLeaveMakeYourCall(){if(makeYourCallSavePending()){alert('Please confirm the pending Make your prediction save before leaving.');return false;}return !makeYourCallHasUnsavedChanges()||confirm('Leave your unsaved Make your prediction changes? Choose Cancel to keep editing.');}
async function openMakeYourCall({week=null}={}){if(!canOpenClubTab('make_your_call')||!await saveClubEditsBeforeNavigation())return;const s=ensureMakeYourCallState();s.week=week||null;s.month=null;s.season=null;if(typeof ensureCallResultsState==='function')ensureCallResultsState().view='board';currentTab='make_your_call';await renderTab();}
function callAwardsSetupLabel(settings){return Number(settings?.revision)>0&&settings?.timezone?'Edit your club’s awards setup':'Set up your club’s awards';}
function callNumber(value,max,label){const text=String(value??'').trim();if(!/^\d+$/.test(text)||Number(text)>max)throw new Error(`${label}: enter a whole number from 0 to ${max}.`);return Number(text);}
const CALL_AWARD_KEYS=[...CALL_RECURRING_AWARDS,'season_points','season_accuracy','season_beats','grinch'];
function callAwardEnabled(settings,key){return key==='grinch'?settings?.grinch_enabled===true:CALL_AWARD_KEYS.includes(key)&&settings?.award_enabled?.[key]!==false;}
function callAwardCheckboxId(key){return key==='grinch'?'callGrinchEnabled':'callAwardEnabled-'+key;}
function callAwardChoiceChecked(key){return document.getElementById(callAwardCheckboxId(key))?.checked===true;}
function callClaimText(rewards,key){return String(rewards?.[key]||'').trim()?String(rewards?.[key+'_claim']||'').trim():'';}
function renderCallClaim(rewards,key){const claim=callClaimText(rewards,key);return claim?`<p class="help call-award-claim"><strong>To claim:</strong> ${esc(claim)}</p>`:'';}
function renderCallClaimSetting(key,rewards){return `<div id="callClaimSetting-${key}" ${String(rewards[key]||'').trim()?'':'hidden'}><label class="help" for="callReward-${key}_claim">Condition for claiming this prize (optional)</label><input id="callReward-${key}_claim" maxlength="300" value="${esc(rewards[key+'_claim']||'')}" placeholder="e.g. Be at Friday club night to collect"></div>`;}
function callRewardText(rewards,key){return String(rewards?.[key]||'').trim()||(key==='engagement_claim'?'No extra claim condition':'Recognition only');}
function callDateTime(value,zone){try{return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:zone||'UTC'}).format(new Date(value));}catch{return String(value||'');}}
function callVoteSliderMaximum(runs){return Math.min(999,Math.max(200,Math.ceil((Number(runs)||0)/50)*50));}
function callDetailsReleased(c){return c?.details_released===true;}
function callVotingOpen(c){const cutoff=Date.parse(c?.cutoff_at),sample=makeYourCallCache?._clockSampledAt,server=Date.parse(makeYourCallCache?.server_now),now=Number.isFinite(server)&&Number.isFinite(sample)?server+Math.max(0,Date.now()-sample):Date.now();return c?.voting_open===true&&!callDetailsReleased(c)&&(!Number.isFinite(cutoff)||now<cutoff);}
function callDeadlineLabel(c,zone){if(callDetailsReleased(c))return 'Predictions revealed';if(!callVotingOpen(c))return 'Predictions closed';try{return 'Enter by '+new Intl.DateTimeFormat('en-AU',{weekday:'short',day:'numeric',month:'short',timeZone:c.timezone||zone||'UTC'}).format(new Date(Date.parse(c.cutoff_at)-1))+' night';}catch{return 'Closes at midnight before match day';}}
function callOfficialResult(c){return c.can_record_result?(c.official_result||(callDetailsReleased(c)?c.result:null)||{status:'pending',revision:0}):null;}
function callResultText(result){return result?.status==='played'?`${result.runs}${result.not_out?'*':''}`:({pending:'Awaiting official result',did_not_bat:'Did not bat',cancelled:'Cancelled'})[result?.status]||'Awaiting official result';}
function callPointsBasis(c){if(c?.eligible===false||c?.result?.status!=='played'||c.club_call==null||c.raw_surplus==null||c.format_weight==null)return '';const surplus=Number(c.raw_surplus),weight=Number(c.format_weight);return Number.isFinite(surplus)&&surplus>=0&&Number.isFinite(weight)&&weight>0?`${surplus} runs above club prediction × ${weight.toFixed(1)}`:'';}
function callPointsDetail(c){const basis=callPointsBasis(c);return `${c.points||0} points${basis?` · ${basis}`:''}`;}
function renderCallRewards(data){return `<dl class="call-rewards">${callPeriodAwards(data).map(award=>`<div><dt>${award.cadence==='monthly'?'Four-week':'Weekly'} · ${esc(callAwardLabel(award.key))}</dt><dd>${esc(String(award.reward_text||'').trim()||'Recognition only')}${String(award.reward_text||'').trim()&&award.claim_text?`<br>To claim: ${esc(award.claim_text)}`:''}</dd></div>`).join('')}${['season_points','season_accuracy','season_beats'].map(key=>`<div><dt>${esc(CALL_REWARD_LABELS[key])}</dt><dd>${esc(callRewardText(data.settings?.rewards,key))}${callClaimText(data.settings?.rewards,key)?`<br>To claim: ${esc(callClaimText(data.settings?.rewards,key))}`:''}</dd></div>`).join('')}</dl>`;}
function callWeeklyWinners(calls,key){const eligible=calls.filter(c=>c.result?.status==='played'&&c.club_call!=null&&!c.voting_open);if(key==='points'){const best=Math.max(0,...eligible.map(c=>Number(c.points)||0));return best>0?eligible.filter(c=>Number(c.points)===best).map(c=>({name:c.name,detail:`${callPointsDetail(c)} · ${c.opposition||'match'}`})):[];}const field=key==='wildest'?'wildest_calls':key==='nasty'?'nasty_calls':'believers',metric=key==='wildest'?'error':'gap';const rows=eligible.flatMap(c=>(c[field]||[]).map(v=>({...v,player_name:c.name})));const best=Math.max(0,...rows.map(r=>Number(r[metric])||0));return rows.filter(r=>best>0&&Number(r[metric])===best).map(r=>({name:r.name,detail:key==='wildest'?`${r.runs} for ${r.player_name} · ${r.error} away`:key==='nasty'?`${r.runs} for ${r.player_name} · others ${r.rest_call} · ${r.gap} below; the batter proved them wrong`:`${r.runs} for ${r.player_name} · ${r.gap} above the others`}));}
function callAccuracyAverage(row){const value=Number(row.average_error);return Number.isFinite(value)?value.toFixed(2):'—';}
function renderCallAccuracyAward(data,season=false){const visibility=season?callSeasonVisibility(data):{pending:data.award_releases?.weekly?.released===false&&!data.can_release_awards};const rows=visibility.pending?[]:data[season?'accuracy_season_rows':'accuracy_week_rows']||[],leaders=rows.filter(r=>r.eligible&&r.is_leader),reward=season?'season_accuracy':'weekly_accuracy';return `<article class="call-accuracy-award"><h3>${season?'Season':'Weekly'} Best Judge</h3>${renderCallAwardHelp(season?'season_accuracy':'weekly_accuracy',season?'season':'weekly')}${leaders.length?leaders.map(r=>`<p><strong>${esc(r.name)}</strong><br><span class="help">${esc(callAccuracyAverage(r))} runs away on average · ${esc(r.predictions)} predictions${season?` · ${esc(r.weeks)} weeks`:''}</span></p>`).join(''):`<p class="help">${visibility.pending?'Results will be announced here.':'No one qualifies yet.'}</p>`}<p class="help">${esc(callRewardText(season?data.settings?.rewards:data.rewards,reward))}</p>${renderCallClaim(season?data.settings?.rewards:data.rewards,reward)}</article>`;}
function renderCallTallySummary(label){return `<summary class="call-tally-summary" aria-expanded="false"><span class="call-tally-name">${esc(label)}</span><span class="call-tally-action"><span class="call-tally-open-label">View tally</span><span class="call-tally-close-label">Hide tally</span><span class="call-tally-chevron" aria-hidden="true">⌄</span></span></summary>`;}
function bindCallTallies(root){root.querySelectorAll('[data-call-tally]').forEach(details=>{const summary=details.querySelector('summary'),sync=()=>summary.setAttribute('aria-expanded',String(details.open));const toggle=()=>{details.open=!details.open;sync();};summary.onclick=e=>{e.preventDefault?.();toggle();};summary.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}};details.ontoggle=sync;sync();});}
function renderCallAccuracyTable(data,season=false){if(season?callSeasonVisibility(data).pending:data.award_releases?.weekly?.released===false&&!data.can_release_awards)return '';const rows=data[season?'accuracy_season_rows':'accuracy_week_rows']||[];return `<details class="call-accuracy-tally" ${season?'data-call-tally="season-accuracy"':''}>${season?renderCallTallySummary(`Season Best Judge tally · ${rows.length} ${rows.length===1?'predictor':'predictors'}`):`<summary>Weekly Best Judge tally · ${rows.length} ${rows.length===1?'predictor':'predictors'}</summary>`}<p class="help">Lower average runs away is better. Every prediction with a confirmed result counts, whether too high or too low. Your average covers the innings you chose to predict.</p><div class="call-table-wrap"><table class="call-table call-accuracy-table"><caption class="call-sr-only">${season?'Season':'Weekly'} prediction accuracy and qualification progress</caption><thead><tr><th scope="col">Predictor</th><th scope="col">Avg. runs away</th><th scope="col">Predictions</th>${season?'<th scope="col">Weeks</th>':''}<th scope="col">Progress</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${esc(callAccuracyAverage(r))}</td><td>${esc(r.predictions)}</td>${season?`<td>${esc(r.weeks)}</td>`:''}<td>${r.eligible?(r.is_leader?'Leader':'Qualified'):season?`${esc(r.predictions)}/10 predictions · ${esc(r.weeks)}/3 weeks`:`${esc(r.predictions)}/3 predictions`}</td></tr>`).join('')||`<tr><td colspan="${season?5:4}">No predictions with confirmed results yet.</td></tr>`}</tbody></table></div><p class="help">Only predictions for another player’s closed entry with an official batted result count, including ducks and not-outs. Pending results, did not bat and cancelled matches are excluded. A club median is not needed. Averages are shown to two decimals; exact averages decide tied places. Score corrections update the tally.</p></details>`;}
function renderCallPointsAward(data){const rows=callWeeklyWinners(data.calls||[],'points');return `<article><h3>Weekly points winner</h3>${rows.length?rows.map(r=>`<p><strong>${esc(r.name)}</strong><br><span class="help">${esc(r.detail)}</span></p>`).join(''):'<p class="help">Waiting for qualifying official results.</p>'}<p class="help">${esc(callRewardText(data.rewards,'weekly_points'))}</p></article>`;}
function callMonthLabel(value){try{return new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${String(value).slice(0,10)}T12:00:00Z`));}catch{return '';}}
function callAwardLabel(key,cadence='weekly'){const labels={weekly_points:'Points winner',weekly_accuracy:'Best Judge',engagement:'Engagement award',believer:'You believed in them',nasty:'That’s just nasty'};return labels[key]||CALL_REWARD_LABELS[key]||'Club award';}
// Award explanations use a native disclosure: touch, keyboard and desktop hover all work.
let callAwardHelpNumber=0;
function callAwardExplanation(key,cadence='weekly'){
 const period=cadence==='monthly'?'four-week period':'week';
 const rules={
  weekly_points:[`Earn the most batting points for scoring above the club’s prediction this ${period}.`,'We allow for the match format, so beating expectations in a shorter game carries more weight. Ties share the award.'],
  weekly_accuracy:[`Get closest to your teammates’ actual scores overall this ${period}.`,'Too high and too low count the same. Make several predictions to qualify.'],
  engagement:[cadence==='monthly'?'Prepare, train and reflect across the four-week period.':'Use your plan to prepare, train and reflect this week.',cadence==='monthly'?'Complete two different personal batting activities in each of two weeks. Admin and coaching duties do not count.':'Prepare for a match, make a training check-in, or reflect on an innings and choose what comes next. Two different activities count; admin and coaching duties do not.'],
  believer:[`Back a teammate more highly than the other voters—and have them prove you right.`,'The biggest vote of confidence that the batter lives up to wins.'],
  nasty:['Predict a much lower score than everyone else—and have the batter prove you wrong.','A light-hearted award for the biggest underestimate. No points are deducted.'],
  season_points:['Collect the most batting points across the season by beating club expectations.','The allowance for match format applies to each innings. Ties share the award.'],
  season_accuracy:['Be the club’s closest predictor across the season.','Keep making predictions over several weeks. Too high and too low count the same.'],
  season_beats:['Beat the club’s prediction in more innings than anyone else.','Every time you beat it counts, whether by one run or many.'],
  grinch:['For the club’s regular doubter whose low predictions keep being proved wrong.','Repeated underestimates across the season count, rather than one unlucky prediction.']
 };
 return rules[key]||['Your club’s award.','Ask your Club Admin about this award.'];
}
function renderCallAwardHelp(key,cadence='weekly',label=callAwardLabel(key),options={}){
 const id='callAwardHelp-'+(++callAwardHelpNumber),copy=callAwardExplanation(key,cadence),compact=!!options.overview;
 return `<details class="call-award-help ${compact?'call-award-disclosure':''}" data-call-award-help="${esc(key)}"><summary id="${id}-toggle" aria-controls="${id}-body" aria-expanded="false" aria-label="How ${esc(label)} works">${options.overview||''}<span class="call-award-help-action">How it works <span aria-hidden="true">⌄</span></span></summary><div class="call-award-help-body" id="${id}-body" role="region" aria-labelledby="${id}-toggle"><p>${esc(copy[0])}</p><p class="help">${esc(copy[1])}</p>${options.extra||''}</div></details>`;
}
function bindCallAwardHelp(root){
 const controls=[];
 root.querySelectorAll('[data-call-award-help]').forEach(details=>{
  const summary=details.querySelector('summary');let pinned=false,hovered=false,dismissed=false;
  const close=()=>{pinned=false;details.removeAttribute('open');summary.setAttribute('aria-expanded','false');};
  const open=()=>{controls.forEach(item=>{if(item.details!==details)item.close();});details.setAttribute('open','');summary.setAttribute('aria-expanded','true');};
  const activate=()=>{if(pinned){close();dismissed=true;}else{dismissed=false;pinned=true;open();}};
  controls.push({details,close});
  summary.onclick=e=>{e.preventDefault?.();activate();};
  summary.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}};
  details.onpointerenter=e=>{if(e.pointerType!=='mouse')return;hovered=true;if(!dismissed)open();};
  details.onpointerleave=()=>{hovered=false;dismissed=false;if(!pinned&&!details.contains(document.activeElement))close();};
  details.onfocusin=()=>{if(!dismissed)open();};
  details.onfocusout=e=>{if(!details.contains(e.relatedTarget)){dismissed=false;if(!hovered)close();}};
  details.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation?.();close();dismissed=true;if(details.contains(document.activeElement))summary.focus({preventScroll:true});}};
 });
 root.callAwardHelpControls=controls;
 if(!root.callAwardHelpOutsideBound){root.callAwardHelpOutsideBound=true;root.addEventListener('click',e=>{if(!e.target.closest?.('[data-call-award-help]'))root.callAwardHelpControls?.forEach(item=>item.close());});}
}
function callPeriodAwards(data){if(Array.isArray(data.period_awards))return data.period_awards.filter(a=>callAwardEnabled(data.settings,a.key));const rewards=data.rewards||data.settings?.rewards||{};return CALL_RECURRING_AWARDS.filter(key=>callAwardEnabled(data.settings,key)).map(key=>{let winners=[];if(key==='weekly_accuracy')winners=(data.accuracy_week_rows||[]).filter(r=>r.eligible&&r.is_leader).map(r=>({name:r.name,detail:`${callAccuracyAverage(r)} runs away on average · ${r.predictions} predictions`}));else if(key==='engagement')winners=(data.engagement?.awards||[]).map(r=>({name:r.name,detail:r.season_awards!=null?`${r.season_awards} awards this season`:''}));else winners=callWeeklyWinners(data.calls||[],key==='weekly_points'?'points':key);return {key,cadence:'weekly',reward_text:rewards[key]||'',claim_text:rewards[key+'_claim']||(key==='engagement'?data.engagement?.claim_text||'':''),period_start:data.week_start,winners,accuracy_rows:key==='weekly_accuracy'?data.accuracy_week_rows||[]:undefined};});}
function callAwardPending(award){return award.released===false&&!award.preview;}
function callSeasonVisibility(data){const live=data.season_awards_live===true||(data.season_awards_live===undefined&&data.settings?.season_awards_visibility!=='on_release'),released=data.award_releases?.season?.released===true;return {live,released,pending:!live&&!released&&!data.can_release_awards,preview:!live&&!!data.can_release_awards};}
function renderCallAwardCard(award,{hidePending=false,showPrizes=false}={}){
 const key=award.key,cadence=award.cadence==='season'?'season':award.cadence==='monthly'?'monthly':'weekly',pending=callAwardPending(award),winners=pending?[]:award.winners||[],reward=showPrizes?String(award.reward_text||'').trim():'',label=award.label||callAwardLabel(key,cadence),names=winners.slice(0,2).map(w=>w.name).join(' · '),status=names?names+(winners.length>2?` +${winners.length-2} more`:''):pending?'Not announced':award.live?'No leader yet':'Awaiting results',claim=reward&&String(award.claim_text||'').trim();
 const overview=`<span class="call-award-overview"><span class="call-award-heading"><strong class="call-award-title">${esc(label)}</strong></span>${pending&&hidePending?'':`<span class="call-award-result">${award.preview?'Staff preview · ':award.live?'Current leader · ':''}${esc(status)}</span>`}</span>`,winnerDetails=winners.length?`<div class="call-award-winners">${winners.map(r=>`<p><strong>${esc(r.name)}</strong>${r.detail?` · ${esc(r.detail)}`:''}</p>`).join('')}</div>`:'',tally=award.tally||((key==='weekly_accuracy'&&!pending)?renderCallPeriodAccuracy(award):'');
 return `<article class="call-award-row" data-call-award="${esc(key)}" data-call-award-cadence="${cadence}" ${key==='engagement'?'id="callSharedEngagement"':''}>${renderCallAwardHelp(key,cadence,label,{overview,extra:(reward?`<p class="call-award-prize"><strong>Club prize:</strong> ${esc(reward)}</p>`:'')+(claim?`<p class="call-award-condition"><strong>To claim:</strong> ${esc(claim)}</p>`:'')+winnerDetails+tally})}</article>`;
}
function callSeasonAwardData(data,key){const visibility=callSeasonVisibility(data),rows=visibility.pending?[]:data.season_rows||[],accuracy=visibility.pending?[]:data.accuracy_season_rows||[],grinch=visibility.pending?[]:data.grinch_rows||[],rewards=data.settings?.rewards||{};let winners=[],label=key==='season_points'?'Season points':key==='season_accuracy'?'Season Best Judge':key==='season_beats'?'Most club predictions beaten':data.settings?.grinch_name||'The Grinch';if(key==='season_accuracy')winners=accuracy.filter(r=>r.eligible&&r.is_leader).map(r=>({name:r.name,detail:`${callAccuracyAverage(r)} runs away on average`}));else {const list=key==='grinch'?grinch:rows,metric=key==='season_points'?'points':key==='season_beats'?'beat_count':'low_calls',best=Math.max(0,...list.map(r=>Number(r[metric])||0));winners=list.filter(r=>best>0&&Number(r[metric])===best).map(r=>({name:r.name,detail:key==='season_points'?`${best} points`:key==='season_beats'?`${best} times`:`${best} predictions proved too low`}));}return {key,label,cadence:'season',reward_text:rewards[key],claim_text:callClaimText(rewards,key),released:!visibility.pending,preview:visibility.preview,live:visibility.live,winners,tally:renderCallSeasonAwardTally(data,key)};}
function renderCallSeasonAwardTally(data,key){if(callSeasonVisibility(data).pending)return '<p class="help">The club will announce these standings when they are released.</p>';let headers,rows;if(key==='season_accuracy'){headers=['Predictor','Avg. away','Progress'];rows=(data.accuracy_season_rows||[]).map(r=>[r.name,callAccuracyAverage(r),`${r.predictions} predictions · ${r.weeks||0} weeks${r.eligible?' · Qualified':''}`]);}else if(key==='grinch'){headers=['Member','Low predictions','Compared'];rows=(data.grinch_rows||[]).map(r=>[r.name,r.low_calls,r.comparable_calls]);}else {headers=['Player',key==='season_points'?'Points':'Times beaten','Innings'];rows=[...(data.season_rows||[])].sort((a,b)=>Number(key==='season_points'?b.points||0:b.beat_count||0)-Number(key==='season_points'?a.points||0:a.beat_count||0)).map(r=>[r.name,key==='season_points'?r.points||0:r.beat_count||0,r.innings||0]);}return `<div class="call-award-tally" data-call-season-tally="${esc(key)}"><h4>Season tally</h4><div class="call-table-wrap"><table class="call-table"><caption class="call-sr-only">${esc(key==='season_accuracy'?'Season Best Judge':key==='season_points'?'Season points':key==='season_beats'?'Club predictions beaten':'Low predictions')} tally</caption><thead><tr>${headers.map(v=>`<th scope="col">${esc(v)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>i?`<td>${esc(v)}</td>`:`<th scope="row">${esc(v)}</th>`).join('')}</tr>`).join('')||'<tr><td colspan="3">No qualifying results yet.</td></tr>'}</tbody></table></div></div>`;}
function renderCallPeriodAccuracy(award){if(!award||callAwardPending(award)||!Array.isArray(award.accuracy_rows))return '';const rows=award.accuracy_rows,period=award.cadence==='monthly'?'Four-week':'Weekly';return `<details class="call-accuracy-tally"><summary>${period} Best Judge tally · ${rows.length} ${rows.length===1?'predictor':'predictors'}</summary><p class="help">Lower average runs away is better. Every prediction with a confirmed result counts equally, whether too high or too low. ${award.cadence==='monthly'?'At least 6 predictions across 2 award weeks are needed.':'At least 3 predictions this week are needed.'}</p><div class="call-table-wrap"><table class="call-table call-accuracy-table"><caption class="call-sr-only">${period} prediction accuracy and qualification progress</caption><thead><tr><th scope="col">Predictor</th><th scope="col">Avg. runs away</th><th scope="col">Predictions</th><th scope="col">Progress</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${esc(callAccuracyAverage(r))}</td><td>${esc(r.predictions)}</td><td>${r.eligible?(r.is_leader?'Leader':'Qualified'):`${esc(r.predictions)}/${award.cadence==='monthly'?6:3} predictions${award.cadence==='monthly'?` · ${esc(r.weeks||0)}/2 weeks`:''}`}</td></tr>`).join('')||'<tr><td colspan="4">No predictions with confirmed results yet.</td></tr>'}</tbody></table></div><p class="help">Only another player’s closed entry with an official batted result counts. Pending results, did not bat and cancelled matches are excluded. Exact averages decide ties; corrections update the tally.</p></details>`;}
function callBoardWeekRange(data,{compact=false}={}){if(!data.week_start)return '';const end=new Date(`${data.week_end||data.week_start}T12:00:00Z`);end.setUTCDate(end.getUTCDate()+(data.week_end?-1:6));const first=new Date(`${data.week_start}T12:00:00Z`),format=new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',timeZone:'UTC',...(first.getUTCFullYear()!==end.getUTCFullYear()?{year:'numeric'}:{})});return compact?`${format.format(first)} – ${new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(end)}`:`${formatDateShort(data.week_start)} – ${formatDateShort(end.toISOString().slice(0,10))}`;}
function renderCallAwardGroup(id,title,items,range='',showPrizes=false){
 if(!items.length)return '';
 const pending=items.every(callAwardPending);
 return `<section class="call-award-group" id="${esc(id)}"><header class="call-award-group-heading"><h3>${esc(title)}</h3>${range?`<span class="call-award-group-dates">${esc(range)}</span>`:''}${pending?'<span class="call-award-group-status">Not announced</span>':''}</header><div class="call-awards">${items.map(award=>renderCallAwardCard(award,{hidePending:pending,showPrizes})).join('')}</div></section>`;
}
function renderCallHonours(data){
 const awards=callPeriodAwards(data),weekly=awards.filter(a=>a.cadence!=='monthly'),fourWeek=awards.filter(a=>a.cadence==='monthly'),showPrizes=data.can_view_prizes===true,seasonKeys=['season_points','season_accuracy','season_beats','grinch'].filter(key=>callAwardEnabled(data.settings,key));
 if(!awards.length&&!seasonKeys.length)return '';
 return `<section class="card call-awards-panel" id="callAwards"><h2>Awards</h2>${renderCallAwardGroup('callWeeklyAwards','Weekly Awards',weekly,callBoardWeekRange(data),showPrizes)}${renderCallAwardGroup('callMonthlyAwards','Four-week awards',fourWeek,fourWeek.length?callAwardReleaseRange({period_start:fourWeek[0].period_start,period_end:fourWeek[0].period_end}):'',showPrizes)}${renderCallAwardGroup('callSeasonAwards','Season awards',seasonKeys.map(key=>callSeasonAwardData(data,key)),`${data.season||''}/${String(Number(data.season||0)+1).slice(-2)}`,showPrizes)}</section>`;
}
function renderCallNamedVote(v,c){const candidate=(c.nasty_candidates||[]).find(n=>n.user_id&&n.user_id===v.user_id),rest=Number(candidate?.rest_call),gap=Number(candidate?.gap),show=!!candidate&&Number.isFinite(rest)&&rest>0&&Number.isFinite(gap)&&gap>0&&gap<=rest,percent=show?Math.max(0,Math.min(100,Math.round(100*gap/rest))):0;return `<li><strong>${esc(v.name)}</strong> · ${esc(v.runs)}${show?`<div class="call-nasty-note"><span class="call-nasty-tag">That’s just nasty</span><span class="call-nasty-context">${esc(v.runs)} · others ${esc(rest)} · ${esc(gap)} below</span><span class="call-nasty-meter" role="meter" aria-label="Low prediction compared with the other voters" aria-valuemin="0" aria-valuemax="${rest}" aria-valuenow="${gap}" aria-valuetext="${esc(v.runs)} runs predicted; the other voters’ median is ${rest}; ${gap} runs below"><span style="width:${percent}%"></span></span><small>${c.voting_open||c.result?.status!=='played'?'Provisional: an award needs the official result to reach the other voters’ prediction.':'A low prediction, not a deduction from anyone’s points.'}</small></div>`:''}</li>`;}
function callEntryAction(c){return !c.own&&callVotingOpen(c)?(c.my_vote?'Change prediction':'Predict'):'Closed';}
function renderCallOfficialResultEditor(c){const id=String(c.id),result=callOfficialResult(c);if(!result||callVotingOpen(c))return '';return `<details class="call-result"><summary>${result.status==='pending'?'Record official result':'Correct official result'}</summary><form data-call-form="result-${esc(id)}" id="callResultForm-${esc(id)}"><p class="help">Scores also update My Innings.</p><label for="callResultDate-${esc(id)}">Result date</label><input id="callResultDate-${esc(id)}" type="date" min="${esc(c.match_date)}" max="${esc(todayIso())}" value="${esc(result.score_date||c.match_date)}" required><p class="help">Use the date the score occurred.</p><label for="callResultStatus-${esc(id)}">Result</label><select id="callResultStatus-${esc(id)}">${[['played','Batted'],['did_not_bat','Did not bat / not selected'],['cancelled','Cancelled']].map(([key,label])=>`<option value="${key}" ${result.status===key?'selected':''}>${label}</option>`).join('')}</select><div data-call-result-runs><label for="callRuns-${esc(id)}">Runs</label><input id="callRuns-${esc(id)}" type="number" min="0" max="9999" step="1" inputmode="numeric" value="${result.runs??''}"><label class="call-check"><input type="checkbox" id="callNotOut-${esc(id)}" ${result.not_out?'checked':''}> Not out</label></div>${result.status!=='pending'?`<label for="callCorrection-${esc(id)}">Reason for correction · required</label><input id="callCorrection-${esc(id)}" maxlength="300" placeholder="e.g. Scorebook corrected">`:''}<button type="submit" class="btn">${result.status==='pending'?'Save official result':'Save correction'}</button><p class="status" data-call-status role="status"></p></form></details>`;}
function renderCallCard(c,data,{showDetails=callDetailsReleased(c)}={}){
 const id=String(c.id),released=callDetailsReleased(c),voting=callVotingOpen(c),result=released?c.result||{status:'pending'}:null,mine=c.my_vote,zone=c.timezone||data.settings?.timezone;
 return `<tr class="call-entry-summary ${showDetails?'':'call-entry-blind'}" data-call-entry="${esc(id)}" id="callRow-${esc(id)}" role="row"><th scope="row" class="call-player-cell" role="rowheader"><strong id="callPlayer-${esc(id)}">${esc(c.name)}</strong><span class="call-match-meta">${esc(formatDateShort(c.match_date))} · ${esc(c.opposition||'Opposition not recorded')} · ${esc(formatLabel(c.format_key))}</span>${voting?`<span class="call-entry-state">${esc(callDeadlineLabel(c,zone))}</span>`:''}<span class="call-draft-label" id="callDraft-${esc(id)}" hidden>Unsaved changes</span></th>${showDetails?`<td class="call-summary-number" role="cell"><span class="call-mobile-label">Player’s prediction</span><strong>${released?esc(c.predicted_runs):'—'}</strong></td><td class="call-summary-number" role="cell"><span class="call-mobile-label">Club prediction</span><strong>${released&&c.club_call!=null?esc(c.club_call):'—'}</strong></td>`:''}<td class="call-summary-number call-own-prediction" role="cell"><span class="call-mobile-label">Your prediction</span><strong id="callSaved-${esc(id)}">${mine?esc(mine.runs):'—'}</strong>${voting?`<form data-call-form="vote-${esc(id)}" id="callVoteForm-${esc(id)}" class="call-inline-vote" hidden><input id="callVote-${esc(id)}" type="number" min="0" max="999" step="1" inputmode="numeric" value="${mine?.runs??''}" placeholder="Runs" aria-label="Your prediction for ${esc(c.name)}" required><p class="status" data-call-status role="status"></p></form>`:''}</td>${showDetails?`<td class="call-summary-number" role="cell"><span class="call-mobile-label">Result</span><strong>${result?.status==='played'?esc(callResultText(result)):result?.status==='did_not_bat'?'DNB':result?.status==='cancelled'?'Cancelled':'—'}</strong></td>`:''}<td class="call-summary-action" role="cell">${voting?`<button type="button" class="btn secondary" id="callToggle-${esc(id)}" data-call-toggle="${esc(id)}" aria-controls="callVoteForm-${esc(id)}" aria-expanded="false" aria-label="${esc(callEntryAction(c))} for ${esc(c.name)}">${esc(callEntryAction(c))}</button><div class="call-inline-actions" id="callEditActions-${esc(id)}" hidden><button type="submit" form="callVoteForm-${esc(id)}" class="btn secondary" id="callSave-${esc(id)}">Save</button><button type="button" class="btn ghost" data-call-close="${esc(id)}" aria-label="Cancel prediction for ${esc(c.name)}">×</button></div>`:''}<span class="call-closed" id="callClosed-${esc(id)}" ${voting?'hidden':''}>Closed</span></td></tr>`;
}
function renderCallScoreEntry(c){
 const id=String(c.id),official=callOfficialResult(c),form=renderCallOfficialResultEditor(c).replace(/^<details class="call-result"><summary>.*?<\/summary>/,'').replace(/<\/details>$/,'');
 return `<details class="call-score-entry" id="callScore-${esc(id)}" data-call-score="${esc(id)}" ${ensureMakeYourCallState().scoreId===id?'open':''}><summary><span><strong>${esc(c.name)}</strong><small>${esc(formatDateShort(c.match_date))} · ${esc(c.opposition||'')} · ${esc(formatLabel(c.format_key))}</small></span><span>${official?.status==='pending'?'Record score':esc(callResultText(official))}</span></summary>${form}</details>`;
}
function renderCallScoring(data){
 const entries=data.calls.filter(c=>c.can_record_result===true&&!callVotingOpen(c));
 return `<section class="card call-scoring"><div class="call-board-heading"><h2>Official scores <span class="call-board-range">${esc(callBoardWeekRange(data,{compact:true}))}</span></h2>${renderCallWeekPicker(data)}</div>${entries.map(renderCallScoreEntry).join('')||'<p class="help">No scores to record for this week.</p>'}</section>`;
}
function renderCallWeekPicker(data){const state=ensureMakeYourCallState();return `<details class="call-week-picker"><summary>Change week <span aria-hidden="true">⌄</span></summary><div class="call-week-picker-body"><label for="callWeek">Choose a date in the week</label><div class="btnrow"><button type="button" class="btn ghost" id="callPreviousWeek" aria-label="Previous week">←</button><input id="callWeek" type="date" value="${esc(state.week||data.week_start)}"><button type="button" class="btn ghost" id="callNextWeek" aria-label="Next week">→</button></div></div></details>`;}
function renderCallEntries(data){const state=ensureMakeYourCallState(),entries=(data.calls||[]).filter(c=>!c.own),showDetails=entries.some(callDetailsReleased);if((data.calls||[]).some(c=>c.own&&String(c.id)===state.openId)){state.openId=null;state.savedOpenId=null;}return `<section class="card call-board"><div class="call-board-heading"><h2>Predictions <span class="call-board-range" title="${esc(callBoardWeekRange(data))}">for week ${esc(callBoardWeekRange(data,{compact:true}))}</span></h2>${renderCallWeekPicker(data)}</div><p class="help call-blind-intro">Predictions stay hidden until awards are released.</p><p class="help" id="callDraftCount" hidden></p><table class="call-entries-table ${showDetails?'':'call-blind-table'}" role="table" aria-label="Score predictions for ${esc(callBoardWeekRange(data))}"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader"><div class="call-table-heading"><span>Player & match</span></div></th>${showDetails?'<th scope="col" role="columnheader">Player’s prediction</th><th scope="col" role="columnheader">Club prediction</th>':''}<th scope="col" role="columnheader">Your prediction</th>${showDetails?'<th scope="col" role="columnheader">Result</th>':''}<th scope="col" role="columnheader" class="call-filter-heading"><label class="call-check"><input type="checkbox" id="callNeedsPrediction" ${state.needsPrediction?'checked':''}> Needs my prediction</label></th></tr></thead><tbody role="rowgroup">${entries.map(c=>renderCallCard(c,data,{showDetails})).join('')}</tbody></table><p class="help" id="callNoEntries" role="status" hidden></p></section>`;}
function syncCallEntries(data){
 const state=ensureMakeYourCallState();let visible=0,hiddenDrafts=0;
 for(const c of data.calls||[]){
  const id=String(c.id),row=document.getElementById('callRow-'+id);if(!row)continue;
  const form=document.getElementById('callVoteForm-'+id),button=document.getElementById('callToggle-'+id),actions=document.getElementById('callEditActions-'+id),pending=makeYourCallCommands.has('vote-'+id),voting=callVotingOpen(c),match=!state.needsPrediction||(!c.own&&voting&&!c.my_vote),show=match||pending||state.savedOpenId===id;
  let dirty=!!form&&form.callBaseline!==makeYourCallFormState(form);
  if(!voting&&!pending&&state.openId===id){state.openId=null;if(dirty){document.getElementById('callVote-'+id).value=c.my_vote?.runs??'';dirty=false;const status=document.getElementById('callPageStatus');if(status){status.hidden=false;status.textContent='Predictions closed. Your unsaved change was not submitted.';}}}
  const editing=!!form&&state.openId===id;
  row.hidden=!show;if(show)visible++;if(dirty&&!show)hiddenDrafts++;
  if(form)form.hidden=!editing;
  document.getElementById('callSaved-'+id).hidden=editing;
  if(button){button.hidden=editing||!voting;button.setAttribute('aria-expanded',String(editing));}
  if(actions){actions.hidden=!editing;const save=document.getElementById('callSave-'+id);save.hidden=!voting&&!pending;save.textContent=pending?'Confirm save':'Save';}
  document.getElementById('callClosed-'+id).hidden=voting||editing;
  document.getElementById('callDraft-'+id).hidden=!dirty;
 }
 const empty=document.getElementById('callNoEntries');if(empty){empty.hidden=visible>0;empty.textContent=(data.calls||[]).some(c=>!c.own)?'No open entries need your prediction.':'No teammates have entered a prediction this week yet.';}
 const note=document.getElementById('callDraftCount');if(note){note.hidden=!hiddenDrafts;note.textContent=`${hiddenDrafts} unsaved ${hiddenDrafts===1?'prediction':'predictions'} hidden by the filter.`;}
}
function scheduleCallDeadlineRefresh(data,current){
 clearTimeout(makeYourCallDeadlineTimer);if(!current()||ensureMakeYourCallState().recordResults)return;
 const server=Date.parse(data.server_now),now=Number.isFinite(server)?server+Math.max(0,Date.now()-data._clockSampledAt):Date.now(),deadlines=data.calls.filter(c=>c.voting_open&&!callDetailsReleased(c)).map(c=>Date.parse(c.cutoff_at)).filter(t=>Number.isFinite(t)&&t>now);
 if(deadlines.length)makeYourCallDeadlineTimer=setTimeout(()=>{if(current()){syncCallEntries(data);scheduleCallDeadlineRefresh(data,current);}},Math.min(2147483000,Math.max(1,Math.min(...deadlines)-now+20)));
}
function toggleCallEntry(id,data,{close=false}={}){
 if(makeYourCallSavePending()){alert('Confirm the pending save first.');return;}
 const state=ensureMakeYourCallState(),c=data.calls.find(c=>String(c.id)===id),form=document.getElementById('callVoteForm-'+id);if(!c||!form)return;
 if(close){const input=document.getElementById('callVote-'+id);input.value=c.my_vote?.runs??'';form.querySelector('[data-call-status]').textContent='';state.openId=null;state.savedOpenId=null;}
 else if(!callVotingOpen(c)){syncCallEntries(data);return;}
 else state.openId=id;
 syncCallEntries(data);
 if(state.openId)document.getElementById('callVote-'+id)?.focus({preventScroll:true});else document.getElementById('callToggle-'+id)?.focus({preventScroll:true});
}
function renderCallAwardSetting(key,s){
 const rewards=s.rewards||{},enabled=callAwardEnabled(s,key),label=key==='grinch'?(s.grinch_name||'The Grinch'):CALL_RECURRING_AWARDS.includes(key)?callAwardLabel(key):CALL_REWARD_LABELS[key];
 return `<div class="call-award-setting"><label class="call-check"><input type="checkbox" id="${callAwardCheckboxId(key)}" ${enabled?'checked':''}> ${esc(label)}</label><div id="callAwardOptions-${key}" ${enabled?'':'hidden'}>${key==='grinch'?`<label class="help" for="callGrinchName">Award name</label><input id="callGrinchName" maxlength="60" value="${esc(s.grinch_name||'The Grinch')}">`:''}<label class="help" for="callReward-${key}">Prize (optional)</label><input id="callReward-${key}" maxlength="300" value="${esc(rewards[key]||'')}" placeholder="Leave blank for recognition only">${renderCallClaimSetting(key,rewards)}${CALL_RECURRING_AWARDS.includes(key)?`<label class="help" for="callCadence-${key}">Award frequency</label><select id="callCadence-${key}"><option value="weekly" ${s.award_cadence?.[key]==='monthly'?'':'selected'}>Weekly</option><option value="monthly" ${s.award_cadence?.[key]==='monthly'?'selected':''}>Every 4 weeks</option></select>`:''}</div></div>`;
}
function renderCallSettings(data){
 if(!data.can_manage)return '';const s=data.settings||{},state=ensureMakeYourCallState(),editing=state.editSettings,staff=(data.members||[]).filter(m=>['captain','coach','head_coach','admin','lead_admin'].includes(m.permission_role));let suggested='Australia/Sydney';try{suggested=Intl.DateTimeFormat().resolvedOptions().timeZone||suggested;}catch{}
 return `<section class="card call-settings" id="callSettingsEditor" ${editing?'':'hidden'}><h2>Club setup</h2><form data-call-form="settings" id="callSettingsForm"><p class="help">Tick the awards your club wants to include. Set a prize, collection condition and frequency where needed, then save once.</p><label class="call-check"><input type="checkbox" id="callEnabled" ${s.enabled?'checked':''}> Enable Make your prediction</label><label class="call-check"><input type="checkbox" id="callConversationEnabled" ${s.conversation_enabled===true?'checked':''}> Include Club Conversation</label><label for="callTimezone">Club timezone</label><input id="callTimezone" value="${esc(s.timezone||suggested)}" placeholder="Australia/Sydney" required><p class="help">Entries and votes close at midnight at the start of the nominated match date. Existing published deadlines stay fixed.</p><div class="call-settings-grid"><div><label for="callWeekStartDay">Our award week starts on</label><select id="callWeekStartDay">${CALL_WEEK_DAYS.map((day,i)=>`<option value="${i}" ${Number(s.week_start_day??1)===i?'selected':''}>${day}</option>`).join('')}</select></div><div><label for="callSeasonMonth">Season starts</label><select id="callSeasonMonth">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${(s.season_start_month||7)===i+1?'selected':''}>${new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1)))}</option>`).join('')}</select></div></div><p class="help" id="callScheduleHelp">${esc(s.schedule_help||'Prize and frequency changes update current and future periods. Closed periods keep their saved prizes.')}${s.week_start_effective?` Weekday changes take effect ${esc(formatDateShort(s.week_start_effective))}; existing weeks stay intact.`:''}</p><label for="callSeasonAwardsVisibility">Season standings</label><select id="callSeasonAwardsVisibility"><option value="live" ${s.season_awards_visibility!=='on_release'?'selected':''}>Live — show current leaders</option><option value="on_release" ${s.season_awards_visibility==='on_release'?'selected':''}>Hold until released</option></select><p class="help">Weekly and four-week awards wait for your club to release them.</p><h3>Awards</h3><p class="help">Unticked awards stay out of the current page and future announcements.</p><div class="call-settings-grid">${CALL_AWARD_KEYS.map(key=>renderCallAwardSetting(key,s)).join('')}</div><div id="callFourWeekSettings"><label for="callFourWeekStart">First four-week award period starts</label><input type="date" id="callFourWeekStart" value="${esc(s.award_cycle_start||data.release_defaults?.weekly?.period_end||data.week_start||'')}"><p class="help">Choose the first award week. Awards then cover four club weeks at a time.</p></div><div class="btnrow"><button type="submit" class="btn" id="callSaveSettings">Save club setup</button><button type="button" class="btn ghost" id="callCancelSettings">Close editor</button></div><p class="status" data-call-status role="status"></p></form><details class="call-result-permissions"><summary>Result permissions</summary><p class="help">Tick everyone who should record official results, then save once. Captains, Coaches and Head Coaches also need existing edit access to each player. Club Admin access is included.</p><form data-call-form="grants" id="callGrantsForm">${staff.map(m=>`<label class="call-check call-permission-row"><input type="checkbox" id="callGrant-${esc(m.user_id)}" ${m.can_record_results?'checked':''} ${['admin','lead_admin'].includes(m.permission_role)?'disabled':''}><span><strong>${esc(m.name)}</strong><small>${esc(String(m.permission_role).replaceAll('_',' '))}${['admin','lead_admin'].includes(m.permission_role)?' · included':''}</small></span></label>`).join('')||'<p class="help">No eligible staff to grant yet.</p>'}<button class="btn" type="submit" id="callSaveGrants">Saved ✓</button><p class="status" data-call-status role="status"></p></form></details></section>`;}
function syncCallSettingsForms(){for(const key of CALL_AWARD_KEYS){const options=document.getElementById('callAwardOptions-'+key);if(options)options.hidden=!callAwardChoiceChecked(key);}const fourWeek=document.getElementById('callFourWeekSettings');if(fourWeek)fourWeek.hidden=!CALL_RECURRING_AWARDS.some(key=>callAwardChoiceChecked(key)&&document.getElementById('callCadence-'+key)?.value==='monthly');for(const key of CALL_AWARD_KEYS){const reward=document.getElementById('callReward-'+key),condition=document.getElementById('callClaimSetting-'+key);if(reward&&condition)condition.hidden=!reward.value.trim();}for(const [id,buttonId,label]of [['callSettingsForm','callSaveSettings','Save club setup'],['callGrantsForm','callSaveGrants','Save permissions']]){const form=document.getElementById(id),button=document.getElementById(buttonId);if(!form||!button)continue;const pending=makeYourCallCommands.has(form.dataset.callForm),dirty=form.callBaseline!==makeYourCallFormState(form),initial=id==='callSettingsForm'&&!makeYourCallCache?.settings?.timezone;button.disabled=makeYourCallSaving||(!pending&&!dirty&&!initial);button.textContent=pending?'Confirm save':dirty||initial?label:'Saved ✓';button.classList.toggle('secondary',!dirty&&!initial&&!pending);}}
function renderCallGrinch(data){if(!data.settings?.grinch_enabled)return '';const pending=callSeasonVisibility(data).pending,rows=pending?[]:data.grinch_rows||[],best=Math.max(0,...rows.map(r=>Number(r.low_calls)||0)),winners=rows.filter(r=>best>0&&Number(r.low_calls)===best);return `<div class="notice compact call-grinch-award"><h3>${esc(data.settings.grinch_name||'The Grinch')}</h3>${renderCallAwardHelp('grinch','season',data.settings.grinch_name||'The Grinch')}${winners.length?winners.map(r=>`<p><strong>${esc(r.name)}</strong> · ${esc(r.low_calls)} of ${esc(r.comparable_calls)} calls proved too low</p>`).join(''):`<p class="help">${pending?'Results will be announced here.':'No one qualifies yet.'}</p>`}<p class="help">${esc(callRewardText(data.settings.rewards,'grinch'))}</p>${renderCallClaim(data.settings.rewards,'grinch')}</div>`;}
function renderCallSeason(){return '';}
function renderCallMessages(data){if(data.settings?.conversation_enabled!==true)return '';return `<section class="card call-conversation"><h2>Club Conversation</h2><p class="help">For your club. Back a teammate and keep the banter kind.</p><div class="call-messages">${(data.messages||[]).map(m=>`<article><header class="call-message-heading"><div class="call-message-byline"><strong>${esc(m.name)}</strong><time datetime="${esc(m.created_at)}">${esc(callDateTime(m.created_at,data.settings?.timezone))}</time></div><div class="call-message-actions">${m.can_delete?`<button class="btn ghost" type="button" data-call-delete="${esc(m.id)}">Remove</button>`:''}${m.reported?'<span class="help">Reported to Club Admin</span>':`<button class="btn ghost" type="button" data-call-report="${esc(m.id)}">Report</button>`}</div></header><p class="call-message-body">${esc(m.body)}</p></article>`).join('')||'<p class="help">No messages yet. Start the conversation.</p>'}</div><form data-call-form="message" id="callMessageForm"><label for="callMessage">Your message</label><textarea id="callMessage" maxlength="500" rows="2" placeholder="Back a teammate. Keep the banter kind."></textarea><button class="btn" type="submit">Post to this week</button><p class="status" data-call-status role="status"></p></form>${data.can_manage&&(data.reports||[]).length?`<details><summary>Reported messages (${data.reports.length})</summary>${data.reports.map(r=>`<p><strong>${esc(r.reporter_name)}</strong>: ${esc(r.reason)} <button class="btn ghost" data-call-delete="${esc(r.message_id)}">Remove reported message</button></p>`).join('')}</details>`:''}</section>`;}
