function captureCallDrafts(){const drafts=new Map();for(const form of document.querySelectorAll('[data-call-form]'))if(form.callBaseline!==makeYourCallFormState(form))drafts.set(form.dataset.callForm,[...form.querySelectorAll('input,textarea,select')].map(f=>({id:f.id,value:f.value,checked:f.checked})));return drafts;}
async function renderMakeYourCall({message='',drafts=null}={}){if(typeof ensureCallResultsState==='function'&&ensureCallResultsState().view==='history')return renderCallResultsHistory();const page=document.getElementById('page'),state=ensureMakeYourCallState(),scope=state.scope,sequence=++makeYourCallSequence;const current=()=>currentTab==='make_your_call'&&ensureMakeYourCallState().scope===scope&&sequence===makeYourCallSequence&&document.getElementById('page')===page;page.innerHTML='<p class="splash">Loading Make your prediction…</p>';try{const {data,error}=await supabase.rpc('get_make_your_call_periods',{p_club_id:club.id,p_week_start:state.week,p_season:state.season,p_month_start:state.month});if(error)throw error;if(!data?.settings||!Array.isArray(data.calls))throw new Error('The club board could not be confirmed.');if(!current())return;makeYourCallCache=data;data._clockSampledAt=Date.now();state.week=data.selection_date||data.week_start;state.month=data.month_start||null;state.season=data.season;
if(!data.calls.some(c=>c.can_record_result===true))state.recordResults=false;
const weeks=[...new Set([data.week_start,...(data.weeks||[])])].sort().reverse(),seasons=[...new Set([Number(data.season),...weeks.map(w=>Number(w.slice(0,4))-(Number(w.slice(5,7))<(data.settings.season_start_month||7)?1:0))])].sort((a,b)=>b-a);
page.innerHTML=`${callStyles()}<div class="call-page"><section class="card call-page-header"><div class="call-header-title"><div class="call-header-copy"><h1>${state.recordResults?'Record results':'Make your prediction'}</h1>${state.recordResults?'':'<p>Back your batting. Predict your teammates’ scores.</p>'}${!state.recordResults&&isPlayerUser()?'<div class="call-header-actions"><button class="btn secondary" id="callPrepare">Predict Your Score</button></div>':''}</div><div class="call-header-tools">${data.calls.some(c=>c.can_record_result===true)?`<button type="button" class="btn ghost" id="callRecordResults">${state.recordResults?'← Predictions':'Record results'}</button>`:''}${!state.recordResults&&data.can_manage?`<button type="button" class="btn ghost" id="callEditSettings" aria-controls="callSettingsEditor" aria-expanded="${!!state.editSettings}" ${state.editSettings?'hidden':''}>${callAwardsSetupLabel(data.settings)}</button>`:''}<button type="button" class="btn ghost" id="callResultsHistory">Results history</button></div></div><p id="callPageStatus" role="status" ${message?'':'hidden'}>${esc(message)}</p></section>${state.recordResults?'':renderCallSettings(data)}${!data.settings.enabled?'<section class="card notice"><h2>Make your prediction is not enabled yet.</h2><p>Your club’s Admin can enable it in Club setup. Private match predictions remain available in My Innings.</p></section>':state.recordResults?renderCallScoring(data):`${renderCallEntries(data)}${typeof renderCallAwardReleaseControls==='function'?renderCallAwardReleaseControls(data):''}${renderCallHonours(data)}${renderCallMessages(data)}`}${!state.recordResults&&myPlayer&&isPlayerUser()&&typeof renderEngagementShell==='function'?renderEngagementShell('callEngagement'):''}</div>`;
for(const form of page.querySelectorAll('[data-call-form]')){form.callBaseline=makeYourCallFormState(form);for(const draft of drafts?.get(form.dataset.callForm)||[]){const f=document.getElementById(draft.id);if(f&&form.contains(f)){f.value=draft.value;if('checked'in f)f.checked=draft.checked;}}}
for(const [key]of drafts||[])if(key.startsWith('result-')){const detail=document.getElementById('callScore-'+key.slice(7));if(detail)detail.open=true;}
if(drafts?.has('settings')){state.editSettings=true;document.getElementById('callSettingsEditor').hidden=false;document.getElementById('callEditSettings').hidden=true;}
bindMakeYourCall(data,current);recordAppNavigation(clubNavigationRoute());if(myPlayer&&isPlayerUser()&&typeof mountEngagement==='function')await mountEngagement(document.getElementById('callEngagement'),{clubId:club.id});
}catch(error){if(current()){page.innerHTML=`<section class="card"><h1>Make your prediction</h1><p>${esc(error?.message||'Could not load the board.')}</p><button class="btn" id="callRetry">Try again</button></section>`;document.getElementById('callRetry').onclick=()=>renderMakeYourCall({message,drafts});}}}
async function saveCallMutation(form,rpc,values,current,success){if(makeYourCallSaving||!current())return;if(typeof callAwardReleaseSavePending==='function'&&callAwardReleaseSavePending()){alert('Confirm the pending award release before saving other changes.');return;}const key=form?.dataset.callForm||rpc;if(makeYourCallCommands.size&&!makeYourCallCommands.has(key)){alert('Confirm the pending save first.');return;}const status=form?.querySelector('[data-call-status]')||document.getElementById('callPageStatus');let command=makeYourCallCommands.get(key);if(!command)command={rpc,args:{p_club_id:club.id,p_request_id:preparationUuid(),p_values:values}};makeYourCallCommands.set(key,command);makeYourCallSaving=true;const controls=[...document.querySelectorAll('.call-page input,.call-page textarea,.call-page select,.call-page button')].map(f=>[f,f.disabled]);controls.forEach(([f])=>f.disabled=true);if(status){status.hidden=false;status.textContent='Saving…';}try{const {data,error}=await supabase.rpc(command.rpc,command.args);if(error)throw error;if(data?.ok!==true)throw new Error('Could not confirm the save.');makeYourCallCommands.delete(key);if(!current())return;if(key.startsWith('vote-')){const s=ensureMakeYourCallState();s.savedOpenId=key.slice(5);s.openId=null;}if(key==='settings')ensureMakeYourCallState().editSettings=false;const focusId=document.activeElement?.id;const drafts=captureCallDrafts();drafts.delete(key);await renderMakeYourCall({message:success?(data.already_saved?'Previous save confirmed. '+success:success):'',drafts});if(currentTab==='make_your_call'){const focus=(key.startsWith('vote-')?document.getElementById('callToggle-'+key.slice(5)):key==='settings'?document.getElementById('callEditSettings'):null)||document.getElementById(focusId||'')||form?.id&&document.getElementById(form.id)?.querySelector('input,textarea,select');focus?.focus({preventScroll:true});}}catch(error){if(definiteInningsSaveFailure(error)){makeYourCallCommands.delete(key);}if(current()&&status){status.textContent=(error?.message||'Could not confirm the save.')+(makeYourCallCommands.has(key)?' Retry the same save to confirm it; these fields stay locked until then.':' Your changes are still here. Load the latest saved data, then try again.');if(!makeYourCallCommands.has(key)){status.insertAdjacentHTML('beforeend',' <button type="button" class="btn ghost" id="callReloadLatest">Load latest saved data</button>');document.getElementById('callReloadLatest').onclick=()=>{if(!makeYourCallSavePending())return renderMakeYourCall({drafts:captureCallDrafts()});};}if(makeYourCallCommands.has(key)&&!form){status.insertAdjacentHTML('beforeend','<button type="button" class="btn secondary" id="retryCallAction">Confirm previous action</button>');document.getElementById('retryCallAction').onclick=()=>saveCallMutation(null,rpc,null,current,success);}}}finally{makeYourCallSaving=false;for(const [f,disabled]of controls)if(document.documentElement.contains(f))f.disabled=disabled;if(makeYourCallCommands.has(key)&&form){for(const f of form.querySelectorAll('input,textarea,select'))f.disabled=true;const retry=document.getElementById('callSave-'+key.slice(5));if(key.startsWith('vote-')&&retry)retry.textContent='Confirm save';}syncCallSettingsForms();}}
function bindMakeYourCall(data,current){scheduleCallDeadlineRefresh(data,current);const page=document.getElementById('page');bindCallAwardHelp(page);bindCallTallies(page);if(typeof wireCallAwardReleaseControls==='function')wireCallAwardReleaseControls(data,current);const submit=(id,rpc,values,success)=>{const form=document.getElementById(id);if(!form)return;form.onsubmit=async e=>{e.preventDefault();if(makeYourCallSaving)return;let value;try{value=makeYourCallCommands.has(form.dataset.callForm)?null:values();}catch(error){form.querySelector('[data-call-status]').textContent=error.message;return;}return saveCallMutation(form,rpc,value,current,success);};};
page.querySelectorAll('[data-call-toggle]').forEach(b=>b.onclick=()=>toggleCallEntry(b.dataset.callToggle,data));page.querySelectorAll('[data-call-close]').forEach(b=>b.onclick=()=>toggleCallEntry(b.dataset.callClose,data,{close:true}));
const needs=document.getElementById('callNeedsPrediction');if(needs)needs.onchange=()=>{const state=ensureMakeYourCallState();if(makeYourCallSavePending()){needs.checked=!!state.needsPrediction;alert('Confirm the pending save before changing the entry filter.');return;}state.savedOpenId=null;state.query='';state.needsPrediction=!!needs.checked;syncCallEntries(data);};
page.querySelectorAll('[data-call-form]').forEach(form=>{const changed=()=>{syncCallEntries(data);syncCallSettingsForms();};form.addEventListener('input',changed);form.addEventListener('change',changed);});syncCallEntries(data);syncCallSettingsForms();
const editor=document.getElementById('callSettingsEditor'),edit=document.getElementById('callEditSettings');if(edit)edit.onclick=()=>{ensureMakeYourCallState().editSettings=true;editor.hidden=false;edit.hidden=true;edit.setAttribute('aria-expanded','true');document.getElementById('callEnabled')?.focus({preventScroll:true});editor.scrollIntoView({block:'start',behavior:'smooth'});};const cancel=document.getElementById('callCancelSettings');if(cancel)cancel.onclick=()=>{if(makeYourCallSavePending()){alert('Confirm the pending save before closing the editor.');return;}const form=document.getElementById('callSettingsForm');if(form.callBaseline!==makeYourCallFormState(form)&&!confirm('Discard these unsaved club setup changes?'))return;for(const [id,value,checked]of JSON.parse(form.callBaseline)){const field=document.getElementById(id);if(field){field.value=value;field.checked=checked;}}ensureMakeYourCallState().editSettings=false;editor.hidden=true;edit.hidden=false;edit.setAttribute('aria-expanded','false');syncCallSettingsForms();edit.focus({preventScroll:true});};
document.getElementById('callRecordResults')?.addEventListener('click',async()=>{if(!confirmLeaveMakeYourCall())return;const s=ensureMakeYourCallState();s.recordResults=!s.recordResults;s.editSettings=false;s.openId=null;s.savedOpenId=null;await renderMakeYourCall();window.scrollTo({top:0,behavior:'instant'});});page.querySelectorAll('[data-call-score]').forEach(el=>el.addEventListener('toggle',()=>{if(el.isConnected&&el.open)ensureMakeYourCallState().scoreId=el.dataset.callScore;}));
document.getElementById('callResultsHistory')?.addEventListener('click',()=>{if(typeof openCallResultsHistory==='function')return openCallResultsHistory();});document.getElementById('callPrepare')?.addEventListener('click',()=>openMyInnings({prepare:true}));
for(const [id,key]of [['callWeek','week'],['callSeason','season']])document.getElementById(id)?.addEventListener('change',async e=>{const state=ensureMakeYourCallState(),value=e.target.value;if(!confirmLeaveMakeYourCall()){e.target.value=state[key];return;}if(key==='week'&&!/^\d{4}-\d{2}-\d{2}$/.test(value)){e.target.value=state.week;return;}state[key]=key==='season'?Number(value):value;if(key==='week'){state.month=null;state.season=null;}state.openId=null;state.savedOpenId=null;await renderMakeYourCall();});
for(const [id,offset]of [['callPreviousWeek',-7],['callNextWeek',7]])document.getElementById(id)?.addEventListener('click',async()=>{if(!confirmLeaveMakeYourCall())return;const state=ensureMakeYourCallState(),date=new Date(`${offset>0?(data.week_end||state.week):data.week_start}T12:00:00Z`);if(offset<0)date.setUTCDate(date.getUTCDate()-1);else if(!data.week_end)date.setUTCDate(date.getUTCDate()+7);state.week=date.toISOString().slice(0,10);state.month=null;state.season=null;state.openId=null;state.savedOpenId=null;await renderMakeYourCall();});
document.getElementById('callToday')?.addEventListener('click',async()=>{if(!confirmLeaveMakeYourCall())return;const state=ensureMakeYourCallState();state.week=null;state.openId=null;state.savedOpenId=null;await renderMakeYourCall();});document.getElementById('callMonth')?.addEventListener('change',async e=>{const state=ensureMakeYourCallState(),value=e.target.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!confirmLeaveMakeYourCall()){e.target.value=state.month||state.week;return;}state.month=value;await renderMakeYourCall();});

submit('callSettingsForm','save_make_your_call_settings',()=>{const timezone=val('callTimezone');try{new Intl.DateTimeFormat(undefined,{timeZone:timezone});}catch{throw new Error('Enter a valid club timezone, for example Australia/Sydney.');}const fourWeekStart=val('callFourWeekStart'),fourWeekEnabled=CALL_RECURRING_AWARDS.some(key=>callAwardChoiceChecked(key)&&val('callCadence-'+key)==='monthly');if(fourWeekEnabled&&!/^\d{4}-\d{2}-\d{2}$/.test(fourWeekStart))throw new Error('Choose the first week for your four-week awards.');return {...(fourWeekEnabled&&fourWeekStart?{award_cycle_start:fourWeekStart}:{}),expected_revision:data.settings.revision||0,enabled:document.getElementById('callEnabled').checked,conversation_enabled:document.getElementById('callConversationEnabled').checked,award_enabled:Object.fromEntries(CALL_AWARD_KEYS.filter(k=>k!=='grinch').map(k=>[k,callAwardChoiceChecked(k)])),timezone,season_start_month:Number(val('callSeasonMonth')),season_awards_visibility:val('callSeasonAwardsVisibility')||'live',week_start_day:Number(val('callWeekStartDay')),award_cadence:Object.fromEntries(CALL_RECURRING_AWARDS.map(key=>[key,val('callCadence-'+key)])),grinch_enabled:document.getElementById('callGrinchEnabled').checked,grinch_name:val('callGrinchName')||'The Grinch',rewards:Object.fromEntries(CALL_AWARD_KEYS.flatMap(k=>[[k,val('callReward-'+k)],[k+'_claim',val('callReward-'+k+'_claim')]]))};},'');
submit('callGrantsForm','save_make_your_call_settings',()=>({action:'grants',expected_revision:data.settings.revision||0,grants:(data.members||[]).filter(m=>['captain','coach','head_coach'].includes(m.permission_role)).map(m=>({user_id:m.user_id,allowed:document.getElementById('callGrant-'+m.user_id).checked}))}),'Result permissions saved.');
for(const c of data.calls||[]){const slider=document.getElementById('callVoteRange-'+c.id),numeric=document.getElementById('callVote-'+c.id);if(slider&&numeric){const syncSlider=()=>{const value=String(numeric.value).trim(),valid=/^\d+$/.test(value)&&Number(value)<=999;slider.classList.toggle('call-vote-unset',!valid);slider.setAttribute('aria-valuetext',valid?value+' runs':'No prediction selected');if(valid){slider.setAttribute('max',String(callVoteSliderMaximum(value)));slider.value=value;}else slider.value='0';};slider.oninput=()=>{numeric.value=slider.value;syncSlider();};numeric.oninput=syncSlider;syncSlider();}submit('callVoteForm-'+c.id,'save_make_your_call_vote',()=>{if(!callVotingOpen(c))throw new Error('Predictions closed at midnight as this match date began.');return {entry_id:c.id,runs:callNumber(val('callVote-'+c.id),999,'Your prediction'),expected_revision:c.my_vote?.revision||0};},'Saved ✓');submit('callResultForm-'+c.id,'save_make_your_call_result',()=>{const status=val('callResultStatus-'+c.id),reason=val('callCorrection-'+c.id),official=callOfficialResult(c);if(official?.status!=='pending'&&!reason)throw new Error('Add the reason for correcting this result.');return {entry_id:c.id,expected_revision:official?.revision||0,status,score_date:val('callResultDate-'+c.id)||official?.score_date||c.match_date,runs:status==='played'?callNumber(val('callRuns-'+c.id),9999,'Official runs'):null,not_out:status==='played'&&document.getElementById('callNotOut-'+c.id).checked,reason};},'Official result saved. Game totals and the player’s My Innings use this result.');const resultStatus=document.getElementById('callResultStatus-'+c.id);if(resultStatus){const sync=()=>{document.getElementById('callResultForm-'+c.id).querySelector('[data-call-result-runs]').hidden=resultStatus.value!=='played';};resultStatus.onchange=sync;sync();}}
submit('callMessageForm','save_make_your_call_message',()=>{const body=val('callMessage');if(!body)throw new Error('Write a short message first.');return {action:'post',week_start:data.week_start,body};},'Posted to this week’s club conversation.');
page.querySelectorAll('[data-call-preparation]').forEach(b=>b.onclick=async()=>{if(!await saveClubEditsBeforeNavigation())return;const s=ensureMyInningsState();s.season='all';s.editId=null;s.openId=b.dataset.callPreparation;currentTab='innings';await renderTab();const prep=myInningsCache?.preparations?.find(p=>p.id===b.dataset.callPreparation);if(prep?.match_id&&s.openId!==prep.match_id){s.openId=prep.match_id;await renderMyInnings({refresh:false});}});
page.querySelectorAll('[data-call-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this message from the club conversation?'))return;return saveCallMutation(null,'save_make_your_call_message',{action:'delete',message_id:b.dataset.callDelete},current,'Message removed.');});
page.querySelectorAll('[data-call-report]').forEach(b=>b.onclick=()=>{const reason=prompt('Why should Club Admin review this message?');if(!reason?.trim())return;return saveCallMutation(null,'save_make_your_call_message',{action:'report',message_id:b.dataset.callReport,reason:reason.trim().slice(0,300)},current,'Reported to Club Admin.');});}
