// BEGIN PREDICTION RESULTS — read-only history of explicitly announced awards.
let callResultsState=null,callResultsSequence=0;
function ensureCallResultsState(){
 const scope=`${club?.id||''}:${session?.user?.id||''}`;
 if(callResultsState?.scope!==scope){callResultsSequence++;callResultsState={scope,view:'board',season:null,kind:'',openKind:null,openStart:null,data:null,detail:null,loading:false,detailLoading:false,error:'',detailError:''};}
 return callResultsState;
}
function serializeCallResultsState(){const s=ensureCallResultsState();return {view:s.view,season:s.season,kind:s.kind,openKind:s.openKind,openStart:s.openStart};}
function restoreCallResultsState(saved={}){
 const s=ensureCallResultsState();callResultsSequence++;
 s.view=saved.view==='history'?'history':'board';s.season=Number.isInteger(saved.season)&&saved.season>=1900&&saved.season<=2200?saved.season:null;
 s.kind=['weekly','monthly','season'].includes(saved.kind)?saved.kind:'';
 s.openKind=['weekly','monthly','season'].includes(saved.openKind)?saved.openKind:null;s.openStart=/^\d{4}-\d{2}-\d{2}$/.test(saved.openStart||'')?saved.openStart:null;
 if(!s.openKind||!s.openStart){s.openKind=null;s.openStart=null;}
 s.data=null;s.detail=null;s.error='';s.detailError='';s.loading=false;s.detailLoading=false;return s;
}
function callResultsActive(scope,sequence){return currentTab==='make_your_call'&&ensureCallResultsState().scope===scope&&callResultsState.view==='history'&&sequence===callResultsSequence;}
function callResultsRecordRoute(){if(typeof recordAppNavigation==='function')recordAppNavigation(clubNavigationRoute());}
function callResultsFocus(id){const el=document.getElementById(id);if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}}
async function openCallResultsHistory({periodKind=null,periodStart=null}={}){
 if(!canOpenClubTab('make_your_call')||!confirmLeaveMakeYourCall())return;
 const s=ensureCallResultsState();if(['weekly','monthly','season'].includes(periodKind)&&/^\d{4}-\d{2}-\d{2}$/.test(periodStart||'')){s.season=null;s.kind=periodKind;s.openKind=periodKind;s.openStart=periodStart;}s.view='history';makeYourCallSequence++;currentTab='make_your_call';
 await renderTab();if(s===callResultsState&&s.view==='history'){window.scrollTo?.({top:0,left:0,behavior:'instant'});callResultsFocus('predictionResultsHeading');}
}
async function closeCallResultsHistory(){
 const s=ensureCallResultsState();callResultsSequence++;s.view='board';s.detail=null;s.data=null;await renderTab();
 if(s===callResultsState&&s.view==='board'){window.scrollTo?.({top:0,left:0,behavior:'instant'});document.getElementById('callResultsHistory')?.focus({preventScroll:true});}
}
function callResultsSeasonLabel(year){return `${year}/${String(Number(year)+1).slice(-2)}`;}
function callResultsKindLabel(kind,basis){return kind==='monthly'?(basis==='legacy_calendar'?'Monthly awards':'Four-week awards'):kind==='season'?'Season awards':'Weekly awards';}
function callResultsRange(period){return typeof callAwardReleaseRange==='function'?callAwardReleaseRange(period):`${period.period_start} – ${period.period_end}`;}
function callResultsAwardLabel(award){return award.key==='grinch'?(award.label||'The Grinch'):typeof callAwardLabel==='function'?callAwardLabel(award.key,award.cadence):award.label||'Club award';}
function callResultsStyles(){return `<style>
 .prediction-results{min-width:0}.prediction-results .card{padding:16px!important}.prediction-results-header{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.prediction-results-header h1{font-size:24px;margin:0}.prediction-results p.help{margin:6px 0}.prediction-results-toolbar{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-top:12px}.prediction-results-toolbar label{display:block;font-size:12px;font-weight:700;margin-bottom:4px}.prediction-results-toolbar select{min-height:44px;max-width:100%}.prediction-results .btn{min-height:44px}.prediction-result-row{border-bottom:1px solid #dce1ed}.prediction-result-summary{display:flex;align-items:center;gap:10px;padding:10px 0;min-width:0}.prediction-result-summary>div{flex:1;min-width:0}.prediction-result-summary strong{font-size:14px}.prediction-result-summary small{display:block;font-size:12px;color:var(--muted,#54617e);margin-top:2px}.prediction-result-summary .btn{padding:8px 14px;flex:none;font-size:12px}.prediction-result-detail{background:#f5f6fc;border:1px solid #dce1ed;border-radius:9px;padding:12px;margin-bottom:10px;min-width:0}.prediction-result-detail h2{font-size:16px;margin:0 0 6px}.prediction-result-detail h3{font-size:14px;margin:12px 0 6px}.prediction-history-award{padding:9px 0;border-bottom:1px solid #e0e4ef}.prediction-history-award:last-child{border-bottom:0}.prediction-history-award p{font-size:13px;margin:3px 0;line-height:1.45}.prediction-history-award>strong{font-size:14px}.prediction-history-award .help{font-size:12px}.prediction-results-table-wrap{overflow:auto;max-width:100%}.prediction-results-table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}.prediction-results-table th,.prediction-results-table td{padding:9px 7px;border-bottom:1px solid #dce1ed;vertical-align:top}.prediction-results-table th{font-weight:700}.prediction-results-table small{display:block;font-weight:400;color:var(--muted,#54617e);margin-top:3px}.prediction-results-empty{padding:12px 0;color:var(--muted,#54617e)}.prediction-results-error{padding:10px;background:#fff3e8;border-radius:8px}.prediction-history-award-list{margin:0;padding:0;list-style:none}
 @media(max-width:480px){.prediction-results .card{padding:12px!important}.prediction-results-toolbar{gap:8px}.prediction-results-toolbar>div{flex:1;min-width:120px}.prediction-results-toolbar select{width:100%}.prediction-results-header h1{font-size:22px}.prediction-results-table th,.prediction-results-table td{padding:8px 4px;font-size:11px}.prediction-result-detail{padding:10px}.prediction-result-summary strong{font-size:13px}}
 </style>`;}
function renderCallResultsAwards(awards,showPrizes=false){return `<ul class="prediction-history-award-list">${awards.map(a=>{const prize=showPrizes?String(a.reward_text||'').trim():'';return `<li class="prediction-history-award"><strong>${esc(callResultsAwardLabel(a))}</strong>${(a.winners||[]).length?a.winners.map(w=>`<p><strong>${esc(w.name||'Club member')}</strong>${w.detail?` · ${esc(w.detail)}`:''}</p>`).join(''):'<p class="help">No qualifying winner announced.</p>'}${prize?`<p>Prize: ${esc(prize)}</p>${a.claim_text?`<p class="help">To claim: ${esc(a.claim_text)}</p>`:''}`:''}</li>`;}).join('')}</ul>`;}
function renderCallResultsScores(rows){
 if(!rows.length)return '';
 return `<h3>Match results</h3><div class="prediction-results-table-wrap"><table class="prediction-results-table"><caption class="call-sr-only">Player and club predictions compared with the announced official score</caption><thead><tr><th scope="col">Batter</th><th scope="col">Their prediction</th><th scope="col">Club prediction</th><th scope="col">Score</th><th scope="col">Points</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.name||'Club member')}<small>${esc(typeof formatDateShort==='function'?formatDateShort(r.match_date):r.match_date||'')}${r.opposition?` · ${esc(r.opposition)}`:''}</small></th><td>${esc(r.predicted_runs??'—')}</td><td>${esc(r.club_call??'—')}</td><td>${esc(typeof callResultText==='function'?callResultText(r.result):r.result?.runs??'—')}</td><td>${esc(r.eligible===false?'—':r.points??'—')}${typeof callPointsBasis==='function'&&callPointsBasis(r)?`<small>${esc(callPointsBasis(r))}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`;
}
function renderCallResultsSeasonTables(detail){
 if(detail.period_kind!=='season')return '';
 const batting=detail.season_rows||[],accuracy=detail.accuracy_season_rows||[],grinch=detail.grinch_rows||[];
 return `${batting.length?`<h3>Season batting tally</h3><div class="prediction-results-table-wrap"><table class="prediction-results-table"><thead><tr><th scope="col">Player</th><th scope="col">Points</th><th scope="col">Club predictions beaten</th></tr></thead><tbody>${batting.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${esc(r.points??0)}</td><td>${esc(r.beat_count??0)}</td></tr>`).join('')}</tbody></table></div>`:''}${accuracy.length?`<h3>Season Best Judge tally</h3><div class="prediction-results-table-wrap"><table class="prediction-results-table"><thead><tr><th scope="col">Predictor</th><th scope="col">Avg. runs away</th><th scope="col">Predictions</th><th scope="col">Weeks</th></tr></thead><tbody>${accuracy.map(r=>`<tr><th scope="row">${esc(r.name)}${r.eligible===false?'<small>Not yet qualified</small>':''}</th><td>${esc(callAccuracyAverage(r))}</td><td>${esc(r.predictions??0)}</td><td>${esc(r.weeks??0)}</td></tr>`).join('')}</tbody></table></div>`:''}${grinch.length?`<h3>${esc((detail.awards||[]).find(a=>a.key==='grinch')?.label||'The Grinch')} tally</h3><div class="prediction-results-table-wrap"><table class="prediction-results-table"><thead><tr><th scope="col">Predictor</th><th scope="col">Low predictions proved wrong</th></tr></thead><tbody>${grinch.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${esc(r.low_calls??0)}</td></tr>`).join('')}</tbody></table></div>`:''}`;
}
function renderCallResultsDetail(row,s){
 if(s.detailLoading)return '<p class="help" role="status">Loading announced results…</p>';
 if(s.detailError)return `<div class="prediction-results-error" role="alert">${esc(s.detailError)} <button class="btn ghost" type="button" id="retryPredictionResult">Try again</button></div>`;
 const d=s.detail;if(!d)return '';
 return `<h2 id="predictionResultDetailHeading" tabindex="-1">${esc(callResultsKindLabel(d.period_kind,d.period_basis))} · ${esc(callResultsRange(d))}</h2><p class="help">Announced ${esc(callDateTime(d.released_at,s.data?.timezone))}${Number(d.revision)>1?' · Updated announcement':''}</p>${renderCallResultsAwards(d.awards||[],d.can_view_prizes===true)}${renderCallResultsScores(d.calls||[])}${renderCallResultsSeasonTables(d)}`;
}
function renderCallResultsContent(){
 const page=document.getElementById('page'),s=ensureCallResultsState();if(!page||currentTab!=='make_your_call'||s.view!=='history')return;
 const seasons=s.data?.seasons||[],rows=(s.data?.releases||[]).filter(r=>!s.kind||r.period_kind===s.kind);
 page.innerHTML=`${typeof callStyles==='function'?callStyles():''}${callResultsStyles()}<div class="prediction-results"><section class="card"><div class="prediction-results-header"><h1 id="predictionResultsHeading" tabindex="-1">Results history</h1><button class="btn ghost" type="button" id="predictionResultsBack">← Predictions</button></div><p class="help">Announced awards and match results. Open a period to see its winners and scores.</p><div class="prediction-results-toolbar"><div><label for="predictionResultsSeason">Season</label><select id="predictionResultsSeason" ${s.loading?'disabled':''}><option value="">All seasons</option>${seasons.map(y=>`<option value="${esc(y)}" ${Number(s.season)===Number(y)?'selected':''}>${esc(callResultsSeasonLabel(y))}</option>`).join('')}</select></div><div><label for="predictionResultsKind">Awards</label><select id="predictionResultsKind" ${s.loading?'disabled':''}><option value="">All awards</option>${[['weekly','Weekly'],['monthly','Four-week'],['season','Season']].map(([k,label])=>`<option value="${k}" ${s.kind===k?'selected':''}>${label}</option>`).join('')}</select></div><button class="btn ghost" type="button" id="predictionResultsRefresh" ${s.loading?'disabled':''}>Refresh</button></div></section><section class="card" aria-label="Released award periods">${s.loading?'<p role="status">Loading results history…</p>':s.error?`<div class="prediction-results-error" role="alert">${esc(s.error)} <button class="btn ghost" type="button" id="predictionResultsRetry">Try again</button></div>`:rows.length?rows.map((r,i)=>{const open=s.openKind===r.period_kind&&s.openStart===r.period_start;return `<article class="prediction-result-row"><div class="prediction-result-summary"><div><strong>${esc(callResultsKindLabel(r.period_kind,r.period_basis))} · ${esc(callResultsRange(r))}</strong><small>${esc(r.award_count??0)} awards${Number(r.call_count)?` · ${esc(r.call_count)} match results`:''}</small></div><button type="button" class="btn ghost" data-prediction-result="${i}" aria-expanded="${open}" aria-controls="predictionResult-${i}">${open?'Hide':'View'}</button></div>${open?`<div id="predictionResult-${i}" class="prediction-result-detail">${renderCallResultsDetail(r,s)}</div>`:`<div id="predictionResult-${i}" hidden></div>`}</article>`;}).join(''):'<p class="prediction-results-empty">No awards have been announced for this selection yet.</p>'}</section></div>`;
 document.getElementById('predictionResultsBack').onclick=closeCallResultsHistory;
 document.getElementById('predictionResultsRefresh').onclick=()=>renderCallResultsHistory();
 document.getElementById('predictionResultsRetry')?.addEventListener('click',()=>renderCallResultsHistory());
 document.getElementById('predictionResultsSeason').onchange=async e=>{s.season=e.target.value?Number(e.target.value):null;s.openKind=null;s.openStart=null;await renderCallResultsHistory();};
 document.getElementById('predictionResultsKind').onchange=e=>{if(s.loading){e.target.value=s.kind;return;}callResultsSequence++;s.kind=e.target.value;s.openKind=null;s.openStart=null;s.detail=null;s.detailLoading=false;renderCallResultsContent();callResultsRecordRoute();};
 page.querySelectorAll('[data-prediction-result]').forEach(b=>b.onclick=async()=>{const r=rows[Number(b.dataset.predictionResult)];if(!r)return;if(s.openKind===r.period_kind&&s.openStart===r.period_start){callResultsSequence++;s.openKind=null;s.openStart=null;s.detail=null;s.detailLoading=false;renderCallResultsContent();callResultsRecordRoute();return;}s.openKind=r.period_kind;s.openStart=r.period_start;await loadCallResultDetail();});
 document.getElementById('retryPredictionResult')?.addEventListener('click',loadCallResultDetail);
}
async function renderCallResultsHistory(){
 const s=ensureCallResultsState(),scope=s.scope,sequence=++callResultsSequence;s.loading=true;s.data=null;s.detail=null;s.error='';s.detailError='';s.detailLoading=false;renderCallResultsContent();
 try{const {data,error}=await supabase.rpc('get_club_prediction_results',{p_club_id:club.id,p_season:s.season});if(error)throw error;if(!callResultsActive(scope,sequence))return;if(!Array.isArray(data?.releases)||!Array.isArray(data?.seasons))throw new Error('The results history could not be confirmed.');s.data=data;}
 catch(error){if(!callResultsActive(scope,sequence))return;s.error=error?.message||'Could not load results history.';}
 if(!callResultsActive(scope,sequence))return;s.loading=false;renderCallResultsContent();callResultsRecordRoute();
 if(s.openKind&&s.openStart&&s.data?.releases.some(r=>r.period_kind===s.openKind&&r.period_start===s.openStart)&&(!s.kind||s.kind===s.openKind))await loadCallResultDetail();
 else if(s.openKind){s.openKind=null;s.openStart=null;callResultsRecordRoute();}
}
async function loadCallResultDetail(){
 const s=ensureCallResultsState(),scope=s.scope,kind=s.openKind,start=s.openStart;if(!kind||!start)return;const sequence=++callResultsSequence;
 s.detailLoading=true;s.detail=null;s.detailError='';renderCallResultsContent();callResultsRecordRoute();
 try{const {data,error}=await supabase.rpc('get_club_prediction_result',{p_club_id:club.id,p_period_kind:kind,p_period_start:start});if(error)throw error;if(!callResultsActive(scope,sequence)||s.openKind!==kind||s.openStart!==start)return;if(data?.period_kind!==kind||data?.period_start!==start||!data?.released_at||!Array.isArray(data.awards)||!Array.isArray(data.calls))throw new Error('This announcement could not be confirmed.');s.detail=data;}
 catch(error){if(!callResultsActive(scope,sequence))return;s.detailError=error?.message||'Could not load this announcement.';}
 if(!callResultsActive(scope,sequence))return;s.detailLoading=false;renderCallResultsContent();callResultsFocus('predictionResultDetailHeading');callResultsRecordRoute();
}
// END PREDICTION RESULTS


