/* BEGIN PLAYER PLAN REMINDERS — maintained source */
let workspaceReminderSelection=null;
function planReminderSelection(){
 const key=`${club?.id}:${session?.user?.id}`;
 if(workspaceReminderSelection?.key!==key)workspaceReminderSelection={key,ids:new Set()};
 return workspaceReminderSelection;
}
function workspaceCanRemind(player){
 const due=playerPlanDeadlineState(player).overdue;
 return isAdmin()&&due.length>0&&!workspaceReminderState(player.id).inCooldown;
}
function renderPlanReminderSelection(players){
 const state=planReminderSelection(),eligible=players.filter(workspaceCanRemind),ids=new Set(eligible.map(p=>p.id));
 state.ids=new Set([...state.ids].filter(id=>ids.has(id)));
 return `<div class="plan-reminder-selection"><label><input type="checkbox" id="selectAllOverdue" ${eligible.length?'':'disabled'}>Select all</label><button class="btn" id="remindSelectedPlans" ${state.ids.size?'':'disabled'}>Remind selected${state.ids.size?` (${state.ids.size})`:''}</button></div>`;
}
function bindPlanReminderSelection(page,players){
 if(!isAdmin()||playersWorkspaceGroupFilter!=='__overdue__')return;
 const state=planReminderSelection(),eligible=players.filter(workspaceCanRemind),all=page.querySelector('#selectAllOverdue');
 if(!all)return;
 const sync=()=>{
  all.checked=eligible.length>0&&state.ids.size===eligible.length;all.indeterminate=state.ids.size>0&&state.ids.size<eligible.length;
  page.querySelectorAll('[data-select-overdue]').forEach(x=>x.checked=state.ids.has(x.dataset.selectOverdue));
  const button=page.querySelector('#remindSelectedPlans');button.disabled=!state.ids.size;button.textContent=`Remind selected${state.ids.size?` (${state.ids.size})`:''}`;
 };
 all.onchange=()=>{state.ids=new Set(all.checked?eligible.map(p=>p.id):[]);sync();};
 page.querySelectorAll('[data-select-overdue]').forEach(x=>x.onchange=()=>{x.checked?state.ids.add(x.dataset.selectOverdue):state.ids.delete(x.dataset.selectOverdue);sync();});
 page.querySelector('#remindSelectedPlans').onclick=()=>openPlanReminders([...state.ids]);sync();
}
async function openPlanReminders(ids){
 if(!isAdmin()||!ids.length||!await saveClubEditsBeforeNavigation())return;
 const state=ensureClubMessages();
 if(state.draft&&clubMessageDirty()&&!confirm('Replace your unsent message with this Player Plan reminder?'))return;
 state.draft={...newClubMessageDraft(),kind:'plan_reminder',player_ids:[...new Set(ids)],reminder_candidate_ids:[...new Set(ids)],include_staff:false,staff_initialised:true,
  title:'Player Plan reminder',body:'Please finish the overdue sections of your Player Plan. Open your plan to see what needs attention.',target:'myplan'};
 state.mode='compose';state.notice='';state.openId=null;currentTab='messages';await renderTab();
}
function clubMessageEmailPeople(state){
 const d=state.draft,people=new Map();
 for(const p of state.context.players||[])if(d.player_ids.includes(p.id))people.set(p.user_id,{...p,user_id:p.user_id});
 if(d.include_staff)for(const p of state.context.staff||[])if(d.staff_user_ids.includes(p.user_id))people.set(p.user_id,p);
 return [...people.values()].filter(p=>p.user_id);
}
function messageEmailChoices(state){
 const d=state.draft,people=clubMessageEmailPeople(state);
 return people.map(p=>`<label class="message-check message-email-person"><span>${esc(p.name)}<small>${p.phone_ready?'Phone alerts enabled':'Email fallback'}</small></span><input type="checkbox" data-message-email="${esc(p.user_id)}" aria-label="Email also for ${esc(p.name)}" ${!p.phone_ready||d.email||d.email_user_ids.includes(p.user_id)?'checked':''} ${!p.phone_ready||d.email?'disabled':''}></label>`).join('')||'<p class="help">Choose recipients first.</p>';
}
function refreshMessageEmailChoices(state){
 const host=document.getElementById('messageEmailPeople');if(host)host.innerHTML=messageEmailChoices(state);
}
/* END PLAYER PLAN REMINDERS */

/* BEGIN CLUB MESSAGES — maintained source: tools/club_messages_ui.js */
let clubMessageState=null,clubMessageUnread=0,clubMessageRefreshSequence=0;
const clubMessageTargets=[['','No app link'],['myplan','My Player Plan'],['howwetrain','How We Train'],['prepare','Prepare for a Match'],['innings','My Innings'],['make_your_call','Make your prediction']];
function ensureClubMessages(){
 const key=`${session?.user?.id}:${club?.id}`;
 if(clubMessageState?.key!==key)clubMessageState={key,mode:'inbox',openId:null,context:null,data:null,draft:null,sending:false,notice:''};
 return clubMessageState;
}
function newClubMessageDraft(){return {request_id:crypto.randomUUID(),player_ids:[],staff_user_ids:[],include_staff:true,staff_initialised:false,recipients_changed:false,title:'',body:'',target:'',email:false,email_user_ids:[],kind:'general'};}
function initialiseMessageStaff(state){
 const d=state.draft;if(!d||d.staff_initialised||!state.context)return;
 d.staff_user_ids=(state.context.staff||[]).filter(p=>p.default_included).map(p=>p.user_id);d.staff_initialised=true;
}
function clubMessageRecipientCount(state){
 const d=state.draft,people=new Set((state.context.players||[]).filter(p=>d.player_ids.includes(p.id)).map(p=>p.user_id||p.id));
 if(d.include_staff)for(const p of state.context.staff||[])if(d.staff_user_ids.includes(p.user_id))people.add(p.user_id);
 return people.size;
}
function messagePeople(count){return `${count} ${count===1?'person':'people'}`;}
function canOpenMessageTarget(target){if(target==='products')return canOpenClubTab('products');if(target==='teams')return canOpenClubTab('teams');if(target==='workshop')return canOpenClubTab('workshop');return target==='make_your_call'||(isPlayerUser()&&clubMessageTargets.some(([key])=>key===target)&&!!target);}
function messageStaffRole(role){return ({admin:'Admin',head_coach:'Head Coach',coach:'Coach',captain:'Captain'})[role]||'Staff';}
function clubMessageDirty(){const d=clubMessageState?.draft;return !!(d&&(d.title||d.body||d.player_ids.length||d.recipients_changed||d.target||d.email));}
function confirmLeaveClubMessages(){
 if(clubMessageState?.sending){alert('Your message is sending. Wait for the result before leaving.');return false;}
 if(currentTab==='messages'&&clubMessageState?.mode==='compose'&&clubMessageDirty()&&!confirm('Leave this unsent message? Your draft will stay here while you remain signed in.'))return false;
 return true;
}
function clubMessageStyles(){return `<style>
 .message-recipient-row{display:flex;align-items:center;gap:4px}.message-recipient-row .message-check{flex:1;min-width:0}.message-recipient-row .message-check span{overflow-wrap:anywhere}
 .messages-page{max-width:840px;margin:0 auto}.messages-head{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.messages-head h1{font-size:24px;margin:0}.messages-head .btn{padding:8px 12px;min-height:44px}.messages-tabs{display:flex;gap:8px;margin:12px 0}.messages-tabs button[aria-pressed=true]{background:var(--navy,#17245f);color:#fff}
 .messages-page .message-row{padding:0;border:1px solid #dce2ee;border-radius:10px;background:white;margin-bottom:8px}.messages-page .message-row>summary{margin:0;display:flex;align-items:center;gap:8px;padding:12px;min-height:44px;box-sizing:border-box;cursor:pointer;list-style:none}.message-row>summary::after{content:'View ⌄';font-size:12px;margin-left:auto;white-space:nowrap}.message-row[open]>summary::after{content:'Close ⌃'}.message-row strong{font-size:15px}.message-row small{display:block;font-size:12px;color:#59657c}.message-content{padding:0 12px 12px;border-top:1px solid #eef0f7}.message-content p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:15px;line-height:1.5;margin:12px 0}.message-unread{width:8px;height:8px;background:#d8232a;border-radius:50%;flex-shrink:0}.message-form{margin-top:12px}.message-form .field{margin-bottom:12px}.message-form input,.message-form textarea,.message-form select{font-size:16px}.message-form label{font-size:13px}.message-form .message-check{display:flex;align-items:center;gap:9px;min-height:44px;margin:0}.message-check input{width:18px;height:18px;margin:0;flex-shrink:0}.message-recipients{max-height:230px;overflow:auto;border:1px solid #dce2ee;border-radius:8px;padding:4px 10px}.message-recipient-tools{display:flex;gap:8px;align-items:center;margin:8px 0}.message-recipient-tools select{min-width:0;flex:1}.message-form fieldset{min-width:0;border:0;padding:0;margin:0}.message-form fieldset:disabled{opacity:.7}.message-form .btn{min-height:44px;padding:8px 10px}.message-form input,.message-form textarea,.message-form select{box-sizing:border-box;max-width:100%}.message-form .help{margin:5px 0;font-size:12px}.message-email-person{justify-content:space-between}.message-email-person small{display:block;color:var(--muted);font-size:12px}.message-form summary{cursor:pointer;min-height:44px;align-content:center;font-size:13px}.se-inbox-followup{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:12px!important}.se-inbox-followup .btn{min-height:44px}.messages-status:empty{display:none}.messages-status{margin:8px 0;font-size:14px}.messages-empty{padding:16px;border:1px solid #dce2ee;border-radius:10px}.message-body-count{float:right;font-weight:400;color:#59657c}
 </style>`;}
async function openClubMessages({compose=false,id=null}={}){
 if(!await saveClubEditsBeforeNavigation())return;
 const state=ensureClubMessages();state.mode=compose?'compose':'inbox';state.openId=id;
 if(compose&&!state.draft)state.draft=newClubMessageDraft();currentTab='messages';await renderTab();
}
async function refreshClubMessageBadge(){
 if(!session?.user||!club||!membership)return;
 const key=`${session.user.id}:${club.id}`,seq=++clubMessageRefreshSequence;
 const [{data,error},followup]=await Promise.all([supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'badge'}),seFetchSignupFollowup(club.id)]);
 if(key!==`${session?.user?.id}:${club?.id}`||seq!==clubMessageRefreshSequence||error)return;
 clubMessageUnread=Number(data?.unread||0);
 const followupCount=followup.can_view?followup.players.length:0,host=document.getElementById('clubMessagesHost');if(host){host.hidden=!clubMessageUnread&&!followupCount;host.innerHTML=clubMessageUnread||followupCount?`<button class="btn ghost" id="unreadClubMessages" aria-label="${clubMessageUnread} unread club messages; ${followupCount} players to follow up">Messages ${clubMessageUnread?`<span class="coaching-unread-badge">${clubMessageUnread}</span>`:''}${followupCount?`<small> · ${followupCount} to follow up</small>`:''}</button>`:'';document.getElementById('unreadClubMessages')?.addEventListener('click',()=>openClubMessages());}
 void updatePhoneAppBadge();
}
async function openClubMessageTarget(target){
 if(target==='products')return openMyClubProducts();
 if(!canOpenMessageTarget(target))return;
 if(!await saveClubEditsBeforeNavigation())return;
 if(target==='prepare')return openMyInnings({prepare:true});
 if(!canOpenClubTab(target))return;currentTab=target;await renderTab();
}
async function copyClubMessage(message,button){
 const label=button.textContent;
 const tab=message.target==='prepare'?'innings':message.target;
 const link=tab?new URL(`./app.html?club=${encodeURIComponent(club.id)}&tab=${tab}${message.target==='prepare'?'&prepare=1':''}`,location.href).href:'';
 const text=`${message.title}\n\n${message.body}${link?'\n\n'+link:''}`;
 try{await navigator.clipboard.writeText(text);button.textContent='Copied ✓';}catch{button.textContent='Select and copy below';const box=document.createElement('textarea');box.value=text;box.readOnly=true;box.setAttribute('aria-label','Message to copy');button.after(box);box.focus();box.select();}
 setTimeout(()=>{if(button.isConnected)button.textContent=label;},2500);
}
async function renderClubMessages(){
 const page=document.getElementById('page'),state=ensureClubMessages();
 const here=()=>state===clubMessageState&&currentTab==='messages'&&page===document.getElementById('page');
 page.innerHTML=clubMessageStyles()+'<section class="card messages-page"><div class="messages-head"><h1>Messages</h1></div><p role="status">Loading messages…</p></section>';
 try{
  const [list,context,followup]=await Promise.all([supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'list'}),supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'context'}),seFetchSignupFollowup(club.id)]);
  if(list.error||context.error)throw list.error||context.error;if(!here())return;
  // A Workshop invitation can arrive while this session is already open.
  // Refresh that permission before drawing its link instead of using stale sign-in data.
  if(list.data.inbox?.some(row=>row.target==='workshop')){
   const [workshopResult,contributorResult]=await Promise.all([
    supabase.from('philosophy_workshops').select('*').eq('club_id',club.id).maybeSingle(),
    supabase.from('philosophy_contributors').select('*').eq('club_id',club.id).eq('user_id',session.user.id).maybeSingle()
   ]);
   if(workshopResult.error||contributorResult.error)throw workshopResult.error||contributorResult.error;if(!here())return;
   workshop=workshopResult.data||null;myContributor=contributorResult.data||null;
  }
  state.data=list.data;state.context=context.data;state.signupFollowup=followup;if(!context.data.can_send&&state.mode!=='inbox'){state.mode='inbox';state.draft=null;}
  drawClubMessages(page,state);void refreshClubMessageBadge();
 }catch(error){if(here()){page.innerHTML=clubMessageStyles()+`<section class="card messages-page"><h1>Messages</h1><p>${esc(error.message||'Messages could not load.')}</p><button class="btn" id="retryClubMessages">Try again</button></section>`;document.getElementById('retryClubMessages').onclick=renderClubMessages;}}
}
function drawClubMessages(page,state){
 initialiseMessageStaff(state);
 const data=state.data,staff=!!state.context.can_send,rows=state.mode==='sent'?data.sent:data.inbox;
 page.innerHTML=clubMessageStyles()+`<section class="card messages-page"><div class="messages-head"><h1>${state.mode==='compose'?(state.draft?.kind==='plan_reminder'?'Player Plan reminder':'New message'):'Messages'}</h1>${staff&&state.mode!=='compose'?'<button class="btn" id="newClubMessage">Message players &amp; staff</button>':''}</div>
 ${staff?`<div class="messages-tabs"><button class="btn ghost" data-message-mode="inbox" aria-pressed="${state.mode==='inbox'}">Inbox</button><button class="btn ghost" data-message-mode="sent" aria-pressed="${state.mode==='sent'}">Sent</button></div>`:''}
 <p class="messages-status" id="clubMessageNotice" role="status">${esc(state.notice)}</p>
 ${state.mode==='inbox'?seInboxFollowup(state.signupFollowup):''}
 ${state.mode==='compose'?clubMessageComposer(state):rows.length?rows.map(row=>`<details class="message-row" data-message-id="${esc(row.id)}" ${state.openId===row.id?'open':''}><summary>${state.mode==='inbox'&&!row.opened_at?'<span class="message-unread" aria-label="Unread"></span>':''}<span><strong>${esc(row.title)}</strong><small>${esc(state.mode==='sent'?messagePeople(row.recipients):row.sender)} · ${esc(formatDateShort(row.created_at))}</small></span></summary><div class="message-content"><p>${esc(row.body)}</p>${row.target&&state.mode==='inbox'&&canOpenMessageTarget(row.target)?`<button class="btn" data-message-target="${esc(row.target)}">${esc(row.target==='products'?'Getting started':row.target==='teams'?'Open Teams':row.target==='workshop'?'Batting Philosophy Workshop':clubMessageTargets.find(([k])=>k===row.target)?.[1]||'Open')}</button>`:''}${state.mode==='sent'?`<small>${row.opened||0} opened · ${row.push_sent||0} phone deliveries${row.email_total||row.email_requested?` · ${row.email_sent||0} emails sent${row.email_failed?` · ${row.email_failed} email failures`:''}`:''}</small><button class="btn ghost" data-message-copy="${esc(row.id)}">Copy for WhatsApp</button>`:''}</div></details>`).join(''):state.mode==='inbox'&&state.signupFollowup?.can_view&&state.signupFollowup.players.length?'':`<div class="messages-empty">${state.mode==='sent'?'Your sent messages will appear here.':'No club messages yet. Coaching discussions stay in Coach Conversations.'}</div>`}</section>`;
 document.getElementById('viewSignupFollowup')?.addEventListener('click',seOpenSignupFollowup);document.getElementById('retrySignupFollowup')?.addEventListener('click',renderClubMessages);
 document.getElementById('newClubMessage')?.addEventListener('click',()=>{state.mode='compose';state.draft??=newClubMessageDraft();drawClubMessages(page,state);});
 page.querySelectorAll('[data-message-mode]').forEach(b=>b.onclick=()=>{if(!confirmLeaveClubMessages())return;state.mode=b.dataset.messageMode;drawClubMessages(page,state);});
 page.querySelectorAll('[data-message-target]').forEach(b=>b.onclick=()=>openClubMessageTarget(b.dataset.messageTarget));
 page.querySelectorAll('[data-message-copy]').forEach(b=>b.onclick=()=>copyClubMessage(rows.find(r=>r.id===b.dataset.messageCopy),b));
 const markOpened=async el=>{
  if(!el.open||state.mode!=='inbox')return;const row=data.inbox.find(r=>r.id===el.dataset.messageId);if(!row||row.opened_at)return;
  const {error}=await supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'open',p_data:{id:row.id}});
  if(error||state!==clubMessageState)return;row.opened_at=new Date().toISOString();el.querySelector('.message-unread')?.remove();void refreshClubMessageBadge();
 };
 page.querySelectorAll('[data-message-id]').forEach(el=>{el.addEventListener('toggle',()=>void markOpened(el));if(el.open)void markOpened(el);});
 if(state.openId&&state.mode==='inbox'&&!data.inbox.some(r=>r.id===state.openId))document.getElementById('clubMessageNotice').textContent='That message is unavailable in this account. Recent messages are shown below.';
 if(state.mode==='compose')bindClubMessageComposer(page,state);
}
function clubMessageComposer(state){
 const d=state.draft??=newClubMessageDraft();initialiseMessageStaff(state);const reminder=d.kind==='plan_reminder',players=(state.context.players||[]).filter(p=>!reminder||d.reminder_candidate_ids.includes(p.id)),staff=reminder?[]:state.context.staff||[],count=clubMessageRecipientCount(state),groups=new Map(players.flatMap(p=>p.groups||[]).map(g=>[g.id,g.name]));
 return `<form class="message-form" id="clubMessageForm"><fieldset ${state.sending?'disabled':''}>
 <details id="messageRecipientPicker" ${d.player_ids.length?'':'open'}><summary>To: <strong id="messageRecipientCount">${messagePeople(count)}</strong> · choose recipients</summary>
 ${reminder?'':`<div class="message-recipient-tools"><select id="messageGroup" aria-label="Choose a Playing Group"><option value="">All players in my access</option><option value="unassigned">Currently unassigned</option>${[...groups].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select><button type="button" class="btn ghost" id="messageSelectGroup">Select</button><button type="button" class="btn ghost" id="messageClearRecipients">Clear</button></div>`}
 <div class="message-recipients">${players.length?players.map(p=>`<div class="message-recipient-row"><label class="message-check"><input type="checkbox" data-message-player="${esc(p.id)}" ${d.player_ids.includes(p.id)?'checked':''}><span>${esc(p.name)}</span></label>${phoneStatusBadge(p.phone_ready)}</div>`).join(''):'No players with messaging access. Ask your Club Admin to check your player access.'}</div></details>
 ${staff.length?`<label class="message-check"><input id="messageIncludeStaff" type="checkbox" ${d.include_staff?'checked':''}>Include coaching staff</label>
 <details id="messageStaffPicker" ${d.include_staff?'':'hidden'}><summary><span id="messageStaffCount">${d.staff_user_ids.length} staff included</span> · choose staff</summary>
 <div class="message-recipients">${staff.map(p=>`<div class="message-recipient-row"><label class="message-check"><input type="checkbox" data-message-staff="${esc(p.user_id)}" ${d.staff_user_ids.includes(p.user_id)?'checked':''}><span>${esc(p.name)} <small>· ${esc(messageStaffRole(p.role))}</small></span></label>${phoneStatusBadge(p.phone_ready)}</div>`).join('')}</div></details>`:''}
 <div class="field" style="margin-top:12px"><label for="clubMessageTitle">Title</label><input id="clubMessageTitle" required maxlength="80" value="${esc(d.title)}" placeholder="e.g. Thursday training"></div>
 <div class="field"><label for="clubMessageBody">Message <span class="message-body-count" id="messageBodyCount">${d.body.length}/1500</span></label><textarea id="clubMessageBody" required maxlength="1500" rows="4" placeholder="What does everyone need to know or do?">${esc(d.body)}</textarea></div>
 <div class="field" ${reminder?'hidden':''}><label for="clubMessageTarget">Link to</label><select id="clubMessageTarget">${clubMessageTargets.map(([key,label])=>`<option value="${key}" ${d.target===key?'selected':''}>${label}</option>`).join('')}</select></div>
 <label class="message-check"><input id="clubMessageEmail" type="checkbox" ${d.email?'checked':''}>Email also for everyone selected</label>
 <details id="messageEmailPicker"><summary>Email also for selected people</summary><div id="messageEmailPeople">${messageEmailChoices(state)}</div></details>
 <p class="help">Everyone receives this in Messages. Phone alerts where enabled; an email link otherwise.</p>
 ${reminder?'<p class="help">Players who have finished or were reminded within 48 hours are skipped.</p>':''}
 ${state.context.email_mode==='prototype'?'<p class="notice">Email delivery is in Prototype mode. In-app messages work; emails will not be delivered yet.</p>':''}
 <div class="btnrow"><button type="submit" class="btn" id="sendClubMessage">Send to ${messagePeople(count)}</button><button type="button" class="btn ghost" id="copyClubMessageDraft">Copy for WhatsApp</button><button type="button" class="btn ghost" id="discardClubMessageDraft">Discard draft</button></div>
 <p class="messages-status" id="clubMessageSendStatus" role="status"></p></fieldset></form>`;
}
function bindClubMessageComposer(page,state){
 const d=state.draft,form=document.getElementById('clubMessageForm'),status=document.getElementById('clubMessageSendStatus');
 const sync=()=>{
  d.title=form.querySelector('#clubMessageTitle').value;d.body=form.querySelector('#clubMessageBody').value;d.target=form.querySelector('#clubMessageTarget').value;d.email=form.querySelector('#clubMessageEmail').checked;
  d.player_ids=[...form.querySelectorAll('[data-message-player]:checked')].map(x=>x.dataset.messagePlayer);
  d.include_staff=!!form.querySelector('#messageIncludeStaff')?.checked;
  d.staff_user_ids=[...form.querySelectorAll('[data-message-staff]:checked')].map(x=>x.dataset.messageStaff);
  const picker=form.querySelector('#messageStaffPicker');if(picker)picker.hidden=!d.include_staff;
  const staffCount=form.querySelector('#messageStaffCount');if(staffCount)staffCount.textContent=`${d.staff_user_ids.length} staff included`;
  const count=clubMessageRecipientCount(state);form.querySelector('#messageRecipientCount').textContent=messagePeople(count);form.querySelector('#sendClubMessage').textContent=`Send to ${messagePeople(count)}`;form.querySelector('#messageBodyCount').textContent=`${d.body.length}/1500`;
 };
 form.addEventListener('input',sync);form.addEventListener('change',event=>{if(event.target.matches('[data-message-player],[data-message-staff],#messageIncludeStaff'))d.recipients_changed=true;if(event.target.matches('[data-message-email]')){const uid=event.target.dataset.messageEmail;d.email_user_ids=event.target.checked?[...new Set([...d.email_user_ids,uid])]:d.email_user_ids.filter(x=>x!==uid);}sync();if(!event.target.matches('[data-message-email]'))refreshMessageEmailChoices(state);});
 document.getElementById('messageSelectGroup')?.addEventListener('click',()=>{d.recipients_changed=true;const group=form.querySelector('#messageGroup').value;form.querySelectorAll('[data-message-player]').forEach(x=>{const p=state.context.players.find(p=>p.id===x.dataset.messagePlayer);if(!group||(group==='unassigned'?!p.groups.length:p.groups.some(g=>g.id===group)))x.checked=true;});sync();refreshMessageEmailChoices(state);});
 document.getElementById('messageClearRecipients')?.addEventListener('click',()=>{d.recipients_changed=true;form.querySelectorAll('[data-message-player],[data-message-staff],#messageIncludeStaff').forEach(x=>x.checked=false);sync();refreshMessageEmailChoices(state);});
 document.getElementById('discardClubMessageDraft').onclick=()=>{if(clubMessageDirty()&&!confirm('Discard this unsent draft?'))return;state.draft=null;state.mode='inbox';drawClubMessages(page,state);};
 document.getElementById('copyClubMessageDraft').onclick=e=>{sync();void copyClubMessage(d,e.currentTarget);};
 form.onsubmit=async event=>{
  event.preventDefault();if(state.sending)return;sync();if(!clubMessageRecipientCount(state)){status.textContent='Choose at least one person.';form.querySelector('#messageRecipientPicker').open=true;return;}
  if(!d.title.trim()||!d.body.trim()){status.textContent='Add a title and a message.';return;}
  const clubId=club.id;state.sending=true;form.querySelector('fieldset').disabled=true;status.textContent='Sending…';
  try{const {data,error}=await supabase.rpc('club_messages_api',{p_club_id:clubId,p_action:'send',p_data:{request_id:d.request_id,player_ids:[...d.player_ids],staff_user_ids:d.include_staff?[...d.staff_user_ids]:[],title:d.title,body:d.body,target:d.target,email:d.email,kind:d.kind,email_user_ids:d.email_user_ids.filter(id=>clubMessageEmailPeople(state).some(p=>p.user_id===id))}});if(error)throw error;
   if(state!==clubMessageState||clubId!==club?.id)return;
   state.draft=null;state.mode='sent';const skipped=Number(data.skipped?.cooldown||0)+Number(data.skipped?.no_longer_overdue||0);state.notice=`In Messages for ${messagePeople(data.recipients)} ✓${data.email_queued?` · ${data.email_queued} email${data.email_queued===1?'':'s'} queued`:''}${skipped?` · ${skipped} no longer due or recently reminded`:''}`;state.openId=data.id;state.sending=false;await renderClubMessages();
  }catch(error){if(state===clubMessageState&&form.isConnected){status.textContent=`Couldn’t confirm sending. Your draft is here; retrying will not send it twice. ${error.message||''}`;form.querySelector('fieldset').disabled=false;}}
  finally{state.sending=false;}
 };
}
/* END CLUB MESSAGES */

/* BEGIN PHONE APP — maintained source: tools/phone_app_ui.js */
let phoneInstallPrompt=null,phoneRegistration=null,phoneStarted=false,phoneSettingsBusy=false;
let phoneRegistrationTask=null,phoneRegistrationError='';
let pendingPhoneLaunch=null;
const phoneIsDemo=()=>typeof window.__fixtureDb!=='undefined'||location.pathname.endsWith('/demo.html');
const phoneIsInstalled=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const phoneIsIOS=()=>/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const phoneIsAndroid=()=>/Android/i.test(navigator.userAgent);
const phonePushSupported=()=>window.isSecureContext&&'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window;
function playerSignupWhatsAppMessage(clubName,playerJoinLink,plansReady){
 return `🏏 ${clubName} players — get started with Club Batting

1. Sign up
Open this Player link in Safari on iPhone or Chrome on Android:
${playerJoinLink}

Register with your email and confirm your name. Check your inbox and junk folder for the sign-in email. Playing coaches and captains use this link too.

2. Put Club Batting on your phone
Once you’ve finished registering:

🍎 iPhone: Tap Safari’s three dots (…) at the bottom right → Share → View More if shown → Add to Home Screen. Keep Open as Web App switched on if shown, then tap Add. If you see the Share icon directly, start there.

🤖 Android: In Chrome, tap three dots (⋮) → Install and create shortcut → Install. Some versions say Install app or Add to Home screen.

3. Turn on notifications
Open the new Club Batting icon on your phone. Sign in if asked, then go to Account → App & notifications. Choose Club messages and Coaching updates, tap Enable notifications, then Allow.

${plansReady?'Your Player Plan, training ideas and match preparation are now one tap away.':'Register now while the club prepares How We Bat and the Player Plan questions. We’ll notify you when your plan is ready; anyone assigned a setup role can help with preparation now.'}`;
}
function phoneIOSInstallSteps(){
 return `<ol><li>Tap Safari’s <strong>three dots (…)</strong> at the bottom-right of your screen.</li><li>Tap <strong>Share</strong> — the square with an arrow pointing upwards.</li><li>Tap <strong>View More</strong> if shown, then <strong>Add to Home Screen</strong>. You may need to scroll down.</li><li>Keep <strong>Open as Web App</strong> switched on if shown, then tap <strong>Add</strong>.</li><li>Go to your phone’s Home Screen and open the <strong>Club Batting icon</strong>. Sign in with your existing account if asked.</li></ol>`;
}
function phoneAndroidInstallSteps(){
 return `<ol><li>Tap Chrome’s <strong>three dots (⋮)</strong>, usually at the top-right.</li><li>Tap <strong>Install and create shortcut → Install</strong>. Some versions say <strong>Install app</strong> or <strong>Add to Home screen</strong>.</li><li>Open the new <strong>Club Batting icon</strong> on your phone. Sign in with your existing account if asked.</li></ol>`;
}
function phoneInstallHelp(ios,android){
 const next='<p class="phone-next"><strong>Then turn on alerts:</strong> open <strong>Account → App &amp; notifications</strong> from the new app.</p>';
 if(ios)return `<p>Add the app icon, then open your plans straight from your phone.</p>${phoneIOSInstallSteps()}${next}<details><summary>Can’t find it?</summary><p>If Safari shows the <strong>Share icon</strong> directly, tap it and continue from step 3. If <strong>Add to Home Screen</strong> is missing, scroll to <strong>Edit Actions</strong> and add it. On iPad, Share may be at the top.</p><p>If you opened Club Batting inside WhatsApp or another browser, open this page in <strong>Safari</strong> first. Already added the icon? Open that icon instead of adding it again.</p></details>`;
 if(android)return `<p>Add the app icon, then open your plans straight from your phone.</p>${phoneInstallPrompt?'<button class="btn" id="installClubBatting">Install Club Batting</button><details><summary>Or use Chrome’s menu</summary>'+phoneAndroidInstallSteps()+'</details>':phoneAndroidInstallSteps()}${next}<details><summary>Can’t find it?</summary><p>If you opened Club Batting inside WhatsApp, use its menu to open this page in <strong>Chrome</strong>. Already added the icon? Open that icon instead of adding it again.</p></details>`;
 return `<details class="phone-other-devices" data-phone-device="iphone"><summary>iPhone or iPad</summary><p>On your phone, open Club Batting in <strong>Safari</strong>.</p>${phoneIOSInstallSteps()}<p class="help">If Share is visible directly, start there. If Add to Home Screen is missing, scroll down or use Edit Actions. On iPad, Share may be at the top.</p>${next}</details><details class="phone-other-devices" data-phone-device="android"><summary>Android</summary><p>On your phone, open Club Batting in <strong>Chrome</strong>.</p>${phoneAndroidInstallSteps()}${next}</details>`;
}
async function phoneWorkerMessage(type,binding=null){
 if(phoneIsDemo()||!('serviceWorker'in navigator))return;
 const reg=phoneRegistration||await navigator.serviceWorker.getRegistration('./');if(!reg?.active)return;
 await new Promise(resolve=>{const channel=new MessageChannel(),timer=setTimeout(resolve,2500);channel.port1.onmessage=()=>{clearTimeout(timer);resolve();};reg.active.postMessage({type,binding},[channel.port2]);});
}
async function updatePhoneAppBadge(){
 if(phoneIsDemo()||!navigator.setAppBadge)return;
 try{const n=clubMessageUnread+(coachingUpdateScopeMatches()?myCoachingUpdates.updates.length:0);if(n)await navigator.setAppBadge(n);else await navigator.clearAppBadge();}catch{}
}
async function initialisePhoneApp(){
 if(phoneIsDemo()||!location.pathname.endsWith('/app.html')||!('serviceWorker'in navigator)||!window.isSecureContext)return;
 if(!phoneStarted){
  phoneStarted=true;
  window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();phoneInstallPrompt=event;if(currentTab==='phone_app')void renderPhoneApp();});
  window.addEventListener('appinstalled',()=>{phoneInstallPrompt=null;if(currentTab==='phone_app')void renderPhoneApp();});
  navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='CB_OPEN')void openPhoneNotification(event.data.url);});
  // Setup never asks for notification permission; only the explicit Enable click does.
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session&&club){void refreshClubMessageBadge();void refreshMyCoachingUpdates();if(phoneSetupPromptState)phoneSetupPromptState.checkedAt=0;void refreshPhoneSetupPrompt();}});
  setInterval(()=>{if(document.visibilityState==='visible'&&session&&club){void refreshClubMessageBadge();void refreshMyCoachingUpdates();}},60000);
 }
 if(phoneRegistrationTask)return phoneRegistrationTask;
 if([phoneRegistration?.active,phoneRegistration?.installing,phoneRegistration?.waiting].some(worker=>worker&&worker.state!=='redundant'))return phoneRegistration;
 phoneRegistrationTask=(async()=>{
  try{
   phoneRegistration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});
   phoneRegistrationError='';return phoneRegistration;
  }catch{
   phoneRegistration=null;
   phoneRegistrationError=navigator.onLine===false?'You’re offline. Reconnect, then try again.':'Phone notification setup couldn’t finish. Please try again.';
   return null;
  }
 })();
 try{return await phoneRegistrationTask;}finally{phoneRegistrationTask=null;}
}
function waitForPhoneWorker(reg){
 if(reg.active?.state==='activated')return Promise.resolve(reg);
 return new Promise((resolve,reject)=>{
  const watched=new Set();let timer;
  const finish=error=>{clearTimeout(timer);reg.removeEventListener('updatefound',check);for(const worker of watched)worker.removeEventListener('statechange',check);error?reject(error):resolve(reg);};
  const check=()=>{
   if(reg.active?.state==='activated'){finish();return;}
   for(const worker of [reg.installing,reg.waiting,reg.active].filter(Boolean))if(!watched.has(worker)){watched.add(worker);worker.addEventListener('statechange',check);}
   if(![reg.installing,reg.waiting,reg.active].some(worker=>worker&&worker.state!=='redundant'))finish(new Error('Phone notification setup couldn’t finish. Please try again.'));
  };
  timer=setTimeout(()=>finish(new Error(navigator.onLine===false?'You’re offline. Reconnect, then try again.':'Phone notification setup hasn’t finished. Please try again.')),10000);
  reg.addEventListener('updatefound',check);check();
 });
}
async function signOutClubBatting(){
 if(phoneIsDemo())return supabase.auth.signOut();
 try{const reg=phoneRegistration||await navigator.serviceWorker?.getRegistration('./'),sub=await reg?.pushManager.getSubscription();if(sub&&session?.user){await Promise.race([supabase.rpc('phone_app_api',{p_club_id:club?.id||null,p_action:'disable',p_data:{endpoint:sub.endpoint}}),new Promise(resolve=>setTimeout(resolve,3000))]);}}catch{}
 await phoneWorkerMessage('CB_SIGN_OUT');clubMessageState=null;clubMessageUnread=0;return supabase.auth.signOut();
}
async function openPhoneApp(){if(!await saveClubEditsBeforeNavigation())return;currentTab='phone_app';await renderTab();}
function phoneAppPrompt(){
 if(phoneIsInstalled()||phoneIsDemo()||localStorage.getItem('cb-hide-install')==='yes')return '';
 return `<div class="phone-install-prompt"><button class="btn ghost" data-phone-open>Get Club Batting on your phone ↗</button><button type="button" class="btn ghost" data-phone-dismiss aria-label="Dismiss phone installation suggestion">×</button></div>`;
}
function bindPhoneAppControls(){
 void refreshPhoneSetupPrompt();
 document.querySelectorAll('[data-phone-open]').forEach(b=>b.onclick=openPhoneApp);
 document.querySelector('[data-phone-dismiss]')?.addEventListener('click',e=>{localStorage.setItem('cb-hide-install','yes');e.currentTarget.closest('.phone-install-prompt').remove();});
 document.querySelectorAll('[data-club-messages]').forEach(b=>b.onclick=()=>openClubMessages());

}
async function renderPhoneApp(){
 const page=document.getElementById('page'),clubId=club?.id,userId=session?.user?.id;
 const here=()=>currentTab==='phone_app'&&club?.id===clubId&&session?.user?.id===userId&&document.getElementById('page')===page;
 const installed=phoneIsInstalled(),ios=phoneIsIOS(),android=phoneIsAndroid(),demo=phoneIsDemo(),mobile=ios||android,installFirst=!installed&&mobile;
 const phoneStyle=`<style>.phone-settings{max-width:640px;margin:0 auto}.phone-settings h1{font-size:24px;margin:0 0 12px}.phone-settings h2{font-size:19px;margin:16px 0 8px}.phone-settings p,.phone-settings li{font-size:15px;line-height:1.5}.phone-settings ol{padding-left:24px}.phone-settings li{padding-left:3px;margin-bottom:10px}.phone-settings label{display:flex;gap:10px;align-items:center;min-height:44px}.phone-settings input{width:18px;height:18px;margin:0}.phone-settings .help{font-size:12px}.phone-settings details{margin:12px 0}.phone-settings summary{cursor:pointer;min-height:44px;align-content:center;font-weight:700}.phone-settings .phone-next{padding:12px;border-radius:10px;background:#eef0ff}.phone-settings .phone-installed{color:#08766a}.phone-settings [hidden]{display:none!important}.phone-settings #phoneActionStatus:empty{display:none}</style>`;
 // Desktop is an instruction page only, including an installed desktop PWA.
 if(!mobile){
  page.innerHTML=`${phoneStyle}<section class="card phone-settings"><h1>Get Club Batting on your phone</h1><p>Open your plans, training and match preparation from an icon on your phone.</p>${phoneInstallHelp(false,false)}${demo?'<p class="help">Demo only — no installation or real notifications.</p>':''}</section>`;
  return;
 }
 page.innerHTML=`${phoneStyle}
 <section class="card phone-settings"><h1>${installFirst?'Get the Club Batting app on your phone':'App &amp; notifications'}</h1>
 ${installed?'<p class="phone-installed">✓ You’re using the Club Batting app.</p>':phoneInstallHelp(ios,android)}
 <div id="phoneNotificationPanel" ${installFirst?'hidden':''}>
 <p id="phoneNotificationStatus" role="status">${demo?'Demo only — no installation or real notifications.':'Checking this device…'}</p>
 <p class="phone-next">Enable phone alerts for club messages and coaching updates. Until phone alerts are enabled, we’ll keep sending email notifications.</p>
 <div id="phoneNotificationChoices" hidden><label><input type="checkbox" id="phoneMessages" checked>Club messages</label><label><input type="checkbox" id="phoneCoaching" checked>Coaching updates</label></div>
 <div class="btnrow"><button class="btn" id="enablePhoneNotifications" hidden>Enable notifications</button><button class="btn ghost" id="disablePhoneNotifications" hidden>Turn off on this device</button><button class="btn" id="retryPhoneSetup" hidden>Try again</button></div>
 <p id="phoneAllowHint" class="help" hidden>Tap <strong>Allow</strong> when your phone asks.</p>
 <details><summary>About notifications</summary><p class="help">Your choices apply to ${esc(club?.name||'this club')} on this device. Previews keep message details private. Alerts depend on your device and its settings; iPhone/iPad needs iOS/iPadOS 16.4 or later. Messages stay in Account → Messages. Messages and coaching updates use enabled phone alerts first; otherwise a brief email links you into the app without sharing the details. Coaching updates stay in Coach Conversations.</p></details>
 <p id="phoneActionStatus" role="status" class="help"></p></div>${demo&&installFirst?'<p class="help">Demo only — no installation or real notifications.</p>':''}</section>`;
 document.getElementById('installClubBatting')?.addEventListener('click',async()=>{const prompt=phoneInstallPrompt;phoneInstallPrompt=null;await prompt?.prompt();if(here())await renderPhoneApp();});
 if(demo)return;
 if(installFirst)return;
 if(!phonePushSupported()){document.getElementById('phoneNotificationStatus').textContent='This browser cannot receive notifications. Open Club Batting in a supported, up-to-date browser.';return;}
 try{
  const reg=await initialisePhoneApp();if(!reg)throw new Error(phoneRegistrationError||'Phone notification setup couldn’t finish. Please try again.');
  await waitForPhoneWorker(reg);if(!here())return;
  let sub=await reg.pushManager.getSubscription();
  const {data,error}=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'get',p_data:{endpoint:sub?.endpoint||null}});if(error)throw error;if(!here())return;
  const status=document.getElementById('phoneNotificationStatus'),button=document.getElementById('enablePhoneNotifications'),off=document.getElementById('disablePhoneNotifications'),choices=document.getElementById('phoneNotificationChoices');
  if(!data.configured){status.textContent='Notifications are not configured yet. Your inbox is available.';return;}
  if(Notification.permission==='denied'){status.textContent='Notifications are blocked. Allow them in your phone or browser notification settings, then return here.';if(sub){off.hidden=false;off.onclick=async()=>{const r=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'disable',p_data:{endpoint:sub.endpoint}});if(!r.error){await phoneWorkerMessage('CB_SIGN_OUT');await renderPhoneApp();}};}return;}
  const enabled=!!(sub&&data.subscription_id&&data.club_enabled);
  const anyUpdates=data.preferences.messages||data.preferences.coaching;
  const choicePrompt='Which updates would you like?';
  status.textContent=enabled&&!anyUpdates?'Both types of update are off. Tick either to turn it on.':choicePrompt;
  choices.hidden=false;document.getElementById('phoneMessages').checked=data.preferences.messages;document.getElementById('phoneCoaching').checked=data.preferences.coaching;
  button.hidden=false;button.textContent=enabled?(anyUpdates?'Notifications on ✓':'Notifications off ✓'):'Enable notifications';button.disabled=enabled;
  document.getElementById('phoneAllowHint').hidden=enabled||Notification.permission==='granted';
  off.hidden=!sub;
  if(enabled)await phoneWorkerMessage('CB_BIND',data.binding);
  choices.onchange=()=>{button.textContent=enabled?'Save notification choices':'Enable notifications';button.disabled=false;};
  const disable=async()=>{
   if(phoneSettingsBusy)return;phoneSettingsBusy=true;off.disabled=true;button.disabled=true;
   try{if(sub){const {error}=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'disable',p_data:{endpoint:sub.endpoint}});if(error)throw error;await sub.unsubscribe();}await phoneWorkerMessage('CB_SIGN_OUT');if(here())await renderPhoneApp();}
   catch(e){if(here())document.getElementById('phoneActionStatus').textContent=e.message||'Could not turn off notifications. Try again.';}
   finally{phoneSettingsBusy=false;if(off.isConnected)off.disabled=false;}
  };
  off.onclick=disable;
  button.onclick=async()=>{
   if(phoneSettingsBusy)return;phoneSettingsBusy=true;button.disabled=true;const result=document.getElementById('phoneActionStatus');
   try{
    // Keep the browser permission request directly within this user click (required on iOS).
    const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();
    if(permission!=='granted'){if(here()){result.textContent=permission==='denied'?'Notifications were not allowed. You can change this in your phone settings.':'No change made. Your inbox still works.';button.disabled=false;}return;}
    if(sub&&!data.subscription_id){await sub.unsubscribe();sub=null;}
    if(!sub){const padded=data.public_key.replace(/-/g,'+').replace(/_/g,'/');const key=Uint8Array.from(atob(padded+'='.repeat((4-padded.length%4)%4)),c=>c.charCodeAt(0));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});}
    if(!here())return;
    const json=sub.toJSON(),saved=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'register',p_data:{endpoint:sub.endpoint,p256dh:json.keys.p256dh,auth:json.keys.auth,messages:document.getElementById('phoneMessages').checked,coaching:document.getElementById('phoneCoaching').checked}});
    if(saved.error)throw saved.error;if(!here())return;await phoneWorkerMessage('CB_BIND',saved.data.binding);await renderPhoneApp();invalidatePhoneSetupPrompt();
   }catch(e){if(here()){result.textContent=`Notifications could not be enabled. ${e.message||'Please try again.'}`;button.disabled=false;}}
   finally{phoneSettingsBusy=false;}
  };
 }catch(error){if(here()){
  document.getElementById('phoneNotificationStatus').textContent=error.message||'Could not check notifications. Please try again.';
  const retry=document.getElementById('retryPhoneSetup');retry.hidden=false;retry.onclick=()=>renderPhoneApp();
 }}
}
function capturePhoneLaunch(params){
 if(params.get('message')||params.get('coaching')||params.get('prepare')==='1')pendingPhoneLaunch={clubId:params.get('club'),message:params.get('message'),coaching:params.get('coaching'),prepare:params.get('prepare')==='1'};
}
async function applyPhoneLaunch(){
 const launch=pendingPhoneLaunch;if(!launch||launch.clubId!==club?.id)return;pendingPhoneLaunch=null;
 if(launch.message){const s=ensureClubMessages();s.mode='inbox';s.openId=launch.message;currentTab='messages';return;}
 if(launch.prepare&&isPlayerUser()){const s=ensureMyInningsState();s.editId='prepare:new';s.openId=null;currentTab='innings';return;}
 if(launch.coaching){
  const requestedUser=session?.user?.id;
  const {data,error}=await supabase.rpc('get_my_coaching_updates',{p_club_id:club.id});
  if(launch.clubId!==club?.id||requestedUser!==session?.user?.id)return;
  const update=!error&&(data?.updates||[]).find(u=>u.source_key===launch.coaching);
  if(!update){currentTab='conversations';return;}
  pendingCoachingUpdate={...update,clubId:club.id,userId:session.user.id};
  currentTab=update.source_kind==='conversation'?'conversations':update.source_kind==='match'?'innings':'howwetrain';
  if(currentTab==='innings'){const state=ensureMyInningsState();state.season='all';state.format='';state.openId=update.match_id;state.editId=update.can_open?null:update.match_id;}
 }
}
async function openPhoneNotification(raw){
 let url;try{url=new URL(raw);if(url.origin!==location.origin||url.pathname!==location.pathname)return;}catch{return;}
 if(!await saveClubEditsBeforeNavigation())return;
 capturePhoneLaunch(url.searchParams);
 if(!session?.user){history.replaceState({},'',url);return routeAuth();}
 const clubId=url.searchParams.get('club');if(!allMemberships.some(m=>m.club_id===clubId)){alert('This notification belongs to another account or a club you no longer belong to.');return;}
 if(club?.id!==clubId||!document.getElementById('page')){localStorage.setItem('bdp-club-id',clubId);localStorage.setItem('bdp-context','club');history.replaceState({},'',url);await loadContext();}
 else{await applyPhoneLaunch();await renderTab();}
}
let phoneSessionSync='';
async function syncPhoneDeviceSession(){
 if(phoneIsDemo()||!phonePushSupported()||!session?.user||!club)return;
 const key=session.user.id+':'+club.id;if(phoneSessionSync===key)return;phoneSessionSync=key;
 try{
  await initialisePhoneApp();const reg=phoneRegistration||await navigator.serviceWorker.getRegistration('./');const sub=await reg?.pushManager.getSubscription();if(!sub||key!==session?.user?.id+':'+club?.id)return;
  if(Notification.permission==='denied'){
   await supabase.rpc('phone_app_api',{p_club_id:club.id,p_action:'disable',p_data:{endpoint:sub.endpoint}});
   if(key===session?.user?.id+':'+club?.id)await phoneWorkerMessage('CB_SIGN_OUT');return;
  }
  const {data,error}=await supabase.rpc('phone_app_api',{p_club_id:club.id,p_action:'get',p_data:{endpoint:sub.endpoint}});
  if(error){phoneSessionSync='';return;}
  if(key!==session?.user?.id+':'+club?.id)return;
  await phoneWorkerMessage(data.subscription_id?'CB_BIND':'CB_SIGN_OUT',data.binding);
 }catch{phoneSessionSync='';}
}
/* END PHONE APP */

/* BEGIN SELECTIONS MODEL — selections-owned attributes; no batting workflow dependency. */
const SE_FORMATS=[['t20','T20'],['limited_overs','Limited overs'],['long_form','Long-form']];
function seFormatLabel(d){return [SE_FORMATS.find(([key])=>key===d.format)?.[1],d.overs?d.overs+' overs':''].filter(Boolean).join(' · ');}
const SE_BATTING=[['unknown','Not coded'],['top','Top order'],['middle','Middle order'],['lower','Lower order']];
const SE_BOWLING=[['unknown','Not coded'],['pace','Quick'],['spin','Spinner'],['none','Does not bowl']];
const SE_LOAD=[['unknown','Not coded'],['frontline','Frontline'],['part_time','Part time']];
function seImportMatch(row,roster){
 const key=v=>String(v||'').trim().toLowerCase().replace(/\s+/g,' '),old=roster.find(p=>p.external_id===row.external_id);
 if(old)return old;
 const matches=roster.filter(p=>key(p.name)===key(row.name));
 if(matches.length>1)throw Error(row.name+' has more than one possible match. Check the playing list.');
 if(matches.length){const p=matches[0];if(p.external_id||(row.account_email&&p.account_email&&key(row.account_email)!==key(p.account_email)))throw Error(row.name+' has different registration details. Check the existing player.');return p;}
 if(row.account_email&&roster.some(p=>!p.external_id&&p.user_id&&key(p.account_email)===key(row.account_email)))throw Error(row.name+' shares an email with another playing-list entry. Check the name.');
 return null;
}
function seValidateRosterNames(rows,roster,importing=false){
 const key=v=>String(v||'').trim().toLowerCase().replace(/\s+/g,' '),working=roster.map(p=>({...p})),seen=new Set();
 for(const [index,row] of rows.entries()){
  const old=importing?seImportMatch(row,working):working.find(p=>row.id&&p.id===row.id),name=key(row.name);
  if((!old||key(old.name)!==name)&&working.some(p=>p!==old&&key(p.name)===name))throw Error(row.name+' is already on the playing list. Edit the existing entry.');
  if(old){if(seen.has(old.id))throw Error('Duplicate player in import.');seen.add(old.id);old.name=row.name;if(importing)old.external_id=row.external_id;}
  else working.push({...row,id:row.id||'new:'+index});
 }
}
function seCSVAccountEmail(row,headers,column){
 if(column<0||column===undefined)return {};
 const key=value=>String(value||'').toLowerCase().replace(/[^a-z]/g,''),heading=key(headers[column]);
 if(/parent|guardian|emergency/.test(heading))return {};
 if(heading==='accountholderemail'){
  const owner=headers.findIndex(h=>key(h)==='accountholder');
  if(owner<0||!['yes','true','1'].includes(String(row[owner]||'').trim().toLowerCase()))return {};
 }
 const email=String(row[column]||'').trim().toLowerCase();if(!email)return {};
 if(email.length>254||! /^[^\s@]+@[^\s@]+$/.test(email))throw Error('Use the player’s own valid email, or leave it blank.');
 return {account_email:email};
}
function seDayStatus(p,d){return (p?.availability?.available_dates||[]).includes(d.date)?'available':'unknown';}
function seCanPick(p,f,index,both=false){return !!p?.active&&f.details.days.filter((_,i)=>both||i===index).every(d=>seDayStatus(p,d)==='available');}
function seRole(p){if(!p)return '';return [SE_BATTING.find(([v])=>v===p.batting)?.[1],p.bowling==='pace'?'Quick':p.bowling==='spin'?'Spinner':p.bowling==='unknown'?'Bowling not coded':'',p.bowling_load==='part_time'?'Part time':'',p.keeper?'Keeper':''].filter(Boolean).join(' · ');}
function seOverlap(a,b){return a.date===b.date;}
function seUnselectedAvailable(roster,fixtures,date){const used=new Set();for(const f of fixtures){if(!f.details||f.details.cancelled)continue;f.details.days.forEach((day,j)=>{if(day.date===date)for(const slot of f.slots)if(slot['d'+(j+1)])used.add(slot['d'+(j+1)]);});}return roster.filter(p=>p.active&&seDayStatus(p,{date})==='available'&&!used.has(p.id)).sort((a,b)=>a.name.localeCompare(b.name));}
function seCounts(f,roster,index){const ps=f.slots.map(s=>roster.find(p=>p.id===s['d'+(index+1)])).filter(Boolean);return {players:ps.length,batters:ps.filter(p=>['top','middle'].includes(p.batting)).length,quicks:ps.filter(p=>p.bowling==='pace'&&p.bowling_load==='frontline').length,spinners:ps.filter(p=>p.bowling==='spin'&&p.bowling_load==='frontline').length,keepers:ps.filter(p=>p.keeper).length};}
function seUsed(p,day,fixtures,exclude={}){return fixtures.some(f=>!f.details.cancelled&&f.details.days.some((d,j)=>seOverlap(d,day)&&f.slots.some((s,i)=>!(f.id===exclude.id&&i===exclude.slot)&&s['d'+(j+1)]===p.id)));}
function sePairs(roster,fixture,fixtures,slot,fixed=null){if(fixture.details.days.length!==2)return [];const [d1,d2]=fixture.details.days,exclude={id:fixture.id,slot};
 const first=roster.filter(p=>p.active&&(!fixed||p.id===fixed)&&seDayStatus(p,d1)==='available'&&!seUsed(p,d1,fixtures,exclude)&&(fixed||seDayStatus(p,d2)!=='available'));
 const second=roster.filter(p=>p.active&&seDayStatus(p,d2)==='available'&&seDayStatus(p,d1)!=='available'&&!seUsed(p,d2,fixtures,exclude));
 return first.flatMap(a=>second.filter(b=>b.id!==a.id).map(b=>{const differences=[];let rank=0;for(const [key,weight,label] of [['batting',3,'batting order'],['bowling',5,'bowling type'],['bowling_load',2,'bowling workload'],['keeper',4,'keeping cover']]){if(a[key]==='unknown'||b[key]==='unknown'){rank+=3;differences.push(label+' not fully coded');}else if(a[key]!==b[key]){rank+=weight;differences.push('Different '+label);}}return {a,b,rank,reason:differences.length?differences.join(' · '):'Same batting role, bowling role and keeping cover'};})).sort((a,b)=>a.rank-b.rank||a.a.name.localeCompare(b.a.name)||a.b.name.localeCompare(b.b.name));
}
function seCSV(text){text=String(text).replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quote in CSV. Export the file again.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)throw Error('The CSV is empty.');return rows;}
function seBlankSlots(){return Array.from({length:11},()=>({d1:null,d2:null}));}
function seDate(date){return new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));}
function seTeamText(f,clubName){const s=f.published;if(!s)return '';const d=s.details,name=id=>s.players.find(p=>p.id===id)?.name||'Vacant';return [clubName+' — '+d.grade,d.competition,seFormatLabel(d),d.opposition?'v '+d.opposition:'',d.days.map((day,i)=>(d.days.length>1?'Day '+(i+1)+': ':'')+seDate(day.date)+(day.start?' · '+day.start:'' )).join('\n'),d.ground,d.meeting,d.cancelled?'MATCH CANCELLED':s.slots.map((slot,i)=>(i+1)+'. '+seSnapshotName(s,slot.d1,0,true)+(seSnapshotSplit(s,slot)?' (Day 1) / '+seSnapshotName(s,slot.d2,1,true)+' (Day 2)':'')).join('\n'),'Published version '+f.publication].filter(Boolean).join('\n');}
/* END SELECTIONS MODEL */

/* Selections terms editor, shared by the club subscription screen and direct setup. */
async function openSelectionsSubscription(clubId,clubName,{onSaved,onCancel,host,mode}={}){
 const call=async(action,data={})=>{
  const {data:result,error}=await supabase.rpc('club_selections_api',{p_club_id:clubId,p_action:action,p_data:data});
  if(error){const failure=Error(error.message);failure.code=error.code;throw failure;}return result;
 };
 let context;
 if(host){host.__canLeave=()=>false;host.innerHTML='<p role="status">Loading…</p>';}
 try{context=await call('subscription_context');}catch(e){
  if(host){host.__canLeave=()=>true;host.innerHTML=`<button class="btn ghost" id="seBillingClose">Back</button><p role="alert">${seEsc(e.message)}</p>`;host.querySelector('#seBillingClose').onclick=()=>onCancel?.();}
  else alert(e.message);return;
 }
 const p=context.pricing,s=context.subscription||{},a=context.access||{},calendars=context.calendars||[],history=context.history||[],readOnly=context.can_manage===false;
 const trialDays=s.status==='trial'&&s.trial_started&&s.trial_ends?Math.round((new Date(s.trial_ends+'T12:00:00Z')-new Date(s.trial_started+'T12:00:00Z'))/86400000)+1:context.default_trial_days||context.inherited_trial_days||60;
 const today=new Date().toLocaleDateString('en-CA',{timeZone:a.timezone||'Australia/Sydney'});
 const annualPrice=productMode=>s.annual_price_cents??(productMode==='bundle'&&p.bundle_annual_price_cents!=null&&context.batting_annual_price_cents!=null?p.bundle_annual_price_cents-context.batting_annual_price_cents:p.annual_price_cents);
 const priceMissing='Set the price in Platform Settings.';
 const freeTerms=terms=>terms.special_rate_never_ends&&Number(terms.adjustment_percent)===100;
 const initial={access_kind:s.status==='disabled'?'ended':s.status==='active'?'paid':'trial',mode:mode||a.mode||'bundle',calendar:s.calendar||calendars.find(x=>x.code==='australia')?.code||calendars[0]?.code||'',active_from:s.active_from||today,active_until:s.active_until||'',adjustment_percent:s.adjustment_percent??0,adjustment_end:s.adjustment_end||'',special_rate_never_ends:!!s.special_rate_never_ends,expiry_action:s.expiry_action||'renewal_approval',amount_paid_cents:s.amount_paid_cents||0,timezone:a.timezone||'Australia/Sydney',continuation_agreed:!!s.continuation_agreed};
 const dialog=host?null:document.createElement('dialog'),view=host||dialog,pricingDialog=dialog||host?.closest('dialog');
 const canOpenPricing=!readOnly&&pricingDialog&&typeof seCanManageSubscriptions==='function'&&seCanManageSubscriptions()&&typeof renderPlatformConsole==='function';
 if(dialog){dialog.style.maxWidth='700px';dialog.style.width='calc(100% - 32px)';dialog.style.maxHeight='90vh';dialog.style.overflow='auto';}
 view.innerHTML=seStyles()+`<section class="se-page"><div class="se-top"><h2>${host?'Selections':`Selections · ${seEsc(clubName)}`}</h2><button class="btn ghost" id="seBillingClose">${host?'Back':'Close'}</button></div><form id="seSubscriptionForm"><input name="status" type="hidden"><div class="se-form-grid"><label>Access<select name="access_kind">${seOpt([['trial','Free trial'],['paid','Subscription'],['ended','Ended']],initial.access_kind)}</select></label><label>Starts<input name="active_from" type="date" value="${initial.active_from}" required></label></div><p class="se-form-note" id="seTrialTerms"></p><div id="sePaidTerms" hidden><p class="se-form-note" id="seAnnualPrice"></p><button class="btn ghost" type="button" id="seOpenPricing" hidden>Platform Settings</button><label class="se-check" id="seAgreementLabel"><input name="continuation_agreed" type="checkbox" ${initial.continuation_agreed?'checked':''}>Club agreement confirmed</label><details id="seTermDetails"><summary>Term details</summary><div class="se-form-grid"><label>Access ends<input name="active_until" type="date" value="${initial.active_until}"></label><label>Rate reduction (%)<input name="adjustment_percent" type="number" min="0" max="100" step="0.01" value="${initial.adjustment_percent}"></label><label>Special rate ends<select name="special_rate_never_ends">${seOpt([['false','On a date'],['true','Never']],String(initial.special_rate_never_ends))}</select><input name="adjustment_end" type="date" aria-label="Special rate end date" value="${initial.adjustment_end}"></label><label>Payment recorded (${seEsc(s.currency||p.currency)})<input name="amount_paid" type="number" min="0" step="0.01" value="${(initial.amount_paid_cents/100).toFixed(2)}"></label><label>At expiry<select name="expiry_action">${seOpt([['renewal_approval','Require renewal approval'],['return_standard','Return to standard rate'],['end_subscription','End access']],initial.expiry_action)}</select></label></div>${s.club_id?'<button class="btn ghost" type="button" id="seRenewTerms">Prepare renewal</button>':''}</details><button class="btn ghost" type="button" id="sePreviewTerms">Preview amount</button><p id="seQuote" class="se-form-note"></p></div><details id="seMoreSettings"><summary>More settings</summary><div class="se-form-grid">${host?`<input name="mode" type="hidden" value="${seEsc(initial.mode)}">`:`<label>Products<select name="mode">${seOpt([['bundle','Club Batting + Selections'],['standalone','Selections only']],initial.mode)}</select></label>`}<label>Club year<select name="calendar">${seOpt(calendars.map(x=>[x.code,x.label]),initial.calendar)}</select></label><label>Fixture time zone<input name="timezone" value="${seEsc(initial.timezone)}" required></label></div></details><div class="se-actions se-editor-actions"><button class="btn" type="submit" id="seSaveSubscription">Save</button></div></form><p id="seBillingStatus" role="status"></p>${history.length?`<details><summary>History</summary>${history.map(h=>`<p class="se-muted">${seEsc(new Date(h.created_at).toLocaleDateString('en-AU'))} · ${seEsc(h.snapshot.status)} · ${seEsc(h.snapshot.active_from)}${h.snapshot.active_until?' to '+seEsc(h.snapshot.active_until):' · ongoing'}</p>`).join('')}</details>`:''}</section>`;
 if(dialog){document.body.append(dialog);dialog.showModal();dialog.onclose=()=>dialog.remove();}
 let dirty=false,busy=false,pending=null,previousKind=initial.access_kind;
 const status=view.querySelector('#seBillingStatus'),form=view.querySelector('#seSubscriptionForm'),save=view.querySelector('#seSaveSubscription'),field=name=>form.elements.namedItem(name);
 const canLeave=()=>{
  if(busy){status.textContent='Saving…';return false;}
  if(pending){status.textContent='Retry the unconfirmed save before leaving.';return false;}
  return !dirty||confirm('Discard unsaved changes?');
 };
 if(host)host.__canLeave=canLeave;
 const cancel=()=>{if(!canLeave())return;if(dialog)dialog.close();onCancel?.();};
 view.querySelector('#seBillingClose').onclick=cancel;
 dialog?.addEventListener('cancel',e=>{e.preventDefault();cancel();});
 const values=()=>{
  const kind=field('access_kind').value;
  const result={status:kind==='trial'?'trial':kind==='ended'?'disabled':'active',mode:field('mode').value,calendar:field('calendar').value,active_from:field('active_from').value,active_until:field('active_until').value,timezone:field('timezone').value,revision:s.revision||0,access_revision:a.revision||0,annual_price_cents:annualPrice(field('mode').value)??null,adjustment_percent:Number(field('adjustment_percent').value||0),adjustment_end:field('adjustment_end').value,special_rate_never_ends:field('special_rate_never_ends').value==='true',expiry_action:field('expiry_action').value,amount_paid_cents:Math.round(Number(field('amount_paid').value||0)*100),continuation_agreed:field('continuation_agreed').checked};
  if(kind==='paid'&&freeTerms(result))Object.assign(result,{active_until:'',adjustment_end:'',continuation_agreed:false});
  if(kind==='trial')Object.assign(result,{active_until:'',adjustment_percent:0,adjustment_end:'',special_rate_never_ends:false,amount_paid_cents:0,continuation_agreed:false});
  if(kind==='ended')Object.assign(result,{annual_price_cents:annualPrice(field('mode').value)??null,adjustment_percent:s.adjustment_percent??0,adjustment_end:s.adjustment_end||'',special_rate_never_ends:!!s.special_rate_never_ends,amount_paid_cents:s.amount_paid_cents||0,continuation_agreed:!!s.continuation_agreed});
  return result;
 };
 const sync=()=>{
  const kind=field('access_kind').value,d=values(),paid=kind==='paid',free=freeTerms(d);
  field('status').value=d.status;
  view.querySelector('#sePaidTerms').hidden=!paid;
  const missing=d.annual_price_cents==null;
  view.querySelector('#seAnnualPrice').textContent=missing?priceMissing:`${s.annual_price_cents==null?'Annual price':'Agreed annual price'} · ${money(d.annual_price_cents,s.currency||p.currency)}`;
  view.querySelector('#seAnnualPrice').hidden=free;
  view.querySelector('#seOpenPricing').hidden=!missing||!canOpenPricing||free;
  view.querySelector('#sePreviewTerms').disabled=busy||!!pending||readOnly||paid&&missing&&!free;
  save.disabled=busy||readOnly||paid&&missing&&!free&&!pending;
  field('continuation_agreed').required=paid&&!free;
  view.querySelector('#seAgreementLabel').hidden=!paid||free;
  field('active_until').disabled=!paid||free||readOnly;
  field('active_until').closest('label').hidden=free;
  field('adjustment_end').hidden=field('special_rate_never_ends').value==='true';
  field('active_from').readOnly=kind==='trial'&&!!s.trial_started;
  save.textContent=pending?'Retry save':!s.club_id&&kind==='trial'?'Start trial':'Save';
  let hint='';
  if(kind==='trial'){
   const date=new Date(field('active_from').value+'T12:00:00Z');
   if(Number.isFinite(+date)){date.setUTCDate(date.getUTCDate()+trialDays-1);hint=`${trialDays}-day trial · ends ${s.status==='trial'&&s.trial_ends?s.trial_ends:date.toISOString().slice(0,10)}`;}
  }else if(paid&&free)hint='$0 · no expiry';
  view.querySelector('#seTrialTerms').textContent=hint;
 };
 if(s.trial_started&&s.status!=='trial')field('access_kind').querySelector('option[value="trial"]').disabled=true;
 const changed=()=>{
  dirty=true;const kind=field('access_kind').value;view.querySelector('#seQuote').textContent='';
  if(kind!==previousKind){
   if(kind==='trial'&&s.trial_started)field('active_from').value=s.trial_started;
   if(kind==='paid'&&previousKind!=='paid'){field('continuation_agreed').checked=false;field('active_until').value='';}
   previousKind=kind;view.querySelector('#seQuote').textContent='';
  }
  sync();
 };
 form.addEventListener('input',changed);form.addEventListener('change',changed);sync();
 view.querySelector('#seOpenPricing').onclick=async()=>{
  if(!canOpenPricing||!canLeave())return;
  pricingDialog.close();platformView='settings';await renderPlatformConsole();
 };
 const preview=async()=>{
  if(busy||pending)return;
  const data=values();
  if(field('access_kind').value==='paid'&&data.annual_price_cents==null&&!freeTerms(data)){status.textContent=priceMissing;return null;}
  status.textContent='Calculating…';
  try{
   const q=await call('preview_subscription',data);
   view.querySelector('#seQuote').textContent=q.ongoing_complimentary?'Free · no expiry':`${money(q.amount_due_cents,q.currency)} · through ${q.active_until}`;
   status.textContent='';return q;
  }catch(e){status.textContent=e.message;return null;}
 };
 view.querySelector('#sePreviewTerms').onclick=preview;
 view.querySelector('#seRenewTerms')?.addEventListener('click',()=>{
  field('access_kind').value='paid';previousKind='paid';const next=new Date((s.active_until||today)+'T12:00:00Z');
  if(s.active_until)next.setUTCDate(next.getUTCDate()+1);
  field('active_from').value=next.toISOString().slice(0,10)>today?next.toISOString().slice(0,10):today;
  field('active_until').value='';field('amount_paid').value='0.00';field('continuation_agreed').checked=false;
  if(s.expiry_action==='return_standard'&&!s.special_rate_never_ends){field('adjustment_percent').value='0';field('adjustment_end').value='';}
  dirty=true;sync();void preview();
 });
 const lock=()=>{
  form.querySelectorAll('input,select,button').forEach(el=>el.disabled=busy||!!pending||readOnly);
  save.disabled=busy||readOnly;
  view.querySelector('#seBillingClose').disabled=busy;
  if(!busy&&!pending)sync();
 };
 form.onsubmit=async e=>{
  e.preventDefault();if(busy||readOnly)return;
  const data=values();
  if(!pending&&field('access_kind').value==='paid'&&data.annual_price_cents==null&&!freeTerms(data)){status.textContent=priceMissing;return;}
  pending??={...data,request_id:crypto.randomUUID()};busy=true;lock();status.textContent='Saving…';
  try{
   const saved=await call('save_subscription',pending);pending=null;dirty=false;busy=false;
   if(host)host.__canLeave=()=>true;
   if(dialog)dialog.close();
   if(onSaved){
    try{await onSaved(saved);}catch(refreshError){
     const message='Saved. Refresh to see the updated status. '+refreshError.message;
     if(view.isConnected)status.textContent=message;else alert(message);
    }
   }else await openSelectionsSubscription(clubId,clubName,{onCancel,host,mode});
  }catch(e){
   if(e.code)pending=null;
   status.textContent=e.code?e.message:'Save not confirmed. Retry save.';
  }finally{busy=false;if(form.isConnected){lock();if(pending)save.textContent='Retry save';}}
 };
 if(readOnly){form.querySelectorAll('input,select').forEach(el=>el.disabled=true);form.querySelectorAll('button').forEach(el=>el.hidden=true);status.textContent='View only';}
}

/* Selections product administration. Uses the existing guarded billing RPC. */
function seCanManageSubscriptions(){return ['owner','commercial_admin'].includes(platformRole);}
function seCanReadSubscriptions(){return ['owner','commercial_admin','support_admin'].includes(platformRole);}
function openPlatformSelections(){return openPlatformClubs();}
function seSubscriptionSummary(context){
 const a=context.access||{},s=context.subscription||{},today=new Date().toLocaleDateString('en-CA',{timeZone:a.timezone||'Australia/Sydney'}),starts=a.active_from||s.active_from,ends=a.valid_until||s.active_until;
 if(!a.status)return {label:'Not activated',detail:'Choose a free trial or agree subscription terms to get started.'};
 if(a.status==='disabled')return {label:s.club_id?'Access ended':'Not activated',detail:'Access is disabled. Open the subscription to review the next step.'};
 if(starts&&starts>today)return {label:'Scheduled',detail:`Access starts ${niceDate(starts)}${ends?` and ends ${niceDate(ends)}`:''}.`};
 if(ends&&ends<today)return {label:'Expired',detail:`Access ended ${niceDate(ends)}. Review continuation or renewal terms.`};
 if(s.status==='trial')return {label:'Free trial',detail:`Trial through ${niceDate(s.trial_ends||ends)}. Continuation needs approval.`};
 if(s.special_rate_never_ends&&Number(s.adjustment_percent)===100)return {label:'Complimentary',detail:'Ongoing free access, with no expiry or renewal.'};
 if(a.status==='pilot')return {label:'Pilot access',detail:ends?`Access through ${niceDate(ends)}.`:'Pilot access is enabled.'};
 return {label:'Active',detail:ends?`Access through ${niceDate(ends)}.`:'Access is enabled.'};
}
async function renderPlatformSelections(){return openPlatformClubs();}

/* One club workspace, independently recorded product terms. */
let platformClubsLoad=0;
function openPlatformClubs(){platformView='clubs';platformSelectedProspectId=null;platformSelectedOnboardingId=null;return renderPlatformConsole();}
async function clubProductContext(id){
 const call=async(name)=>{const {data,error}=await supabase.rpc(name,{p_club_id:id,p_action:'context'});if(error)throw Error(error.message);return data;};
 const [batting,selections]=await Promise.allSettled([call('platform_club_batting_api'),(async()=>{const {data,error}=await supabase.rpc('club_selections_api',{p_club_id:id,p_action:'subscription_context'});if(error)throw Error(error.message);return data;})()]);
 return {batting:batting.status==='fulfilled'?batting.value:null,battingError:batting.status==='rejected'?batting.reason.message:'',selections:selections.status==='fulfilled'?selections.value:null,selectionsError:selections.status==='rejected'?selections.reason.message:''};
}
function clubBattingSummary(context){
 const s=context?.subscription,t=context?.trial;
 if(!s||context.can_activate)return {label:'No subscription',detail:''};
 const today=context.starts_on||new Date().toISOString().slice(0,10);
 if(s.active_until&&s.active_until!=='infinity'&&s.active_until<today)return {label:'Expired',detail:`Ended ${niceDate(s.active_until)}`};
 if(s.special_rate_never_ends&&Number(s.adjustment_percent)===100)return {label:'Complimentary',detail:'$0 · no expiry'};
 if(context.status==='trial')return {label:'Free trial',detail:`Until ${niceDate(t?.ends_on||s.active_until)}`};
 return {label:'Active',detail:s.active_until==='infinity'?'Ongoing':`Until ${niceDate(s.active_until)}`};
}
function clubSelectionSummary(context){
 const summary=seSubscriptionSummary(context);const s=context?.subscription,a=context?.access;
 if(summary.label==='Not activated')return {label:'Not added',detail:''};
 if(summary.label==='Complimentary')return {label:'Complimentary',detail:'$0 · no expiry'};
 const end=summary.label==='Free trial'?s?.trial_ends||a?.valid_until:a?.valid_until||s?.active_until;
 return {label:summary.label,detail:summary.label==='Scheduled'?`From ${niceDate(a?.active_from||s?.active_from)}`:end?`${summary.label==='Expired'?'Ended':'Until'} ${niceDate(end)}`:summary.label==='Complimentary'?'$0 · no expiry':''};
}
function clubProductsStyles(){return seStyles()+`<style>.cp-list{display:grid;gap:10px;margin-top:16px}.cp-row{display:grid;grid-template-columns:minmax(180px,1.4fr) minmax(160px,1fr) minmax(150px,1fr) auto;gap:16px;align-items:center;padding:16px;border:1px solid #dce2ee;border-radius:12px;background:white}.cp-product-label{display:block;font-size:12px;color:#64748b;margin-bottom:4px}.cp-row strong{font-size:16px}.cp-detail{font-size:13px;color:#64748b;margin:4px 0 0}.cp-products{display:grid;gap:12px;margin-top:18px}.cp-product{display:flex;gap:16px;align-items:center;justify-content:space-between;border:1px solid #dce2ee;padding:16px;border-radius:10px}.cp-product h3{margin:0 0 6px}.cp-product p{margin:0}.cp-dialog{border:1px solid #cbd5e1;border-radius:14px;width:calc(100% - 32px);max-width:680px;max-height:90vh;overflow:auto;padding:20px}.cp-dialog::backdrop{background:#0b173766}.cp-dialog details{margin:16px 0}.cp-dialog summary{cursor:pointer;min-height:36px}.cp-dialog [hidden]{display:none!important}.cp-dialog input,.cp-dialog select{font:inherit}.cp-search{max-width:440px;margin-top:16px}@media(max-width:700px){.cp-row{grid-template-columns:1fr 1fr;gap:12px}.cp-row>strong{grid-column:1/-1}.cp-row>.btn{grid-column:1/-1}.cp-dialog{padding:14px}.cp-product{padding:12px;gap:8px}}</style>`;}
async function renderPlatformActiveClubs(message=''){
 const page=document.getElementById('platformPage'),sequence=++platformClubsLoad,userId=session?.user?.id;
 const current=()=>sequence===platformClubsLoad&&platformView==='clubs'&&userId===session?.user?.id&&page===document.getElementById('platformPage');
 page.innerHTML='<div class="splash">Loading clubs…</div>';
 const [clubsRes,removedRes]=await Promise.all([supabase.from('clubs').select('id,name,archived_at').is('archived_at',null).order('name'),supabase.from('platform_club_removals').select('club_id,club_name,contact_name,contact_email,removed_at').order('removed_at',{ascending:false})]);
 if(!current())return;
 if(clubsRes.error||removedRes.error){page.innerHTML=`<section class="admin-card"><p>${seEsc(clubsRes.error?.message||removedRes.error?.message)}</p><button class="btn" id="cpRetry">Retry</button></section>`;page.querySelector('#cpRetry').onclick=()=>renderPlatformActiveClubs();return;}
 const rows=(clubsRes.data||[]).map(club=>({club})),removed=removedRes.data||[];let next=0;
 if(seCanReadSubscriptions())await Promise.all(Array.from({length:Math.min(4,rows.length)},async()=>{while(next<rows.length){const row=rows[next++];row.products=await clubProductContext(row.club.id);}}));
 if(!current())return;
 page.innerHTML=clubProductsStyles()+`<section class="se-page"><div class="se-top"><h1>Clubs</h1><button class="btn ghost" id="cpRefresh">Refresh</button></div><label class="cp-search">Find a club<input id="cpSearch" type="search" placeholder="Club name"></label>${message?`<p role="status">${seEsc(message)}</p>`:''}<div class="cp-list" id="cpClubs"></div><p id="cpEmpty" hidden>No matching clubs.</p>${removed.length?`<details class="se-card" style="margin-top:16px"><summary>Archived clubs · ${removed.length}</summary>${removed.map(row=>`<div class="message-row"><strong>${seEsc(row.club_name)}</strong><button class="btn ghost" data-removed-promo="${seEsc(row.club_id)}">Add to pipeline</button></div>`).join('')}</details>`:''}</section>`;
 const render=()=>{const q=page.querySelector('#cpSearch').value.trim().toLowerCase(),visible=rows.filter(row=>row.club.name.toLowerCase().includes(q));page.querySelector('#cpEmpty').hidden=!!visible.length;page.querySelector('#cpClubs').innerHTML=visible.map(({club:c,products:p})=>{
  const batting=p?.batting?clubBattingSummary(p.batting):null,selections=p?.selections?clubSelectionSummary(p.selections):null;
  const status=(label,summary,error)=>`<div><span class="cp-product-label">${label}</span>${error?'Status unavailable':seEsc(summary?.label||'Restricted')}<div class="cp-detail">${seEsc(summary?.detail||'')}</div></div>`;
  return `<article class="cp-row"><strong>${seEsc(c.name)}</strong>${status('Club Batting',batting,p?.battingError)}${status('Selections',selections,p?.selectionsError)}${seCanReadSubscriptions()?`<button class="btn" data-club-manage="${seEsc(c.id)}">${seCanManageSubscriptions()?'Manage':'View'}</button>`:''}</article>`;
 }).join('');page.querySelectorAll('[data-club-manage]').forEach(button=>button.onclick=()=>{const row=rows.find(r=>r.club.id===button.dataset.clubManage);return openClubSubscriptions(row.club.id,row.club.name);});};
 page.querySelector('#cpSearch').oninput=render;page.querySelector('#cpRefresh').onclick=()=>renderPlatformActiveClubs();page.querySelectorAll('[data-removed-promo]').forEach(button=>button.onclick=()=>openPlatformLeadEntry(removed.find(r=>r.club_id===button.dataset.removedPromo)));render();
}
async function openClubSubscriptions(clubId,clubName,{onSelectionsSaved}={}){
 const dialog=document.createElement('dialog');dialog.id='clubSubscriptionDialog';dialog.className='cp-dialog';dialog.innerHTML=clubProductsStyles()+`<section class="se-page"><div class="se-top"><h2>${seEsc(clubName)}</h2><button class="btn ghost" id="cpClose">Close</button></div><div id="clubProductEditor"><p>Loading…</p></div></section>`;document.body.append(dialog);dialog.showModal();
 const host=dialog.querySelector('#clubProductEditor'),userId=session?.user?.id;let products,busy=false;
 const current=()=>dialog.isConnected&&userId===session?.user?.id;
 const canLeave=()=>!busy&&(!host.__canLeave||host.__canLeave());
 dialog.querySelector('#cpClose').onclick=()=>{if(canLeave())dialog.close();};dialog.addEventListener('cancel',event=>{if(!canLeave())event.preventDefault();});dialog.onclose=()=>dialog.remove();
 const refresh=async()=>{busy=true;products=await clubProductContext(clubId);busy=false;if(current())overview();};
 const saved=async(product)=>{await refresh();if(!current())return;if(platformView==='clubs'&&document.getElementById('platformPage'))await renderPlatformActiveClubs();if(product==='selections'&&onSelectionsSaved){dialog.close();await onSelectionsSaved();}};
 const overview=()=>{
  delete host.__canLeave;
  host.innerHTML=`<div class="cp-products">${[['batting','Club Batting'],['selections','Selections']].map(([key,label])=>{
   const context=products[key],error=products[key+'Error'],summary=context?(key==='batting'?clubBattingSummary(context):clubSelectionSummary(context)):null,has=context&&(key==='batting'?!context.can_activate:!!context.subscription||context.access?.status&&context.access.status!=='disabled');
   return `<section class="cp-product"><div><h3>${label}</h3><p>${error?'Status unavailable':seEsc(summary?.label||'Unavailable')}</p>${summary?.detail?`<p class="cp-detail">${seEsc(summary.detail)}</p>`:''}</div>${error?'<button class="btn ghost" data-cp-retry>Retry</button>':`<button class="btn ${has?'ghost':''}" data-club-product="${key}" ${key==='selections'&&products.battingError?'disabled':''}>${context.can_manage===false?'View':has?'Change':'Add'}</button>`}</section>`;
  }).join('')}</div>${platformRole==='owner'?'<details><summary>Club settings</summary><button class="btn ghost danger-lite" id="cpArchive">End &amp; remove club</button></details>':''}`;
  host.querySelectorAll('[data-cp-retry]').forEach(button=>button.onclick=refresh);
  host.querySelectorAll('[data-club-product]').forEach(button=>button.onclick=()=>{
   if(button.dataset.clubProduct==='selections')return openSelectionsSubscription(clubId,clubName,{host,mode:products.batting?.subscription&&['active','grace'].includes(products.batting.subscription.status)?'bundle':'standalone',onCancel:overview,onSaved:()=>saved('selections')});
   return renderClubBattingEditor(host,clubId,products.batting,{onCancel:overview,onSaved:()=>saved('batting')});
  });host.querySelector('#cpArchive')?.addEventListener('click',()=>{dialog.close();openEndClubDialog(clubId);});
 };
 await refresh();
}
function renderClubBattingEditor(host,clubId,context,{onCancel,onSaved}){
 const s=context.can_activate?null:context.subscription,canManage=context.can_manage!==false,initialFree=s?.special_rate_never_ends&&Number(s.adjustment_percent)===100,existingTrial=context.status==='trial';let busy=false,dirty=false,pending=null,previousKind=initialFree?'complimentary':existingTrial?'trial':'paid';
 host.__canLeave=()=>{if(busy||pending){alert('Retry the unconfirmed save before leaving.');return false;}return !dirty||confirm('Discard these changes?');};
 host.innerHTML=`<form id="cpBattingForm"><div class="se-top" style="margin:18px 0"><h3>Club Batting</h3><button class="btn ghost" type="button" id="cpBattingBack">Back</button></div><div class="se-form-grid"><label>Access<select name="access_kind">${seOpt(s?[...(existingTrial?[['trial','Free trial']]:[]),['complimentary','Complimentary'],['paid','Paid subscription']]:[...(context.trial_available?[['trial','Free trial']]:[]),['complimentary','Complimentary']],s?initialFree?'complimentary':existingTrial?'trial':'paid':context.trial_available?'trial':'complimentary')}</select></label>${s?`<label id="cpBattingEndLabel">Until<input name="active_until" type="date" value="${s.active_until==='infinity'?'':seEsc(s.active_until)}"></label>`:''}</div><p id="cpBattingHint" class="cp-detail"></p>${s?`<details id="cpBattingMore"><summary>More settings</summary><div class="se-form-grid"><label>Rate reduction %<input name="adjustment_percent" type="number" min="0" max="100" value="${Number(s.adjustment_percent)||0}"></label><label>Special rate ends<select name="never_ends">${seOpt([['false','On a date'],['true','Never']],String(!!s.special_rate_never_ends))}</select><input name="adjustment_end" type="date" aria-label="Special rate ends" value="${seEsc(s.adjustment_end||'')}"></label><label>At expiry<select name="expiry_action">${seOpt([['renewal_approval','Review renewal'],['return_standard','Return to standard price'],['end_subscription','End access']],s.expiry_action||'renewal_approval')}</select></label></div></details><label class="se-check" id="cpBattingAgreement"><input name="agreed" type="checkbox">Club has agreed to these terms</label>`:`<details><summary>More settings</summary><label>Club year<select name="calendar">${seOpt((context.calendars||[]).map(c=>[c.code,c.label]),context.calendar)}</select></label></details>`}<div class="se-actions" style="margin-top:16px"><button class="btn" type="submit" id="cpBattingSave">${s?'Save':'Start trial'}</button></div><p id="cpBattingStatus" role="status"></p></form>`;
 const form=host.querySelector('form'),field=name=>form.elements.namedItem(name),status=host.querySelector('#cpBattingStatus');
 const sync=()=>{const kind=field('access_kind').value;if(s&&kind==='paid'&&previousKind!=='paid'){field('adjustment_percent').value='0';field('never_ends').value='false';field('adjustment_end').value='';field('agreed').checked=false;if(s.active_until==='infinity')field('active_until').value='';}previousKind=kind;host.querySelector('#cpBattingHint').textContent=kind==='trial'?(s?`Until ${niceDate(s.active_until)}`:`${context.default_trial_days}-day trial`):kind==='complimentary'?'$0 · no expiry':'';if(s){host.querySelector('#cpBattingEndLabel').hidden=kind!=='paid';host.querySelector('#cpBattingMore').hidden=kind!=='paid';host.querySelector('#cpBattingAgreement').hidden=kind!=='paid';field('active_until').required=kind==='paid';}host.querySelector('#cpBattingSave').textContent=s?'Save':kind==='trial'?'Start trial':'Add Club Batting';};sync();
 form.addEventListener('input',()=>{dirty=true;sync();});form.addEventListener('change',()=>{dirty=true;sync();});host.querySelector('#cpBattingBack').onclick=()=>{if(host.__canLeave())onCancel();};
 if(!canManage){form.querySelectorAll('input,select').forEach(x=>x.disabled=true);host.querySelector('#cpBattingSave').hidden=true;}
 form.onsubmit=async(event)=>{
  event.preventDefault();if(busy||!canManage)return;
  const kind=field('access_kind').value;
  if(!pending&&s&&kind==='paid'&&!field('agreed').checked){status.textContent='Confirm the club agreement.';return;}
  let name,data;
  if(s){const free=kind==='complimentary';name='platform_club_batting_api';data={p_club_id:clubId,p_action:'update_terms',p_data:{kind,state_token:context.state_token,request_id:crypto.randomUUID(),adjustment_percent:free?100:Number(field('adjustment_percent').value),never_ends:free||field('never_ends').value==='true',adjustment_end:free||field('never_ends').value==='true'?null:field('adjustment_end').value||null,active_until:free?null:field('active_until').value,expiry_action:field('expiry_action').value,continuation_agreed:field('agreed').checked}};}
  else{name='platform_club_batting_api';data={p_club_id:clubId,p_action:'activate',p_data:{kind,calendar:field('calendar').value,timezone:context.timezone||'Australia/Sydney',state_token:context.state_token,request_id:crypto.randomUUID()}};}
  pending??={name,data};busy=true;status.textContent='Saving…';form.querySelectorAll('input,select,button').forEach(x=>x.disabled=true);
  try{const result=await supabase.rpc(pending.name,pending.data);if(result.error){if(result.error.code)pending=null;throw Error(result.error.message);}pending=null;dirty=false;busy=false;delete host.__canLeave;try{await onSaved();}catch(e){status.textContent='Saved. Refresh to see the change.';}}
  catch(e){status.textContent=(pending?'Save not confirmed. Retry. ':'')+e.message;}
  finally{busy=false;if(form.isConnected){form.querySelectorAll('input,select,button').forEach(x=>x.disabled=!!pending);host.querySelector('#cpBattingSave').disabled=false;host.querySelector('#cpBattingSave').textContent=pending?'Retry save':s?'Save':kind==='trial'?'Start trial':'Add Club Batting';}}
 };
}
function clubPlatformSettingsStyles(){return `<style>
 #productPriceSettings,.cp-settings-disclosure{max-width:980px;margin:0 auto 14px;min-width:0;box-sizing:border-box}
 .cp-price-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}
 .cp-price-product{min-width:0;margin:0;padding:16px;border:1px solid var(--line,#d8deea);border-radius:12px;background:#fafbfd}
 .cp-price-product h3{font-size:16px;margin:0 0 16px;color:var(--navy2,#172544)}
 .cp-price-product h3 small{display:inline;margin-left:4px;font-size:12px;font-weight:400;color:var(--muted,#667085)}
 .cp-price-product label{display:grid;gap:7px;font-size:13px}
 .cp-price-product label+label{margin-top:16px}
 .cp-price-product input{min-width:0;width:100%;box-sizing:border-box}
 .cp-price-unit{margin:0;color:var(--muted,#667085);font-size:13px}
 details.cp-settings-disclosure{display:block;border:1px solid var(--line,#d8deea);border-radius:12px;background:#fff;padding:0;overflow:hidden}
 details.cp-settings-disclosure>summary{display:list-item;list-style:disclosure-closed inside;padding:16px 18px;cursor:pointer;font-weight:700;color:var(--navy2,#172544)}
 details.cp-settings-disclosure[open]>summary{list-style-type:disclosure-open}
 details.cp-settings-disclosure>summary::-webkit-details-marker{display:inline}
 details.cp-settings-disclosure:not([open])>:not(summary){display:none!important}
 .cp-settings-body{padding:0 18px 18px;min-width:0}
 .cp-settings-body>.admin-card{margin:0 0 14px}
 .cp-settings-body .form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .cp-settings-body input,.cp-settings-body select{max-width:100%;min-width:0;box-sizing:border-box}
 @media(max-width:760px){.cp-price-grid,.cp-settings-body .form-grid{grid-template-columns:minmax(0,1fr)}.cp-settings-body{padding:0 12px 12px}.cp-price-product{padding:14px}.cp-price-product h3{margin-bottom:12px}}
 </style>`;}
async function mountProductPriceSettings(){
 const host=document.getElementById('productPriceSettings');if(!host||!seCanReadSubscriptions())return;
 host.innerHTML='<section class="admin-card"><h2>Product pricing &amp; trials</h2><p>Loading…</p></section>';
 const {data:p,error}=await supabase.rpc('platform_product_pricing_api',{p_action:'context'});if(!host.isConnected)return;
 if(error){host.innerHTML=`<section class="admin-card"><h2>Product pricing &amp; trials</h2><p>${seEsc(error.message)}</p><button class="btn" id="cpPricingRetry">Retry</button></section>`;host.querySelector('button').onclick=mountProductPriceSettings;return;}
 const amount=v=>v==null?'':(v/100).toFixed(2);
 host.innerHTML=seStyles()+`<section class="admin-card form-wide se-page"><h2>Product pricing &amp; trials</h2><p class="cp-price-unit">${seEsc(p.currency)} per year</p><form id="cpProductPricingForm"><div class="cp-price-grid"><section class="cp-price-product" aria-labelledby="cpBattingPriceHeading"><h3 id="cpBattingPriceHeading">Club Batting</h3><label>Annual price<input name="batting_annual_price" type="number" min="0" step="0.01" required value="${amount(p.batting_annual_price_cents)}"></label><label>Free trial (days)<input name="batting_trial_days" type="number" min="1" max="180" step="1" required value="${Number(p.trial_days??60)}"></label></section><section class="cp-price-product" aria-labelledby="cpSelectionsPriceHeading"><h3 id="cpSelectionsPriceHeading">Teams &amp; availability</h3><label>Annual price<input name="selection_annual_price" type="number" min="0" step="0.01" placeholder="Not set" value="${amount(p.selection_annual_price_cents)}"></label><label>Free trial (days)<input name="selection_trial_days" type="number" min="1" max="365" step="1" required value="${Number(p.selection_trial_days??21)}"></label></section><section class="cp-price-product" aria-labelledby="cpBothPriceHeading"><h3 id="cpBothPriceHeading">Both products <small>Optional</small></h3><label>Annual price<input name="bundle_annual_price" type="number" min="0" step="0.01" placeholder="Not set" value="${amount(p.bundle_annual_price_cents)}"></label><p>Each product keeps its own trial length.</p></section></div><p class="help">Trial lengths apply to new trials. Existing trial dates and agreed club terms stay unchanged.</p><button class="btn" id="cpPricingSave" type="submit" disabled>Saved</button><p role="status"></p></form></section>`;
 const form=host.querySelector('form'),status=form.querySelector('[role=status]'),save=form.querySelector('button');if(!p.can_manage){form.querySelectorAll('input').forEach(x=>x.disabled=true);save.hidden=true;return;}
 let pending=null,busy=false,dirty=false;
 const edited=()=>{if(busy||pending)return;dirty=true;save.disabled=false;save.textContent='Save settings';status.textContent='';};
 form.addEventListener('input',edited);form.addEventListener('change',edited);
 form.onsubmit=async event=>{event.preventDefault();if(busy||(!dirty&&!pending))return;
 const value=name=>form.elements.namedItem(name).value,price=name=>value(name)===''?null:Math.round(Number(value(name))*100);
 pending??={batting_annual_price_cents:price('batting_annual_price'),selection_annual_price_cents:price('selection_annual_price'),bundle_annual_price_cents:price('bundle_annual_price'),batting_trial_days:Number(value('batting_trial_days')),selection_trial_days:Number(value('selection_trial_days')),state_token:p.state_token,request_id:crypto.randomUUID()};
 busy=true;form.querySelectorAll('input,button').forEach(x=>x.disabled=true);save.textContent='Saving…';status.textContent='';
 try{const {error}=await supabase.rpc('platform_product_pricing_api',{p_action:'save',p_data:pending});if(error){if(error.code)pending=null;throw Error(error.message);}pending=null;dirty=false;await mountProductPriceSettings();}
 catch(e){status.textContent=(pending?'Save not confirmed. Retry. ':'')+e.message;}
 finally{busy=false;if(form.isConnected){form.querySelectorAll('input').forEach(x=>x.disabled=!!pending);save.disabled=!pending&&!dirty;save.textContent=pending?'Retry save':dirty?'Save settings':'Saved';}}
 };
}

/* Club setup does not grant access to draft team selections. */
function seCanSetup(d=ensureSelections().data){return !!(d?.admin||d?.selector);}
function seFixtures(){
 const s=ensureSelections();if(!seCanSetup())return;
 const fixtures=s.data.fixtures.filter(f=>f.details).slice().sort((a,b)=>a.details.days[0].date.localeCompare(b.details.days[0].date)||a.details.grade.localeCompare(b.details.grade));
 document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><div class="se-top"><h2>Fixtures</h2><button class="btn" id="seNewFixture">Add fixture</button></div>${fixtures.map(f=>`<div class="se-top" style="padding:12px 0;border-bottom:1px solid #e6ebf1"><div><strong>${seEsc(f.details.grade)}</strong><span class="se-role">${seEsc(f.details.opposition)} · ${f.details.days.map(d=>seDate(d.date)).join(' / ')}${f.details.cancelled?' · Cancelled':''}</span></div><button class="btn ghost" data-se-fixture-setup="${f.id}">Edit fixture</button></div>`).join('')||'<p>No fixtures added yet.</p>'}</section>`;
 document.getElementById('seNewFixture').onclick=()=>seFixtureEditor();
 document.querySelectorAll('[data-se-fixture-setup]').forEach(b=>b.onclick=()=>seFixtureEditor(fixtures.find(f=>f.id===b.dataset.seFixtureSetup)));
}
function seShowSelectorNames(form){
 const chosen=new Set(new FormData(form).getAll('users')),head=form.elements.head_selector_id.value;
 document.getElementById('seSelectorNames').textContent=ensureSelections().data.members.filter(m=>chosen.has(m.user_id)&&m.user_id!==head).map(m=>m.name).join(', ')||'None assigned';
}

/* Live sign-up/link follow-up; no messages are sent from these read operations. */
async function seFetchSignupFollowup(clubId){
 try{const {data,error}=await supabase.rpc('get_selection_signup_followup',{p_club_id:clubId});if(error)throw error;return data||{can_view:false,players:[]};}
 catch{return {can_view:false,players:[],error:true};}
}
function seNeedsAccountLink(p){const f=ensureSelections().data?.signup_followup;return !!(f?.can_view&&f.players.some(x=>x.id===p.id));}
function seSignupFlag(p){const item=ensureSelections().data?.signup_followup?.players.find(x=>x.id===p.id);return seNeedsAccountLink(p)?`<span class="se-signup-flag">${item?.status==='link'?'Check account link':'Sign-up needed'}</span>`:'';}
function seSignupFilter(){const s=ensureSelections();return s.data.signup_followup?.can_view?`<label class="se-check"><input type="checkbox" id="seSignupOnly" ${s.signupOnly?'checked':''}>Sign-up / link needed (${s.data.signup_followup.players.length})</label>`:'';}
async function seOpenSignupFollowup(){
 if(!await saveClubEditsBeforeNavigation())return;const s=ensureSelections();s.view='roster';s.rosterPanel=null;s.signupOnly=true;s.rosterGrade='';s.rosterSearch='';currentTab='teams';await renderTab();
}
function seInboxFollowup(f){
 if(f?.error)return '<p class="messages-status">Player follow-up could not load. <button class="btn ghost" id="retrySignupFollowup">Retry</button></p>';
 if(!f?.can_view||!f.players.length)return '';
 return `<div class="message-row se-inbox-followup"><div><strong>Players to follow up</strong><small>${f.players.length} player${f.players.length===1?'':'s'} · sign-up / link needed</small></div><button class="btn ghost" id="viewSignupFollowup">View players</button></div>`;
}

/* Compact playing-list editing. Grades and attributes remain Selections-owned. */
function seRosterStyles(){return `<style>
.se-roster-filters{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:12px}.se-roster-filter-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin:8px 0}.se-roster-filter-footer .se-check{margin:0}.se-roster-count{font-size:12px;color:#64748b}.se-inactive-link{display:inline-block;margin:0;border:0;background:transparent;color:#52647b;text-decoration:underline;font:inherit;font-size:13px;min-height:44px;cursor:pointer}.se-inactive-person{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:12px 0;border:0;border-bottom:1px solid #e6ebf1;background:transparent;color:#24344c;text-align:left;cursor:pointer;font:inherit}.se-inactive-person strong{font-size:14px}.se-inactive-person small{display:block;color:#64748b;font-size:12px;margin-top:3px}.se-inactive-person:hover{background:#f4f6fb}
#seRosterForm .se-roster-row,.se-roster-head{display:grid;grid-template-columns:minmax(155px,1.3fr) minmax(518px,4fr) 166px;gap:12px;align-items:center}#seRosterForm .se-roster-row{padding:7px 0;border-bottom:1px solid #e6ebf1}#seRosterForm .se-roster-row>div{min-width:0;grid-column:auto}.se-roster-head{padding:8px 0;font-size:12px;color:#56657b;border-bottom:1px solid #dce2ee}.se-roster-controls{display:grid;grid-template-columns:minmax(120px,1.2fr) minmax(100px,1fr) minmax(132px,1.1fr) minmax(102px,1fr) 32px;gap:8px;align-items:center}#seRosterForm .se-roster-controls label{min-width:0;margin:0}#seRosterForm .se-roster-controls select{margin:0;min-height:36px;padding:7px 5px;font-size:14px;width:100%}#seRosterForm .se-roster-controls .se-check{justify-content:center;min-height:36px}.se-roster-control-label{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.se-roster-person{position:relative;overflow-wrap:anywhere}.se-roster-person strong{font-size:14px;line-height:1.4}.se-roster-meta{font-size:11px;color:#64748b;display:flex;flex-wrap:wrap;gap:3px 6px;align-items:center;line-height:1.5}.se-roster-person .se-signup-flag{font-size:10px;padding:1px 4px;margin:0}.se-roster-actions{display:flex;gap:3px;flex-wrap:nowrap}.se-page .se-roster-actions .btn{min-height:30px;padding:5px 7px;font-size:11px;white-space:nowrap}.se-roster-summary,.se-roster-expand{display:none}.se-roster-save{position:sticky;bottom:0;z-index:2;display:flex;justify-content:flex-end;padding:10px 0 calc(10px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #dce2ee;margin-top:8px}.se-roster-empty{color:#64748b;font-size:13px;padding:16px 0;margin:0}.se-roster-readonly .se-unselected-row{padding:8px 0;overflow-wrap:anywhere}
@media(max-width:960px){.se-roster-head{display:none}#seRosterForm .se-roster-row{display:block;padding:0}.se-roster-person{padding:11px 56px 11px 0;min-height:44px}.se-roster-person strong{font-size:15px}.se-roster-summary{display:block;font-size:12px;color:#56657b;line-height:1.5;margin-top:2px}.se-roster-expand{display:flex;align-items:center;justify-content:center;gap:5px;position:absolute;right:0;top:9px;min-width:48px;min-height:44px;border:0;border-radius:7px;color:#17345c;background:#eef2f8;font:inherit;font-size:12px;cursor:pointer}.se-roster-expand:focus-visible{outline:2px solid #315dad;outline-offset:2px}.se-roster-expand[aria-expanded=true] span{transform:rotate(180deg)}#seRosterForm .se-roster-controls,#seRosterForm .se-roster-actions{display:none}#seRosterForm .se-roster-row.is-open>.se-roster-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:0 0 10px}#seRosterForm .se-roster-row.is-open>.se-roster-actions{display:flex;padding-bottom:12px;gap:8px}.se-roster-control-label{position:static;display:block;width:auto;height:auto;clip-path:none;white-space:normal;margin:0 0 5px}#seRosterForm .se-roster-controls select{font-size:16px;min-height:44px;padding:9px 7px}#seRosterForm .se-roster-controls .se-check{justify-content:flex-start;align-self:end;min-height:44px}.se-roster-controls .se-check .se-roster-control-label{margin:0}.se-page .se-roster-actions .btn{font-size:13px;min-height:44px;padding:8px 12px}.se-roster-save .btn{width:100%}}
@media(max-width:560px){.se-roster-filters{grid-template-columns:minmax(0,1fr);gap:10px}.se-roster-filter-footer{gap:2px}.se-roster-count{margin-left:auto}}@media(max-width:420px){#seRosterForm .se-roster-row.is-open>.se-roster-controls{grid-template-columns:minmax(0,1fr)}}
</style>`;}
function seRosterGradeKey(grade){return String(grade||'').trim().toLowerCase();}
function seRosterFilters(){
 const s=ensureSelections(),seen=new Set(),options=[['','All grades'],['none','No usual grade']];
 for(const c of seGradeChoices()){const key=seRosterGradeKey(c.grade);if(!key||seen.has(key))continue;seen.add(key);options.push(['grade:'+key,c.grade]);}
 if(!options.some(([key])=>key===s.rosterGrade))s.rosterGrade='';
 return `${seRosterStyles()}<div class="se-roster-filters"><label>Find player<input type="search" id="seRosterSearch" placeholder="Name or grade" value="${seEsc(s.rosterSearch||'')}"></label><label>Show players<select id="seRosterGrade">${seOpt(options,s.rosterGrade)}</select></label></div><div class="se-roster-filter-footer">${seSignupFilter()}<span class="se-roster-count" id="seRosterCount" role="status"></span></div>`;
}
function seBindRosterSearch(){
 const s=ensureSelections(),filter=()=>{
  s.rosterSearch=document.getElementById('seRosterSearch').value;s.rosterGrade=document.getElementById('seRosterGrade').value;
  const q=s.rosterSearch.trim().toLowerCase(),followup=new Set(s.data.signup_followup?.players.map(p=>p.id)||[]);let visible=0,total=0;
  document.querySelectorAll('[data-se-roster-id]').forEach(row=>{total++;const grade=row.dataset.seRosterGrade||'';row.hidden=!row.dataset.seRosterName.includes(q)||(s.rosterGrade==='none'&&grade!=='')||(s.rosterGrade.startsWith('grade:')&&grade!==s.rosterGrade.slice(6))||(s.signupOnly&&s.data.signup_followup?.can_view&&!followup.has(row.dataset.seRosterId));if(!row.hidden)visible++;});
  document.getElementById('seRosterCount').textContent=(visible===total?total:visible+' of '+total)+' player'+(total===1?'':'s');
  const empty=document.getElementById('seRosterEmpty');if(empty){empty.hidden=visible>0;empty.textContent=total?'No matching players.':s.data.roster.length?'No active players.':'No players added yet.';}
 };
 document.getElementById('seRosterSearch').oninput=filter;document.getElementById('seRosterGrade').onchange=filter;document.getElementById('seSignupOnly')?.addEventListener('change',e=>{s.signupOnly=e.target.checked;filter();});filter();
}
function seRosterSummary(p){
 const labels=[p.batting!=='unknown'?SE_BATTING.find(([key])=>key===p.batting)?.[1]:'',p.bowling==='pace'?'Quick':p.bowling==='spin'?'Spinner':'',['pace','spin'].includes(p.bowling)&&p.bowling_load==='part_time'?'Part time':'',p.keeper?'WK':''].filter(Boolean);
 return labels.join(' · ')||(p.bowling==='none'?'Does not bowl':'Roles not set');
}
function seRosterGradeEditor(p){
 const grades=seGradeChoices().map(c=>c.grade);if(p.grade&&!grades.includes(p.grade))grades.push(p.grade);
 return `<label><span class="se-roster-control-label">Usual grade</span><select name="grade" aria-label="Usual grade for ${seEsc(p.name)}">${seOpt([['','No usual grade'],...grades.map(grade=>['grade:'+grade,grade])],p.grade?'grade:'+p.grade:'')}</select></label>`;
}
function seRosterRow(p){
 const open=ensureSelections().rosterOpen===p.id,id=seEsc(p.id);
 return `<div class="se-roster-row${open?' is-open':''}" data-se-roster-id="${id}" data-se-roster-name="${seEsc((p.name+' '+p.grade).toLowerCase())}" data-se-roster-grade="${seEsc(seRosterGradeKey(p.grade))}"><div class="se-roster-person"><strong>${seEsc(p.name)}${p.active?'':' · inactive'}${memberPhoneStatusIcon(p.user_id)}</strong><div class="se-roster-meta"><span class="se-roster-grade-label">${seEsc(p.grade||'No usual grade')}</span>${seSignupFlag(p)}</div><span class="se-roster-summary">${seEsc(seRosterSummary(p))}</span><button class="se-roster-expand" type="button" data-se-expand-player="${id}" aria-expanded="${open}" aria-controls="seRosterFields-${id}" aria-label="${open?'Close':'Edit'} roles for ${seEsc(p.name)}">${open?'Close':'Edit'} <span aria-hidden="true">⌄</span></button></div><div class="se-roster-controls" id="seRosterFields-${id}">${seRosterGradeEditor(p)}${[['batting','Batting role',SE_BATTING],['bowling','Bowling role',SE_BOWLING],['bowling_load','Bowling workload',SE_LOAD]].map(([key,label,options])=>`<label><span class="se-roster-control-label">${label}</span><select name="${key}" aria-label="${label} for ${seEsc(p.name)}">${seOpt(options,p[key])}</select></label>`).join('')}<label class="se-check"><input name="keeper" type="checkbox" aria-label="Wicketkeeper: ${seEsc(p.name)}" ${p.keeper?'checked':''}><span class="se-roster-control-label">WK</span></label></div><div class="se-roster-actions"><button class="btn ghost" type="button" data-se-edit-player="${id}">${!p.user_id||seNeedsAccountLink(p)?'Link':'Details'}</button><button class="btn ghost" type="button" data-se-player-calendar="${id}">Calendar</button></div></div>`;
}
function seRosterEdits(){
 const s=ensureSelections();return [...document.querySelectorAll('#seRosterForm [data-se-roster-id]')].map(row=>{const p=s.data.roster.find(p=>p.id===row.dataset.seRosterId);return {...p,grade:row.querySelector('[name=grade]').value.slice(6),batting:row.querySelector('[name=batting]').value,bowling:row.querySelector('[name=bowling]').value,bowling_load:row.querySelector('[name=bowling_load]').value,keeper:row.querySelector('[name=keeper]').checked};}).filter(p=>{const old=s.data.roster.find(x=>x.id===p.id);return ['grade','batting','bowling','bowling_load','keeper'].some(key=>old[key]!==p[key]);});
}
function seRosterSaveState(){
 const s=ensureSelections(),button=document.getElementById('seSaveRosterRoles');if(!button)return;
 const dirty=seRosterEdits().length>0;s.formDirty=dirty;if(dirty)s.rosterSaved=false;
 button.disabled=!!(s.busy||s.pending||!dirty);button.textContent=s.rosterSaved&&!dirty&&!s.pending?'Saved':'Save changes';
}
function seRoster(){
 const s=ensureSelections();if(!seCanSetup())return seReadonlyPlayingList();
 if(s.rosterPanel==='inactive')return seInactivePlayers();const players=s.data.roster.filter(p=>p.active);
 document.getElementById('seContent').innerHTML=`<div class="se-toolbar"><button class="btn" id="seImportRoster">Import / refresh registration CSV</button><button class="btn ghost" id="seAddPlayer">Add player</button><button class="btn ghost" id="seRosterTemplate">CSV template</button><button class="se-inactive-link" id="seFindInactive" type="button">Inactive players</button></div>${seInviteButton()}${s.data.signup_followup?.error?'<p class="se-muted">Player follow-up could not load. Use Refresh to check.</p>':''}<form id="seRosterForm" class="se-card" style="margin-top:12px">${seRosterFilters()}<div class="se-roster-head" aria-hidden="true"><span>Player</span><div class="se-roster-controls"><span>Usual grade</span><span>Batting role</span><span>Bowling role</span><span>Workload</span><span>WK</span></div><span></span></div><div id="seRosterRows">${players.map(seRosterRow).join('')}</div><p class="se-roster-empty" id="seRosterEmpty" hidden></p>${players.length?'<div class="se-roster-save"><button type="submit" class="btn" id="seSaveRosterRoles">Save changes</button></div>':''}</form>`;
 document.getElementById('seFindInactive').onclick=()=>{if(!confirmLeaveSelections())return;s.rosterPanel='inactive';s.inactiveSearch='';s.rosterOpen=null;seInactivePlayers();};
 seBindInvites();seBindRosterSearch();document.getElementById('seImportRoster').onclick=()=>{if(confirmLeaveSelections())seImport();};document.getElementById('seAddPlayer').onclick=()=>{if(confirmLeaveSelections())sePlayerEditor();};document.getElementById('seRosterTemplate').onclick=()=>seDownload('Playing-list-template.csv','Registration ID,Player name,Usual grade,Player email\r\n','text/csv');
 document.querySelectorAll('[data-se-expand-player]').forEach(button=>button.onclick=()=>{s.rosterOpen=s.rosterOpen===button.dataset.seExpandPlayer?null:button.dataset.seExpandPlayer;document.querySelectorAll('#seRosterForm [data-se-roster-id]').forEach(row=>{const open=row.dataset.seRosterId===s.rosterOpen,toggle=row.querySelector('[data-se-expand-player]'),p=s.data.roster.find(p=>p.id===row.dataset.seRosterId);row.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',(open?'Close':'Edit')+' roles for '+p.name);toggle.innerHTML=(open?'Close':'Edit')+' <span aria-hidden="true">⌄</span>';});});
 document.querySelectorAll('[data-se-edit-player]').forEach(button=>button.onclick=()=>{if(confirmLeaveSelections()){const p=s.data.roster.find(p=>p.id===button.dataset.seEditPlayer);sePlayerEditor(p);if(!p.user_id||seNeedsAccountLink(p))document.getElementById('seAccountLink').open=true;}});document.querySelectorAll('[data-se-player-calendar]').forEach(button=>button.onclick=()=>{if(confirmLeaveSelections()){s.view='availability';drawSelections();seAvailability(button.dataset.sePlayerCalendar);}});
 const form=document.getElementById('seRosterForm');form.addEventListener('change',event=>{const row=event.target.closest('[data-se-roster-id]');if(!row)return;const p={...s.data.roster.find(p=>p.id===row.dataset.seRosterId),grade:row.querySelector('[name=grade]').value.slice(6),batting:row.querySelector('[name=batting]').value,bowling:row.querySelector('[name=bowling]').value,bowling_load:row.querySelector('[name=bowling_load]').value,keeper:row.querySelector('[name=keeper]').checked};row.querySelector('.se-roster-summary').textContent=seRosterSummary(p);row.querySelector('.se-roster-grade-label').textContent=p.grade||'No usual grade';seRosterSaveState();});
 form.onsubmit=async event=>{event.preventDefault();const rows=seRosterEdits();if(!rows.length||s.pending||s.busy)return;const ok=await seMutate('save_roster',{revision:s.data.roster_revision,rows});if(ok&&s===selectionState){s.rosterSaved=true;if(s.view==='roster')seRosterSaveState();}};seRosterSaveState();void mountMemberPhoneStatuses(document.getElementById('seContent'));
}
function seInactivePlayers(){
 const s=ensureSelections();if(!seCanSetup())return seReadonlyPlayingList();
 const players=s.data.roster.filter(p=>!p.active).sort((a,b)=>a.name.localeCompare(b.name));
 document.getElementById('seContent').innerHTML=seRosterStyles()+`<section class="se-card se-drawer"><div class="se-top"><h2>Inactive players</h2><button class="btn ghost" id="seInactiveBack" type="button">Playing list</button></div><label>Find player<input type="search" id="seInactiveSearch" placeholder="Name or grade" value="${seEsc(s.inactiveSearch||'')}"></label><div id="seInactiveRows">${players.map(p=>`<button type="button" class="se-inactive-person" data-se-inactive-player="${seEsc(p.id)}" data-se-inactive-name="${seEsc((p.name+' '+p.grade).toLowerCase())}" aria-label="Edit ${seEsc(p.name)}"><span><strong>${seEsc(p.name)}</strong>${p.grade?`<small>${seEsc(p.grade)}</small>`:''}</span><span aria-hidden="true">›</span></button>`).join('')}</div><p class="se-roster-empty" id="seInactiveEmpty" hidden></p></section>`;
 document.getElementById('seInactiveBack').onclick=()=>{s.rosterPanel=null;seRoster();};
 document.querySelectorAll('[data-se-inactive-player]').forEach(b=>b.onclick=()=>{const p=s.data.roster.find(p=>p.id===b.dataset.seInactivePlayer);if(p&&!p.active)sePlayerEditor(p);});
 const filter=()=>{s.inactiveSearch=document.getElementById('seInactiveSearch').value;const q=s.inactiveSearch.trim().toLowerCase();let visible=0;document.querySelectorAll('[data-se-inactive-player]').forEach(b=>{b.hidden=!b.dataset.seInactiveName.includes(q);if(!b.hidden)visible++;});const empty=document.getElementById('seInactiveEmpty');empty.hidden=visible>0;empty.textContent=players.length?'No matching inactive players.':'No inactive players.';};
 document.getElementById('seInactiveSearch').oninput=filter;filter();
}
function seReadonlyPlayingList(){
 const s=ensureSelections();if(!s.data.signup_followup?.can_view)return;
 document.getElementById('seContent').innerHTML=`${seInviteButton()}<section class="se-card se-drawer se-roster-readonly">${seRosterFilters()}${s.data.roster.filter(p=>p.active).map(p=>`<div class="se-unselected-row" data-se-roster-id="${seEsc(p.id)}" data-se-roster-name="${seEsc((p.name+' '+p.grade).toLowerCase())}" data-se-roster-grade="${seEsc(seRosterGradeKey(p.grade))}"><strong>${seEsc(p.name)}</strong>${seSignupFlag(p)}<span class="se-role">${seEsc(p.grade||'No usual grade')}</span></div>`).join('')}<p class="se-roster-empty" id="seRosterEmpty" hidden></p></section>`;seBindRosterSearch();seBindInvites();
}

function seBindPlayerNameCheck(form,player){
 const key=value=>String(value||'').trim().toLowerCase().replace(/\s+/g,' '),host=form.querySelector('#seNameMatch'),save=form.querySelector('[type=submit]');
 const check=()=>{const name=key(form.elements.name.value),changed=!player.id||name!==key(player.name),match=changed&&name&&ensureSelections().data.roster.find(p=>p.id!==player.id&&key(p.name)===name);
  host.hidden=!match;host.textContent=match?match.active?'This player is already on the playing list. Edit the existing entry.':'This player is inactive. Open Inactive players to edit or reactivate them.':'';save.disabled=!!match;return !match;
 };
 form.elements.name.addEventListener('input',check);check();return check;
}

/* Club setup date action and the available, unselected list. */
function seAvailabilityDateSetup(){
 const s=ensureSelections(),d=s.data;if(!seCanSetup(d))return;
 const players=d.roster.filter(p=>p.active).sort((a,b)=>a.name.localeCompare(b.name)),today=new Date().toLocaleDateString('en-CA',{timeZone:d.access.timezone}),initial=s.bulkAvailabilityDate||s.date||today;
 document.getElementById('seContent').innerHTML=`<form id="seAvailabilityDateForm" class="se-card se-drawer"><h2>Set all players for a date</h2><label>Date<input id="seBulkDate" type="date" required value="${initial}"></label><label class="se-check"><input id="seAllAvailable" type="checkbox">Make all players available for this date</label><p class="se-form-note">This date only. Tick anyone who is unavailable.</p><div id="seBulkExceptions" hidden><label>Find player<input id="seBulkSearch" type="search" placeholder="Name"></label><div class="se-bulk-players">${players.map(p=>`<label class="se-check" data-se-bulk-name="${seEsc(p.name.toLowerCase())}"><input type="checkbox" name="unavailable" value="${p.id}">${seEsc(p.name)}</label>`).join('')}</div></div><div class="se-actions se-editor-actions"><button class="btn" id="seSaveDate" type="submit" disabled>Save date</button><button class="btn ghost" type="button" id="seDateCancel">Back</button></div></form>`;
 const form=document.getElementById('seAvailabilityDateForm'),all=document.getElementById('seAllAvailable');
 all.onchange=()=>{document.getElementById('seBulkExceptions').hidden=!all.checked;document.getElementById('seSaveDate').disabled=!all.checked||!players.length;s.formDirty=all.checked;};
 form.oninput=e=>{if(e.target.id!=='seBulkSearch')s.formDirty=all.checked;};
 document.getElementById('seBulkSearch').oninput=e=>{const q=e.target.value.toLowerCase().trim();document.querySelectorAll('[data-se-bulk-name]').forEach(row=>row.hidden=!row.dataset.seBulkName.includes(q));};
 document.getElementById('seDateCancel').onclick=()=>{if(confirmLeaveSelections())drawSelections();};
 form.onsubmit=async e=>{e.preventDefault();if(!all.checked)return;const date=document.getElementById('seBulkDate').value;s.bulkAvailabilityDate=date;
  if(await seMutate('availability_batch',{date,make_all_available:true,roster_revision:d.roster_revision,revisions:Object.fromEntries(players.map(p=>[p.id,p.availability?.revision||0])),unavailable_ids:new FormData(form).getAll('unavailable')}))seNotice('Availability saved for '+seDate(date)+'.');
 };
}
function seAvailableUnselected(){
 const s=ensureSelections();if(!s.data.selector)return;s.boardPanel='unselected';const today=new Date().toLocaleDateString('en-CA',{timeZone:s.data.access.timezone}),date=s.unselectedDate||s.date||today,players=seUnselectedAvailable(s.data.roster,s.data.fixtures,date);s.unselectedDate=date;
 document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><div class="se-top"><h2>Available, not selected</h2><button class="btn ghost" id="seUnselectedBack">Selection board</button></div><label>Date<input type="date" id="seUnselectedDate" value="${date}"></label><p class="se-muted">${players.length} player${players.length===1?'':'s'} · current drafts, all grades</p>${players.map(p=>`<div class="se-unselected-row"><strong>${seEsc(p.name)}</strong><span class="se-role">${seEsc([p.grade,seRole(p)].filter(Boolean).join(' · '))}</span></div>`).join('')||'<p>No available players are unselected on this date.</p>'}</section>`;
 document.getElementById('seUnselectedBack').onclick=()=>{s.boardPanel=null;seBoard();};document.getElementById('seUnselectedDate').onchange=e=>{if(e.target.value){s.unselectedDate=e.target.value;seAvailableUnselected();}else e.target.value=date;};
}

/* Match appointments are roster identities, independent of batting accounts. */
function seMatchGroup(f,data){
 if(data.access.mode!=='bundle')return null;
 const d=f.details,groups=data.groups||[],link=(data.group_links||[]).find(l=>l.grade===d.grade&&l.competition===(d.competition||''));
 return groups.find(g=>g.id===d.grade_group_id)||groups.find(g=>g.id===link?.group_id)||groups.find(g=>g.name.toLowerCase()===d.grade.toLowerCase());
}
function seMatchRoles(f,data){
 const group=seMatchGroup(f,data),out={};
 f.details.days.forEach((day,i)=>{
  const key='d'+(i+1),ps=f.slots.map(s=>data.roster.find(p=>p.id===s[key]&&p.active)).filter(Boolean),old=f.details.match_roles?.[key]||{},role={};
  for(const kind of ['captain','keeper']){
   const manual=old[kind+'_manual']===true&&ps.some(p=>p.id===old[kind+'_id']);
   const choices=kind==='keeper'?ps.filter(p=>p.keeper):ps.filter(p=>p.user_id&&(group?.captain_user_ids||[]).includes(p.user_id));
   role[kind+'_id']=manual?old[kind+'_id']:choices.length===1?choices[0].id:null;role[kind+'_manual']=manual;
  }
  out[key]=role;
 });return out;
}
function sePrepareMatch(f,data=ensureSelections().data){const copy=structuredClone(f);copy.details.match_roles=seMatchRoles(copy,data);copy.details.captain_id=null;return copy;}
function seMatchRoleIssues(f,roles){
 if(f.details.cancelled)return [];
 return f.details.days.flatMap((_,i)=>['captain','keeper'].filter(k=>!roles['d'+(i+1)]?.[k+'_id']).map(k=>({level:'error',text:`Day ${i+1}: choose ${k==='captain'?'a captain':'who is keeping'}`})));
}
function seGloves(){return '<span class="se-keeper" role="img" aria-label="Wicketkeeper" title="Wicketkeeper"><svg viewBox="0 0 26 24" aria-hidden="true" focusable="false" fill="#e8eef7" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"><g transform="translate(0 3) scale(.63)"><path d="M7 22v-4l-4-6a1.4 1.4 0 0 1 2.2-1.7L7 13V5a1.3 1.3 0 0 1 2.6 0v5V3.5a1.3 1.3 0 0 1 2.6 0V10V4.5a1.3 1.3 0 0 1 2.6 0V10V7a1.3 1.3 0 0 1 2.6 0v6c0 2.7-1.4 4-1.4 5v4Z"/><path d="M7 18h9"/></g><g transform="translate(26 3) scale(-.63 .63)"><path d="M7 22v-4l-4-6a1.4 1.4 0 0 1 2.2-1.7L7 13V5a1.3 1.3 0 0 1 2.6 0v5V3.5a1.3 1.3 0 0 1 2.6 0V10V4.5a1.3 1.3 0 0 1 2.6 0V10V7a1.3 1.3 0 0 1 2.6 0v6c0 2.7-1.4 4-1.4 5v4Z"/><path d="M7 18h9"/></g></svg></span>';}
function seRoleMarks(id,role={},text=false){return (id&&role.captain_id===id?' (c)':'')+(id&&role.keeper_id===id?text?' (wk)':' '+seGloves():'');}
function seSnapshotName(snap,id,day,text=false){const name=snap.players.find(p=>p.id===id)?.name||'Vacant';return (text?name:seEsc(name))+seRoleMarks(id,snap.details.match_roles?.['d'+(day+1)],text);}
function seSnapshotSplit(snap,slot){return snap.details.days.length>1&&(slot.d1!==slot.d2||seRoleMarks(slot.d1,snap.details.match_roles?.d1,true)!==seRoleMarks(slot.d2,snap.details.match_roles?.d2,true));}
function seMatchRoleFields(f,roles){
 const data=ensureSelections().data;if(f.details.cancelled)return '';
 const shared=f.details.days.length===2&&f.slots.every(slot=>slot.d1===slot.d2)&&['captain','keeper'].every(kind=>roles.d1[kind+'_id']===roles.d2[kind+'_id']),days=shared?[0]:f.details.days.map((_,i)=>i);
 return `<div class="se-match-roles">${days.map(i=>{const key='d'+(i+1),ps=f.slots.map(s=>data.roster.find(p=>p.id===s[key]&&p.active)).filter(Boolean);return `<div>${days.length>1?`<small>Day ${i+1}</small>`:''}${['captain','keeper'].map(kind=>{const value=roles[key][kind+'_id']||'',label=kind==='captain'?'Captain':'Keeper';return `<label>${label}<select data-se-match-role="${kind}" data-se-role-fixture="${f.id}" data-se-role-day="${key}" data-se-role-all="${shared?'1':'0'}" aria-label="${seEsc(f.details.grade)} ${label}${days.length>1?' Day '+(i+1):''}" class="${value?'':'se-role-needed'}" ${ps.length?'':'disabled'}>${seOpt([['',kind==='captain'?'Choose captain':'Who is keeping?'],...ps.map(p=>[p.id,p.name])],value)}</select></label>`;}).join('')}</div>`;}).join('')}</div>`;
}
function seBindMatchRoles(){document.querySelectorAll('[data-se-match-role]').forEach(el=>el.onchange=async()=>{const s=ensureSelections();if(s.busy||s.pending)return;const f=s.data.fixtures.find(f=>f.id===el.dataset.seRoleFixture),copy=sePrepareMatch(f),kind=el.dataset.seMatchRole,day=el.dataset.seRoleDay;copy.details.match_roles[day][kind+'_id']=el.value||null;copy.details.match_roles[day][kind+'_manual']=!!el.value;
 // A shared control edits the whole match; separate day controls preserve other manual choices.
 for(const other of Object.keys(copy.details.match_roles))if(other!==day&&(el.dataset.seRoleAll==='1'||!copy.details.match_roles[other][kind+'_manual']&&el.value&&copy.slots.some(slot=>slot[other]===el.value))){copy.details.match_roles[other][kind+'_id']=el.value||null;copy.details.match_roles[other][kind+'_manual']=!!el.value;}
 await seMutate('save_board',{fixtures:[copy]},{undo:[structuredClone(f)]});});}
async function seWithSavedRoles(fs,next){const s=ensureSelections(),changed=fs.filter(f=>!f.details.cancelled).map(f=>sePrepareMatch(f)).filter(f=>JSON.stringify(f.details)!==JSON.stringify(s.data.fixtures.find(x=>x.id===f.id).details));if(changed.length&&!await seMutate('save_board',{fixtures:changed}))return;next(fs.map(f=>s.data.fixtures.find(x=>x.id===f.id)));}
function seReviewCaptains(f,data=ensureSelections().data){const roles=f.details.match_roles;if(!roles)return data.members.filter(m=>m.user_id===f.details.captain_id).map(m=>({name:m.name,user_id:m.user_id}));return [...new Set(Object.values(roles).map(r=>r.captain_id).filter(Boolean))].map(id=>data.roster.find(p=>p.id===id)).filter(Boolean);}

/* Fixture defaults and captain input. Final publication belongs to the Head of Selections. */
function seGradeChoices(extra=[]){
 const d=ensureSelections().data,groups=d.groups||[],choices=groups.map(g=>({value:'group:'+g.id,grade:g.name,grade_group_id:g.id}));
 for(const r of [...(d.access.fixture_defaults?.rows||[]),...d.fixtures.map(f=>f.details).filter(Boolean),...d.roster,...extra]){
  const grade=r.grade?.trim();if(!grade||choices.some(c=>c.grade.toLowerCase()===grade.toLowerCase()))continue;
  choices.push({value:'grade:'+grade,grade,grade_group_id:null});
 }
 return choices;
}
function seGradeFields(key,grade='',groupId=null,options={}){
 const choices=seGradeChoices(grade?[{grade}]:[]),value=(choices.find(c=>groupId&&c.grade_group_id===groupId)||choices.find(c=>c.grade===grade))?.value||'';
 return `<label>${seEsc(options.label||'Grade')}<select name="${key}" ${options.required===false?'':'required'}>${seOpt([['',options.required===false?'No usual grade':'Choose grade'],...choices.map(c=>[c.value,c.grade]),['other','Other grade…']],value)}</select></label><label data-grade-other="${key}" hidden>Grade name<input name="${key}_other" maxlength="${options.maxlength||120}" value=""></label>`;
}
function seReadGrade(form,key){const value=form.elements[key].value;if(value==='other')return {grade:form.elements[key+'_other'].value.trim(),grade_group_id:null};return seGradeChoices().find(c=>c.value===value)||{grade:value.startsWith('grade:')?value.slice(6):'',grade_group_id:null};}
function seBindGrade(form,key,changed=()=>{}){
 const select=form.elements[key],other=form.elements[key+'_other'],label=form.querySelector(`[data-grade-other="${key}"]`);
 select.onchange=()=>{label.hidden=select.value!=='other';other.required=!label.hidden;changed();if(!label.hidden)other.focus();};other.onchange=changed;
}
function seFixtureEditor(f=null){
 if(!seCanSetup())return;
 const s=ensureSelections(),d=f?.details||{grade:'',competition:'',opposition:'',ground:'',meeting:'',format:'',overs:null,days:[{date:s.date||'',start:'12:00'}],brackets:false,min_quicks:3,min_batters:5,staff:[]};
 document.getElementById('seContent').innerHTML=`<form id="seFixtureForm" class="se-card se-drawer"><h2>${f?'Fixture details':'Add fixture'}</h2><div class="se-form-grid">
 <label>Competition<input name="competition" maxlength="120" value="${seEsc(d.competition)}"></label>${seGradeFields('grade',d.grade,d.grade_group_id)}
 <label>Format<select name="format" required>${seOpt([['','Choose format'],...SE_FORMATS],d.format||'')}</select></label>
 <label>Overs per innings<input name="overs" type="number" min="1" max="999" step="1" value="${d.overs??''}" placeholder="No fixed limit"></label>
 <label>Opposition<input name="opposition" maxlength="120" required value="${seEsc(d.opposition)}"></label><label>Ground<input name="ground" maxlength="120" value="${seEsc(d.ground)}"></label>
 </div>
 <div class="se-form-grid" style="margin-top:12px">${[0,1].map(i=>`<div><label>Day ${i+1} date${i?' · optional':''}<input type="date" name="date${i}" value="${d.days[i]?.date||''}" ${i?'':'required'}></label><label>Start<input type="time" name="start${i}" value="${d.days[i]?.start||''}"></label></div>`).join('')}</div>
 <label class="se-check"><input name="brackets" type="checkbox" ${d.brackets?'checked':''}>Bracketing permitted</label>
 <details><summary>Team balance &amp; match staff</summary><div class="se-form-grid"><label>Minimum frontline quicks<input name="min_quicks" type="number" min="0" max="11" value="${d.min_quicks??3}"></label><label>Minimum top/middle-order batters<input name="min_batters" type="number" min="0" max="11" value="${d.min_batters??5}"></label></div>
 ${s.data.members.map(m=>`<label class="se-check"><input type="checkbox" name="staff" value="${m.user_id}" ${(d.staff||[]).includes(m.user_id)?'checked':''}>${seEsc(m.name)}</label>`).join('')}</details>
 <label style="margin-top:12px">Meeting / match instructions<textarea name="meeting" maxlength="800" rows="2">${seEsc(d.meeting)}</textarea></label>
 ${f?`<label class="se-check"><input name="cancelled" type="checkbox" ${d.cancelled?'checked':''}>Match cancelled</label>`:''}
 <div class="se-actions se-editor-actions"><button class="btn" type="submit">Save fixture</button><button class="btn ghost" type="button" id="seCancelEdit">Cancel</button></div><p id="seFormError" role="alert"></p></form>`;
 const form=document.getElementById('seFixtureForm');form.oninput=()=>s.formDirty=true;
 const fillOvers=()=>{const grade=seReadGrade(form,'grade'),format=form.elements.format.value,row=(s.data.access.fixture_defaults?.rows||[]).find(r=>r.format===format&&(grade.grade_group_id?r.grade_group_id===grade.grade_group_id||!r.grade_group_id&&r.grade.toLowerCase()===grade.grade.toLowerCase():r.grade.toLowerCase()===grade.grade.toLowerCase()));form.elements.overs.value=row?row.overs??'':format==='t20'?20:'';s.formDirty=true;};
 seBindGrade(form,'grade',fillOvers);form.elements.format.onchange=fillOvers;
 document.getElementById('seCancelEdit').onclick=()=>{if(confirmLeaveSelections())drawSelections();};
 form.onsubmit=async e=>{e.preventDefault();const data=new FormData(form),grade=seReadGrade(form,'grade'),days=[0,1].filter(i=>data.get('date'+i)).map(i=>({date:data.get('date'+i),start:data.get('start'+i)}));
  if(days.length===2&&days[1].date<=days[0].date){document.getElementById('seFormError').textContent='Day 2 must follow Day 1.';return;}
  const details={...d,...Object.fromEntries(['competition','opposition','ground','meeting'].map(k=>[k,data.get(k).trim()])),grade:grade.grade,grade_group_id:grade.grade_group_id,format:data.get('format'),overs:data.get('overs')===''?null:Number(data.get('overs')),captain_id:d.captain_id||null,days,brackets:data.has('brackets'),min_quicks:Number(data.get('min_quicks')),min_batters:Number(data.get('min_batters')),staff:data.getAll('staff'),cancelled:data.has('cancelled')};
  if(!s.data.selector){s.date=days[0].date;return seMutate('save_fixture',{id:f?.id||crypto.randomUUID(),revision:f?.revision||0,details});}
  let slots=structuredClone(f?.slots||seBlankSlots());if(f&&f.details.days.length===2&&days.length===1&&slots.some(x=>x.d2&&x.d1!==x.d2)&&!confirm('Changing to one day removes Day 2 selections from this draft. Continue?'))return;
  if(days.length===1)slots=slots.map(x=>({...x,d2:null}));else if(!details.brackets)slots=slots.map(x=>({...x,d2:x.d1}));s.date=days[0].date;
  await seMutate('save_board',{fixtures:[{id:f?.id||crypto.randomUUID(),revision:f?.revision||0,details,slots}]});
 };
}
function seSettingsSaveState(form,label,action){
 const s=ensureSelections(),save=form.querySelector('[type="submit"]');save.textContent=s.pending?.action===action?'Save not confirmed':'Saved';save.disabled=true;
 const changed=()=>{s.formDirty=true;save.textContent=label;save.disabled=false;};form.addEventListener('input',changed);form.addEventListener('change',changed);return changed;
}
function seRenderDefaults(){
 const s=ensureSelections(),settings=s.data.access.fixture_defaults||{revision:0,rows:[]},host=document.getElementById('seFixtureDefaults');let sequence=0;
 host.innerHTML='<summary>Grade &amp; format defaults</summary><form id="seDefaultsForm"><div id="seDefaultRows"></div><div class="se-actions se-editor-actions"><button class="btn ghost" type="button" id="seAddDefault">Add default</button><button class="btn" type="submit">Save defaults</button></div></form>';
 const form=document.getElementById('seDefaultsForm'),rows=document.getElementById('seDefaultRows'),changed=seSettingsSaveState(form,'Save defaults','fixture_defaults');
 const add=(row={})=>{const key='default_'+sequence++,div=document.createElement('div');div.className='se-default-row';div.dataset.key=key;
  div.innerHTML=`${seGradeFields(key,row.grade,row.grade_group_id)}<label>Format<select name="${key}_format" required>${seOpt([['','Choose format'],...SE_FORMATS],row.format||'')}</select></label><label>Overs per innings<input name="${key}_overs" type="number" min="1" max="999" step="1" value="${row.overs??''}" placeholder="No fixed limit"></label><button type="button" class="btn ghost" aria-label="Remove default">Remove</button>`;
  rows.append(div);seBindGrade(form,key,changed);div.querySelector('button').onclick=()=>{div.remove();changed();};
 };
 settings.rows.forEach(add);document.getElementById('seAddDefault').onclick=()=>{add();changed();};
 form.onsubmit=async e=>{e.preventDefault();const values=[...rows.children].map(div=>{const key=div.dataset.key,grade=seReadGrade(form,key),overs=form.elements[key+'_overs'].value;return {grade:grade.grade,grade_group_id:grade.grade_group_id,format:form.elements[key+'_format'].value,overs:overs===''?null:Number(overs)};});
  if(await seMutate('fixture_defaults',{revision:settings.revision,rows:values}))document.getElementById('seFixtureDefaults').open=true;
 };
}
function seDraftChanged(f){return !f.published||JSON.stringify(f.details)!==JSON.stringify(f.published.details)||JSON.stringify(f.slots)!==JSON.stringify(f.published.slots);}
function seReviewLabel(f){const r=ensureSelections().data.reviews?.find(r=>r.id===f.id);return r?(r.draft_changed?'Changed since shared':'Shared with captain'):'Not yet shared with captain';}
function seSendReview(fs){
 const s=ensureSelections(),teams=fs.filter(f=>!f.details.cancelled&&seDraftChanged(f)),ready=teams.filter(f=>seReviewCaptains(f).some(p=>p.user_id&&s.data.members.some(m=>m.user_id===p.user_id))),missing=teams.some(f=>!seReviewCaptains(f).length);
 document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><h2>Send to captains</h2>${teams.map(f=>`<p><strong>${seEsc(f.details.grade)}</strong> · ${seReviewCaptains(f).map(p=>seEsc(p.name)+(p.user_id&&s.data.members.some(m=>m.user_id===p.user_id)?'':' — account not linked')).join(' / ')||'Choose captain on the board'}</p>`).join('')||'<p>No changed teams to send.</p>'}<div class="se-actions"><button class="btn" id="seConfirmReview" ${!ready.length||missing?'disabled':''}>Send drafts</button><button class="btn ghost" id="seReviewBack">Back</button></div></section>`;
 document.getElementById('seReviewBack').onclick=seBoard;document.getElementById('seConfirmReview').onclick=()=>seMutate('send_review',{ids:ready.map(f=>f.id),revisions:Object.fromEntries(ready.map(f=>[f.id,f.revision]))});
}
function seReviews(){
 const s=ensureSelections(),reviews=[...(s.data.reviews||[])].sort((a,b)=>b.sent_at.localeCompare(a.sent_at));
 document.getElementById('seContent').innerHTML=reviews.length?`<div class="se-grid">${reviews.map(r=>`<section class="se-card"><h2>${seEsc(r.snapshot.details.grade)}</h2><p>v ${seEsc(r.snapshot.details.opposition)} · ${r.snapshot.details.days.map(d=>seDate(d.date)).join(' / ')}</p><p class="se-muted">${seEsc(r.captain_name)} · ${r.draft_changed?'Changed since shared':'Shared draft'}</p><button class="btn" data-se-review="${r.id}">View &amp; comment</button></section>`).join('')}</div>`:'<div class="se-card se-empty">Drafts sent to captains appear here.</div>';
 document.querySelectorAll('[data-se-review]').forEach(b=>b.onclick=()=>seReviewScreen(b.dataset.seReview));
}
async function seReviewScreen(id){
 const s=ensureSelections(),r=s.data.reviews?.find(x=>x.id===id);if(!r)return;
 try{const posts=await seRPC('review_posts',{id});if(s!==selectionState||currentTab!=='teams')return;const snap=r.snapshot,d=snap.details,name=pid=>snap.players.find(p=>p.id===pid)?.name||'Vacant';
  document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><div class="se-top"><h2>${seEsc(d.grade)} · captain input</h2><button class="btn ghost" id="seReviewClose">Back</button></div><p class="se-muted">Private to this captain and selectors. Final selection rests with the Head of Selections.</p><p>v ${seEsc(d.opposition)} · ${seEsc(seFormatLabel(d))}</p><p>${d.days.map((day,i)=>(d.days.length>1?'Day '+(i+1)+': ':'')+seDate(day.date)+(day.start?' · '+day.start:'')).join(' / ')}</p><p>${seEsc(d.ground)}${d.meeting?' · '+seEsc(d.meeting):''}</p>${r.draft_changed?'<p class="se-warn">Selectors have since changed this draft.</p>':''}<ol>${snap.slots.map(slot=>`<li class="se-published-name">${seSnapshotName(snap,slot.d1,0)}${seSnapshotSplit(snap,slot)?` (Day 1) / ${seSnapshotName(snap,slot.d2,1)} (Day 2)`:''}</li>`).join('')}</ol><p class="se-muted se-review-prompt">Please check the draft and add any thoughts here.</p><button class="btn ghost" id="seReviewRefresh">Refresh comments</button>${posts.map(p=>`<article class="se-post"><strong>${seEsc(p.author_name)}</strong><small> · ${seEsc(new Date(p.created_at).toLocaleString('en-AU'))}${p.review_revision!==snap.draft_revision?' · earlier draft':''}</small><p>${seEsc(p.body)}</p></article>`).join('')}<form id="seReviewPostForm"><label>Comment<textarea name="body" required maxlength="1500" rows="3"></textarea></label><button class="btn se-editor-actions" type="submit">Add comment</button></form></section>`;
  document.getElementById('seReviewClose').onclick=()=>{if(confirmLeaveSelections()){s.view='reviews';drawSelections();}};
  document.getElementById('seReviewRefresh').onclick=async()=>{if(confirmLeaveSelections()){await seReload();if(s.data.reviews.some(x=>x.id===id))await seReviewScreen(id);else drawSelections();}};
  const form=document.getElementById('seReviewPostForm');form.oninput=()=>s.formDirty=true;form.onsubmit=async e=>{e.preventDefault();if(await seMutate('review_post',{id,body:form.elements.body.value,review_revision:snap.draft_revision}))await seReviewScreen(id);};
 }catch(e){seNotice(e.message);}
}
function sePublishReview(fs){
 const s=ensureSelections(),changed=fs.filter(seDraftChanged),issues=changed.flatMap(f=>(f.details.cancelled?[]:f.issues||[]).map(i=>({...i,text:f.details.grade+': '+i.text}))),errors=issues.filter(i=>i.level==='error'),warnings=issues.filter(i=>i.level==='warning');
 const unlinked=[...new Set(changed.flatMap(f=>f.slots.flatMap(x=>[x.d1,x.d2])).filter(Boolean))].map(id=>s.data.roster.find(p=>p.id===id)).filter(p=>p&&!p.user_id);
 document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><h2>Publish to players</h2><p>${changed.length} changed team${changed.length===1?'':'s'} will become visible to club members.</p>${changed.map(f=>`<p><strong>${seEsc(f.details.grade)}</strong> · ${f.details.cancelled?'Cancelled':f.details.days.map(d=>seDate(d.date)).join(' / ')}<br><small>${seReviewLabel(f)}</small></p>`).join('')}${issues.map(i=>`<p class="${i.level==='error'?'se-warn':'se-muted'}">${seEsc(i.text)}</p>`).join('')}${unlinked.length?`<p class="se-muted">${unlinked.length} players need a shared team list until their app account is linked.</p>`:''}${warnings.length?'<label class="se-check"><input type="checkbox" id="seAcknowledge">Balance warnings reviewed</label>':''}<div class="se-actions"><button class="btn secondary" id="seConfirmPublish" ${!s.data.head_selector||errors.length||!changed.length?'disabled':''}>Publish to players</button><button class="btn ghost" id="seBackBoard">Back</button></div></section>`;
 document.getElementById('seBackBoard').onclick=seBoard;document.getElementById('seConfirmPublish').onclick=async()=>{if(warnings.length&&!document.getElementById('seAcknowledge').checked){seNotice('Review the balance warnings before publishing.');return;}await seMutate('publish',{ids:changed.map(f=>f.id),revisions:Object.fromEntries(changed.map(f=>[f.id,f.revision])),acknowledge_balance:!warnings.length||document.getElementById('seAcknowledge').checked});};
}

/* Inline selection picker: open at a slot, close only after its save is confirmed. */
function sePickingDays(f,a,both){return f.details.days.map((day,index)=>({day,index})).filter(x=>both||x.index===a.day);}
function seSlotButton(a){if(!a)return null;const buttons=[...document.querySelectorAll('[data-se-slot]')].filter(b=>b.dataset.seFixture===a.id&&Number(b.dataset.seSlot)===a.slot);return buttons.find(b=>Number(b.dataset.seDay)===a.day)||buttons.find(b=>b.dataset.seBoth==='1');}
function seVisibleTop(){return Math.max(0,...[...document.querySelectorAll('.nav,header,[data-demo-toolbar],#demoToolbar')].map(el=>{const r=el.getBoundingClientRect(),style=getComputedStyle(el);return r.height&&style.display!=='none'?(style.position==='sticky'?r.height+Math.max(0,parseFloat(style.top)||0):style.position==='fixed'&&r.top<=1?r.bottom:0):0;}))+12;}
function seFocusSlot(a){const target=seSlotButton(a);if(!target)return;target.focus({preventScroll:true});const r=target.getBoundingClientRect(),top=seVisibleTop();if(r.top<top||r.bottom>innerHeight)window.scrollBy({top:r.top-top,behavior:'instant'});}
function sePickerSaved(){const s=ensureSelections();s.search='';s.role='';s.pairs=false;s.active=null;}
function seClosePicker(){const s=ensureSelections();if(s.busy||s.pending)return;const a=s.active;sePickerSaved();seBoard();seFocusSlot(a);}
function seFocusPicker(){
 const picker=document.getElementById('sePicker');if(!picker)return;picker.scrollTop=0;
 const target=document.getElementById('seSearch')||document.getElementById('sePickerHeading');target?.focus({preventScroll:true});
 const r=picker.getBoundingClientRect(),top=seVisibleTop();if(r.top<top||r.top>innerHeight-240)window.scrollBy({top:r.top-top,behavior:'instant'});
}
function sePicker(){
 const s=ensureSelections(),host=document.getElementById('sePicker'),a=s.active,f=s.data.fixtures.find(f=>f.id===a?.id);if(!host||!f)return;
 const closeButton='<button type="button" class="btn ghost" data-se-close-picker aria-label="Close player picker">×</button>',heading=text=>`<div class="se-picker-head"><h2 id="sePickerHeading" tabindex="-1">${text}</h2>${closeButton}</div>`;
 const bindClose=()=>{host.querySelector('[data-se-close-picker]').onclick=seClosePicker;host.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();seClosePicker();}};};
 if(s.pairs){const fixed=f.slots[a.slot].d1,pairs=sePairs(s.data.roster,f,s.data.fixtures,a.slot,s.fixed?fixed:null);host.innerHTML=heading('Find a bracketed pair')+`<p class="se-muted">${seEsc(f.details.grade)} · slot ${a.slot+1}. Closest roles first. These pairs are available on their own day; declare both names before the toss.</p>${fixed?`<label class="se-check"><input type="checkbox" id="seFixedPair" ${s.fixed?'checked':''}>Keep ${seEsc(seName(fixed))} on Day 1</label>`:''}${pairs.slice(0,30).map((pair,i)=>`<div class="se-pair"><strong>${seEsc(pair.a.name)}</strong> <small>Day 1</small><span class="se-role">${seEsc(seRole(pair.a))}</span><strong>${seEsc(pair.b.name)}</strong> <small>Day 2</small><span class="se-role">${seEsc(seRole(pair.b))}</span><p>${seEsc(pair.reason)}</p><button class="btn ghost" data-se-pair="${i}">Use this pair</button></div>`).join('')||'<p>No confirmed complementary pairs. Check the calendars or keep a Day 1 player to find their partner.</p>'}<button class="btn ghost" id="seBackPicker">Back to players</button>`;
 bindClose();document.getElementById('seFixedPair')?.addEventListener('change',e=>{s.fixed=e.target.checked;sePicker();});document.getElementById('seBackPicker').onclick=()=>{s.pairs=false;sePicker();seFocusPicker();};host.querySelectorAll('[data-se-pair]').forEach(b=>b.onclick=()=>seAssign(pairs[Number(b.dataset.sePair)].a.id,pairs[Number(b.dataset.sePair)].b.id));return;}
 host.innerHTML=`<div class="se-picker-head"><input id="seSearch" type="search" value="${seEsc(s.search)}" placeholder="Search players" aria-label="Search players by name or usual grade">${closeButton}</div><div class="se-picker-filters"><select id="seRoleFilter" aria-label="Player role">${seOpt([['','All roles'],['pace','Quicks'],['spin','Spinners'],['batters','Batters'],['keeper','Keepers']],s.role)}</select><button class="btn ghost" id="seClearSlot">Clear slot</button></div>${f.details.days.length===2&&f.details.brackets?`<div class="se-picker-options"><label class="se-check"><input type="checkbox" id="seBothDays" ${s.both!==false?'checked':''}>Both days</label><select id="sePickDay" aria-label="Selection day" ${s.both!==false?'hidden':''}>${seOpt([[0,'Day 1'],[1,'Day 2']],a.day)}</select><button class="btn ghost" id="seFindPair">Find matching pair</button></div>`:''}<div id="seCandidates"></div>`;
 const renderCandidates=()=>{
  const both=f.details.days.length===2&&(s.both!==false||!f.details.brackets),days=sePickingDays(f,a,both),available=[];
  for(const p of s.data.roster){
   if(!seCanPick(p,f,a.day,both)||s.search&&![p.name,p.grade].join(' ').toLowerCase().includes(s.search.trim().toLowerCase())||s.role&&!(p.bowling===s.role||s.role==='batters'&&['top','middle'].includes(p.batting)||s.role==='keeper'&&p.keeper))continue;
   if(days.every(x=>f.slots[a.slot]['d'+(x.index+1)]===p.id))continue;
   const nameKey=value=>String(value||'').trim().toLowerCase().replace(/\s+/g,' ');if(s.data.roster.some(other=>other.id!==p.id&&nameKey(other.name)===nameKey(p.name)&&days.some(x=>seUsed(other,x.day,s.data.fixtures))))continue;
   if(days.some(x=>seUsed(p,x.day,s.data.fixtures,{id:f.id,slot:a.slot})))continue;available.push(p);
  }
  document.getElementById('seCandidates').innerHTML=available.map(p=>`<button class="se-candidate" data-se-player="${p.id}"><strong>${seEsc(p.name)}</strong><span class="se-role">${seEsc(seRole(p))}</span>${f.details.days.length>1?`<span class="se-role">${f.details.days.map((d,i)=>`D${i+1}: ${seDayStatus(p,d)==='available'?'available':'not confirmed'}`).join(' · ')}</span>`:''}</button>`).join('')||'<p class="se-muted">No unselected players match these dates and filters.</p>';
  const clear=document.getElementById('seClearSlot');clear.hidden=!days.some(x=>f.slots[a.slot]['d'+(x.index+1)]);clear.textContent=both?'Clear both days':f.details.days.length===2?'Clear Day '+(a.day+1):'Clear slot';
  host.querySelectorAll('[data-se-player]').forEach(b=>b.onclick=()=>seAssign(b.dataset.sePlayer));
 };
 bindClose();document.getElementById('seSearch').oninput=e=>{s.search=e.target.value;renderCandidates();};document.getElementById('seRoleFilter').onchange=e=>{s.role=e.target.value;renderCandidates();};document.getElementById('seBothDays')?.addEventListener('change',e=>{s.both=e.target.checked;document.getElementById('sePickDay').hidden=s.both;renderCandidates();});document.getElementById('sePickDay')?.addEventListener('change',e=>{a.day=Number(e.target.value);host.closest('.se-slot').querySelectorAll('[data-se-slot]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.seBoth==='1'||Number(b.dataset.seDay)===a.day)));renderCandidates();});document.getElementById('seFindPair')?.addEventListener('click',()=>{s.pairs=true;s.fixed=!!f.slots[a.slot].d1;sePicker();seFocusPicker();});document.getElementById('seClearSlot').onclick=()=>seAssign(null);renderCandidates();
}
async function seAssign(id,pairDay2=undefined){const s=ensureSelections();if(s.busy||s.pending)return;const a=s.active,old=s.data.fixtures.find(f=>f.id===a?.id);if(!old||!old.slots[a.slot])return;const f=structuredClone(old),both=pairDay2!==undefined||(s.both!==false||!f.details.brackets)&&f.details.days.length===2,changes=new Map([[f.id,f]]);if(pairDay2!==undefined){f.slots[a.slot]={d1:id,d2:pairDay2};}else{f.slots[a.slot]['d'+(a.day+1)]=id;if(both)f.slots[a.slot]={d1:id,d2:id};}
 const selectedDays=f.details.days.filter((_,j)=>both||j===a.day);if(selectedDays.some(day=>{const j=f.details.days.indexOf(day),pid=f.slots[a.slot]['d'+(j+1)];return pid&&seDayStatus(s.data.roster.find(p=>p.id===pid),day)!=='available';})){seNotice('Mark availability before selecting this player.');return;}
 for(const day of selectedDays){const j=f.details.days.indexOf(day),p=s.data.roster.find(p=>p.id===f.slots[a.slot]['d'+(j+1)]);if(p&&seUsed(p,day,s.data.fixtures,{id:f.id,slot:a.slot})){seNotice(`${p.name} is already selected for ${seDate(day.date)}. Clear their other slot first.`);return;}}
 const before=[...changes.keys()].map(key=>structuredClone(s.data.fixtures.find(f=>f.id===key)));const names=[...new Set([id,pairDay2].filter(Boolean))].map(seName).join(' / '),message=id?`${names} → ${f.details.grade} · slot ${a.slot+1}${f.details.days.length>1&&!both?' · Day '+(a.day+1):''}`:`${f.details.grade} · slot ${a.slot+1} cleared`;await seMutate('save_board',{fixtures:[...changes.values()]},{undo:before,picker:{active:{...a},both,clear:!id,message}});}

/* BEGIN TEAMS SELECTION — maintained source: tools/teams_selection_ui.js */
let selectionAccess=null,selectionState=null,selectionRefreshTimer=null,selectionAccessSequence=0;
function selectionsScopeKey(){return session?.user?.id&&club?.id?`${session.user.id}:${club.id}`:null;}
function selectionsEnabled(){const key=selectionsScopeKey();return !!(key&&membership&&selectionAccess?.key===key&&selectionAccess.enabled===true&&!selectionAccess.error);}
function selectionsStandalone(){if(productTrialBattingWaiting())return true;const key=selectionsScopeKey();return !!(key&&selectionAccess?.key===key&&selectionAccess.mode==='standalone');}
async function loadSelectionsAccess(){
 const key=selectionsScopeKey(),clubId=club?.id,sequence=++selectionAccessSequence;
 if(!key){selectionAccess=null;return null;}
 let result;
 try{result=await supabase.rpc('club_selections_api',{p_club_id:clubId,p_action:'access'});}catch(error){result={error};}
 if(key===selectionsScopeKey()&&sequence===selectionAccessSequence){
  const {data,error}=result||{};
  selectionAccess={...(data||{}),key,enabled:!error&&data?.enabled===true,error:error?(error.message||'Selections access could not be checked.') : ''};
 }
 if(key===selectionsScopeKey()&&sequence===selectionAccessSequence)await loadMatchCaptainAccess();
 return selectionAccess?.key===selectionsScopeKey()?selectionAccess:null;
}
function ensureSelections(){const key=`${session?.user?.id}:${club?.id}`;if(selectionState?.key!==key){let pending=null;try{pending=JSON.parse(sessionStorage.getItem('selections-pending-'+key)||'null');}catch{}selectionState={key,view:'published',data:null,notice:'',busy:false,pending,undo:[],date:'',search:'',role:'',active:null,pairs:false,formDirty:false};}return selectionState;}
function seEsc(v){return esc(String(v??''));}
function seOpt(opts,value){return opts.map(([v,label])=>`<option value="${seEsc(v)}" ${v===value?'selected':''}>${seEsc(label)}</option>`).join('');}
function seName(id){return ensureSelections().data?.roster.find(p=>p.id===id)?.name||'Choose player';}
function seNotice(text){const s=ensureSelections();s.notice=text;const n=document.getElementById('seNotice');if(n)n.textContent=text;}
function sePersist(){const s=ensureSelections();try{const key='selections-pending-'+s.key;s.pending?sessionStorage.setItem(key,JSON.stringify(s.pending)):sessionStorage.removeItem(key);}catch{}}
function confirmLeaveSelections(){const s=selectionState;if(currentTab!=='teams'||!s)return true;if(s.busy){alert('The selection change is saving. Please wait.');return false;}if(s.pending){alert('This save is not confirmed. Retry it or download the recovery file before leaving.');return false;}if(s.formDirty&&!confirm('Leave these unsaved form changes?'))return false;s.formDirty=false;return true;}
async function seRPC(action,data={}){const {data:result,error}=await supabase.rpc('club_selections_api',{p_club_id:club.id,p_action:action,p_data:data});if(error)throw Error(error.message+(error.details&&error.details.startsWith('[')?' '+error.details:''));return result;}
async function seReload(){const s=ensureSelections(),sequence=(s.loadSequence||0)+1;s.loadSequence=sequence;const result=await seRPC('context'),followup=await seFetchSignupFollowup(club.id);result.signup_followup=followup;if(s!==selectionState||s.key!==selectionsScopeKey()||sequence!==s.loadSequence)return false;s.data=result;if(!result.selector){s.undo=[];s.active=null;}selectionAccess={...selectionAccess,key:s.key,enabled:true,error:'',mode:result.access.mode,selector:result.selector,admin:result.admin};return true;}
async function seMutate(action,data,{undo=null,picker=null}={}){const s=ensureSelections();if(s.busy)return false;if(action==='save_board'&&!s.pending)data={...data,fixtures:data.fixtures.map(f=>sePrepareMatch(f))};const pending=s.pending||{action,data:{...data,request_id:crypto.randomUUID()},...(undo?{undo}:{}),...(picker?{picker}:{})};s.pending=pending;s.busy=true;sePersist();seNotice('Saving…');seLock(true);
 try{const result=await seRPC(pending.action,pending.data);if(s!==selectionState)return false;s.formDirty=false;const loaded=await seReload();if(!loaded||s!==selectionState||s.key!==selectionsScopeKey())return false;s.pending=null;sePersist();if(pending.undo)s.undo.push({before:pending.undo,expected:result.revisions});if(action==='save_roster')s.rosterSaved=true;s.notice=action==='send_review'?'Sent to captains ✓':action==='publish'?`Published ✓${result.groups?.unlinked_players?.length?' · Club Batting group updates apply to linked players only.':''}`:'Saved ✓';if(pending.picker)sePickerSaved(pending.picker);s.busy=false;drawSelections();if(pending.picker&&currentTab==='teams'&&s.view==='board')seFocusSlot(pending.picker.active);if(['save_roster','import_roster','selectors'].includes(action))void refreshClubMessageBadge();return true;}catch(error){s.notice=`Save not confirmed. Your change is kept here. ${error.message}`;s.busy=false;drawSelections();return false;}finally{s.busy=false;seLock(false);}}
function seLock(disabled){document.querySelectorAll('#sePage button,#sePage input,#sePage select,#sePage textarea').forEach(x=>{if(disabled){x.dataset.seWasDisabled=x.disabled?'1':'0';x.disabled=true;}else if(x.dataset.seWasDisabled!==undefined){x.disabled=x.dataset.seWasDisabled==='1';delete x.dataset.seWasDisabled;}});}
function seDownload(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function seStyles(){return `<style>
.se-page{max-width:1400px;margin:auto;overflow-anchor:none}.se-page h1{font-size:26px;margin:0}.se-page h2{font-size:19px;margin:0 0 12px}.se-page p{line-height:1.5}.se-page .btn{min-height:44px;padding:8px 12px}.se-top,.se-toolbar,.se-tabs,.se-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.se-top{justify-content:space-between}.se-top small{display:block;color:#64748b;margin:6px 0}.se-tabs{margin:14px 0;border-bottom:1px solid #dce2ee;padding-bottom:10px}.se-tabs [aria-pressed=true]{background:var(--navy,#17245f);color:white}.se-notice{font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere}.se-notice:empty{display:none}.se-page input,.se-page select,.se-page textarea{font-size:16px;min-width:0;max-width:100%;box-sizing:border-box}.se-page label{font-size:13px;display:block}.se-page input:not([type=checkbox]),.se-page select,.se-page textarea{border:1px solid #cbd5e1;border-radius:7px;padding:9px 10px;background:white;color:#24344c;min-height:42px}.se-page textarea{width:100%}.se-month-tools{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;gap:8px;align-items:end;max-width:560px}.se-pick>.se-day-caption{display:block;margin-bottom:2px}.se-page label input:not([type=checkbox]),.se-page label select{margin-top:5px;width:100%}.se-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:14px;margin:14px 0}.se-card{background:white;border:1px solid #dce2ee;border-radius:12px;padding:16px;min-width:0}.se-team-head{padding-bottom:10px;border-bottom:1px solid #e7eaf1}.se-team-head p{font-size:13px;color:#64748b;margin:4px 0}.se-team-compact-head>div{display:flex;align-items:baseline;justify-content:space-between;gap:6px}.se-team-compact-head h2{margin:0}.se-team-state{font-size:11px;color:#64748b;text-align:right}.se-team-compact-head p{margin:4px 0 0}.se-counts{display:flex;flex-wrap:wrap;gap:5px;font-size:12px;margin:8px 0}.se-chip{padding:4px 7px;border-radius:5px;background:#edf3f1;color:#285749}.se-warn{background:#fff2d9;color:#7a5319}.se-role{font-size:11px;color:#64748b;display:block;line-height:1.5}.se-slot{display:grid;grid-template-columns:22px 1fr;gap:6px;align-items:center;border-bottom:1px solid #eef0f7;padding:2px 0}.se-slot-number{font-size:12px;color:#64748b}.se-slot-names{display:grid;grid-template-columns:repeat(var(--se-days,1),minmax(0,1fr));gap:3px}.se-pick{border:1px solid transparent;border-radius:6px;background:transparent;text-align:left;font:inherit;font-size:13px;padding:5px;min-height:36px;cursor:pointer;color:#24344c;overflow-wrap:anywhere}.se-pick:hover{background:#f4f6fb}.se-pick[aria-expanded=true]{border-color:#25458e;background:#e7eefa;box-shadow:inset 0 0 0 1px #25458e}.se-match-roles{display:flex;gap:8px;margin:8px 0}.se-match-roles>div{flex:1;min-width:0;display:grid;grid-template-columns:1fr 1fr;gap:5px}.se-match-roles small{grid-column:1/-1}.se-match-roles label{min-width:0}.se-match-roles select{font-size:12px;padding:5px!important;min-height:36px!important}.se-match-roles .se-role-needed{border-color:#ae781d;background:#fff8e9}.se-keeper{display:inline-flex;width:22px;height:20px;vertical-align:middle;color:#4d648e}.se-keeper svg{width:100%;height:100%}.se-day-caption{font-size:11px;color:#64748b}.se-status{font-size:11px;display:block;color:#997027}.se-status.available{color:#33785b}.se-status.unavailable{color:#b03b35}.se-board-layout .se-grid{align-items:start}.se-picker{grid-column:1/-1;border:1px solid #bccae5;border-radius:8px;padding:8px;margin:4px 0 8px;max-height:min(560px,65vh);overflow:auto;overscroll-behavior:contain;background:#f8faff}.se-picker-head{display:flex;align-items:start;justify-content:space-between;gap:6px}.se-picker-head input{flex:1;min-width:0}.se-picker-filters{display:flex;gap:6px;align-items:center;margin:6px 0}.se-picker-filters select{flex:1;min-width:0}.se-picker-filters .btn{flex-shrink:0}.se-picker-options{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.se-picker-options .se-check{margin:0}.se-picker-head h2{font-size:16px;margin:10px 0}.se-picker-head .btn{flex:0 0 44px;font-size:24px;padding:0}.se-picker .se-candidate{background:transparent}.se-picker input{width:100%}.se-candidate{width:100%;display:block;border:0;border-bottom:1px solid #e5eaf0;background:white;padding:10px 0;text-align:left;cursor:pointer;color:#24344c;min-height:52px;font-size:14px}.se-candidate:hover{background:#f5f8fe}.se-picker h2{overflow-wrap:anywhere}.se-pair{border:1px solid #dce2ee;border-radius:8px;padding:10px;margin-top:8px}.se-pair p{font-size:12px;margin:5px 0}.se-empty{padding:28px 18px;text-align:center;color:#62738d}.se-issues{font-size:12px;margin:8px 0}.se-issues summary{cursor:pointer;min-height:36px;align-content:center}.se-issues p{margin:4px 0}.se-form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,180px),1fr));gap:12px}.se-check{display:flex!important;gap:9px;align-items:center;min-height:44px}.se-check input{width:18px;height:18px;flex:0 0 18px}.se-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;max-width:560px;margin:12px 0}.se-calendar button{border:1px solid #dce2ee;background:#fff;min-height:44px;border-radius:6px;font:inherit;cursor:pointer}.se-calendar button[aria-pressed=true]{background:#d8efe1;border-color:#27754b;color:#154e32;font-weight:700}.se-calendar button{position:relative}.se-calendar button:disabled{opacity:1;cursor:default}.se-calendar-tick{position:absolute;right:3px;bottom:1px;font-size:10px}.se-calendar small{text-align:center;font-size:11px}.se-date-entry{display:flex;align-items:end;gap:8px;flex-wrap:wrap}.se-date-entry label{flex:1;min-width:130px}.se-blackout{display:flex;align-items:center;gap:8px;border-bottom:1px solid #e6ebf1;padding:6px 0;font-size:13px}.se-blackout span{flex:1}.se-roster-row{display:grid;grid-template-columns:minmax(160px,1.4fr) repeat(3,minmax(120px,1fr)) 70px;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid #e6ebf1}.se-roster-row select{width:100%}.se-roster-row strong{font-size:14px;display:block}.se-published-name{font-size:14px;line-height:1.7}.se-date-tag{font-size:11px;background:#edf2fa;padding:2px 4px;border-radius:4px}.se-drawer{max-width:860px}.se-post{border-bottom:1px solid #e2e8f0;padding:12px 0}.se-post p{white-space:pre-wrap;overflow-wrap:anywhere;margin:5px 0}.se-post small{font-size:12px;color:#64748b}.se-preview-scroll{overflow:auto}.se-preview-scroll table{width:100%;font-size:13px}.se-recovery{border:1px solid #b88432;background:#fff7e8;border-radius:8px;padding:14px;margin:10px 0}.se-editor-actions{margin-top:16px}.se-link-row{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:8px;margin:8px 0;align-items:end}.se-muted{color:#64748b;font-size:13px}.se-form-note{font-size:13px;color:#56657b;margin:10px 0}.se-default-row{display:grid;grid-template-columns:1.3fr 1fr 1fr auto;gap:8px;align-items:end;margin:12px 0}.se-bulk-players{max-height:320px;overflow:auto;margin-top:8px;border:1px solid #dce2ee;border-radius:7px;padding:8px}.se-unselected-row{padding:10px 0;border-bottom:1px solid #e6ebf1}.se-signup-flag{display:inline-block;border-radius:5px;padding:3px 6px;margin:4px 0 4px 5px;background:#fff2d9;color:#704b11;font-size:12px;font-weight:600}.se-page [hidden]{display:none!important}
@media(pointer:coarse){.se-pick{min-height:44px}}@media(max-width:1100px){.se-board-layout{grid-template-columns:1fr}.se-roster-row{grid-template-columns:1fr 1fr}.se-roster-row>div:first-child{grid-column:1/-1}}@media(max-width:560px){.se-card{padding:12px}.se-top h1{font-size:23px}.se-tabs{gap:4px}.se-tabs .btn{padding:7px 8px;font-size:13px}.se-link-row,.se-default-row{grid-template-columns:1fr}.se-actions .btn{flex-grow:1}.se-toolbar>label{width:100%}.se-toolbar select{width:100%}}
</style>`;}
async function renderSelections(){
 const page=document.getElementById('page'),s=ensureSelections();page.innerHTML='<div class="splash">Loading Selections…</div>';await loadSelectionsAccess();if(s!==selectionState||s.key!==selectionsScopeKey()||currentTab!=='teams')return;
 if(!selectionsEnabled()){
  const failed=!!selectionAccess?.error,canSetup=seCanManageSubscriptions(),clubId=club.id,clubName=club.name;
  page.innerHTML=seStyles()+`<section class="se-page se-card"><h1>Club Selections</h1><p>${failed?`Access could not be checked. ${seEsc(selectionAccess.error)}`:canSetup?'Add Selections to your club.':'Ask your Club Admin to arrange Selections access.'}</p><div class="se-actions">${canSetup&&!failed?'<button class="btn" id="seSetupSelections">Manage club</button>':''}<button class="btn ghost" id="seRetryAccess">${failed?'Retry':'Refresh'}</button></div></section>`;
  document.getElementById('seRetryAccess').onclick=renderSelections;
  document.getElementById('seSetupSelections')?.addEventListener('click',()=>openClubSubscriptions(clubId,clubName,{onSelectionsSaved:async()=>{
   if(s!==selectionState||club?.id!==clubId||currentTab!=='teams')return;
   await loadData();if(s!==selectionState||club?.id!==clubId||currentTab!=='teams')return;
   s.view=selectionAccess?.selector||selectionAccess?.admin?'roster':'published';renderShell();
  }}));return;
 }
 try{if(!await seReload()||s.key!==selectionsScopeKey()||currentTab!=='teams')return;seStartLiveRefresh();if(s.view==='board'&&!s.data.selector)s.view=s.data.admin?'fixtures':'published';drawSelections();}catch(e){if(s.key!==selectionsScopeKey()||currentTab!=='teams')return;page.innerHTML=`<section class="card"><h2>Selections could not load</h2><p>${seEsc(e.message)}</p><button class="btn" id="seRetryAccess">Try again</button></section>`;document.getElementById('seRetryAccess').onclick=renderSelections;}
}
function seHasAvailability(d){return seCanSetup(d)||d.can_view_club_availability||d.roster.some(p=>p.active&&p.user_id===session?.user?.id)||['player','both'].includes(membership?.involvement);}
function drawSelections(){if(currentTab!=='teams'||!document.getElementById('page'))return;const s=ensureSelections(),d=s.data;if(!d)return;const tabs=[...(d.admin?[['settings','Settings']]:[]),...(seCanSetup(d)||d.signup_followup?.can_view?[['roster','Playing List']]:[]),...(seHasAvailability(d)?[['availability','Availability']]:[]),...(d.selector?[['board','Selection Board']]:d.admin?[['fixtures','Fixtures']]:[]),...(d.selector||d.reviews?.length?[['reviews','Captain Checks']]:[]),['published','Teams']];if(!tabs.some(([key])=>key===s.view))s.view='published';
 document.getElementById('page').innerHTML=seStyles()+`<section class="se-page" id="sePage"><div class="se-top"><div><h1>Club Selections</h1><small>${d.access.mode==='standalone'?'Selections subscription':'Selections · connected to Club Batting'}</small></div><button class="btn ghost" id="seRefresh">Refresh</button></div><div class="se-tabs">${tabs.map(([key,label])=>`<button class="btn ghost" data-se-view="${key}" aria-pressed="${s.view===key}">${label}</button>`).join('')}</div>${s.view==='settings'?'':clubBrandingSetupPrompt()}<p id="seNotice" class="se-notice" role="status" aria-live="polite">${seEsc(s.notice)}</p>${s.pending?`<div class="se-recovery"><strong>Unconfirmed save</strong><p>Your proposed change is kept in this browser tab. Retry uses the same request and cannot apply it twice. If another selector changed the team, download your proposal before reloading.</p><div class="se-actions"><button class="btn" id="seRetrySave">Retry save</button><button class="btn ghost" id="seRecovery">Download &amp; reload</button></div></div>`:''}<div id="seContent"></div></section>`;
 document.querySelectorAll('[data-se-view]').forEach(b=>b.onclick=()=>{if(!confirmLeaveSelections())return;s.view=b.dataset.seView;s.boardPanel=null;s.rosterPanel=null;s.active=null;s.formDirty=false;s.notice='';drawSelections();});
 document.getElementById('seRefresh').onclick=async()=>{if(!confirmLeaveSelections())return;s.notice='';await renderSelections();};
 document.getElementById('seRetrySave')?.addEventListener('click',()=>seMutate(s.pending.action,s.pending.data));
 document.getElementById('seRecovery')?.addEventListener('click',async()=>{seDownload('Selection-save-recovery.json',JSON.stringify(s.pending,null,2),'application/json');s.pending=null;sePersist();s.notice='Proposal downloaded. Review it against the latest saved teams before making changes.';await seReload();drawSelections();});
 ({published:sePublished,reviews:seReviews,board:seBoard,fixtures:seFixtures,roster:seRoster,availability:seAvailability,settings:seSettings}[s.view]||sePublished)();bindClubBrandingLinks();
 if(s.pending)document.querySelectorAll('#seContent button,#seContent input,#seContent select,#seContent textarea').forEach(x=>x.disabled=true);
}
function seBoardFixtures(){const s=ensureSelections();const dates=[...new Set(s.data.fixtures.map(f=>f.details.days[0].date))].sort();if(!dates.includes(s.date))s.date=dates.find(x=>x>=new Date().toLocaleDateString('en-CA',{timeZone:s.data.access.timezone}))||dates.at(-1)||'';return s.data.fixtures.filter(f=>f.details.days[0].date===s.date);}
function seBoard(){const s=ensureSelections();if(!s.data.selector){s.view=s.data.admin?'fixtures':'published';return drawSelections();}if(s.boardPanel==='unselected')return seAvailableUnselected();const fs=seBoardFixtures(),dates=[...new Set(s.data.fixtures.map(f=>f.details.days[0].date))].sort();
 if(!dates.length){document.getElementById('seContent').innerHTML='<section class="se-card se-drawer"><p>Add a fixture and its playing dates to start selecting.</p><button class="btn" id="seNewFixture">Add first fixture</button><button class="btn ghost" id="seUnselected">Available, not selected</button></section>';document.getElementById('seNewFixture').onclick=()=>seFixtureEditor();document.getElementById('seUnselected').onclick=seAvailableUnselected;return;}
 document.getElementById('seContent').innerHTML=`<div class="se-toolbar"><label>Show fixtures starting <select id="seBoardDate">${dates.map(x=>`<option value="${x}" ${x===s.date?'selected':''}>${seDate(x)}</option>`).join('')}</select></label><button class="btn" id="seNewFixture">Add fixture</button><button class="btn ghost" id="seUnselected">Available, not selected</button><button class="btn ghost" id="seUndo" ${s.undo.length?'':'disabled'}>Undo last selection</button>${fs.length?'<button class="btn secondary" id="seSendReview">Send to captains</button>':''}${fs.length&&s.data.head_selector?'<button class="btn" id="sePublish">Publish to players</button>':''}</div>${!s.data.access.head_selector_id?(s.data.admin?'<button class="btn ghost" id="seAssignHead">Assign Head of Selections</button>':'<p class="se-muted">Ask Club Admin to assign the Head of Selections.</p>'):''}<div class="se-board-layout"><div class="se-grid">${fs.map(f=>seTeamCard(f)).join('')||'<div class="se-empty">Add a fixture with its actual playing date or dates to start selecting.</div>'}</div></div>`;
 document.getElementById('seUnselected').onclick=seAvailableUnselected;
 document.getElementById('seAssignHead')?.addEventListener('click',()=>{s.view='settings';drawSelections();});
 document.getElementById('seBoardDate').onchange=e=>{s.date=e.target.value;s.active=null;seBoard();};document.getElementById('seNewFixture').onclick=()=>seFixtureEditor();document.getElementById('seSendReview')?.addEventListener('click',()=>seWithSavedRoles(fs,seSendReview));document.getElementById('sePublish')?.addEventListener('click',()=>seWithSavedRoles(fs,sePublishReview));
 document.getElementById('seUndo').onclick=()=>{const previous=s.undo.at(-1);if(!previous)return;if(previous.before.some(f=>s.data.fixtures.find(x=>x.id===f.id)?.revision!==previous.expected?.[f.id])){seNotice('A team has changed since your edit. Review it before undoing anything.');return;}s.undo.pop();const fixtures=previous.before.map(f=>({...f,revision:previous.expected[f.id]}));void seMutate('save_board',{fixtures});};
 document.querySelectorAll('[data-se-slot]').forEach(b=>b.onclick=()=>{if(s.busy||s.pending)return;const a={id:b.dataset.seFixture,slot:Number(b.dataset.seSlot),day:Number(b.dataset.seDay)};if(s.active?.id===a.id&&s.active.slot===a.slot&&(b.dataset.seBoth==='1'||s.active.day===a.day))return seClosePicker();s.active=a;s.pairs=false;s.search='';s.role='';const f=s.data.fixtures.find(f=>f.id===a.id),slot=f.slots[a.slot];s.both=f.details.days.length===2&&(!f.details.brackets||slot.d1===slot.d2);seBoard();seFocusPicker();});
 document.querySelectorAll('[data-se-edit]').forEach(b=>b.onclick=()=>seFixtureEditor(s.data.fixtures.find(f=>f.id===b.dataset.seEdit)));
 document.querySelectorAll('[data-se-copylast]').forEach(b=>b.onclick=()=>seCopyLast(b.dataset.seCopylast));seBindMatchRoles();sePicker();
}
function seBoardCounts(f,roles){
 const rows=f.details.days.map((_,i)=>({...seCounts(f,ensureSelections().data.roster,i),keepers:roles['d'+(i+1)].keeper_id?1:0})),shared=rows.length===2&&JSON.stringify(rows[0])===JSON.stringify(rows[1]);
 return (shared?rows.slice(0,1):rows).map((c,i)=>`<div class="se-counts">${rows.length>1&&!shared?`<span>Day ${i+1}</span>`:''}<span class="se-chip ${c.players!==11?'se-warn':''}">${c.players}/11</span><span class="se-chip ${c.quicks<f.details.min_quicks?'se-warn':''}">${c.quicks} quicks</span><span class="se-chip">${c.spinners} spin</span><span class="se-chip ${c.batters<f.details.min_batters?'se-warn':''}">${c.batters} batters</span><span class="se-chip ${c.keepers?'':'se-warn'}">${c.keepers} WK</span></div>`).join('');
}
function seBoardRoleMarks(id,roles,days,text=false){
 if(!id)return '';
 if(days.length===1||seRoleMarks(id,roles.d1,true)===seRoleMarks(id,roles.d2,true))return seRoleMarks(id,roles['d'+(days[0]+1)],text);
 return ['captain','keeper'].map(kind=>{const appointed=days.filter(i=>roles['d'+(i+1)][kind+'_id']===id);if(!appointed.length)return '';const when=appointed.length===days.length?'':appointed.map(i=>'Day '+(i+1)).join(' / ');return kind==='captain'?` (c${when?' · '+when:''})`:text?` (wk${when?' · '+when:''})`:' '+seGloves()+(when?` <span class="se-day-caption">${when}</span>`:'');}).join('');
}
function seBoardSlot(f,slot,index,roles){
 const s=ensureSelections(),d=f.details,split=d.days.length===2&&slot.d1!==slot.d2,both=d.days.length===2&&!split,days=split?[0,1]:[0],active=s.active?.id===f.id&&s.active.slot===index;
 return `<div class="se-slot"><span class="se-slot-number">${index+1}</span><div class="se-slot-names" style="--se-days:${days.length}">${days.map(j=>{
  const id=slot['d'+(j+1)],p=s.data.roster.find(x=>x.id===id),checked=both?[0,1]:[j],status=p?checked.map(i=>({day:i,status:seDayStatus(p,d.days[i])})).filter(x=>x.status!=='available'):[],when=both?'both days':split?'Day '+(j+1):'',badges=seBoardRoleMarks(id,roles,checked,true);
  return `<button class="se-pick" data-se-fixture="${f.id}" data-se-slot="${index}" data-se-day="${j}" data-se-both="${both?'1':'0'}" aria-expanded="${active&&(both||s.active.day===j)}" aria-label="${seEsc(d.grade)}, slot ${index+1}${when?', '+when:''}: ${seEsc(p?.name||'Choose player')}${seEsc(badges)}">${split?`<span class="se-day-caption">Day ${j+1}</span>`:''}<strong>${seEsc(p?.name||'+ Choose player')}${seBoardRoleMarks(id,roles,checked)}</strong>${status.map(x=>`<span class="se-status ${x.status}">${d.days.length>1?'Day '+(x.day+1)+': ':''}${({unknown:'Not confirmed',partial:'Check times',available:'Available',unavailable:'Unavailable'})[x.status]}</span>`).join('')}</button>`;
 }).join('')}</div>${active?'<section class="se-picker" id="sePicker" aria-label="Choose a player"></section>':''}</div>`;
}
function seTeamCard(f){const s=ensureSelections(),d=f.details,roles=seMatchRoles(f,s.data),problems=[...(f.issues||[]).filter(i=>!i.match_role),...seMatchRoleIssues(f,roles)],same=f.published&&JSON.stringify(f.slots)===JSON.stringify(f.published.slots)&&JSON.stringify(d)===JSON.stringify(f.published.details);return `<section class="se-card"><div class="se-team-head se-team-compact-head"><div><h2>${seEsc(d.grade)}</h2><small class="se-team-state">${d.cancelled?'Cancelled':same?'Published':f.published?'Unpublished changes':'Draft'}</small></div><p>v ${seEsc(d.opposition)} · ${d.days.map(x=>seDate(x.date)).join(' / ')}${d.format?' · '+seEsc(SE_FORMATS.find(([key])=>key===d.format)?.[1]||''):''}</p></div>${seBoardCounts(f,roles)}${seMatchRoleFields(f,roles)}<div>${f.slots.map((slot,i)=>seBoardSlot(f,slot,i,roles)).join('')}</div>${problems.length?`<details class="se-issues"><summary>${problems.filter(i=>i.level==='error').length} issues · ${problems.filter(i=>i.level==='warning').length} balance warnings</summary>${problems.map(i=>`<p>${seEsc(i.text)}</p>`).join('')}</details>`:''}<div class="se-actions" style="margin-top:10px"><button class="btn ghost" data-se-edit="${f.id}">Fixture details</button><button class="btn ghost" data-se-copylast="${f.id}">Copy previous team</button></div></section>`;}
async function seCopyLast(id){const s=ensureSelections(),f=s.data.fixtures.find(x=>x.id===id),last=s.data.fixtures.filter(x=>x.id!==id&&x.details.grade===f.details.grade&&x.details.competition===f.details.competition&&x.details.format===f.details.format&&x.details.days[0].date<f.details.days[0].date).sort((a,b)=>b.details.days[0].date.localeCompare(a.details.days[0].date))[0];if(!last){seNotice('There is no earlier team for this competition and grade.');return;}if(!confirm('Copy the previous team? Only players marked available for these dates will be included.'))return;const copy=structuredClone(f);copy.slots=(last.published?.slots||last.slots).map(slot=>{const available=(id,day)=>{const p=s.data.roster.find(p=>p.id===id);return p?.active&&seDayStatus(p,day)==='available'?id:null;};let d1=available(slot.d1,f.details.days[0]),d2=f.details.days.length===2?available(f.details.brackets?slot.d2||slot.d1:slot.d1,f.details.days[1]):null;if(f.details.days.length===2&&!f.details.brackets&&(!d1||!d2))d1=d2=null;return {d1,d2};});await seMutate('save_board',{fixtures:[copy]},{undo:[structuredClone(f)]});}
function sePublished(){const s=ensureSelections(),fs=s.data.fixtures.filter(f=>f.published).sort((a,b)=>b.published.details.days[0].date.localeCompare(a.published.details.days[0].date));document.getElementById('seContent').innerHTML=fs.length?`<div class="se-grid">${fs.map(f=>{const d=f.published.details,ps=f.published.players,own=s.data.roster.find(p=>p.user_id===session.user.id),name=id=>ps.find(p=>p.id===id)?.name||'Vacant';return `<section class="se-card"><div class="se-team-head"><h2>${seEsc(d.grade)}</h2><p>${seEsc(d.competition)} · v ${seEsc(d.opposition)}</p><p>${seEsc(seFormatLabel(d))}</p><p>${d.days.map((x,i)=>(d.days.length>1?'Day '+(i+1)+': ':'')+seDate(x.date)+(x.start?' · '+x.start:'')).join(' / ')}</p><p>${seEsc(d.ground)}</p><p>${seEsc(d.meeting)}</p></div>${d.cancelled?'<p>Match cancelled</p>':`<ol>${f.published.slots.map(slot=>`<li class="se-published-name">${seSnapshotName(f.published,slot.d1,0)}${slot.d1===own?.id?' · you':''}${seSnapshotSplit(f.published,slot)?` <span class="se-date-tag">Day 1</span><br>${seSnapshotName(f.published,slot.d2,1)}${slot.d2===own?.id?' · you':''} <span class="se-date-tag">Day 2</span>`:''}</li>`).join('')}</ol>`}<p class="se-muted">Published version ${f.publication}</p><div class="se-actions"><button class="btn ghost" data-se-export="${f.id}">Copy team list</button>${f.can_chat?`<button class="btn" data-se-chat="${f.id}">Match conversation</button>`:''}</div></section>`;}).join('')}</div>`:'<div class="se-card se-empty">Published teams will appear here. Selectors can start in Selection board.</div>';
 document.querySelectorAll('[data-se-export]').forEach(b=>b.onclick=async()=>{const text=seTeamText(fs.find(f=>f.id===b.dataset.seExport),club.name);try{await navigator.clipboard.writeText(text);seNotice('Team list copied. You can paste it into WhatsApp or your publication.');}catch{seDownload('Team-list.txt',text);seNotice('Team list downloaded.');}});document.querySelectorAll('[data-se-chat]').forEach(b=>b.onclick=()=>seChat(b.dataset.seChat));}
async function seChat(id){const s=ensureSelections();try{const posts=await seRPC('posts',{id}),f=s.data.fixtures.find(f=>f.id===id);document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><div class="se-top"><h2>${seEsc(f.published.details.grade)} · match conversation</h2><button class="btn ghost" id="seChatBack">Teams</button></div><p class="se-muted">Current selected players, both bracket partners, selectors and nominated match staff. Refresh for new replies.</p><button class="btn ghost" id="seChatRefresh">Refresh conversation</button>${posts.map(p=>`<article class="se-post"><strong>${seEsc(p.author_name)}</strong><small> · ${seEsc(new Date(p.created_at).toLocaleString('en-AU'))}</small><p>${seEsc(p.body)}</p></article>`).join('')||'<p>No messages yet.</p>'}<form id="sePostForm"><label>Message<textarea name="body" required maxlength="1500" rows="3"></textarea></label><div class="se-actions se-editor-actions"><button class="btn" type="submit">Send to match group</button></div></form></section>`;document.getElementById('seChatBack').onclick=()=>{if(confirmLeaveSelections())sePublished();};document.getElementById('seChatRefresh').onclick=()=>{if(confirmLeaveSelections())seChat(id);};const form=document.getElementById('sePostForm');form.oninput=()=>s.formDirty=true;form.onsubmit=async e=>{e.preventDefault();const body=new FormData(form).get('body');if(await seMutate('post',{id,body}))await seChat(id);};}catch(e){seNotice(e.message);}}

function seAvailability(playerId=null){
 const s=ensureSelections(),d=s.data,viewAll=seCanSetup(d)||d.can_view_club_availability,players=d.roster.filter(p=>p.active).sort((a,b)=>a.name.localeCompare(b.name)),host=document.getElementById('seContent');
 const selected=playerId??s.availabilityPlayerId,p=viewAll?players.find(p=>p.id===selected):players.find(p=>p.user_id===session.user.id);
 const dateSetup=seCanSetup(d)&&players.length?'<button type="button" class="btn" id="seSetAvailabilityDate">Set all players for a date</button>':'';
 const chooser=value=>`<label style="display:block;margin-top:14px">Individual player<select id="seAvailabilityPlayer" aria-label="Player availability"><option value="">Choose a player</option>${players.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${seEsc(x.name)}</option>`).join('')}</select></label>`;
 if(!p){
  s.availabilityPlayerId=null;
  host.innerHTML=viewAll?`<section class="se-card se-drawer"><h2>Player availability</h2>${players.length?dateSetup+chooser(''):seCanSetup(d)?'<button class="btn" id="seAvailabilityAddPlayers">Add players</button>':'<p>No players added yet.</p>'}</section>`:'<section class="se-card se-drawer"><h2>Your availability</h2><p>Ask a selector to link your name in the playing list to your account.</p></section>';
  document.getElementById('seSetAvailabilityDate')?.addEventListener('click',seAvailabilityDateSetup);
  document.getElementById('seAvailabilityPlayer')?.addEventListener('change',e=>seAvailability(e.target.value));
  document.getElementById('seAvailabilityAddPlayers')?.addEventListener('click',()=>{s.view='roster';drawSelections();});return;
 }
 s.availabilityPlayerId=p.id;
 const editable=seCanSetup(d)||p.user_id===session.user.id,own=p.user_id===session.user.id,a=p.availability||{revision:0,available_dates:[]},saved=[...new Set(a.available_dates||[])].sort(),dates=new Set(saved),today=new Date().toLocaleDateString('en-CA',{timeZone:d.access.timezone});let month=s.availabilityMonth||today.slice(0,7);
 const instruction=!editable?'Only players with dates marked available can be selected.':own?'Tap the dates you can play, then Save. You can only be selected for dates marked available.':'Tap the dates the player has confirmed, then Save. Only marked dates can be selected.';
 host.innerHTML=`<form id="seAvailabilityForm" class="se-card se-drawer"><div class="se-top"><h2>${own?'Your availability':seEsc(p.name)+' · availability'}</h2></div>${dateSetup}${viewAll?chooser(p.id):''}<p class="se-form-note">${instruction}</p><div class="se-month-tools"><button type="button" class="btn ghost" id="seMonthPrev" aria-label="Previous month">‹</button><label>Month<input type="month" id="seMonth" value="${month}"></label><button type="button" class="btn ghost" id="seMonthNext" aria-label="Next month">›</button></div><div id="seCalendar" class="se-calendar"></div>${editable?`<button type="submit" class="btn" id="seSaveAvailability" disabled>${a.revision?'Saved':'Save'}</button>`:''}</form>`;
 const form=document.getElementById('seAvailabilityForm');
 document.getElementById('seSetAvailabilityDate')?.addEventListener('click',()=>{if(confirmLeaveSelections())seAvailabilityDateSetup();});
 const paint=()=>{
  s.availabilityMonth=month;document.getElementById('seMonth').value=month;
  const first=new Date(month+'-01T12:00:00Z'),offset=(first.getUTCDay()+6)%7,count=new Date(first.getUTCFullYear(),first.getUTCMonth()+1,0).getDate();
  document.getElementById('seCalendar').innerHTML=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<small>${x}</small>`).join('')+'<span></span>'.repeat(offset)+Array.from({length:count},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0'),available=dates.has(date);return `<button type="button" data-se-date="${date}" aria-pressed="${available}" aria-label="${date}, ${available?'available':'not available for selection'}" ${editable?'':'disabled'}>${i+1}${available?'<span class="se-calendar-tick" aria-hidden="true">✓</span>':''}</button>`;}).join('');
  if(editable){document.querySelectorAll('[data-se-date]').forEach(b=>b.onclick=()=>{const date=b.dataset.seDate;dates.has(date)?dates.delete(date):dates.add(date);s.formDirty=JSON.stringify([...dates].sort())!==JSON.stringify(saved);paint();});const save=document.getElementById('seSaveAvailability');save.disabled=!s.formDirty;save.textContent=s.formDirty?'Save':a.revision?'Saved':'Save';}
 };
 const changeMonth=n=>{const next=new Date(month+'-01T12:00:00Z');next.setUTCMonth(next.getUTCMonth()+n);month=next.toISOString().slice(0,7);paint();};
 document.getElementById('seMonthPrev').onclick=()=>changeMonth(-1);document.getElementById('seMonthNext').onclick=()=>changeMonth(1);
 document.getElementById('seMonth').onchange=e=>{if(/^\d{4}-\d{2}$/.test(e.target.value)&&e.target.value.slice(0,4)!=='0000'){month=e.target.value;paint();}else e.target.value=month;};
 document.getElementById('seAvailabilityPlayer')?.addEventListener('change',e=>{if(confirmLeaveSelections())seAvailability(e.target.value);else e.target.value=p.id;});
 form.onsubmit=async e=>{e.preventDefault();if(!editable||!s.formDirty)return;if(await seMutate('availability',{id:p.id,revision:a.revision||0,calendar_mode:'opt_in',available_dates:[...dates].sort()}))seAvailability(p.id);};paint();
}
function sePlayerEditor(player=null){const s=ensureSelections(),p=player||{name:'',grade:'',external_id:'',batting:'unknown',bowling:'unknown',bowling_load:'unknown',keeper:false,active:true,user_id:null};document.getElementById('seContent').innerHTML=`<form class="se-card se-drawer" id="sePlayerForm"><h2>${player?'Player details':'Add player'}</h2><div class="se-form-grid"><label>Name<input name="name" value="${seEsc(p.name)}" maxlength="120" required></label><label>Registration ID (optional)<input name="external_id" value="${seEsc(p.external_id)}" maxlength="120"></label>${seGradeFields('grade',p.grade,null,{label:'Usual grade (optional)',required:false,maxlength:80})}</div><div id="seNameMatch" class="se-form-note" hidden></div><p class="se-form-note">No player sign-up needed. A registration ID helps match future CSV imports.</p><details id="seAccountLink" ${p.user_id?'open':''}><summary>App account (optional)</summary><label>Player email (optional)<input name="account_email" type="email" maxlength="254" value="${seEsc(p.account_email||'')}"></label><p class="se-form-note">Verified email and name matches link automatically. Otherwise choose the account below.</p><label>Player’s club account<select name="user_id"><option value="">Not linked yet</option>${s.data.members.filter(m=>!s.data.roster.some(x=>x.user_id===m.user_id&&x.id!==p.id)).map(m=>`<option value="${m.user_id}" ${m.user_id===p.user_id?'selected':''}>${seEsc(m.name)}${m.email?' · '+seEsc(m.email):''}</option>`).join('')}</select></label><p class="se-form-note">For their availability and team messages. No Club Batting subscription needed.</p></details><label class="se-check"><input name="active" type="checkbox" ${p.active?'checked':''}>Active player</label><div class="se-actions se-editor-actions"><button class="btn" type="submit">Save player</button><button class="btn ghost" type="button" id="sePlayerCancel">Cancel</button></div></form>`;const form=document.getElementById('sePlayerForm');form.oninput=()=>s.formDirty=true;const confirmName=seBindPlayerNameCheck(form,p);seBindGrade(form,'grade',()=>s.formDirty=true);document.getElementById('sePlayerCancel').onclick=()=>{if(confirmLeaveSelections())seRoster();};form.onsubmit=e=>{e.preventDefault();if(!confirmName())return;const d=new FormData(form),user_id=d.get('user_id')||null;if(user_id!==p.user_id&&user_id&&!confirm('Confirm this account belongs to '+d.get('name')+'? It will receive this player’s selections and can edit their availability.'))return;return seMutate('save_roster',{revision:s.data.roster_revision,rows:[{...p,name:d.get('name').trim(),grade:seReadGrade(form,'grade').grade,external_id:d.get('external_id').trim(),account_email:d.get('account_email').trim(),user_id,active:d.has('active')}]});};}
function seImport(){const s=ensureSelections();document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><h2>Refresh the registered playing list</h2><p>Upload your registration CSV. Existing players are matched; roles and availability stay.</p><label>Registration CSV<input type="file" id="seCSVFile" accept=".csv,text/csv"></label><div id="seCSVMap"></div><p id="seCSVError" role="alert"></p><button class="btn ghost" id="seImportCancel">Back to playing list</button></section>`;document.getElementById('seImportCancel').onclick=()=>{if(confirmLeaveSelections())seRoster();};document.getElementById('seCSVFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('Choose a CSV smaller than 2 MB.');const rows=seCSV(await file.text()),headers=rows.shift();if(rows.length>1000)throw Error('Import up to 1000 players at a time.');const guess=(re,fallback=-1)=>headers.findIndex(h=>re.test(h))>=0?headers.findIndex(h=>re.test(h)):fallback,choices=[['-1','Not used'],...headers.map((h,i)=>[String(i),h||'Column '+(i+1)])];document.getElementById('seCSVMap').innerHTML=`<div class="se-form-grid" style="margin:16px 0">${[['id','Stable registration ID',guess(/participant.?id|registration.?id|profile.?id|player.?id|^id$/i)],['name','Full name / first name',guess(/player.?name|full.?name|first.?name|^name$/i)],['last','Surname (if separate)',/first.?name/i.test(headers[guess(/player.?name|full.?name|first.?name|^name$/i)]||'')?guess(/last.?name|surname/i):-1],['grade','Usual grade (optional)',guess(/grade|team/i)],['email','Player email (optional)',guess(/^(?:(?:player|participant|account.?holder).?)?e.?mail$/i)]].map(([k,l,v])=>`<label>${l}<select data-se-map="${k}">${seOpt(choices,String(v))}</select></label>`).join('')}</div><div id="seCSVPreview"></div><button class="btn" id="seCSVCommit">Import playing list</button>`;
 const preview=()=>{const map=Object.fromEntries([...document.querySelectorAll('[data-se-map]')].map(el=>[el.dataset.seMap,Number(el.value)]));if(map.id<0||map.name<0)throw Error('Choose both a stable ID and name column.');const data=rows.map(r=>({external_id:(r[map.id]||'').trim(),name:[r[map.name],map.last>=0&&map.last!==map.name?r[map.last]:''].filter(Boolean).join(' ').trim(),...(map.grade>=0?{grade:(r[map.grade]||'').trim()}:{}),...seCSVAccountEmail(r,headers,map.email)}));if(data.some(r=>!r.external_id||!r.name))throw Error('Every row must have a registration ID and name.');if(new Set(data.map(r=>r.external_id)).size!==data.length)throw Error('Duplicate registration IDs. Remove duplicate rows before importing.');seValidateRosterNames(data,s.data.roster,true);return data;};
 const draw=()=>{try{const data=preview(),matches=data.filter(r=>seImportMatch(r,s.data.roster)).length;document.getElementById('seCSVError').textContent='';document.getElementById('seCSVCommit').disabled=false;document.getElementById('seCSVPreview').innerHTML=`<p>${data.length} rows · ${matches} existing players · ${data.length-matches} new players</p><div class="se-preview-scroll"><table><thead><tr><th>ID</th><th>Name</th><th>Grade</th></tr></thead><tbody>${data.slice(0,8).map(r=>`<tr><td>${seEsc(r.external_id)}</td><td>${seEsc(r.name)}</td><td>${seEsc(r.grade)}</td></tr>`).join('')}</tbody></table></div><p class="se-muted">Preview of the first ${Math.min(8,data.length)} rows. Matched players keep their account, roles and availability.</p>`;}catch(err){document.getElementById('seCSVError').textContent=err.message;document.getElementById('seCSVCommit').disabled=true;}};document.querySelectorAll('[data-se-map]').forEach(el=>el.onchange=draw);document.getElementById('seCSVCommit').onclick=()=>seMutate('import_roster',{revision:s.data.roster_revision,rows:preview()});draw();}catch(err){document.getElementById('seCSVError').textContent=err.message;}};}
function seSettings(){const s=ensureSelections(),d=s.data;document.getElementById('seContent').innerHTML=`<div class="btnrow" style="margin-bottom:14px"><button class="btn ghost" type="button" data-club-branding>Club logo &amp; colours</button></div><section class="se-card se-drawer"><h2>Selection permissions</h2><form id="seSelectors"><label>Head of Selections<select name="head_selector_id">${seOpt([['','Choose Head of Selections'],...d.members.map(m=>[m.user_id,m.name])],d.access.head_selector_id||'')}</select></label><p class="se-muted">The Head of Selections publishes teams to players.</p><details id="seOtherSelectors"><summary>Other selectors<span class="se-form-note" style="display:block;margin:6px 0" id="seSelectorNames"></span></summary>${d.members.map(m=>`<label class="se-check"><input name="users" type="checkbox" value="${m.user_id}" ${m.explicit_selector?'checked':''}>${seEsc(m.name)}${m.is_admin?' · Club Admin':''}</label>`).join('')}</details><button class="btn se-editor-actions" type="submit">Save permissions</button></form></section><details class="se-card se-drawer" id="seFixtureDefaults" style="margin-top:14px"></details>${d.access.mode==='bundle'?`<details class="se-card se-drawer" id="seBattingConnection" style="margin-top:14px"><summary>Club Batting connection (optional)</summary><p>Publishing teams can add linked players to Club Batting Playing Groups. Players without a link stay in the team.</p><p class="se-form-note">Group membership can affect Player Plan due dates and coaching access. Existing memberships stay.</p><form id="seGroupLinks"><div id="seGroupLinkRows"></div><div class="se-actions"><button class="btn ghost" type="button" id="seAddGroupLink">Add grade mapping</button><button class="btn" type="submit">Save group connections</button></div></form></details>`:''}`;
 const selectorForm=document.getElementById('seSelectors');seShowSelectorNames(selectorForm);selectorForm.addEventListener('change',()=>seShowSelectorNames(selectorForm));seSettingsSaveState(selectorForm,'Save permissions','selectors');selectorForm.onsubmit=e=>{e.preventDefault();return seMutate('selectors',{revision:d.access.revision,users:new FormData(selectorForm).getAll('users'),head_selector_id:selectorForm.elements.head_selector_id.value||null});};seRenderDefaults();bindClubBrandingLinks();if(d.access.mode!=='bundle')return;const links=structuredClone(d.group_links),form=document.getElementById('seGroupLinks');
 const renderLinks=()=>{document.getElementById('seGroupLinkRows').innerHTML=links.map((l,i)=>`<div class="se-link-row" data-se-link="${i}"><label>Competition<input name="competition" maxlength="120" value="${seEsc(l.competition)}"></label><label>Grade<input name="grade" required maxlength="120" value="${seEsc(l.grade)}"></label><label>Playing Group<select name="group_id" required><option value="">Choose</option>${d.groups.map(g=>`<option value="${g.id}" ${g.id===l.group_id?'selected':''}>${seEsc(g.name)}</option>`).join('')}</select></label><button type="button" class="btn ghost" data-se-remove-link="${i}">Remove</button></div>`).join('')||'<p class="se-muted">No group connections set.</p>';document.querySelectorAll('[data-se-remove-link]').forEach(b=>b.onclick=()=>{sync();links.splice(Number(b.dataset.seRemoveLink),1);s.formDirty=true;renderLinks();});};
 const sync=()=>document.querySelectorAll('[data-se-link]').forEach(el=>{links[Number(el.dataset.seLink)]={competition:el.querySelector('[name=competition]').value.trim(),grade:el.querySelector('[name=grade]').value.trim(),group_id:el.querySelector('[name=group_id]').value};});form.oninput=()=>s.formDirty=true;document.getElementById('seAddGroupLink').onclick=()=>{sync();links.push({competition:'',grade:'',group_id:''});s.formDirty=true;renderLinks();};form.onsubmit=e=>{e.preventDefault();sync();return seMutate('group_links',{revision:d.access.revision,links});};renderLinks();}
async function openSelectionsAccess(clubId,clubName){return openClubSubscriptions(clubId,clubName);}
function seStartLiveRefresh(){if(selectionRefreshTimer)return;selectionRefreshTimer=setInterval(async()=>{const s=selectionState;if(!s||currentTab!=='teams'||s.view!=='board'||s.busy||s.pending||s.formDirty||s.active||document.activeElement?.matches('input,select,textarea')||(!document.querySelector('.se-board-layout')&&s.boardPanel!=='unselected'))return;try{const before=JSON.stringify(s.data);await seReload();if(s===selectionState&&currentTab==='teams'&&s.view==='board'&&!s.busy&&!s.pending&&!s.formDirty&&before!==JSON.stringify(s.data)){s.notice='Updated from the shared selection board.';drawSelections();}}catch{seNotice('Live refresh could not connect. Your saved selections are retained; use Refresh to reconnect.');}},20000);}
