/* BEGIN SCHEDULED TRIALS */
const TRIAL_PRIMERS={"shared": ["Add your club logo and colours through Account → Club settings.", "Use People & sign-up to invite people and assign the club roles they need. Each person uses one account for both products.", "Ask members to open Account → App & notifications and register their phone for alerts."], "selections": ["In Teams & availability → Settings, set up your grades and selection permissions.", "Check your Playing list and invite players to join so they can enter their availability.", "Create your first match, build the draft team and appoint its captain.", "Send the draft to captains for their check, then publish when the selectors are ready. Use the match conversation for team messages."], "batting": ["Appoint your Philosophy Lead and choose contributors for the Batting Philosophy Workshop.", "Complete the Workshop. The Philosophy Lead compares the options and selects your club’s approach.", "Review How We Bat and the Player Plan questions, then publish the club setup to open Player Plans.", "Set Playing Groups and relevant format due dates. Use players’ plans to guide training and Coach Conversations."], "both_note": "Start the availability and selection setup while your Philosophy Lead runs the Workshop. Teams & availability can be used before the batting setup is published."};
let scheduledTrialContext=null;
function productTrialCurrentProducts(){return scheduledTrialContext?.key===`${session?.user?.id}:${club?.id}`?scheduledTrialContext.products:null;}
function productTrialWaiting(){const p=productTrialCurrentProducts();return !!p&&!p.batting?.active&&!p.selections?.active&&(p.batting?.scheduled||p.selections?.scheduled);}
function productTrialBattingWaiting(){const p=productTrialCurrentProducts();return !!p?.batting?.scheduled&&!p.batting.active;}
async function loadScheduledTrialContext(){
 const uid=session?.user?.id,cid=club?.id;scheduledTrialContext=null;
 if(!uid||!cid||!isAdmin())return;
 try{const r=await productTrialRPC('context',{club_id:cid});if(uid===session?.user?.id&&cid===club?.id)scheduledTrialContext={key:`${uid}:${cid}`,products:r.products};}catch{}
}
function trialLocalDate(zone){
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
 const get=k=>parts.find(p=>p.type===k).value;return `${get('year')}-${get('month')}-${get('day')}`;
}
function trialEndDate(start,days=60){const d=new Date(start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+Number(days)-1);return d.toISOString().slice(0,10);}
function trialScheduleFields(saved={}){
 const zone=saved.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Australia/Sydney';
 const zones=[...new Set([zone,'Australia/Sydney','Australia/Brisbane','Australia/Adelaide','Australia/Perth','Australia/Darwin','Pacific/Auckland','Europe/London','Asia/Kolkata','Asia/Karachi','Africa/Johannesburg','America/Barbados','America/Jamaica','America/Port_of_Spain','UTC'])];
 const mode=saved.start_mode||(saved.starts_on?'later':'');
 return `<div class="field"><label for="ptStartMode">When should your trial start?</label><select id="ptStartMode" name="start_mode" required><option value="">Choose when to start</option><option value="now" ${mode==='now'?'selected':''}>Start now</option><option value="later" ${mode==='later'?'selected':''}>Choose a date</option></select></div><div class="field" id="ptStartDateField" ${mode==='later'?'':'hidden'}><label for="ptStartDate">Trial start date</label><input type="date" id="ptStartDate" name="starts_on" value="${esc(saved.starts_on||'')}" ${mode==='later'?'required':''}></div><div class="field"><label for="ptTimeZone">Club time zone</label><select id="ptTimeZone" name="timezone">${zones.map(z=>`<option value="${esc(z)}" ${z===zone?'selected':''}>${esc(z.replaceAll('_',' '))}</option>`).join('')}</select></div><p class="help" id="ptDateSummary"></p>`;
}
function bindTrialScheduleFields(form,clubs,days){
 const refresh=()=>{
  const existing=clubs.find(c=>c.id===form.elements.club_id?.value),select=form.elements.timezone;
  if(existing?.timezone){if(![...select.options].some(o=>o.value===existing.timezone))select.add(new Option(existing.timezone,existing.timezone));select.value=existing.timezone;}
  select.disabled=!!existing?.timezone;
  const later=form.elements.start_mode.value==='later',today=trialLocalDate(select.value);
  document.getElementById('ptStartDateField').hidden=!later;form.elements.starts_on.required=later;form.elements.starts_on.min=today;
  const start=later?form.elements.starts_on.value:today,product=form.elements.product.value;
  const keys=product==='both'?['batting','selections']:product?[product]:[];
  document.getElementById('ptDateSummary').textContent=!form.elements.start_mode.value?'Your full trial begins on your chosen date.':start?keys.map(k=>`${PRODUCT_ENQUIRY_LABELS[k]}: ${niceDate(start)} – ${niceDate(trialEndDate(start,days?.[k]||(k==='selections'?21:60)))}.`).join(' ')+' We’ll alert your Club Admin when it begins.':'Choose a date that suits your club’s season.';
  document.getElementById('ptSubmit').textContent=later?'Schedule free trial':'Start free trial';
 };
 for(const key of ['start_mode','starts_on','timezone','product','club_id'])form.elements[key]?.addEventListener('change',refresh);
 refresh();
}
function trialPrimerHtml(products){
 const selected=['selections','batting'].filter(k=>products[k]?.active||products[k]?.scheduled);
 if(!selected.length)return '';
 return `<section class="card pt-primer" id="trialGettingStarted"><div class="section-label">Your starter guide</div><h2>Getting started</h2><p>${selected.length===2?'Set up your club once, then begin each product in the order that suits you.':'A short sequence to help your club get useful results from the trial.'}</p><h3>Set up your club</h3><ol>${TRIAL_PRIMERS.shared.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${selected.map(k=>`<h3>${esc(PRODUCT_ENQUIRY_LABELS[k])}</h3><ol>${TRIAL_PRIMERS[k].map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`).join('')}${selected.length===2?`<p>${esc(TRIAL_PRIMERS.both_note)}</p>`:''}<p>For step-by-step guidance, open Help & Tutorials.</p><button class="btn ghost" data-trial-help>Open Help & Tutorials</button></section>`;
}
async function renderScheduledClubProducts(message=''){
 const page=document.getElementById('page'),cid=club?.id,uid=session?.user?.id;if(!page||!isAdmin())return;
 const current=()=>page.isConnected&&club?.id===cid&&session?.user?.id===uid&&currentTab==='products';
 page.innerHTML=productEnquiryStyles()+'<section class="card"><h1>Products & trials</h1><p>Loading…</p></section>';
 try{
  const r=await productTrialRPC('context',{club_id:cid});if(!current())return;
  const products=r.products||{};scheduledTrialContext={key:`${uid}:${cid}`,products};
  page.innerHTML=productEnquiryStyles()+`<section class="card"><h1>Products & trials</h1><p>Choose when your club is ready. Each trial runs for the full period from its start date.</p><p role="status">${esc(message)}</p><div class="pt-products">${['selections','batting'].map(k=>{
   const p=products[k]||{},free=p.active&&p.complimentary;
   const label=free?'Permanently free':p.scheduled?'Trial scheduled':p.active&&p.on_trial?'Free trial':p.active?'Active':p.trial_available?'Ready to try':'Access ended';
   const detail=free?'No expiry or payment required.':p.scheduled?`${niceDate(p.starts_on)} – ${niceDate(p.trial_ends)}. Your trial has not started.`:p.active&&p.on_trial?`Trial ends ${niceDate(p.trial_ends)}.`:p.active?(p.access_ends?`Access until ${niceDate(p.access_ends)}.`:'Available for your club.'):p.trial_available?`${r.trial_days?.[k]||(k==='selections'?21:60)} days free. Start now or choose a date.`:p.access_ends?`Access ended ${niceDate(p.access_ends)}.`:p.trial_ends?`Your trial ended ${niceDate(p.trial_ends)}.`:'This product has already been used by your club.';
   const target=new URL('./app.html',location.href);target.searchParams.set('trial_product',k);target.searchParams.set('trial_club',cid);
   return `<article class="pt-product"><h2>${esc(PRODUCT_ENQUIRY_LABELS[k])}</h2><p class="pt-status"><strong>${label}</strong></p><p>${esc(detail)}</p>${p.scheduled?`<p class="help">${esc(p.timezone)} · We’ll send your Club Admin a start alert and the starter guide.</p>`:''}${p.trial_available?`<a class="btn secondary" href="${esc(target.href)}">Choose trial start</a>`:''}${p.can_reschedule?`<button class="btn ghost" data-change-trial="${k}">Change start date</button><form class="pt-date-edit" data-trial-edit="${k}" hidden><label for="ptEdit-${k}">New start date</label><input id="ptEdit-${k}" name="starts_on" type="date" required min="${trialLocalDate(p.timezone)}" value="${esc(p.starts_on)}"><p class="help" data-date-end></p><div class="btnrow"><button class="btn secondary" type="submit">Save date</button><button class="btn ghost" type="button" data-start-today>Start today</button><button class="btn ghost" type="button" data-cancel-date>Cancel</button></div><p role="status" data-edit-status></p></form>`:''}${p.active?`<button class="btn ghost" data-trial-open="${k==='selections'?'teams':'dashboard'}">Open ${k==='selections'?'Teams':'Club Home'}</button>`:''}</article>`;
  }).join('')}</div>${Object.values(products).some(p=>p.scheduled)?'<p>Your club is registered. You can read the starter guide now and change a future start date here.</p>':''}${Object.values(products).some(p=>p.on_trial&&!p.complimentary)?'<p class="help">Online payments are not enabled during this pilot. Nothing is automatically charged when a trial ends.</p>':''}</section>${trialPrimerHtml(products)}<style>.pt-products{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,270px),1fr));gap:16px;margin:24px 0}.pt-product{padding:20px;border:1px solid #dce2ee;border-radius:12px}.pt-product h2{font-size:22px;margin:0 0 16px}.pt-product p,.pt-primer p,.pt-primer li{line-height:1.55}.pt-product .btn{display:inline-block;min-height:44px;margin:4px 4px 4px 0;text-decoration:none}.pt-primer{margin-top:16px}.pt-primer h3{margin-top:24px}.pt-primer li{margin:8px 0}.pt-date-edit input{max-width:100%;box-sizing:border-box;font-size:16px}.pt-date-edit{margin-top:16px}.pt-date-edit[hidden]{display:none}</style>`;
  page.querySelectorAll('[data-change-trial]').forEach(b=>b.onclick=()=>{const f=page.querySelector(`[data-trial-edit="${b.dataset.changeTrial}"]`);f.hidden=false;b.hidden=true;f.elements.starts_on.focus();});
  page.querySelectorAll('[data-trial-open]').forEach(b=>b.onclick=()=>{if(canOpenClubTab(b.dataset.trialOpen)){currentTab=b.dataset.trialOpen;renderShell();}});
  page.querySelector('[data-trial-help]')?.addEventListener('click',()=>{currentTab='guide';renderTab();});
  page.querySelectorAll('[data-trial-edit]').forEach(form=>{
   const k=form.dataset.trialEdit,p=products[k],duration=Math.round((Date.parse(p.trial_ends)-Date.parse(p.starts_on))/86400000)+1;let busy=false,pending=null;
   const preview=()=>{const start=form.elements.starts_on.value;form.querySelector('[data-date-end]').textContent=start?`Trial ends ${niceDate(trialEndDate(start,duration||60))}. ${p.timezone}.`:'';};preview();form.elements.starts_on.onchange=preview;
   form.querySelector('[data-cancel-date]').onclick=()=>{if(busy)return;form.hidden=true;page.querySelector(`[data-change-trial="${k}"]`).hidden=false;};
   form.querySelector('[data-start-today]').onclick=()=>{form.elements.starts_on.value=trialLocalDate(p.timezone);preview();form.querySelector('[type="submit"]').textContent='Start trial today';};
   form.onsubmit=async event=>{
    event.preventDefault();if(busy)return;busy=true;form.querySelectorAll('input,button').forEach(e=>e.disabled=true);
    const status=form.querySelector('[data-edit-status]');status.textContent='Saving…';
    pending=pending||{club_id:cid,product:k,starts_on:form.elements.starts_on.value,expected_revision:p.schedule_revision,request_id:crypto.randomUUID()};
    try{await productTrialRPC('reschedule',pending);if(current()){await loadData();await renderScheduledClubProducts('Trial dates saved.');}}
    catch(error){if(current()){status.textContent=(error.message||'Could not confirm the new date.')+(error.code?' Refresh to check the current dates.':' Choose Save date to safely check the same change again.');if(error.code)pending=null;}}
    finally{busy=false;if(form.isConnected)form.querySelectorAll('input,button').forEach(e=>e.disabled=!!pending);if(form.isConnected&&pending)form.querySelector('[type="submit"]').disabled=false;}
   };
  });
 }catch(error){if(current()){page.innerHTML=`<section class="card"><h1>Products & trials</h1><p role="status">${esc(error.message)}</p><button class="btn ghost" id="ptReloadProducts">Retry</button></section>`;page.querySelector('#ptReloadProducts').onclick=()=>renderScheduledClubProducts();}}
}
/* END SCHEDULED TRIALS */

/* BEGIN PHONE SETUP PROMPT — no permission request until the member chooses Enable */
let phoneSetupPromptState=null;
function phoneSetupPromptKey(){return session?.user?.id&&club?.id?`${session.user.id}:${club.id}`:null;}
function phoneSetupSnoozed(key){try{return Number(localStorage.getItem('cb-phone-setup-later:'+key)||0)>Date.now();}catch{return false;}}
function invalidatePhoneSetupPrompt(){phoneSetupPromptState=null;void refreshPhoneSetupPrompt();}
function paintPhoneSetupPrompt(host,state,key){
 if(!host?.isConnected||key!==phoneSetupPromptKey()||currentTab==='phone_app'||phoneSetupSnoozed(key)){if(host)host.hidden=true;return;}
 if(state==='ready'||state==='chosen_off'){host.hidden=true;host.innerHTML='';return;}
 const copy=state==='blocked'
  ?['Phone notifications are blocked','Open notification settings to see how to allow Club Batting alerts.','Review notification settings']
  :state==='unknown'
   ?['Check your phone notifications','We couldn’t confirm this phone’s notification setup. Open settings to check.','Check notification setup']
   :['Finish setting up notifications','Your app is installed. Turn on notifications to receive team and club updates on your phone. Until phone alerts are enabled, we’ll keep sending email notifications.','Set up notifications'];
 host.innerHTML=`<style>.phone-setup-prompt{margin:12px 16px 0;padding:14px 16px;border:1px solid #c9d2ee;border-radius:10px;background:#f0f4ff;color:#172033}.phone-setup-prompt strong{display:block;font-size:16px}.phone-setup-prompt p{margin:7px 0 10px;font-size:14px;line-height:1.5}.phone-setup-prompt .btnrow{display:flex;gap:8px;flex-wrap:wrap}.phone-setup-prompt button{min-height:44px;max-width:100%;white-space:normal}.phone-setup-prompt[hidden]{display:none}</style><strong>${copy[0]}</strong><p>${copy[1]}</p><div class="btnrow"><button type="button" class="btn secondary" data-phone-setup-open>${copy[2]}</button><button type="button" class="btn ghost" data-phone-setup-later>Remind me later</button></div>`;
 host.hidden=false;
 host.querySelector('[data-phone-setup-open]').onclick=openPhoneApp;
 host.querySelector('[data-phone-setup-later]').onclick=()=>{
  try{localStorage.setItem('cb-phone-setup-later:'+key,String(Date.now()+7*86400000));}catch{}
  host.hidden=true;
 };
}
async function refreshPhoneSetupPrompt(){
 const host=document.getElementById('phoneSetupPromptHost'),key=phoneSetupPromptKey();
 if(!host)return;
 if(!key||phoneIsDemo()||!phoneIsInstalled()||!(phoneIsIOS()||phoneIsAndroid())||currentTab==='phone_app'||phoneSetupSnoozed(key)){host.hidden=true;return;}
 if(!phonePushSupported()){host.hidden=true;return;}
 let state=phoneSetupPromptState;
 if(!state||state.key!==key){state={key,checkedAt:0,result:null,pending:null};phoneSetupPromptState=state;}
 if(!state.pending&&Date.now()-state.checkedAt>=45000){
  const clubId=club.id;
  state.pending=Promise.resolve().then(async()=>{
   try{
    if(Notification.permission==='denied'){state.result='blocked';return;}
    const reg=await initialisePhoneApp();if(!reg)throw Error('Registration unavailable');
    await waitForPhoneWorker(reg);
    const sub=await reg.pushManager.getSubscription();
    if(key!==phoneSetupPromptKey())return;
    const {data,error}=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'get',p_data:{endpoint:sub?.endpoint||null}});
    if(error||!data||!data.configured)throw Error('Notification status unavailable');
    // A saved choice to turn both categories off is respected. Browser permission
    // alone is not enough: the device must be registered for this member and club.
    state.result=sub&&data.subscription_id&&data.club_enabled&&Notification.permission==='granted'
     ?(data.preferences.messages||data.preferences.coaching?'ready':'chosen_off'):'incomplete';
   }catch{state.result='unknown';}
   finally{state.checkedAt=Date.now();state.pending=null;}
  });
 }
 if(state.pending)await state.pending;
 if(state!==phoneSetupPromptState||key!==phoneSetupPromptKey()||document.getElementById('phoneSetupPromptHost')!==host)return;
 paintPhoneSetupPrompt(host,state.result||'unknown',key);
}
/* END PHONE SETUP PROMPT */
